# --- FUNC: prioritize_projects ---
def prioritize_projects(self, max_investment: float = 500) -> List[Dict]:
        """Приоритизация проектов по критерию ROI/время"""
        if not self.quick_wins:
            self.identify_quick_wins()
            
        # Рассчитываем ROI для каждого проекта
        for project in self.quick_wins:
            if "annual_savings" in project:
                annual_return = project["annual_savings"]
            else:
                annual_return = project["annual_profit"]
                
            project["roi"] = annual_return / project["investment_required"]
            project["score"] = (project["roi"] * 0.6 + 
                              (1/project["implementation_time"]) * 0.4)
        
        # Сортируем по убыванию score
        sorted_projects = sorted(self.quick_wins, key=lambda x: x["score"], reverse=True)
        
        # Выбираем проекты в рамках бюджета
        selected = []
        total_investment = 0
        
        for project in sorted_projects:
            if total_investment + project["investment_required"] <= max_investment:
                selected.append(project)
                total_investment += project["investment_required"]
        
        return selected

