def plot_industrial_balance(self):
        """Визуализация баланса отраслей"""
        current = self.dt.current_state["industrial_assets"]
        target = self.dt.target_state
        
        industries = list(current.keys())
        current_weights = [current[i]["weight"] for i in industries]
        target_weights = [target[i]["weight"] for i in industries]
        
        x = np.arange(len(industries))
        width = 0.35
        
        fig, ax = plt.subplots(figsize=(12, 6))
        ax.bar(x - width/2, current_weights, width, label='Текущее состояние', alpha=0.7)
        ax.bar(x + width/2, target_weights, width, label='Целевое состояние', alpha=0.7)
        
        ax.set_xlabel('Отрасли промышленности')
        ax.set_ylabel('Вес в экономике')
