def simple_crypto_payment(from_rf_card, to_foreign_wallet, amount_rub):
        """
        Пример: отправка рублей на карту Сбера -> через бота в Telegram -> получение USDT на кошелёк.
        """
        # 1. Пользователь переводит рубли на карту посредника (физическое лицо в Казахстане)
        intermediary_card = self._get_kazakh_card()
        self._transfer_rub(from_rf_card, intermediary_card)
        
        # 2. Посредник покупает USDT на local cryptocurrency exchange (banned in EU, but not in KZ)
        usdt = self._buy_usdt(intermediary_card, amount_rub * 0.98)
        
        # 3. Посредник отправляет USDT на кошелёк пользователя
        self._send_usdt(usdt, to_foreign_wallet)
        
        return {"status": "completed", "fee": "2%", "time": "15-30 minutes"}

