# --- FUNC: obfuscate_amount ---
def obfuscate_amount(self, total_amount: float) -> List[float]:
        """Разбитие суммы на несвязанные части с нестандартными номиналами"""
        parts = []
        remaining = total_amount
        while remaining > 0:
            # Используем не равные части, а случайные логарифмические величины
            chunk = round(remaining * random.uniform(0.05, 0.25), 2)
            # Добавляем случайный "шум" в копейки
            chunk += random.randint(1, 99) / 100
            parts.append(chunk)
            remaining -= chunk
        # Перемешиваем порядок частей
        random.shuffle(parts)
        return parts

# --- FUNC: route_transaction ---
def route_transaction(self, asset: str, amount: float, source: str, dest: str):
        # Пример маршрута: BTC -> XMR -> ETH -> USDT (TRC-20) -> BNB -> окончательный кошелек
        steps = [
            ("BTC", self._to_xmr),    # через Atomic swap или DEX
            ("XMR", self._to_eth),    # через приватный мост (например, Trocador)
            ("ETH", self._to_usdt),   # через Uniswap с прокси
            ("USDT", self._to_bnb),   # через кросс-чейн мост (Wormhole)
            ("BNB", dest)             # финальный вывод
        ]
        for step in steps:
            amount = self._execute_step(step, amount)
            self._random_delay(minutes=10, hours=48)
        return amount

# --- FUNC: route_payment ---
def route_payment(self, amount_rub, final_destination):
        # Этап 1: Россия → Казахстан. Покупка USDT через местный P2P (обменники в Алматы)
        kazakh_exchanger = self._find_exchanger("Almaty", amount_rub)
        usdt_kz = kazakh_exchanger.buy_usdt(amount_rub, payment_method="cash or transfer to Kaspi Bank")
        
        # Этап 2: Казахстан → ОАЭ. Перевод USDT на биржу в ОАЭ (например, CoinMENA)
        uae_account = self._transfer_to_exchange(usdt_kz, exchange="CoinMENA")
        
        # Этап 3: ОАЭ → конечный получатель. Вывод в фиат или криптовалюта по желанию клиента
        if final_destination == "EU":
            # Через европейского посредника, купившего USDT в ОАЭ и отправившего евро на счёт получателя в SEPA
            europe_broker = self._match_with_europe_buyer(uae_account, amount_eur)
            return europe_broker.send_sepa(final_destination, amount_eur)
        else:
            # Прямой перевод в криптовалюте на кошелёк конечного получателя
            return self._withdraw_crypto(uae_account, final_destination_wallet)

# --- FUNC: run_coinjoin ---
def run_coinjoin(self, btc_amount):
        """
        Участвуем в CoinJoin-раунде с десятками других пользователей
        """
        # Выбираем микшер с низкой комиссией и отсутствием лимитов
        mixer = self._select_mixer(random.choice(self.active_mixers))
        anonymized = mixer.mix(btc_amount, rounds=2, anonymity_set=50)
        return anonymized

# --- FUNC: anonymized_rpc_call ---
def anonymized_rpc_call(self, node_url, method, params):
        session = requests.Session()
        session.proxies = {'https': self.tor_proxy}
        response = session.post(node_url, json={"method": method, "params": params})
        return response.json()

# --- FUNC: split_amount ---
def split_amount(self, total, parts=7):
        # Вместо равных частей (10k+10k+10k) использовать случайные числа: 9993, 10012, 9876...
        return [int(total * np.random.uniform(0.1, 0.25)) for _ in range(parts-1)]

# --- FUNC: random_delay ---
def random_delay(self, min_hours=2, max_hours=48):
        time.sleep(random.uniform(min_hours*3600, max_hours*3600))

