# --- FUNC: collective_observation ---
def collective_observation(self):
        """Совместное наблюдение всех наблюдателей"""
        if not self.observers:
            return self.quantum_state
            
        # Суммарный оператор наблюдения:
        total_chi = np.zeros_like(self.quantum_state, dtype=complex)
        
        for obs in self.observers:
            # Каждый наблюдатель вносит свой вклад
            individual_effect = obs.observe(self.quantum_state)
            total_chi += individual_effect
            
        # Консенсусное состояние
        consensus_state = total_chi / len(self.observers)
        
        # Коллапс к консенсусу
        norm = np.sqrt(np.sum(np.abs(consensus_state)**2))
        if norm > 0:
            consensus_state /= norm
            
        self.quantum_state = consensus_state
        return consensus_state

# --- FUNC: measure_correlation ---
def measure_correlation(self, other_network):
        """Корреляция между двумя сетями наблюдателей"""
        corr = np.abs(np.dot(self.quantum_state.conj(), other_network.quantum_state))
        return corr

