# --- FUNC: update_projections ---
def update_projections(self):
        """Проекция единого электрона на N наблюдателей"""
        # Каждый наблюдатель видит свою "копию"
        projections = []
        for obs in self.observers:
            # Проекция зависит от положения и уровня сознания
            proj = self.psi_universe * obs['χ'] * np.exp(-1j*self.time)
            projections.append(proj)
        return projections

# --- FUNC: collective_measurement ---
def collective_measurement(self):
        """Коллективное измерение → консенсусная реальность"""
        projections = self.update_projections()
        # Консенсус = среднее по всем наблюдателям
        consensus = np.mean(projections, axis=0)
        # Коллапс волновой функции
        probability = np.abs(consensus)**2
        return probability / np.sum(probability)

