# --- FUNC: weave ---
def weave(self, speed, tension_threshold=0.5):
        # Генерация точек плетения в зависимости от паттерна
        if self.pattern == "radial":
            points = self.generate_radial_points(8)  # 8 лучей
        elif self.pattern == "spiral":
            points = self.generate_spiral_points()
        else:
            raise ValueError("Unknown pattern")

        # Движение робота по точкам с контролем натяжения
        for point in points:
            self.move_to(point)
            self.adjust_tension(speed, tension_threshold)

# --- FUNC: generate_radial_points ---
def generate_radial_points(self, n_rays):
        angles = np.linspace(0, 2*np.pi, n_rays, endpoint=False)
        radius = 1.0
        return [(radius * np.cos(angle), radius * np.sin(angle)) for angle in angles]

