# --- FUNC: is_eol ---
def is_eol(self, as_of: Optional[date] = None) -> bool:
        """Версия на EOL?"""
        if self.eol_date is None:
            return False
        return (as_of or date.today()) >= self.eol_date

# --- FUNC: get ---
def get(self, key: str) -> Optional[Any]:
        """Получение данных из кэша"""
        if key in self.cache:
            data, expiry = self.cache[key]
            if datetime.now() < expiry:
                return data
            else:
                del self.cache[key]
        return None

# --- FUNC: exists ---
def exists(self, version: str) -> bool:
        return self._normalize(version) in self._registry

# --- FUNC: all_versions ---
def all_versions(self) -> list[str]:
        return sorted(self._registry.keys(), key=self._version_key)

# --- FUNC: supported_versions ---
def supported_versions(self) -> list[str]:
        return [v for v, i in self._registry.items() if i.status in ("supported", "security")]

# --- FUNC: eol_versions ---
def eol_versions(self) -> list[str]:
        return [v for v, i in self._registry.items() if i.status == "eol"]

# --- FUNC: has_syntax ---
def has_syntax(self, version: str, feature: str) -> bool:
        """Доступна ли синтаксическая конструкция в указанной версии?"""
        first_available = self._first_version_for_syntax(feature)
        if first_available is None:
            return False
        return self._version_key(self._normalize(version)) >= self._version_key(first_available)

# --- FUNC: has_module ---
def has_module(self, version: str, module: str) -> bool:
        """Доступен ли модуль в указанной версии (с учётом удаления)?"""
        ver_key = self._version_key(self._normalize(version))

        # Удалён?
        removal = self._removed_index.get(module)
        if removal:
            first_removed = min(removal, key=self._version_key)
            if ver_key >= self._version_key(first_removed):
                return False

        # Появился?
        introduced = self._module_index.get(module)
        if introduced:
            first_introduced = min(introduced, key=self._version_key)
            return ver_key >= self._version_key(first_introduced)

        # Не в индексе новых — значит был всегда (base stdlib)
        return True

# --- FUNC: find_syntax_since ---
def find_syntax_since(self, feature: str) -> Optional[str]:
        """С какой версии доступна конструкция?"""
        return self._first_version_for_syntax(feature)

# --- FUNC: find_module_removed_since ---
def find_module_removed_since(self, module: str) -> Optional[str]:
        """С какой версии модуль удалён?"""
        removal = self._removed_index.get(module)
        if not removal:
            return None
        return min(removal, key=self._version_key)

# --- FUNC: eol_warning ---
def eol_warning(self, version: str) -> Optional[str]:
        """Вернуть предупреждение, если версия на EOL или близко."""
        info = self.get(version)
        if not info:
            return None
        if info.status == "eol":
            return f"Python {info.version} на EOL с {info.eol_date}. Обновитесь."
        if info.status == "prerelease":
            return f"Python {info.version} ещё не выпущен. Возможны изменения."
        return None

# --- FUNC: removed_modules_in ---
def removed_modules_in(self, version: str) -> tuple[str, ...]:
        """Какие модули удалены в указанной версии."""
        info = self.get(version)
        return info.removed_modules if info else ()

# --- FUNC: _normalize ---
def _normalize(version: str) -> str:
        """'3.11.5' → '3.11';  '3.11' → '3.11'."""
        parts = version.split(".")
        return f"{parts[0]}.{parts[1]}" if len(parts) >= 2 else version

# --- FUNC: _version_key ---
def _version_key(version: str) -> tuple[int, int]:
        major, minor = version.split(".")[:2]
        return (int(major), int(minor))

# --- FUNC: _first_version_for_syntax ---
def _first_version_for_syntax(self, feature: str) -> Optional[str]:
        versions = self._syntax_index.get(feature, [])
        if not versions:
            return None
        return min(versions, key=self._version_key)

# --- FUNC: attach_to ---
def attach_to(self, system, hook_name: str = "check_code"):
        """Подключает инструмент к любой системе, у которой есть метод-приёмник."""
        setattr(system, hook_name, self._sim.analyze)
        return system

# --- FUNC: detach_from ---
def detach_from(self, system, hook_name: str = "check_code"):
        """Отключает без следов."""
        if hasattr(system, hook_name):
            delattr(system, hook_name)
        return system

# --- FUNC: __getattr__ ---
def __getattr__(name: str):
    if name == "__doc_url__":
        return "https://example.com/universal-simulator"
    raise AttributeError(f"module 'universal_simulator' has no attribute {name!r}")

# --- FUNC: attach_simulator ---
def attach_simulator(
    target: Any,
    simulator: Optional[UniversalSimulator] = None,
    hooks: Optional[dict[str, str]] = None,
) -> SimulatorAdapter:
    """
    Одна строка: подключить симулятор к объекту.

    Возвращает адаптер — чтобы можно было потом .detach().
    """
    sim = simulator or UniversalSimulator()
    adapter = SimulatorAdapter(sim, hooks=hooks)
    adapter.attach(target)
    return adapter

# --- FUNC: can_attach ---
def can_attach(self, target: Any) -> bool:
        """
        Можно ли подключиться к этому объекту?
        Проверяем: объект не None, не является базовым неизменяемым типом,
        не имеет конфликтов имён (или разрешает их).
        """
        if target is None:
            return False
        # Не позволяем лезть в неизменяемые встроенные типы
        if isinstance(target, (int, str, tuple, frozenset, bytes)):
            return False
        # Уже привязан — ок, повторный attach идемпотентен
        return True

# --- FUNC: attach ---
def attach(
        self,
        target: Any,
        hook_name: Optional[str] = None,
        overwrite: bool = False,
    ) -> Any:
        """
        Подключить симулятор к объекту.

        hook_name: если указан — добавить только один метод под этим именем;
                   если None — добавить весь набор из self._hooks.
        overwrite: перезаписывать ли существующие методы (по умолчанию нет).

        Возвращает тот же объект (для chaining).
        """
        if not self.can_attach(target):
            raise TypeError(f"К этому объекту нельзя подключиться: {type(target).__name__}")

        spec = {hook_name: self._sim.analyze} if hook_name else self._make_hook_map()

        attached_here: dict[str, Callable] = {}

        for sys_name, method in spec.items():
            # Конфликт имён?
            if hasattr(target, sys_name) and not overwrite:
                existing = getattr(target, sys_name)
                # Если это наш же метод — уже привязан, ничего не делаем
                if getattr(existing, _ADAPTER_MARKER, False):
                    continue
                # Иначе — конфликт, пропускаем (мягко) или падаем
                raise AttributeError(
                    f"У объекта уже есть атрибут {sys_name!r}. "
                    f"Используйте overwrite=True, если хотите перезаписать."
                )

            # Привязываем
            setattr(target, sys_name, self._wrap_method(method, sys_name))
            attached_here[sys_name] = method

        # Запоминаем для корректного detach
        key = id(target)
        self._attached.setdefault(key, {})
        self._attached[key].update(attached_here)

        return target

# --- FUNC: detach ---
def detach(
        self,
        target: Any,
        hook_name: Optional[str] = None,
    ) -> Any:
        """
        Отключить симулятор. Убирает ровно то, что добавил attach().
        Если hook_name=None — убирает все ранее добавленные методы.
        """
        key = id(target)
        registry = self._attached.get(key)
        if not registry:
            return target

        if hook_name:
            if hook_name in registry:
                self._safe_delattr(target, hook_name)
                registry.pop(hook_name, None)
        else:
            for name in list(registry.keys()):
                self._safe_delattr(target, name)
                registry.pop(name, None)

        if not registry:
            self._attached.pop(key, None)

        return target

# --- FUNC: detach_all ---
def detach_all(self) -> None:
        """Отключить всё отовсюду — «аварийный выключатель»."""
        for key in list(self._attached.keys()):
            registry = self._attached[key]
            # Мы не храним ссылку на объект, только id — поэтому удалим
            # зарегистрированные имена, если объект всё ещё жив
            for name in list(registry.keys()):
                registry.pop(name, None)
        self._attached.clear()

# --- FUNC: list_attached ---
def list_attached(self) -> dict[int, list[str]]:
        """Кому и что мы сейчас дали (только для диагностики)."""
        return {k: sorted(v.keys()) for k, v in self._attached.items()}

# --- FUNC: mixin_class ---
def mixin_class(self, base_cls: type) -> type:
        """
        Создать класс, наследующий base_cls + методы симулятора.

        Пример:
            CoreWithSim = adapter.mixin_class(AbsoluteCore)
            core = CoreWithSim()
            core.check_code(code, env)
        """
        sim = self._sim

        class _WithSimulator(base_cls):    # type: ignore
            def check_code(self, code: str, target: Any = None) -> dict:
                return sim.analyze(code, target)

            def simulate_code(self, code: str, target: Any = None, **kw) -> dict:
                return sim.analyze_and_execute(code, target, **kw)

            def execute_code(self, code: str, target: Any = None, **kw) -> dict:
                return sim.execute(code, target, **kw)

            def simulator_caps(self) -> dict:
                return sim.capabilities()

        _WithSimulator.__name__ = f"{base_cls.__name__}WithSimulator"
        _WithSimulator.__qualname__ = _WithSimulator.__name__
        return _WithSimulator

# --- FUNC: wrap ---
def wrap(self, target: Any) -> Any:
        """
        Вернуть прокси-объект: оригинальные атрибуты + методы симулятора.
        Оригинал не меняется.
        """
        sim = self._sim
        original = target

        class _Proxy:
            def __init__(self, base):
                object.__setattr__(self, "_base", base)

            def __getattr__(self, name):
                return getattr(self._base, name)

            def __setattr__(self, name, value):
                if name == "_base":
                    object.__setattr__(self, name, value)
                else:
                    setattr(self._base, name, value)

            def __repr__(self):
                return f"<Wrapped {type(self._base).__name__} with simulator>"

            # Методы симулятора
            def check_code(self, code: str, target_env: Any = None) -> dict:
                return sim.analyze(code, target_env)

            def simulate_code(self, code: str, target_env: Any = None, **kw) -> dict:
                return sim.analyze_and_execute(code, target_env, **kw)

            def execute_code(self, code: str, target_env: Any = None, **kw) -> dict:
                return sim.execute(code, target_env, **kw)

            def simulator_caps(self) -> dict:
                return sim.capabilities()

        return _Proxy(original)

# --- FUNC: _make_hook_map ---
def _make_hook_map(self) -> dict[str, Callable]:
        """Собрать карту {имя_в_системе: метод_симулятора}."""
        result = {}
        for sys_name, sim_method in self._hooks.items():
            method = getattr(self._sim, sim_method, None)
            if callable(method):
                result[sys_name] = method
        return result

# --- FUNC: _wrap_method ---
def _wrap_method(method: Callable, sys_name: str) -> Callable:
        """
        Обёртка метода, помеченная маркером — чтобы detach знал,
        что метод «наш».
        """
        def _bound(self, *args, **kwargs):
            return method(*args, **kwargs)

        setattr(_bound, _ADAPTER_MARKER, True)
        setattr(_bound, "__name__", sys_name)
        return _bound

# --- FUNC: _safe_delattr ---
def _safe_delattr(target: Any, name: str) -> None:
        try:
            # Проверяем: это точно наш метод?
            existing = getattr(target, name, None)
            if existing is not None and not getattr(existing, _ADAPTER_MARKER, False):
                return  # не наш — не трогаем
            delattr(target, name)
        except AttributeError:
            pass

# --- FUNC: simulate_code ---
def simulate_code(self, code: str, target_env: Any = None, **kw) -> dict:
                return sim.analyze_and_execute(code, target_env, **kw)

# --- FUNC: execute_code ---
def execute_code(self, code: str, target_env: Any = None, **kw) -> dict:
                return sim.execute(code, target_env, **kw)

# --- FUNC: simulator_caps ---
def simulator_caps(self) -> dict:
        return self.simulator.capabilities()

# --- FUNC: _bound ---
def _bound(self, *args, **kwargs):
            return method(*args, **kwargs)

# --- FUNC: __setattr__ ---
def __setattr__(self, name, value):
                if name == "_base":
                    object.__setattr__(self, name, value)
                else:
                    setattr(self._base, name, value)

# --- FUNC: check_simulator ---
def check_simulator(obj: Any) -> tuple[bool, List[str]]:
    """
    Проверяет объект на соответствие SimulatorProtocol.

    Возвращает: (соответствует_ли, список_проблем).

    Полезно перед подключением: адаптер вызывает check_simulator(сим),
    убеждается, что контракт выполнен, и только тогда подключает.
    """
    problems: List[str] = []

    if not isinstance(obj, SimulatorProtocol):
        problems.append("Объект не соответствует SimulatorProtocol")

    # Дополнительные проверки на всякий случай (гибкость)
    required_methods = ["analyze", "execute", "capabilities", "requirements"]
    for method in required_methods:
        if not callable(getattr(obj, method, None)):
            problems.append(f"Отсутствует метод: {method}()")

    if not hasattr(obj, "version"):
        problems.append("Отсутствует поле: version")

    return (len(problems) == 0, problems)

# --- FUNC: check_engine ---
def check_engine(obj: Any) -> tuple[bool, List[str]]:
    """Проверка движка на соответствие EngineProtocol."""
    problems: List[str] = []

    if not isinstance(obj, EngineProtocol):
        problems.append("Объект не соответствует EngineProtocol")

    for method in ["is_available", "execute", "requirements"]:
        if not callable(getattr(obj, method, None)):
            problems.append(f"Отсутствует метод: {method}()")

    if not hasattr(obj, "name"):
        problems.append("Отсутствует поле: name")

    return (len(problems) == 0, problems)

