# --- FUNC: can_build_for ---
def can_build_for(
        self,
        package: str,
        target: TargetEnv,
        wheel_filename: Optional[str] = None,
        needs_native: bool = False,
    ) -> dict:
        """
        Полная проверка: «может ли этот пакет установиться в целевом окружении?»

        Возвращает:
        {
            "ok": bool,
            "reasons": [...],           # почему да/нет
            "warnings": [...],          # предупреждения (EOL, старый менеджер, ...)
            "recommended_manager": str,
            "wheel_compatible": bool | None,
        }
        """
        reasons: list[str] = []
        warnings: list[str] = []
        ok = True

        # 1. Версия Python — существует и не EOL?
        if not self.python.exists(target.py_major_minor):
            ok = False
            reasons.append(
                f"Python {target.py_major_minor} отсутствует в реестре базы знаний."
            )
        else:
            eol = self.eol_warning(target.py_major_minor)
            if eol:
                warnings.append(eol)

        # 2. Менеджер пакетов — совместим?
        mgr = target.package_manager
        if not self.packages.exists(mgr):
            ok = False
            reasons.append(f"Менеджер пакетов {mgr!r} неизвестен.")
        elif not self.packages.compatible_with(mgr, target):
            ok = False
            reasons.append(self.packages.compatibility_reason(mgr, target))

        # 3. Менеджер умеет собирать C-расширения (если пакет нативный)?
        if needs_native:
            if not self.packages.can_build_native(mgr):
                ok = False
                reasons.append(
                    f"{mgr} не умеет собирать C-расширения, а для {package} они нужны."
                )

        # 4. Wheel-файл — совместим?
        wheel_ok: Optional[bool] = None
        if wheel_filename:
            check = self.abi.check_wheel(wheel_filename, target)
            wheel_ok = check["compatible"]
            if not wheel_ok:
                ok = False
                reasons.append(check["reason"])

        # 5. Рекомендация менеджера
        rec = (
            self.packages.recommended_for_native(target)[0]
            if needs_native
            else self.packages.fastest(target)
        )

        return {
            "ok": ok,
            "reasons": reasons or ["Все проверки пройдены."],
            "warnings": warnings,
            "recommended_manager": rec,
            "wheel_compatible": wheel_ok,
        }

# --- FUNC: describe_environment ---
def describe_environment(self, target: TargetEnv) -> dict:
        """
        Полное описание целевой среды: что с Python, что с ABI, что с пакетами.
        """
        py_info = self.version_info(target.py_major_minor)
        return {
            "target": target.slug(),
            "python": {
                "version": target.py,
                "implementation": target.implementation,
                "status": py_info.status if py_info else "unknown",
                "eol_warning": self.eol_warning(target.py_major_minor),
                "new_features": py_info.new_features if py_info else (),
                "removed_modules": py_info.removed_modules if py_info else (),
            },
            "abi": {
                "abi_tags": self.abi_tags_for(target),
                "python_tags": self.python_tags_for(target),
                "platform_tags": self.platform_tags_for(target),
            },
            "packages": {
                "manager": target.package_manager,
                "available": self.available_managers(target),
                "fastest": self.fastest_manager(target),
                "strategy": self.packages.resolution_strategy(target.package_manager),
            },
            "paths": {
                "separators": target.path_separators,
                "primary": target.primary_separator,
                "case_sensitive": target.case_sensitive_fs,
            },
        }

# --- FUNC: stats ---
def stats(self) -> dict:
        if 'stats' in self._cache: return self._cache['stats']
        effs = [e.eff.thermal for e in self.engines.values() if e.eff]
        powers = []
        for e in self.engines.values():
            if e.spec: powers.extend(e.spec.power)
        stats = {
            'total': len(self.engines),
            'avg_eff': sum(effs)/len(effs) if effs else 0,
            'max_eff': max(effs) if effs else 0,
            'min_eff': min(effs) if effs else 0,
            'power_min': min(powers) if powers else 0,
            'power_max': max(powers) if powers else 0,
            'power_avg': sum(powers)/len(powers) if powers else 0
        }
        self._cache['stats'] = stats
        return stats

