# --- FUNC: craft_fake_command ---
def craft_fake_command(self, original_packet: StarlingPacket, new_lat, new_lon, new_cmd=2):
        """Создаёт подменный пакет, отправляемый вместо оригинального"""
        fake = StarlingPacket(
            drone_id=original_packet.drone_id,
            lat=new_lat,
            lon=new_lon,
            alt=original_packet.alt,
            vn=0, ve=0, vd=0,
            cmd=new_cmd
        )
        # Копируем временную метку (replay)
        fake.timestamp = original_packet.timestamp
        # Подпись пересчитаем? Если нет секрета – просто копируем старую
        fake.signature = original_packet.signature
        return fake.pack()

# --- FUNC: channel_capacity ---
def channel_capacity(H: np.ndarray, snr_db: float) -> float:
        """Ёмкость MIMO-канала (бит/с/Гц)"""
        snr_linear = 10 ** (snr_db / 10)
        HH = H @ H.conj().T
        eigenvalues = np.linalg.eigvalsh(HH)
        capacity = np.sum(np.log2(1 + snr_linear * eigenvalues / H.shape[0]))
        return capacity.real

# --- FUNC: optimal_jamming_strength ---
def optimal_jamming_strength(H: np.ndarray, target_capacity_reduction=0.5) -> float:
        """
        Определяет мощность помехи (в единицах шума), необходимую
        для снижения ёмкости на target_capacity_reduction.
        """
        original_cap = MIMOAnalyzer.channel_capacity(H, snr_db=20)
        # Простой бинарный поиск (можно заменить на более точный)
        low, high = 0.1, 100.0
        for _ in range(20):
            mid = (low+high)/2
            jammed_H = H + mid * np.eye(H.shape[0])
            new_cap = MIMOAnalyzer.channel_capacity(jammed_H, snr_db=20)
            if new_cap < original_cap * (1 - target_capacity_reduction):
                high = mid
            else:
                low = mid
        return low

# --- FUNC: add_observation ---
def add_observation(self, lat, lon, success):
        self.X.append([lat, lon])
        self.y.append(success)
        if len(self.X) >= 3:
            self.gp.fit(self.X, self.y)

# --- FUNC: suggest_trap ---
def suggest_trap(self, current_lat, current_lon, n_candidates=100):
        """Предлагает оптимальные координаты ловушки вблизи текущей позиции"""
        if len(self.X) < 3:
            # случайная ловушка в пределах 500 м
            delta_lat = random.uniform(-0.005, 0.005)
            delta_lon = random.uniform(-0.005, 0.005)
            return current_lat + delta_lat, current_lon + delta_lon
        
        # Генерируем кандидатов
        candidates = []
        for _ in range(n_candidates):
            lat = np.clip(current_lat + random.gauss(0, 0.003), *self.bounds[0])
            lon = np.clip(current_lon + random.gauss(0, 0.003), *self.bounds[1])
            candidates.append([lat, lon])
        
        # Предсказание вероятности успеха (среднее + 2*std = exploration)
        mu, sigma = self.gp.predict(candidates, return_std=True)
        scores = mu + 2 * sigma  # UCB acquisition
        best_idx = np.argmax(scores)
        return candidates[best_idx][0], candidates[best_idx][1]

# --- FUNC: learn_from_outcome ---
def learn_from_outcome(self, fake_packet: NavigationPacket, drone_actually_crashed: bool):
        self.trap_success_history.append({
            'lat': fake_packet.lat,
            'lon': fake_packet.lon,
            'success': drone_actually_crashed
        })

# --- FUNC: pack ---
def pack(self, secret_key=None) -> bytes:
        fmt = '<H B H I d d f f f f H I'
        data = struct.pack(fmt, 
            0x5A5A,  # preamble
            0x01,    # type navigation
            self.drone_id,
            self.timestamp,
            self.lat, self.lon, self.alt,
            self.vn, self.ve, self.vd,
            self.cmd,
            0)  # placeholder signature
        # Вычисление контрольной суммы
        checksum = bytes([b ^ 0xFF for b in data])  # упрощённо
        # Если секрет есть – подпись
        if secret_key:
            self.signature = crc32_func(data + secret_key.encode()) & 0xFFFFFFFF
            # Вставляем подпись в последние 4 байта перед checksum
            data = data[:-4] + struct.pack('<I', self.signature) + data[-1:]
        return data + checksum

# --- FUNC: capture_spectrum ---
def capture_spectrum(self, iq_samples: np.ndarray) -> np.ndarray:
        """Преобразование IQ-выборок в спектр мощности"""
        freqs, psd = welch(iq_samples, fs=self.sampling_rate, nperseg=self.fft_size)
        return freqs, psd

# --- FUNC: detect_anomaly ---
def detect_anomaly(self, current_psd: np.ndarray, threshold_db=3) -> bool:
        """Обнаружение новых сигналов на основе скользящего среднего"""
        if not self.spectrum_history:
            self.spectrum_history.append(current_psd)
            return False
        avg_psd = np.mean(self.spectrum_history, axis=0)
        diff_db = 10 * np.log10(current_psd / (avg_psd + 1e-12))
        return np.any(diff_db > threshold_db)

# --- FUNC: classify_protocol ---
def classify_protocol(self, peaks: list) -> str:
        """Сопоставление частотных пиков с известными протоколами"""
        for proto, freqs in self.protocol_signatures.items():
            if all(np.isclose(peak, freq, atol=5e6) for peak in peaks for freq in freqs):
                return proto
        return 'unknown'

# --- FUNC: process_threat ---
def process_threat(self, iq_samples, packets: list) -> list:
        # 1. Мониторинг спектра
        freqs, psd = self.monitor.capture_spectrum(iq_samples)
        is_anomaly = self.monitor.detect_anomaly(psd)
        if not is_anomaly:
            return packets  # нет угрозы
        
        # 2. Для каждого пакета проверить подпись
        modified_packets = []
        for pkt in packets:
            if self.filter.verify_starling_packet(pkt, int(time.time())):
                modified_packets.append(pkt)  # свой
            else:
                # враг – подмена с ловушкой
                current = (pkt.lat, pkt.lon)
                trap_lat, trap_lon = self.trap_opt.suggest_trap(current[0], current[1])
                fake_raw = self.exploiter.craft_fake_command(pkt, trap_lat, trap_lon, new_cmd=2)
                modified_packets.append(fake_raw)
        return modified_packets

# --- FUNC: sign_packet ---
def sign_packet(self, packet: NavigationPacket) -> str:
        """Цифровая подпись для своих дронов"""
        content = f"{packet.timestamp}{packet.lat}{packet.lon}{packet.alt}{self.secret_key}"
        return hashlib.sha256(content.encode()).hexdigest()[:16]

# --- FUNC: is_friendly ---
def is_friendly(self, packet: NavigationPacket) -> bool:
        """Проверка подписи (свои не глушим)"""
        expected = self.sign_packet(packet)
        return packet.signature == expected

# --- FUNC: predict_deviation ---
def predict_deviation(self, packet: NavigationPacket, external_impact: float) -> Tuple[float, float]:
        """
        Прогноз отклонения траектории при внешнем воздействии (например, облучении).
        Использует модель возмущённого движения.
        """
        # Простейшая модель: воздействие меняет скорость по оси X и Y
        noise_x = np.random.normal(0, external_impact * 0.1)
        noise_y = np.random.normal(0, external_impact * 0.1)
        return packet.lat + noise_x, packet.lon + noise_y

# --- FUNC: generate_trap_coordinates ---
def generate_trap_coordinates(self, real_packet: NavigationPacket) -> NavigationPacket:
        """Создаёт ложный пакет, уводящий дрон в безопасную зону"""
        # Определяем ближайшую «ловушку» (полигон, пустырь, зону поражения)
        trap_lat = real_packet.lat + 0.01  # ~1 км к востоку
        trap_lon = real_packet.lon + 0.01
        trap_alt = real_packet.alt - 10   # снижение
        
        fake_packet = NavigationPacket(
            raw_data=real_packet.raw_data,
            timestamp=real_packet.timestamp,
            lat=trap_lat,
            lon=trap_lon,
            alt=trap_alt,
            signature=None  # нет подписи – значит враг
        )
        return fake_packet

# --- FUNC: process_packet ---
def process_packet(self, packet: NavigationPacket, threat_level: float) -> Optional[NavigationPacket]:
        """
        Главный цикл фильтрации:
        - Свои → без изменений
        - Чужие → подмена навигации (увод)
        - Если threat_level высок – добавить прогноз отклонения
        """
        if self.is_friendly(packet):
            return packet  # прозрачный пропуск
        
        # Враг – применяем когнитивный увод
        trap = self.generate_trap_coordinates(packet)
        
        # Если требуется эмуляция помехи – добавляем отклонение
        if threat_level > 0.7:
            dev_lat, dev_lon = self.predict_deviation(trap, threat_level)
            trap.lat, trap.lon = dev_lat, dev_lon
        
        return trap

# --- FUNC: channel_condition_number ---
def channel_condition_number(H: np.ndarray) -> float:
        """Число обусловленности – чем выше, тем хуже устойчивость"""
        U, S, Vh = np.linalg.svd(H)
        return S[0] / S[-1] if S[-1] > 1e-6 else np.inf

# --- FUNC: simulate_interference ---
def simulate_interference(H: np.ndarray, snr_db: float, jammer_power: float) -> float:
        """Снижение ёмкости при наличии помехи"""
        noise_floor = 10 ** (-snr_db / 10)
        interference = jammer_power * np.eye(H.shape[0])
        H_eff = H + interference
        cond = MIMOStabilityAnalyzer.channel_condition_number(H_eff)
        # Эмпирическая формула потери битрейта
        capacity_loss = 1 - (1 / cond) if cond > 1 else 0
        return capacity_loss

# --- FUNC: temperature_rise ---
def temperature_rise(power_density_mw_cm2: float, exposure_time_sec: float) -> float:
        """
        Повышение температуры (°C) для типичного дрона.
        """
        # Удельная теплоёмкость корпуса ~ 1 Дж/(г·°C), масса 1 кг, площадь 0.1 м²
        absorbed_energy = power_density_mw_cm2 * 10 * exposure_time_sec  # мДж/см² -> Дж на 10 см²
        delta_T = absorbed_energy / 1000  # очень грубо: 1 Дж → 1°C на 1 кг
        return delta_T

# --- FUNC: is_critical ---
def is_critical(temp_rise: float, ambient: float = 25) -> bool:
        """Критическая температура 80°C (отказ электроники)"""
        return (ambient + temp_rise) > 80

# --- FUNC: generate_starling_signature ---
def generate_starling_signature(self, packet: NavigationPacket, timestamp: int) -> str:
        """HMAC-SHA256 на основе секретного ключа и текущего временного окна"""
        window = timestamp // self.time_step
        message = f"{window}{packet.lat}{packet.lon}{packet.alt}".encode()
        signature = hmac.new(self.secret_key.encode(), message, hashlib.sha256).hexdigest()[:16]
        return signature

# --- FUNC: verify_starling_packet ---
def verify_starling_packet(self, packet: NavigationPacket, timestamp: int) -> bool:
        expected = self.generate_starling_signature(packet, timestamp)
        return hmac.compare_digest(expected, packet.signature or "")

# --- FUNC: temp_rise ---
def temp_rise(self, power_density_w_m2: float, duration_sec: float) -> float:
        """
        Повышение температуры (°C) с учётом поглощения ~30% энергии.
        """
        absorbed_power = power_density_w_m2 * self.area * 0.3
        energy = absorbed_power * duration_sec
        delta_T = energy / (self.mass * self.cp)
        return delta_T

# --- FUNC: time_to_critical ---
def time_to_critical(self, power_density_w_m2: float, ambient=25, critical=80) -> float:
        """Время до достижения критической температуры (сек)"""
        if power_density_w_m2 <= 0:
            return float('inf')
        required_delta = critical - ambient
        # delta_T = (0.3 * power_density * area * t) / (mass * cp)
        t = (required_delta * self.mass * self.cp) / (0.3 * power_density_w_m2 * self.area)
        return t

