# --- FUNC: assess_risk ---
def assess_risk(self, development_plan: dict) -> str:
        """Оценка риска плана разработки"""
        risk_factors = []
        
        if development_plan['risk_level'] == 'высокий':
            risk_factors.append("Высокий исходный риск")
        
        if 'мультивселенная' in development_plan['description']:
            risk_factors.append("Вмешательство в другие реальности")
            
        if 'сжатие' in development_plan['description']:
            risk_factors.append("Риск неконтролируемой реакции")
        
        if risk_factors:
            self.current_warning_level = 'желтый'
            return f"⚠️ Требуется осторожность. Факторы риска: {', '.join(risk_factors)}"
        else:
            self.current_warning_level = 'зеленый'
            return "✅ Уровень риска приемлемый"

