# --- FUNC: regulated_division ---
def regulated_division(self, numerator, denominator):
        """
        Регуляризованное деление с учётом скорости Вселенной
        """
        if denominator == 0:
            # Вместо деления на ноль, делим на (∞ × v) ≈ 1/(H·t)
            # где t — возраст Вселенной
            t_universe = 4.35e17  # секунд (~13.8 млрд лет)
            regulated_denominator = 1 / (self.H * t_universe)
            return numerator / regulated_denominator
        else:
            return numerator / denominator

# --- FUNC: update_external_inflow ---
def update_external_inflow(self, time: float):
        # Моделируем изменчивость внешнего притока
        # Например, синусоидальная модуляция с очень длинным периодом
        long_term_modulation = 0.1 * np.sin(time * 0.01)  # очень медленные колебания
        self.external_energy_inflow = 1.0 + long_term_modulation

