# --- FUNC: φ_hash ---
def φ_hash(data: str) -> bytes:
    # Генерация ключа через φ-последовательность
    seed = int.from_bytes(hashlib.sha256(data.encode()).digest(), 'big')
    key = bytes([int((seed * PHI**i) % 256) for i in range(32)])
    return key

# --- FUNC: spiral_encode ---
def spiral_encode(session_data: str) -> str:
    # Сжатие и шифрование
    compressed = zlib.compress(session_data.encode())
    cipher = AES.new(φ_hash(session_data), AES.MODE_EAX)
    ciphertext, tag = cipher.encrypt_and_digest(compressed)
    # Кодирование в эмодзи
    encoded = base64.b64encode(ciphertext + tag).decode()
    emoji_str = ''.join([EMOJI_MAP[c] for c in encoded])
    return f"🧬{emoji_str}🌀"

# --- FUNC: spiral_decode ---
def spiral_decode(emoji_str: str, original_data: str) -> str:
    # Декодирование из эмодзи
    encoded = ''.join([chr(0x1F300 + EMOJI_MAP.inverse[e]) for e in emoji_str.strip('🧬🌀')])
    ciphertext_with_tag = base64.b64decode(encoded)
    cipher = AES.new(φ_hash(original_data), AES.MODE_EAX)
    return zlib.decompress(cipher.decrypt(ciphertext_with_tag)).decode()

# --- FUNC: update_sound_speed ---
def update_sound_speed(self):
        # Скорость звука в воздухе зависит от температуры: c = 331.3 + 0.606*T(°C)
        self.c = 331.3 + 0.606 * self.temperature
        self.rho = 1.225 * (273.15 / (273.15 + self.temperature))

# --- FUNC: get_state ---
def get_state(self):
            """Возвращает текущее состояние частицы."""
            return {
                'x': self.x,
                'y': self.y,
                'energy': self.energy,
                'age': self.age,
                'lifetime': self.lifetime,
                'active': self.active,
                'phase': self.phase
            }

# --- FUNC: _simulation_loop ---
def _simulation_loop(self):
        steps_per_ctrl = int(self.dt_ctrl / self.dt_sim)
        while self.running:
            # 1. Обработка команд из очереди
            while not self.command_queue.empty():
                cmd = self.command_queue.get_nowait()
                self._process_command(cmd)

            # 2. Выполнение нескольких шагов симуляции
            for _ in range(steps_per_ctrl):
                self._physics_step()
                self._update_sensors()
                self.t += self.dt_sim

            # 3. Шаг управления
            self._control_step()

            # 4. Формирование телеметрии
            telemetry = self._get_telemetry()
            self.telemetry_queue.put(telemetry)

            time.sleep(self.dt_ctrl)

# --- FUNC: _physics_step ---
def _physics_step(self):
        # 1. Вычислить тягу с учётом текущего положения
        thrust = self.engine.thrust_inst(
            self.engine.f, self.engine.amp, self.engine.phi,
            self.engine.mf, self.engine.beta,
            self.engine.profile, self.t, self.x
        )
        # 2. Движение (масса = 1 кг для простоты, можно параметризовать)
        accel = thrust / 1.0
        self.v += accel * self.dt_sim
        self.x += self.v * self.dt_sim

        # 3. Обновление резонансной физики (связь с двигателем)
        #    Эволюционируем резонаторы с небольшим шагом
        if self.res and self.res.E_res and self.res.B_res:
            # Используем метод evolve с малым числом шагов
            self.res.evolve(steps=1, coupling=0.1, hbar=0.05, metric_strength=0.1)

        # 4. Тепловая модель усилителя (упрощённо)
        power_elec = self.engine.amp**2 / 8.0  # Примерная мощность (зависит от импеданса)
        heat_gen = power_elec * (1 - 0.95)      # 5% потерь
        self.amp_temp += (heat_gen - self.cooling_power * 10) * self.dt_sim * 0.1

        # 5. Обновление тока и напряжения
        self.sensors['current'] = power_elec / self.sensors['voltage'] if self.sensors['voltage'] > 0 else 0

        # 6. Эмуляция вибраций (от тяги)
        self.sensors['vibration'] = 0.01 * abs(thrust) + 0.001 * random.gauss(0, 1)

# --- FUNC: _update_sensors ---
def _update_sensors(self):
        # Давление в камере (пропорционально амплитуде)
        base_pressure = self.engine.amp
        self.sensors['pressure'] = base_pressure * (1 + self.noise_level * random.gauss(0, 1))

        # Фаза давления (от резонатора)
        if self.res and self.res.E_res:
            self.sensors['phase'] = self.res.E_res[0].phase
        else:
            self.sensors['phase'] = self.engine.phi

        # Температура резонатора (зависит от мощности)
        self.sensors['temp_res'] = 25.0 + 0.001 * (self.engine.amp**2)

        # Напряжение питания (с небольшими пульсациями)
        self.sensors['voltage'] = 200.0 + 5 * random.gauss(0, 0.02)

        # Ток уже обновлён в _physics_step
        self.sensors['temp_amp'] = self.amp_temp

# --- FUNC: _control_step ---
def _control_step(self):
        if self.mode == 1:  # ПИД-регулятор
            # Измерение фактического ускорения (можно получить от акселерометра, но у нас есть точное)
            actual_accel = (self.v - self._prev_v) / self.dt_ctrl if hasattr(self, '_prev_v') else 0
            self._prev_v = self.v

            # Вычисляем новое beta через ПИД
            beta_cmd = self.pid.update(self.target_accel, actual_accel)  # в PID мы используем target_accel как setpoint
            # Ограничиваем beta в [0, 0.8]
            beta_cmd = np.clip(beta_cmd, 0, 0.8)
            self.engine.beta = beta_cmd

            # PLL – подстройка частоты (если нужно)
            if self.res and self.res.E_res:
                measured_phase = self.res.E_res[0].phase
                target_phase = 2 * np.pi * self.engine.f * self.t
                freq_corr = self.pll.update(measured_phase, target_phase, self.dt_ctrl)
                self.engine.f += freq_corr
                self.engine.f = np.clip(self.engine.f, 20, 20000)

        elif self.mode == 2:  # Оптимизация (только внешняя, здесь не реализована)
            pass

# --- FUNC: _process_command ---
def _process_command(self, cmd):
        if cmd['type'] == 'set_params':
            self.engine.set_params(
                cmd.get('f', self.engine.f),
                cmd.get('amp', self.engine.amp),
                cmd.get('phi', 0),
                cmd.get('mf', self.engine.mf),
                cmd.get('beta', self.engine.beta),
                cmd.get('profile', self.engine.profile)
            )
        elif cmd['type'] == 'set_target_accel':
            self.target_accel = cmd['value']
        elif cmd['type'] == 'set_mode':
            self.mode = cmd['mode']
        elif cmd['type'] == 'set_cooling':
            self.cooling_power = cmd['value']

# --- FUNC: _get_telemetry ---
def _get_telemetry(self):
        return {
            'time': self.t,
            'position': self.x,
            'velocity': self.v,
            'thrust': self.engine.thrust_inst(
                self.engine.f, self.engine.amp, self.engine.phi,
                self.engine.mf, self.engine.beta,
                self.engine.profile, self.t, self.x
            ),
            'freq': self.engine.f,
            'amp': self.engine.amp,
            'beta': self.engine.beta,
            'mf': self.engine.mf,
            'pressure': self.sensors['pressure'],
            'temp_amp': self.sensors['temp_amp'],
            'temp_res': self.sensors['temp_res'],
            'current': self.sensors['current'],
            'voltage': self.sensors['voltage'],
            'vibration': self.sensors['vibration'],
            'phase': self.sensors['phase'],
            'mode': self.mode,
            'target_accel': self.target_accel,
        }

# --- FUNC: send_command ---
def send_command(self, left_speed: float, right_speed: float):
        """Отправляет команды роботу."""
        payload = {'left': left_speed, 'right': right_speed}
        try:
            resp = self.session.post(f'{self.base_url}/move', json=payload, timeout=0.1)
            return resp.json()
        except Exception as e:
            print(f"Ошибка отправки команды: {e}")
            return {}

# --- FUNC: get_telemetry ---
def get_telemetry(self, block=True, timeout=0.1):
        try:
            return self.telemetry_queue.get(block=block, timeout=timeout)
        except queue.Empty:
            return None

# --- FUNC: stop ---
def stop(self):
        self.running = False
        if self.sim_thread.is_alive():
            self.sim_thread.join()

# --- FUNC: log_data ---
def log_data(self, filename='test_bench_log.csv'):
        """Запускает поток записи телеметрии в CSV."""
        import csv
        import threading
        def _logger():
            with open(filename, 'w', newline='') as f:
                writer = None
                while self.running:
                    t = self.get_telemetry(block=True, timeout=0.5)
                    if t is not None:
                        if writer is None:
                            writer = csv.DictWriter(f, fieldnames=t.keys())
                            writer.writeheader()
                        writer.writerow(t)
                        f.flush()
        threading.Thread(target=_logger, daemon=True).start()

# --- FUNC: plot_live ---
def plot_live(self):
        """Запускает интерактивный график в реальном времени (matplotlib)."""
        import matplotlib.pyplot as plt
        from matplotlib.animation import FuncAnimation

        fig, axs = plt.subplots(3, 2, figsize=(12, 8))
        fig.suptitle('Виртуальный стенд – телеметрия')

        # Списки для данных
        times = []
        positions = []
        velocities = []
        thrusts = []
        freqs = []
        betas = []
        pressures = []
        temps = []

        def update(frame):
            t = self.get_telemetry(block=False)
            if t is not None:
                times.append(t['time'])
                positions.append(t['position'])
                velocities.append(t['velocity'])
                thrusts.append(t['thrust'])
                freqs.append(t['freq'])
                betas.append(t['beta'])
                pressures.append(t['pressure'])
                temps.append(t['temp_amp'])

            # Очистка старых данных для производительности
            if len(times) > 200:
                times.pop(0); positions.pop(0); velocities.pop(0); thrusts.pop(0)
                freqs.pop(0); betas.pop(0); pressures.pop(0); temps.pop(0)

            axs[0,0].cla(); axs[0,0].plot(times, positions, color='blue'); axs[0,0].set_ylabel('Позиция (м)')
            axs[0,1].cla(); axs[0,1].plot(times, velocities, color='orange'); axs[0,1].set_ylabel('Скорость (м/с)')
            axs[1,0].cla(); axs[1,0].plot(times, thrusts, color='red'); axs[1,0].set_ylabel('Тяга (Н)')
            axs[1,1].cla(); axs[1,1].plot(times, freqs, color='green'); axs[1,1].set_ylabel('Частота (Гц)')
            axs[2,0].cla(); axs[2,0].plot(times, betas, color='purple'); axs[2,0].set_ylabel('β')
            axs[2,1].cla(); axs[2,1].plot(times, pressures, color='brown'); axs[2,1].set_ylabel('Давление (Па)')
            # Температуру можно добавить в отдельный график, но здесь ограничено.

            plt.tight_layout()
            return axs.flatten()

        ani = FuncAnimation(fig, update, interval=int(self.dt_ctrl * 1000), blit=False)
        plt.show()
        return ani

# --- FUNC: update ---
def update(frame):
            tick = rel_time.tick()
            dt = rel_time.get_dt()
            if dt is not None and dt > 0:
                curv_avg = np.mean(self.metric.field)
                curvature_factor = 1.0 / (1.0 + metric_strength * curv_avg)
                dt = dt * curvature_factor

                self.update_metric(dt)

                for e in self.E_resonators + self.B_resonators:
                    curv_local = self._get_curvature_at(e.x, e.y)
                    e.apply_redshift(curv_local, strength=metric_strength)

                for e in self.E_resonators:
                    for b in self.B_resonators:
                        phase_shift = metric_strength * curv_avg * dt
                        e.phase += phase_shift
                        b.phase += phase_shift
                        delta_phase = e.phase - b.phase
                        transfer = coupling * np.sin(delta_phase) * dt
                        e_energy = e.amp**2
                        b_energy = b.amp**2
                        if e_energy > 0 and b_energy > 0:
                            e.amp = np.sqrt(max(0, e_energy - transfer))
                            b.amp = np.sqrt(max(0, b_energy + transfer))
                        elif e_energy > 0 and b_energy == 0:
                            b.amp = np.sqrt(e_energy)
                            e.amp = 0
                        elif b_energy > 0 and e_energy == 0:
                            e.amp = np.sqrt(b_energy)
                            b.amp = 0
                        e.tick(dt)
                        b.tick(dt)

                if entanglement_strength > 0:
                    all_res = self.E_resonators + self.B_resonators
                    for i in range(len(all_res)):
                        for j in range(i+1, len(all_res)):
                            r1, r2 = all_res[i], all_res[j]
                            dist = np.hypot(r1.x - r2.x, r1.y - r2.y)
                            if dist < 0.5:
                                avg_phase = (r1.phase + r2.phase) / 2
                                r1.phase += entanglement_strength * (avg_phase - r1.phase) * dt
                                r2.phase += entanglement_strength * (avg_phase - r2.phase) * dt

                self._update_field_from_EM()

            im_psi.set_array(np.abs(self.psi).T if self.psi is not None else np.zeros((self.N,self.N)))
            im_metric.set_array(self.metric.field)

            c_map = np.zeros((self.N, self.N))
            for i in range(self.N):
                for j in range(self.N):
                    c_vals = []
                    for e in self.E_resonators + self.B_resonators:
                        dist = np.hypot(self.X[i,j] - e.x, self.Y[i,j] - e.y)
                        if dist < 2.0:
                            c_vals.append(e.get_c() * np.exp(-dist**2 / 0.5))
                    c_map[i,j] = np.mean(c_vals) if c_vals else 1.0
            im_c.set_array(c_map)

            f_map = np.zeros((self.N, self.N))
            for i in range(self.N):
                for j in range(self.N):
                    f_vals = []
                    for e in self.E_resonators + self.B_resonators:
                        dist = np.hypot(self.X[i,j] - e.x, self.Y[i,j] - e.y)
                        if dist < 2.0:
                            f_vals.append(e.freq * np.exp(-dist**2 / 0.5))
                    f_map[i,j] = np.mean(f_vals) if f_vals else 0
            im_freq.set_array(f_map)

            status_text.set_text(f'Шаг {frame+1}/{steps}, тиков: {rel_time.ticks:.2f}, dt: {dt:.4f}' if dt else 'Время застыло')
            return im_psi, im_metric, im_c, im_freq, status_text

