# --- FUNC: ExchangeData ---
def ExchangeData(self, request, context):
        with open("/proc/1c_data", "w") as f:
            f.write(request.payload)
        return linux_kernel_pb2.Response(status="OK")

# --- FUNC: handle_1c_request ---
def handle_1c_request():
    # Конвертация SOAP -> Protobuf
    soap_data = request.data
    pb_request = convert_soap_to_protobuf(soap_data)
    
    # gRPC вызов к ядру
    channel = grpc.insecure_channel('localhost:50051')
    stub = soap_to_protobuf_pb2_grpc.FormulaStub(channel)
    response = stub.ProcessData(pb_request)
    
    # Конвертация Protobuf -> JSON для 1С
    return json.dumps({
        "result": response.value,
        "status": "OK"
    })

# --- FUNC: convert_soap_to_protobuf ---
def convert_soap_to_protobuf(soap: str) -> soap_to_protobuf_pb2.InputData:
    # Упрощенная конвертация (реализация зависит от структуры SOAP)
    return soap_to_protobuf_pb2.InputData(
        timestamp=int(time.time()),
        payload=soap.encode('utf-8')
    )

