# --- FUNC: on_message ---
def on_message(ws, message):
            try:
                data = json.loads(message)
                # Ожидаем, что приходят списки событий или одно событие
                if isinstance(data, list):
                    events = data
                else:
                    events = [data]
                # Преобразуем в единый формат
                parsed = []
                for ev in events:
                    if 'time' in ev and 'magnitude' in ev:
                        parsed.append(ev)
                if parsed and self.callback:
                    self.callback(parsed)
            except Exception as e:
                print(f"WS parse error: {e}")

# --- FUNC: get_events ---
def get_events(self, start_time: str, end_time: str, 
                   min_magnitude: float = 2.5, max_events: int = 1000) -> List[Dict]:
        params = {
            'format': 'geojson',
            'starttime': start_time,
            'endtime': end_time,
            'minmagnitude': min_magnitude,
            'limit': max_events
        }
        try:
            resp = requests.get(self.url, params=params, timeout=30)
            data = resp.json()
            events = []
            for feat in data.get('features', []):
                props = feat['properties']
                geom = feat['geometry']['coordinates']
                events.append({
                    'id': props.get('id', ''),
                    'time': props.get('time', 0),
                    'magnitude': props.get('mag', 0),
                    'latitude': geom[1],
                    'longitude': geom[0],
                    'depth_km': geom[2],
                    'place': props.get('place', ''),
                    'felt': props.get('felt', 0)
                })
            return events
        except Exception as e:
            print(f"USGS API error: {e}")
            return []

# --- FUNC: start_streaming ---
def start_streaming(self, callback: Callable[[List[Dict]], None]):
        """Запускает поток-демон для приёма сообщений."""
        if self.running:
            return
        self.callback = callback
        self.running = True
        
        def on_message(ws, message):
            try:
                data = json.loads(message)
                # Ожидаем, что приходят списки событий или одно событие
                if isinstance(data, list):
                    events = data
                else:
                    events = [data]
                # Преобразуем в единый формат
                parsed = []
                for ev in events:
                    if 'time' in ev and 'magnitude' in ev:
                        parsed.append(ev)
                if parsed and self.callback:
                    self.callback(parsed)
            except Exception as e:
                print(f"WS parse error: {e}")
        
        def on_error(ws, error):
            print(f"WS error: {error}")
        
        def on_close(ws, close_status_code, close_msg):
            self.running = False
            print("WS connection closed")
        
        def run():
            self.ws = websocket.WebSocketApp(
                self.ws_url,
                on_message=on_message,
                on_error=on_error,
                on_close=on_close
            )
            self.ws.run_forever()
        
        self.thread = threading.Thread(target=run, daemon=True)
        self.thread.start()
        print(f"WebSocket подключён к {self.ws_url}")

# --- FUNC: stop_streaming ---
def stop_streaming(self):
        self.running = False
        if self.ws:
            self.ws.close()
        if self.thread:
            self.thread.join(timeout=1)

