# --- FUNC: reset ---
def reset(self):
        # Случайное начальное положение дрона
        self.drone_pos = np.random.uniform(-self.domain_size/2+5, self.domain_size/2-5, size=3)
        # Направление движения: случайный вектор
        angle_h = np.random.uniform(0, 2*np.pi)
        angle_v = np.random.uniform(-np.pi/4, np.pi/4)
        self.drone_vel = self.target_speed * np.array([
            np.cos(angle_h)*np.cos(angle_v),
            np.sin(angle_h)*np.cos(angle_v),
            np.sin(angle_v)
        ])
        self.phases = np.random.uniform(0, 2*np.pi, size=self.n_antennas).astype(np.float32)
        self.antenna_field.set_phases(self.phases)
        self.steps = 0
        self.done = False
        return self._get_state()

# --- FUNC: _get_state ---
def _get_state(self):
        # Состояние: позиция дрона + текущие фазы
        return np.concatenate([self.drone_pos, self.phases]).astype(np.float32)

# --- FUNC: _add_puff ---
def _add_puff(self, x, y, mass, t):
        # Добавляем пуфф в момент времени t (относительно текущего времени)
        # Для простоты: считаем, что распыление происходит мгновенно, и концентрация добавляется по гауссу.
        # Но в реальности пуфф дрейфует и расширяется. Мы будем обновлять концентрацию на каждом шаге, храня список пуффов.
        # Для упрощения пока используем мгновенное добавление (без динамики) – потом улучшим.
        # Вместо этого реализуем динамику через метод step, обновляя все пуффы.
        pass

# --- FUNC: _advect_diffuse ---
def _advect_diffuse(self, conc, dt):
        # Очень упрощённая эволюция: сдвиг с ветром и диффузия (простое размытие)
        # Для реальной симуляции нужен список пуффов. Пока заглушка.
        # Сдвиг:
        shift_pixels = self.u_wind * dt / self.cell_size
        # ... реализация сдвига (с помощью scipy.ndimage.shift)
        # Диффузия: гауссово размытие
        from scipy.ndimage import gaussian_filter
        conc = gaussian_filter(conc, sigma=np.sqrt(2*self.D*dt)/self.cell_size)
        return conc

# --- FUNC: _add_instant_cloud ---
def _add_instant_cloud(self, x, y, mass):
        # Добавляем гауссово облако в клетку (x,y)
        ix = int((x + self.world_size/2) / self.cell_size)
        iy = int((y + self.world_size/2) / self.cell_size)
        if 0 <= ix < self.grid_size and 0 <= iy < self.grid_size:
            # Просто увеличиваем концентрацию в клетке
            self.concentration[iy, ix] += mass / (self.cell_size**2)

# --- FUNC: _check_capture ---
def _check_capture(self):
        # Цель в (0,0) в высотном интервале [0, capture_height]
        # Находим индексы клеток, попадающих в куб вокруг цели
        x_idx = int((0 + self.world_size/2) // self.dx)
        y_idx = int((0 + self.world_size/2) // self.dy)
        z_max_idx = int(self.capture_height // self.dz)
        # Проверяем концентрацию в этих клетках
        for iz in range(z_max_idx+1):
            if self.concentration[iz, y_idx, x_idx] > self.capture_thresh:
                return True
        return False

# --- FUNC: render ---
def render(self, mode='human'):
        # Визуализация с mayavi
        mlab.figure(size=(800,600), bgcolor=(0,0,0))
        # Изоповерхность плотности (например, 0.5*max)
        max_rho = np.max(self.rho)
        if max_rho > 0:
            mlab.contour3d(self.x, self.y, self.z, self.rho,
                           contours=[0.3*max_rho], opacity=0.4, color=(1,0.5,0))
        # Антенны
        for pos in self.antenna_positions:
            mlab.points3d(pos[0], pos[1], pos[2], scale_factor=2, color=(0,1,0))
        # Дрон
        mlab.points3d(self.drone_pos[0], self.drone_pos[1], self.drone_pos[2],
                      scale_factor=1.5, color=(1,0,0), opacity=0.8)
        mlab.show()

# --- FUNC: compute_field ---
def compute_field(self, X, Y, Z):
        """
        Вычисляет комплексное поле E в точках сетки (X,Y,Z).
        X,Y,Z - meshgrid (3D массивы).
        Возвращает комплексный массив E той же формы.
        """
        E = np.zeros_like(X, dtype=np.complex64)
        for i in range(self.N):
            # Вектор от антенны к точке
            rx = X - self.positions[i,0]
            ry = Y - self.positions[i,1]
            rz = Z - self.positions[i,2]
            r = np.sqrt(rx**2 + ry**2 + rz**2)
            r = np.maximum(r, 0.5)  # избегаем сингулярности
            # Направление от антенны к точке (для каждой точки)
            dir_x = rx / r
            dir_y = ry / r
            dir_z = rz / r
            # Формируем массив векторов (...,3)
            r_vec = np.stack([dir_x, dir_y, dir_z], axis=-1)
            # Направление луча для этой антенны (широковещательно)
            beam_dir = self.directions[i][None, None, None, :]
            pattern = self._pattern(r_vec, beam_dir)
            # Вклад антенны
            Ei = self.amplitudes[i] * pattern / r * np.exp(1j * self.phases[i])
            E += Ei
        return E

# --- FUNC: potential ---
def potential(x, y, t):
    r2 = x*x + y*y
    if r2 > R*R:
        return 0
    r = np.sqrt(r2)
    # Угловая модуляция от Χ
    theta = np.arctan2(y, x)
    chi = chi_factor * np.cos(2*theta)   # крестовая зависимость
    # Временная модуляция от Τ
    tau_mod = np.sin(omega_T * t + chi)
    return Phi0 * np.exp(-r2/R**2) * tau_mod

# --- FUNC: lcg ---
def lcg(seed, a=1664525, c=1013904223, m=2**32):
    while True:
        seed = (a * seed + c) % m
        yield seed / m

# --- FUNC: _compute_concentration ---
def _compute_concentration(self):
        # Создаём пустой тензор
        conc = np.zeros((self.nx, self.ny, self.nz), dtype=np.float32)
        # Координаты центров клеток для быстрого доступа
        x_centers = (np.arange(self.nx) - self.nx//2) * self.dx
        y_centers = (np.arange(self.ny) - self.ny//2) * self.dy
        z_centers = np.arange(self.nz) * self.dz + self.dz/2
        # Предвычисляем meshgrid для ускорения (но будем итерировать по пуффам)
        for puff in self.puffs:
            age = self.time - puff.t0
            if age <= 0:
                continue
            # Параметры распределения
            sigma_h = np.sqrt(2 * self.Dh * age)
            sigma_z = np.sqrt(2 * self.Dv * age)
            # Центр пуффа
            xc = puff.x0 + self.wind[0] * age
            yc = puff.y0 + self.wind[1] * age
            zc = puff.z0 - self.ws * age
            # Определяем границы влияния (3 sigma)
            h_range = 3 * sigma_h
            z_range = 3 * sigma_z
            # Индексы клеток, попадающих в диапазон
            ix_min = max(0, int((xc - h_range + self.world_size/2) // self.dx))
            ix_max = min(self.nx-1, int((xc + h_range + self.world_size/2) // self.dx))
            iy_min = max(0, int((yc - h_range + self.world_size/2) // self.dy))
            iy_max = min(self.ny-1, int((yc + h_range + self.world_size/2) // self.dy))
            iz_min = max(0, int((zc - z_range) // self.dz))
            iz_max = min(self.nz-1, int((zc + z_range) // self.dz))

            # Предвычисляем нормализацию
            norm = puff.mass / ((2*np.pi)**1.5 * sigma_h**2 * sigma_z)

            for ix in range(ix_min, ix_max+1):
                xcell = x_centers[ix]
                dx2 = (xcell - xc)**2
                for iy in range(iy_min, iy_max+1):
                    ycell = y_centers[iy]
                    dy2 = (ycell - yc)**2
                    r2_h = dx2 + dy2
                    if r2_h > (3*sigma_h)**2:
                        continue
                    for iz in range(iz_min, iz_max+1):
                        zcell = z_centers[iz]
                        dz2 = (zcell - zc)**2
                        if dz2 > (3*sigma_z)**2:
                            continue
                        conc[iz, iy, ix] += norm * np.exp(-r2_h/(2*sigma_h**2) - dz2/(2*sigma_z**2))
        return conc

# --- FUNC: extract_features ---
def extract_features(self, audio_data):
        """
        Извлекает признаки из аудиосигнала (MFCC, спектральный центроид, полоса пропускания).
        """
        # MFCC
        mfcc = librosa.feature.mfcc(y=audio_data, sr=self.sample_rate,
                                    n_mfcc=self.n_mfcc, n_fft=self.n_fft,
                                    hop_length=self.hop_length)
        mfcc_mean = np.mean(mfcc, axis=1)
        mfcc_std = np.std(mfcc, axis=1)
        # Спектральный центроид
        centroid = librosa.feature.spectral_centroid(y=audio_data, sr=self.sample_rate,
                                                     n_fft=self.n_fft, hop_length=self.hop_length)
        centroid_mean = np.mean(centroid)
        centroid_std = np.std(centroid)
        # Полоса пропускания
        bandwidth = librosa.feature.spectral_bandwidth(y=audio_data, sr=self.sample_rate,
                                                       n_fft=self.n_fft, hop_length=self.hop_length)
        bandwidth_mean = np.mean(bandwidth)
        bandwidth_std = np.std(bandwidth)
        # Объединение в вектор признаков
        features = np.concatenate([mfcc_mean, mfcc_std,
                                   [centroid_mean, centroid_std],
                                   [bandwidth_mean, bandwidth_std]])
        return features

# --- FUNC: add_sample ---
def add_sample(self, audio_chunk, label):
        features = self.extract_features(audio_chunk)
        self.feature_buffer.append(features)
        self.label_buffer.append(label)

# --- FUNC: _pattern ---
def _pattern(self, r_vecs, dirs):
        """
        Вычисляет значение диаграммы направленности для каждого вектора r_vecs
        относительно соответствующих направлений dirs.
        r_vecs: (...,3) массив векторов от антенны к точке
        dirs: (...,3) массив направлений лучей (широковещательно совместим)
        Возвращает массив pattern той же формы, что и r_vecs[...,0]
        """
        # Вычисляем косинус угла между r_vec и dir
        # Нормализуем r_vecs
        r_norm = np.linalg.norm(r_vecs, axis=-1, keepdims=True)
        # Избегаем деления на ноль
        r_norm = np.maximum(r_norm, 1e-8)
        unit_r = r_vecs / r_norm
        cos_theta = np.sum(unit_r * dirs, axis=-1)
        cos_theta = np.clip(cos_theta, -1, 1)
        theta = np.arccos(cos_theta)
        # Гауссов луч
        pattern = np.exp(-(theta**2) / (2 * self.beamwidth**2))
        return pattern

# --- FUNC: set_phases ---
def set_phases(self, phases):
        """Установить новые фазы"""
        self.phases = np.asarray(phases, dtype=np.float32)

# --- FUNC: set_amplitudes ---
def set_amplitudes(self, amplitudes):
        self.amplitudes = np.asarray(amplitudes, dtype=np.float32)

# --- FUNC: set_directions ---
def set_directions(self, directions):
        self.directions = np.asarray(directions, dtype=np.float32)
        norms = np.linalg.norm(self.directions, axis=1, keepdims=True)
        self.directions = self.directions / norms

# --- FUNC: create_lstm_data ---
def create_lstm_data(data, window_size):
    X_lstm, y_lstm = [], []
    for i in range(window_size, len(data)):
        X_lstm.append(data[i-window_size:i])
        y_lstm.append(data[i])
    return np.array(X_lstm), np.array(y_lstm)

# --- FUNC: forward ---
def forward(self, x):
        # Пропускаем через основную модель
        detections = self.original(x)   # [batch, N, 5+num_classes]
        # Извлекаем координаты bbox
        boxes = detections[:, :, :4]
        scores = detections[:, :, 4]
        class_probs = detections[:, :, 5:]

        # В реальности нужно получить маску гражданских зон (отдельная сеть или слой)
        # Упростим: для каждого bbox вычисляем «индекс риска» через этический вектор
        risk_factor = torch.sigmoid(torch.dot(self.ethical_vector, boxes.mean(dim=1)))   # абстрактно
        # Снижаем уверенность там, где риск высок
        scores = scores * (1 - 0.8 * risk_factor)
        return torch.cat([boxes, scores.unsqueeze(-1), class_probs], dim=-1)

# --- FUNC: _compute_spectrogram ---
def _compute_spectrogram(self, iq_samples, fs=2e6, nperseg=256):
        """Преобразует I/Q данные в спектрограмму (логарифмическую)"""
        f, t, Sxx = spectrogram(iq_samples, fs=fs, nperseg=nperseg, return_onesided=False)
        Sxx_log = 10 * np.log10(np.abs(Sxx) + 1e-12)
        # Нормализация к [0,1]
        Sxx_norm = (Sxx_log - Sxx_log.min()) / (Sxx_log.max() - Sxx_log.min())
        # Превращаем в 3D тензор (1, height, width) для Conv2d
        return torch.tensor(Sxx_norm, dtype=torch.float32).unsqueeze(0)

# --- FUNC: _compute_cwd ---
def _compute_cwd(self, iq_samples):
        """Упрощённая версия CWD (псевдо-код, нужна реализация)"""
        # Здесь должна быть реализация Choi-Williams distribution
        # Для демонстрации используем спектрограмму
        return self._compute_spectrogram(iq_samples)

# --- FUNC: preprocess ---
def preprocess(self, iq_samples):
        if self.tfa_type == 'spectrogram':
            img = self._compute_spectrogram(iq_samples)
        elif self.tfa_type == 'cwd':
            img = self._compute_cwd(iq_samples)
        else:
            raise ValueError("Unsupported TFA type")
        # Добавляем размерность канала (1, H, W) -> (1, 1, H, W)
        return img.unsqueeze(0).to(self.device)

# --- FUNC: visualize_3d ---
def visualize_3d(self, iq_samples):
        """Создаёт 3D-визуализацию частотно-временной плоскости с наложением результата"""
        # Вычисляем спектрограмму для визуализации
        f, t, Sxx = spectrogram(iq_samples, fs=2e6, nperseg=256)
        Sxx_db = 10 * np.log10(np.abs(Sxx) + 1e-12)
        # Создаём meshgrid
        T, F = np.meshgrid(t, f)
        # Используем mayavi для поверхности
        mlab.figure(size=(800,600), bgcolor=(0,0,0))
        mlab.surf(T, F, Sxx_db, colormap='viridis', warp_scale='auto')
        mlab.title('3D Time-Frequency Representation')
        mlab.show()

# --- FUNC: load_dataset ---
def load_dataset(data_dir, labels_file):
    """
    Загружает аудиофайлы из data_dir и метки из labels_file.
    labels_file: CSV с колонками 'filename', 'label'
    """
    df = pd.read_csv(labels_file)
    X = []
    y = []
    analyzer = AcousticSignatureAnalyzer()  # для извлечения признаков
    for idx, row in df.iterrows():
        filepath = os.path.join(data_dir, row['filename'])
        try:
            audio, sr = librosa.load(filepath, sr=analyzer.sample_rate)
            features = analyzer.extract_features(audio)
            X.append(features)
            y.append(row['label'])
        except Exception as e:
            print(f"Ошибка загрузки {filepath}: {e}")
    return np.array(X), np.array(y)

# --- FUNC: train_classifier ---
def train_classifier(X, y):
    """
    Обучает классификатор на признаках X и метках y.
    Возвращает обученный классификатор, скейлер и энкодер меток.
    """
    # Кодируем метки
    le = LabelEncoder()
    y_encoded = le.fit_transform(y)
    # Масштабируем признаки
    scaler = StandardScaler()
    X_scaled = scaler.fit_transform(X)
    # Разделяем на обучающую и тестовую выборки
    X_train, X_test, y_train, y_test = train_test_split(X_scaled, y_encoded, test_size=0.2, random_state=42)
    # Обучаем классификатор
    clf = RandomForestClassifier(n_estimators=100, random_state=42)
    clf.fit(X_train, y_train)
    # Оценка
    y_pred = clf.predict(X_test)
    print("Classification Report:")
    print(classification_report(y_test, y_pred, target_names=le.classes_))
    return clf, scaler, le

# --- FUNC: visualize_field ---
def visualize_field(env, model, steps=500):
    """Визуализация траектории и поля в реальном времени"""
    fig = plt.figure(figsize=(12, 8))
    ax = fig.add_subplot(111, projection='3d')
    ax.set_xlim(-10, 10)
    ax.set_ylim(-10, 10)
    ax.set_zlim(-5, 5)
    ax.set_xlabel('X')
    ax.set_ylabel('Y')
    ax.set_zlabel('Z')
    ax.set_title('Дрон и подвижные источники (обученный агент)')

    # Инициализация
    obs = env.reset()
    drone_traj = [obs[:3].copy()]
    source_positions = [obs[6:].reshape(env.N_sources, 3).copy()]

    # Элементы графика
    drone_line, = ax.plot([], [], [], 'b-', linewidth=1.5, label='Дрон')
    drone_point = ax.scatter([], [], [], c='blue', s=30)
    source_lines = [ax.plot([], [], [], 'g--', linewidth=1)[0] for _ in range(env.N_sources)]
    source_points = [ax.scatter([], [], [], c='green', s=50) for _ in range(env.N_sources)]
    target_point = ax.scatter([0,0,0], c='red', s=80, label='Цель')
    ax.legend()

    def update(frame):
        nonlocal obs
        # Получить действие от модели
        action, _ = model.predict(obs, deterministic=True)
        obs, reward, done, _ = env.step(action)
        # Сохранить траекторию
        drone_traj.append(obs[:3].copy())
        src_pos = obs[6:].reshape(env.N_sources, 3)
        source_positions.append(src_pos.copy())

        # Обновить траекторию дрона
        drone_traj_arr = np.array(drone_traj)
        drone_line.set_data(drone_traj_arr[:,0], drone_traj_arr[:,1])
        drone_line.set_3d_properties(drone_traj_arr[:,2])
        drone_point._offsets3d = (drone_traj_arr[-1:,0], drone_traj_arr[-1:,1], drone_traj_arr[-1:,2])

        # Обновить источники
        for i, (line, point) in enumerate(zip(source_lines, source_points)):
            traj_i = np.array([pos[i] for pos in source_positions])
            line.set_data(traj_i[:,0], traj_i[:,1])
            line.set_3d_properties(traj_i[:,2])
            point._offsets3d = (traj_i[-1:,0], traj_i[-1:,1], traj_i[-1:,2])

        # Опционально: отобразить изоповерхность поля (трудоёмко, можно раз в несколько кадров)
        # if frame % 50 == 0:
        #     plot_potential_surface(ax, env, obs[6:].reshape(env.N_sources,3), env.source_params)

        ax.set_title(f'Шаг {frame}, расстояние до цели: {np.linalg.norm(obs[:3]):.2f}')
        return [drone_line, drone_point] + source_lines + source_points

    ani = animation.FuncAnimation(fig, update, frames=steps, interval=50, blit=False)
    plt.show()

# --- FUNC: update_acoustic ---
def update_acoustic(n):
    # Получить аудиочанк из буфера
    audio_chunk = get_latest_audio()  # функция-заглушка
    # Классифицировать
    label, conf = shield.process_audio_stream(audio_chunk)
    # Построить спектрограмму
    fig = go.Figure(data=go.Heatmap(z=librosa.stft(audio_chunk), colorscale='Viridis'))
    return fig, f"Обнаружен: {label} (уверенность: {conf:.2f})"

# --- FUNC: generate_fonon_hypotheses ---
def generate_fonon_hypotheses(self, drone_type):
        """
        Генерирует гипотезы о резонансных частотах на основе
        спектральных данных и констант.
        """
        # Получаем спектр дрона (из акустического модуля)
        spectrum = self.shield.acoustic.get_spectrum(drone_type)
        # Ищем пики
        peaks = self._find_peaks(spectrum)
        # Формируем гипотезы: частоты пиков * φ, * √5, * γ/Λ
        hypotheses = []
        for p in peaks[:3]:
            for factor in [self.phi, self.sqrt5, self.gamma/self.Lambda]:
                freq = p * factor
                hypotheses.append({
                    'type': 'resonance',
                    'frequency': freq,
                    'drone_type': drone_type,
                    'confidence': 0.7,
                    'basis': 'spectral_peak'
                })
        return hypotheses

# --- FUNC: field ---
def field(self, X, Y, Z):
        # X,Y,Z — meshgrid массивы
        # возвращает комплексное поле E (такой же формы)
        dx = X - self.position[0]
        dy = Y - self.position[1]
        dz = Z - self.position[2]
        r = np.sqrt(dx**2 + dy**2 + dz**2)
        r = np.maximum(r, 0.5)   # защита от деления на 0
        # угол между направлением и вектором к точке
        dot = (dx*self.direction[0] + dy*self.direction[1] + dz*self.direction[2]) / r
        dot = np.clip(dot, -1, 1)
        theta = np.arccos(dot)
        # гауссова диаграмма
        pattern = np.exp(- (theta**2) / (2 * self.sigma_beam**2))
        E = self.amplitude * pattern / r * np.exp(1j * self.phase)
        return E

# --- FUNC: resonance ---
def resonance(self):
        # Формула из третьей части (исправленная)
        a = self.n1729 / self.base / self.phi  # примерно 16.8
        b = self.n1729 / self.base / self.pi   # примерно 8.6
        return (a * self.phi + b * self.pi) / self.dim * self.base

# --- FUNC: spiral_length ---
def spiral_length(self):
        return self.n1729 * self.phi / 1000

# --- FUNC: torus_radius ---
def torus_radius(self):
        return self.n1729 / self.pi / 100

# --- FUNC: __str__ ---
def __str__(self):
        return f"""
🌌 ABSOLUTE ЯДРО v4.0 🌌
Печать: {self.seal}
Резонаторов: {len(self.E_resonators)+len(self.B_resonators)}
Артефактов: {len(self.artifacts)}
Тиков времени: {self.time_ticks}
Средняя любовь: {np.mean(self.love_field):.3f}
Средняя кривизна: {np.mean(self.metric.field):.3f}
Когерентность: {self._compute_coherence():.3f}
"""

# --- FUNC: get_drone_positions ---
def get_drone_positions(self):
        # Извлекаем данные из shield
        if hasattr(self.shield, 'drone_tracks'):
            return self.shield.drone_tracks
        return []

