# --- FUNC: _compute_potential ---
def _compute_potential(self):
    antennas = []
    for i, pos in enumerate(self.antenna_positions):
        # направление луча – на центр области (0,0,0) или другое
        direction = -pos / np.linalg.norm(pos)   # смотреть к центру
        antennas.append(Antenna(pos, amplitude=self.amplitudes[i],
                                phase=self.phases[i], direction=direction,
                                beam_width=np.pi/4))   # 45 градусов
    field = AntennaField(antennas)
    return field.potential(self.X, self.Y, self.Z)

# --- FUNC: _compute_positions ---
def _compute_positions(self):
        x = np.linspace(-(self.nx-1)/2 * self.d, (self.nx-1)/2 * self.d, self.nx)
        y = np.linspace(-(self.ny-1)/2 * self.d, (self.ny-1)/2 * self.d, self.ny)
        xx, yy = np.meshgrid(x, y)
        return np.stack([xx.flatten(), yy.flatten(), np.zeros(self.nx*self.ny)], axis=1)

# --- FUNC: steering_vector ---
def steering_vector(self, theta, phi):
        # theta - угол места, phi - азимут
        k = 2 * np.pi / self.wavelength
        u = np.sin(theta) * np.cos(phi)
        v = np.sin(theta) * np.sin(phi)
        w = np.cos(theta)
        dir_vec = np.array([u, v, w])
        phase = k * np.dot(self.positions, dir_vec)
        return np.exp(1j * phase)

# --- FUNC: pattern ---
def pattern(self, theta_range, phi_range, steering_theta, steering_phi):
        sv = self.steering_vector(steering_theta, steering_phi)
        pattern = np.zeros((len(theta_range), len(phi_range)), dtype=complex)
        for i, theta in enumerate(theta_range):
            for j, phi in enumerate(phi_range):
                sv_test = self.steering_vector(theta, phi)
                pattern[i,j] = np.sum(sv.conj() * sv_test)
        return np.abs(pattern)**2

