# --- FUNC: antenna_pattern ---
def antenna_pattern(direction, r_vec, beamwidth=0.5):
    # direction: единичный вектор оси луча
    # r_vec: вектор от антенны к точке
    r_norm = np.linalg.norm(r_vec)
    if r_norm < 1e-6:
        return 0.0
    dir_point = r_vec / r_norm
    cos_theta = np.dot(direction, dir_point)
    # ограничим, чтобы не было отрицательных
    cos_theta = np.clip(cos_theta, 0, 1)
    # гауссов луч
    theta = np.arccos(cos_theta)
    return np.exp(-(theta/beamwidth)**2)

