# --- FUNC: force_from_rho ---
def force_from_rho(rho, pos):
    # интерполяция градиента
    ix = int((pos[0] - x[0]) / (x[1]-x[0]))
    iy = int((pos[1] - y[0]) / (y[1]-y[0]))
    ix = np.clip(ix, 0, nx-2)
    iy = np.clip(iy, 0, ny-2)
    grad_x = (rho[iy, ix+1] - rho[iy, ix]) / (x[1]-x[0])
    grad_y = (rho[iy+1, ix] - rho[iy, ix]) / (y[1]-y[0])
    return -np.array([grad_x, grad_y]) * 0.5

# --- FUNC: circulation_force ---
def circulation_force(pos, center, strength):
    r = pos - center
    r_norm = np.linalg.norm(r)
    if r_norm < 0.1:
        return np.zeros(2)
    # сила, перпендикулярная радиусу
    return strength / r_norm * np.array([-r[1], r[0]])

# --- FUNC: update_rho ---
def update_rho(rho, t):
    # источники создают акустическое давление: синусоидальные волны
    phase1 = 2 * np.pi * source_freq * t
    phase2 = 2 * np.pi * source_freq * t + TAU  # сдвиг TAU
    p1 = source_amplitude * np.cos(phase1) * np.exp(-((X-source1[0])**2 + (Y-source1[1])**2)/5)
    p2 = source_amplitude * np.cos(phase2) * np.exp(-((X-source2[0])**2 + (Y-source2[1])**2)/5)
    # изменение плотности пропорционально давлению
    new_rho = rho + (p1 + p2) * dt * 0.1
    # диффузия и сглаживание
    new_rho = gaussian_filter(new_rho, sigma=0.5)
    new_rho = np.clip(new_rho, 0, 2)
    return new_rho

# --- FUNC: animate ---
def animate(self, steps: int = 200, interval: int = 50):
        """
        Анимация активности нейронной сети и акустического управления.
        """
        fig, axs = plt.subplots(2, 2, figsize=(12, 8))
        # 1. Карта активности (матрица)
        im = axs[0,0].imshow(np.zeros((self.num_neurons, self.num_neurons)),
                            cmap='hot', interpolation='nearest', aspect='auto')
        axs[0,0].set_title('Синаптические веса')
        axs[0,0].set_xlabel('Постсинаптический нейрон')
        axs[0,0].set_ylabel('Пресинаптический нейрон')

        # 2. Мембранные потенциалы
        line, = axs[0,1].plot([], [], 'b-', lw=1)
        axs[0,1].set_ylim(-80, -40)
        axs[0,1].set_xlim(0, self.num_neurons)
        axs[0,1].set_title('Мембранные потенциалы')
        axs[0,1].set_xlabel('Нейрон')

        # 3. Акустические параметры
        bar = axs[1,0].bar(range(self.num_neurons), self.acoustic_strength)
        axs[1,0].set_ylim(0, 1)
        axs[1,0].set_title('Акустическая сила')
        axs[1,0].set_xlabel('Нейрон')

        # 4. Спайки в реальном времени
        spike_ax = axs[1,1]
        spike_ax.set_xlim(0, 100)
        spike_ax.set_ylim(0, self.num_neurons)
        spike_ax.set_title('Спайки')
        spike_ax.set_xlabel('Время (шаги)')
        spike_ax.set_ylabel('Нейрон')
        scatter = spike_ax.scatter([], [], s=10, c='red')

        def update(frame):
            # Обновляем состояние сети
            for _ in range(2):
                self.update()
                self.update_synaptic_weights()
                self.adapt_acoustic_parameters()
            # Обновляем карту весов
            im.set_array(self.W)
            # Обновляем потенциалы
            line.set_data(range(self.num_neurons), self.V)
            # Обновляем акустические параметры
            for i, b in enumerate(bar):
                b.set_height(self.acoustic_strength[i])
            # Обновляем спайки
            if len(self.spike_history) > 0:
                recent = list(self.spike_history)[-100:]
                times = range(len(recent))[-len(recent):]
                scatter.set_offsets(np.c_[times, recent])
            return im, line, *bar, scatter

        ani = FuncAnimation(fig, update, frames=steps, interval=interval, blit=True)
        plt.tight_layout()
        plt.show()
        return ani

# --- FUNC: retrain ---
def retrain(self):
        if len(self.buffer) < 100:
            return  # недостаточно данных
        X_buf = np.array([x for x, _ in self.buffer])
        y_buf = np.array([y for _, y in self.buffer])
        # Переобучаем RandomForest
        self.rf_model.fit(X_buf, y_buf)
        # Переобучаем LSTM (несколько эпох)
        self._retrain_lstm(X_buf, y_buf)
        print("Модели обновлены на новых данных")

# --- FUNC: _retrain_lstm ---
def _retrain_lstm(self, X, y):
        # Преобразуем в последовательности (окна)
        # Здесь нужна функция create_lstm_data
        X_lstm, y_lstm = create_lstm_data(y, window_size=10)  # используем y как последовательность
        # Нормализуем
        X_lstm_scaled = self.scaler.transform(X_lstm.reshape(-1,10)).reshape(-1,10,1)
        # Дообучаем модель (несколько эпох)
        optimizer = optim.Adam(self.lstm_model.parameters(), lr=0.0005)
        criterion = torch.nn.MSELoss()
        self.lstm_model.train()
        for epoch in range(5):
            for i in range(0, len(X_lstm_scaled), 64):
                batch_X = torch.tensor(X_lstm_scaled[i:i+64], dtype=torch.float32)
                batch_y = torch.tensor(y_lstm[i:i+64], dtype=torch.float32)
                optimizer.zero_grad()
                pred = self.lstm_model(batch_X)
                loss = criterion(pred, batch_y)
                loss.backward()
                optimizer.step()
        self.lstm_model.eval()

