# --- FUNC: load_model ---
def load_model(self, model_path):
        """Загружает обученную модель и сопутствующие компоненты."""
        data = joblib.load(model_path)
        self.classifier = data['classifier']
        self.label_encoder = data['label_encoder']
        self.feature_scaler = data['scaler']
        print(f"Модель загружена: {len(self.label_encoder.classes_)} классов")

# --- FUNC: save_model ---
def save_model(self, model_path):
        """Сохраняет модель и компоненты."""
        data = {
            'classifier': self.classifier,
            'label_encoder': self.label_encoder,
            'scaler': self.feature_scaler
        }
        joblib.dump(data, model_path)
        print(f"Модель сохранена в {model_path}")

# --- FUNC: classify_audio ---
def classify_audio(self, audio_data):
        """
        Классифицирует аудиофрагмент (один или несколько).
        Возвращает название класса и уровень уверенности.
        """
        if self.classifier is None:
            raise ValueError("Модель не загружена или не обучена")
        features = self.extract_features(audio_data)
        features_scaled = self.feature_scaler.transform([features])
        probs = self.classifier.predict_proba(features_scaled)[0]
        idx = np.argmax(probs)
        label = self.label_encoder.inverse_transform([idx])[0]
        confidence = probs[idx]
        return label, confidence

