# --- FUNC: process_frame ---
def process_frame(self, audio_chunk, ir_frame, rf_signal, seismic=None):
        """Мультисенсорный фьюжн: обнаружение + классификация + подавление"""
        # 1. Каждый сенсор делает предсказание
        audio_pred, audio_conf = self.acoustic.classify(audio_chunk)
        ir_pred, ir_conf = self.ir_processor.detect(ir_frame)
        rf_pred, rf_conf = self.rf_processor.analyze(rf_signal)

        # 2. Фьюжн (взвешенное голосование)
        final_pred, final_conf = self.sensors.fuse([
            (audio_pred, audio_conf, 'audio'),
            (ir_pred, ir_conf, 'ir'),
            (rf_pred, rf_conf, 'rf')
        ])

        # 3. Если обнаружен дрон — запускаем фононное воздействие
        if final_conf > 0.7 and audio_pred is not None:
            drone_pos = self._estimate_position(audio_chunk, rf_signal)
            drone_sig = self.acoustic.extract_signature(audio_chunk)

            # Гравитационная ловушка
            trap = self.fonon.create_gravity_trap(drone_pos)
            # Акустический резонанс
            if drone_sig:
                beam = self.fonon.resonate_drone(drone_sig)
                self.fonon.focus_beam(beam)
            # Эхо-барьер
            barrier = self.fonon.deploy_echo_barrier([-50,50,-50,50])

            # Логируем событие
            self.events.append({
                'time': time.time(),
                'type': final_pred,
                'conf': final_conf,
                'action': 'fonon_strike',
                'pos': drone_pos
            })

        return final_pred, final_conf

# --- FUNC: _estimate_position ---
def _estimate_position(self, audio_chunk, rf_signal):
        """Пеленгация по акустике и RF"""
        # упрощённо — используем усреднение
        return (0, 0, 0)

# --- FUNC: fuse ---
def fuse(self, predictions):
        """
        predictions: list of (pred, confidence)
        Возвращает взвешенное предсказание
        """
        total_conf = 0
        weighted_pred = 0
        for i, (pred, conf) in enumerate(predictions):
            # Используем веса сенсоров
            sensor_type = ['acoustic', 'infrared', 'rf', 'seismic'][i]
            weight = self.weights.get(sensor_type, 0.3)
            weighted_pred += pred * conf * weight
            total_conf += conf * weight
        
        final_pred = weighted_pred / total_conf if total_conf > 0 else 0
        final_conf = total_conf / len(predictions) if predictions else 0
        return final_pred, final_conf

