# --- FUNC: analyze_sound ---
def analyze_sound(self, audio_samples, sample_rate=44100):
        """Извлекает спектральные признаки из звука и возвращает сигнатуру."""
        # Используем FFT для получения спектра
        fft_vals = np.abs(np.fft.rfft(audio_samples))
        freqs = np.fft.rfftfreq(len(audio_samples), 1/sample_rate)
        # Выделяем пики (гармоники винтов, двигателя)
        peaks = self._find_peaks(fft_vals, freqs)
        signature = {
            "dominant_freqs": peaks[:5].tolist(),  # первые 5 доминирующих пиков
            "spectral_centroid": np.average(freqs, weights=fft_vals),
            "bandwidth": freqs[-1] - freqs[0]
        }
        return signature

# --- FUNC: match_signature ---
def match_signature(self, signature):
        """Сравнивает сигнатуру с базой и возвращает тип БПЛА."""
        best_match = None
        best_score = 0
        for name, known in self.signatures.items():
            # Простое сравнение по евклидовому расстоянию между пиками
            dist = np.linalg.norm(
                np.array(signature["dominant_freqs"]) - 
                np.array(known["dominant_freqs"])
            )
            score = 1 / (1 + dist)
            if score > best_score:
                best_score = score
                best_match = name
        return best_match, best_score

# --- FUNC: calculate_resonant_frequency ---
def calculate_resonant_frequency(self, drone_type):
        """По типу дрона выдаёт частоту, которая вызовет резонанс его конструкции."""
        # Эвристика: резонансная частота ≈ 3 × (первая гармоника винтов)
        if drone_type in self.signatures:
            base_freq = self.signatures[drone_type]["dominant_freqs"][0]
            return base_freq * 3.2  # примерный коэффициент для разрушения
        return None

# --- FUNC: generate_phononic_beam ---
def generate_phononic_beam(self, freq, duration=0.1, amplitude=0.8):
        """
        Генерирует звуковой импульс заданной частоты и длительности.
        В реальной системе это будет управлять массивом ультразвуковых излучателей.
        """
        t = np.linspace(0, duration, int(duration * 44100))
        beam = amplitude * np.sin(2 * np.pi * freq * t)
        # Добавляем затухание
        envelope = np.exp(-t / (duration / 2))
        beam = beam * envelope
        return t, beam

