# --- FUNC: update_fonon_fields ---
def update_fonon_fields(fig_3d, shield):
    """Обновляет 3D-сцену полями от UnifiedEngine."""
    if shield.last_fonon_state is None:
        return fig_3d
    
    # Поле метрики (кривизна)
    metric = shield.last_fonon_state['metric']
    if metric is not None:
        # Добавляем изоповерхность кривизны (уровень 0.3)
        x = np.linspace(-3, 3, metric.shape[0])
        y = np.linspace(-3, 3, metric.shape[1])
        X, Y = np.meshgrid(x, y)
        
        # Находим точки, где кривизна > 0.3
        mask = metric > 0.3
        if np.any(mask):
            xs = X[mask].flatten()
            ys = Y[mask].flatten()
            zs = metric[mask].flatten()
            fig_3d.add_trace(go.Scatter3d(
                x=xs, y=ys, z=zs,
                mode='markers',
                marker=dict(size=3, color='gold', opacity=0.5),
                name='Зона гравитационной аномалии'
            ))
    
    # Комплексное поле (амплитуда)
    psi = shield.last_fonon_state['field']
    if psi is not None:
        amplitude = np.abs(psi)
        # Добавляем изоповерхность амплитуды > 0.7
        mask_amp = amplitude > 0.7
        if np.any(mask_amp):
            x_amp = X[mask_amp].flatten()
            y_amp = Y[mask_amp].flatten()
            z_amp = amplitude[mask_amp].flatten()
            fig_3d.add_trace(go.Scatter3d(
                x=x_amp, y=y_amp, z=z_amp,
                mode='markers',
                marker=dict(size=2, color='cyan', opacity=0.3),
                name='Резонансное поле'
            ))
    
    return fig_3d

# --- FUNC: field_element ---
def field_element(pos_ant, r, direction, beam_width):
    # direction – единичный вектор оси луча
    # beam_width – угол раскрыва
    angle = np.arccos(np.dot(direction, (r - pos_ant)/np.linalg.norm(r - pos_ant)))
    pattern = np.exp(-(angle/beam_width)**2)
    return pattern / np.linalg.norm(r - pos_ant) * np.exp(1j * phase)

