# --- FUNC: find_barriers ---
def find_barriers(self, species: str) -> list:
        """Поиск термических барьеров для вида"""
        prefs = self.THERMAL_PREFS.get(species, {})
        barrier_temp = prefs.get('barrier_temp')
        if not barrier_temp:
            return []
        barriers = []
        for zone, data in self.sst_data.items():
            if data['temp'] > barrier_temp:
                barriers.append({
                    'zone': zone,
                    'temp': data['temp'],
                    'excess': data['temp'] - barrier_temp,
                    'status': 'БЛОКИРОВКА'
                })
        self.barrier_zones = barriers
        return barriers

# --- FUNC: find_optimal_zones ---
def find_optimal_zones(self, species: str) -> list:
        """Определение зон, пригодных для вылова"""
        prefs = self.THERMAL_PREFS.get(species, {})
        optimal = []
        for zone, data in self.sst_data.items():
            if prefs['min'] <= data['temp'] <= prefs['max']:
                optimal.append({'zone': zone, 'temp': data['temp']})
        return optimal

# --- FUNC: adapt_quota ---
def adapt_quota(self, species: str, base_quota: float) -> float:
        """Адаптивная корректировка квоты с учётом барьеров"""
        barriers = self.find_barriers(species)
        if not barriers:
            return base_quota
        # Коэффициент снижения: чем больше барьеров, тем ниже квота
        penalty = min(0.6, len(barriers) * 0.15)
        return base_quota * (1 - penalty)

