# --- FUNC: import_json ---
def import_json(self, filename="strannik_data.json", clear_existing=False) -> int:
        """
        Атомарный импорт сессий из JSON-файла.

        Проверяет версию схемы и тип данных, валидирует все сессии во временном
        буфере, и только при полном успехе применяет изменения к self.sessions.

        Параметры:
            filename       — путь к JSON-файлу экспорта.
            clear_existing — True: заменить всё содержимое; False: слить с текущим.

        Возвращает:
            Количество успешно загруженных сессий.

        Raises:
            ValueError — при несовпадении schema_version, неверном типе данных,
                         дубликате ID внутри файла или коллизии с существующими ID.

        Внимание:
            В отличие от add_session, метод ВСЕГДА бросает исключение при ошибке,
            независимо от self.strict. Это сделано намеренно: файл нельзя
            применять частично (иначе состояние контейнера будет испорчено).
        """
        with open(filename, "r", encoding="utf-8") as f:
            data = json.load(f)
            
        if not isinstance(data, dict):
            raise ValueError(f"Ожидался объект (dict), получен {type(data).__name__}")
            
        version = data.get("schema_version", "unknown")
        if version != STRANNIK_SCHEMA_VERSION:
            raise ValueError(f"Ожидалась схема {STRANNIK_SCHEMA_VERSION}, получена {version!r}")

        sessions_data = data.get("sessions")
        if not isinstance(sessions_data, list):
            raise ValueError(f"Ожидался список сессий, получен {type(sessions_data).__name__}")

        # Шаг 1: буферизация и валидация всех сессий БЕЗ записи в self.sessions
        new_sessions: Dict[str, Session] = {}
        for s_data in sessions_data:
            s = Session(**s_data)
            if s.id in new_sessions:
                raise ValueError(f"Дубликат ID в файле: {s.id}")
            new_sessions[s.id] = s

        # Шаг 2: атомарное применение (только после полной валидации)
        if clear_existing:
            self.sessions = new_sessions
        else:
            collisions = set(new_sessions) & set(self.sessions)
            if collisions:
                raise ValueError(f"ID уже существуют: {sorted(collisions)}")
            self.sessions.update(new_sessions)

        logging.info(f"📂 Импортировано {len(new_sessions)} сессий.")
        return len(new_sessions)

# --- FUNC: test_strict_false_returns_none ---
def test_strict_false_returns_none(base_session, caplog):
    s = ZStrannik(strict=False)
    bad = copy.deepcopy(base_session)
    bad["tags"] = ["x", "x"]
    with caplog.at_level("WARNING"):
        assert s.add_session(bad) is None
    assert "Отклонено" in caplog.text
    assert len(s.sessions) == 0

# --- FUNC: new_session_id ---
def new_session_id(day: date, existing: list[Session]) -> str:
    prefix = f"session_{day:%Y_%m_%d}_"
    used = {int(s.id[-3:]) for s in existing if s.id.startswith(prefix)}
    n = max(used, default=0) + 1
    return f"{prefix}{n:03d}"

# --- FUNC: check_applied_timestamp ---
def check_applied_timestamp(self):
        # Теперь мы НЕ подменяем время, а требуем его наличия для аудита
        if self.status == "applied" and self.applied_at is None:
            raise ValueError(f"status='applied' требует явного applied_at (decision={self.decision[:30]!r})")
        return self

# --- FUNC: require_timezone ---
def require_timezone(cls, v: Optional[datetime]) -> Optional[datetime]:
        if v is not None and v.tzinfo is None:
            raise ValueError("applied_at должен содержать таймзону (например +00:00)")
        return v

# --- FUNC: test_import_collision_atomic ---
def test_import_collision_atomic(tmp_path, base_session):
    """КРИТИЧЕСКИЙ ТЕСТ: проверяет атомарность при коллизии ID (clear_existing=False)."""
    s1 = ZStrannik()
    s1.add_session(base_session)   # 001 уже есть

    # В файле: 002 (новая) + 001 (коллизия)
    collision_file = tmp_path / "collision.json"
    collision_file.write_text(json.dumps({
        "schema_version": STRANNIK_SCHEMA_VERSION, # Используем импортированную константу
        "sessions": [
            {**base_session, "id": "session_2026_10_28_002", "date": "2026-10-28"},
            {**base_session, "id": "session_2026_10_28_001", "date": "2026-10-28"},
        ],
    }))

    with pytest.raises(ValueError, match="уже существуют"):
        s1.import_json(collision_file, clear_existing=False)

    # 002 НЕ должна просочиться (атомарность)
    assert len(s1.sessions) == 1
    assert "session_2026_10_28_002" not in s1.sessions

# --- FUNC: test_export_import_roundtrip ---
def test_export_import_roundtrip(tmp_path, base_session):
    """Проверяет, что model_dump(mode='json') и Session(**...) дают тождественный объект."""
    s1 = ZStrannik()
    s1.add_session(base_session)
    f = tmp_path / "roundtrip.json"
    s1.export_json(f)

    s2 = ZStrannik()
    loaded = s2.import_json(f, clear_existing=True)
    assert loaded == 1
    assert s2.sessions["session_2026_10_28_001"].summary == base_session["summary"]
    assert s2.sessions["session_2026_10_28_001"].tags == base_session["tags"]

