def start_mission(self, coordinates):  
        try:  
            self.nav.set_route(coordinates)  
            while not self.nav.is_route_complete():  
                altitude = self.nav.get_altitude()  
                soil_data = self.nav.scan_soil()  
                # Корректировка плотности посева  
                if soil_data.moisture < 30:  
                    self.dispenser.set_density(10)  
                else:  
                    self.dispenser.set_density(25)  
                # Посев  
                self.dispenser.release_seeds()  
                self.motors.move_to_next_point()  
            self.return_to_base()  
        except HackingAttempt:  
            self.activate_defense()

