def balance_container(container_weight):  
    # Распределение нагрузки по лучам  
    load_per_arm = container_weight / 8  
    for arm in arms:  
        drones = arm.get_drones()  
        drones.sort(key=lambda d: d.thrust)  
        # 20% дронов работают на 100%, остальные на 50%  
        for i, drone in enumerate(drones):  
            drone.thrust = 100 if i < 16 else 50

