# --- FUNC: dynamic_stress_distribution ---
def dynamic_stress_distribution(sensors_data):  
    # sensors_data: тензодатчики на лучах  
    from torch import nn  
    model = nn.Sequential(  
        nn.Linear(800, 256),  # 800 дронов → 256 нейронов  
        nn.ReLU(),  
        nn.Linear(256, 8)     # Коррекция для 8 лучей  
    )  
    return model(sensors_data)

