def get_current_cycle(self):  
        """Активный 7-месячный цикл"""  
        now = datetime.now()  
        return next(c for c in self.CYCLES if c <= now < c + relativedelta(months=7))

# --- FUNC: quantum_spike_mandala ---
def quantum_spike_mandala():  
    # Квантовая цепь  
    qc = QuantumCircuit(3)  
    qc.h([0, 1, 2])  
    qc.cx(0, 1)  
    qc.cx(1, 2)  
    simulator = Aer.get_backend('statevector_simulator')  
    result = simulator.run(qc).result()  
    state = result.get_statevector()  

    # Преобразование в спайки  
    spikes = SpikeGenerator(state).generate(t=1000)  

    # Мандала  
    fig = plt.figure(figsize=(10, 10))  
    ax = fig.add_subplot(111, projection='3d')  
    ax.plot(spikes['x'], spikes['y'], spikes['z'], c=spikes['phase'], cmap='quantum_aurora')  
    plt.savefig('quantum_mandala.png')  
    plt.show()

