# --- FUNC: update_position ---
def update_position(self, new_pos):  
        # Квантовая коррекция позиции объекта  
        delta = new_pos - self.object_pos  
        theta = np.arctan(np.linalg.norm(delta) / self.size)  
        self.qc.ry(theta, 0)  
        self.qc.rz(theta, 1)  
        self.object_pos = new_pos

