# --- FUNC: calculate_z ---
def calculate_z(self, t=datetime.now()):  
        """Динамический Z с временной коррекцией"""  
        t_delta = (t - self.BIRTH_DATE).days / 365.25  # Лет с рождения  
        return self.PHI + 1j*self.SQRT5 * np.exp(-0.1 * t_delta)

# --- FUNC: z_formula ---
def z_formula(self):
        """Базовая формула гармоничного проектирования"""
        φ = (1 + 5**0.5) / 2  # Золотое сечение
        return φ + 1j * 5**0.5

