# --- FUNC: generate_heating_path ---
def generate_heating_path(step):
    commands = []
    y = 0
    direction = 1  # +1 вправо, -1 влево
    while y <= height:
        if direction == 1:
            commands.append(f"G1 X{width} Y{y}")  # нить вправо
        else:
            commands.append(f"G1 X0 Y{y}")        # нить влево
        y += step
        direction *= -1
    return commands

# --- FUNC: calculate_heating ---
def calculate_heating(voltage, resistance_per_meter, wire_length, density_factor):
    """
    Рассчитывает температуру нагрева токопроводящей нити.
    """
    resistance = resistance_per_meter * wire_length
    power = (voltage ** 2) / resistance  # Вт
    # Упрощённо: температура = мощность * коэффициент теплопередачи
    temperature_rise = power * density_factor * 0.1  # градусы Цельсия
    return temperature_rise

# --- FUNC: get_layer_angles ---
def get_layer_angles(pattern_type, layer_index, total_layers):
    if pattern_type == "quasi_isotropic":
        # Чередование 0°, 90°, +45°, -45°
        angles = [0, 90, 45, -45]
        return angles[layer_index % len(angles)]
    elif pattern_type == "triaxial":
        # Три направления через 60°
        angles = [0, 60, 120]
        return angles[layer_index % len(angles)]
    elif pattern_type == "3d_lattice":
        # В каждом слое один угол, но добавляются Z-нити
        return 0  # упрощённо: все слои однонаправленные, а Z-нити генерируются отдельно
    elif pattern_type == "gradient":
        # Плотность меняется по высоте
        base_angle = 0
        return base_angle
    else:
        return 0

# --- FUNC: generate_layer_path ---
def generate_layer_path(angle, z, L, W, density):
    """
    Генерирует траекторию укладки нитей в слое под углом angle.
    Возвращает список команд G-кода.
    """
    commands = []
    step = 10.0 / density  # шаг между соседними нитями в мм
    
    # Определяем размеры проекции с учётом угла
    cos_a = cos(radians(angle))
    sin_a = sin(radians(angle))
    
    # Создаём семейство параллельных линий, покрывающих прямоугольник
    # Для простоты будем двигаться вдоль направления, перпендикулярного нитям
    perp_vector = (-sin_a, cos_a)  # единичный вектор, перпендикулярный нитям
    
    # Начальная точка смещения
    offset = 0.0
    while offset <= (L * abs(cos_a) + W * abs(sin_a) + step):
        # Вычисляем линию, проходящую через точку offset * perp_vector
        # и идущую вдоль направления (cos_a, sin_a)
        # Находим точки пересечения этой линии с границами прямоугольника
        # Это сложно, упростим: будем класть нити от одного края до другого
        
        # Начальная точка линии
        start_x = -L/2 + offset * perp_vector[0]
        start_y = -W/2 + offset * perp_vector[1]
        
        # Конечная точка (идём вдоль направления на большое расстояние)
        end_x = start_x + 2*max(L,W) * cos_a
        end_y = start_y + 2*max(L,W) * sin_a
        
        # Обрезаем до границ прямоугольника (здесь опущено для краткости)
        
        # Добавляем команду быстрого перемещения к началу
        commands.append(f"G0 X{start_x} Y{start_y} Z{z}")
        # Рабочее перемещение с подачей материала
        commands.append(f"G1 X{end_x} Y{end_y} Z{z} F300")
        
        offset += step
    
    return commands

# --- FUNC: generate_gcode ---
def generate_gcode(pattern_type, L, W, H, layer_height, fiber_diameter, density):
    gcode = ["; Generated by PletPatternGenerator v1.0", "; Start G-code"]
    gcode.append("G21 ; Units in mm")
    gcode.append("G90 ; Absolute positioning")
    
    total_layers = int(H / layer_height)
    for layer in range(total_layers):
        z = layer * layer_height
        angle = get_layer_angles(pattern_type, layer, total_layers)
        layer_commands = generate_layer_path(angle, z, L, W, density)
        gcode.extend(layer_commands)
        
        # Если нужны Z-нити (для 3D-плетения), добавим их после каждого слоя или между
        if pattern_type == "3d_lattice" and layer % 2 == 0:
            # Генерация вертикальных нитей (прошивка)
            # Это сложный процесс, упростим: делаем точки приварки
            pass
    
    gcode.append("G0 X0 Y0 Z10 ; Return to home")
    gcode.append("M84 ; Disable motors")
    return gcode

