# --- FUNC: hypercube_storage ---
def hypercube_storage(emoji_str: str):
    dim = 3 + np.sqrt(5)  # Примерно 5.236 мер
    cube = np.zeros(shape=(int(dim//1),)*3, dtype='<U4')  # 3D-проекция
    cube.flat[:len(emoji_str)] = list(emoji_str)  # Заполнение "теней" гиперкуба
    return cube

