# --- FUNC: prime_factors ---
def prime_factors(self, n):
        """Разложение на простые множители"""
        i = 2
        factors = []
        while i * i <= n:
            if n % i:
                i += 1
            else:
                n //= i
                factors.append(i)
        if n > 1:
            factors.append(n)
        return factors

# --- FUNC: early_wave_dynamics ---
def early_wave_dynamics(self, t):
        """
        Динамика волн в ранней Вселенной
        t - время в планковских единицах
        """
        # На ранних этапах волны сжатые
        if t < 10 * self.ε:
            # Дисперсионное соотношение меняется
            wavelength = self.ε * np.exp(-t/self.ε)
            frequency = self.v_sound / wavelength
            
            # Аналог ваших "сжатых волн около струи"
            wave_number = 2 * np.pi / wavelength
            
            return {
                'wavelength': wavelength,
                'frequency': frequency,
                'phase_velocity': self.v_sound * (1 + np.exp(-t/self.ε)),
                'state': 'compressed_early'
            }
        
        # После установления - равномерные волны
        else:
            # Волны становятся регулярными
            wavelength = 2 * np.pi * self.v_sound * t / self.Ω
            frequency = self.v_sound / wavelength
            
            return {
                'wavelength': wavelength,
                'frequency': frequency,
                'phase_velocity': self.v_sound,
                'state': 'regular_expanding'
            }

# --- FUNC: horizon_absorption ---
def horizon_absorption(self, wavelength, R_horizon):
        """
        Эффект "овального сужения" - поглощение волн на горизонте
        """
        # Коэффициент поглощения (аналог вашего наблюдения)
        absorption = 1 - np.exp(-(wavelength / R_horizon)**2)
        
        # Нет отражения, только поглощение
        reflection = 0.0
        
        return {
            'absorption_coefficient': absorption,
            'reflection_coefficient': reflection,
            'transmission': np.exp(-absorption)
        }

# --- FUNC: generate_spectrum ---
def generate_spectrum(self):
        """Генерация спектра возмущений по аналогии с ванной"""
        times = np.logspace(np.log10(self.ε), np.log10(self.Ω), 1000)
        spectrum = []
        
        for t in times:
            wave_info = self.early_wave_dynamics(t)
            horizon = 1.0 / t  # Горизонт обратно пропорционален времени
            
            # Эффект от границ (овального сужения)
            absorption_info = self.horizon_absorption(
                wave_info['wavelength'], 
                horizon
            )
            
            spectrum.append({
                'time': t,
                'wavelength': wave_info['wavelength'],
                'frequency': wave_info['frequency'],
                'state': wave_info['state'],
                'absorption': absorption_info['absorption_coefficient'],
                'horizon_size': horizon
            })
        
        return spectrum

