# --- FUNC: stability_analysis ---
def stability_analysis(self, h, dH_dt, viscosity):
        """
        Анализ устойчивости формы
        h - текущая глубина
        dH_dt - скорость изменения уровня
        viscosity - вязкость воды
        """
        # Число Рейнольдса для пятна
        Re = self.calculate_reynolds(h, dH_dt, viscosity)
        
        # Критические значения для перехода форм
        transitions = {
            'circle': {'Re_max': 1000, 'condition': 'Стабильное течение'},
            'triangle': {'Re_max': 3000, 'condition': 'Начало турбулентности'},
            'pentagon': {'Re_max': 5000, 'condition': 'Развитая турбулентность'},
            'chaotic': {'Re_max': 10000, 'condition': 'Полный хаос'}
        }
        
        # Определяем текущую форму
        current_shape = 'circle'
        for shape, params in transitions.items():
            if Re < params['Re_max']:
                current_shape = shape
            else:
                break
        
        return {
            'reynolds_number': Re,
            'predicted_shape': current_shape,
            'stability': 'устойчивая' if Re < 2000 else 'неустойчивая'
        }

# --- FUNC: calculate_reynolds ---
def calculate_reynolds(self, h, v, nu=1e-6):
        """Число Рейнольдса для пятна"""
        characteristic_length = h  # Глубина как характерный размер
        return v * characteristic_length / nu

