# --- FUNC: spot_diameter ---
def spot_diameter(self, h, Q, v):
        """
        h - глубина воды (м)
        Q - расход воды (м³/с)
        v - скорость струи (м/с)
        """
        # Эмпирическая формула на основе наблюдений
        # Диаметр пропорционален корню из кинетической энергии
        kinetic_energy = 0.5 * 1000 * Q * v**2
        
        # Диссипация пропорциональна глубине
        dissipation = 0.1 * h
        
        # Диаметр пятна
        D = 0.3 * np.sqrt(kinetic_energy / dissipation)
        
        return D

# --- FUNC: wave_generation ---
def wave_generation(self, D, h, g=9.81):
        """
        Генерация волн от бурлящего пятна
        D - диаметр пятна
        h - глубина
        """
        # Частота пульсаций (Гц)
        f = 1 / (2 * np.pi * np.sqrt(D / (2 * g)))
        
        # Длина волны (м)
        wavelength = np.sqrt(g * h) / f
        
        # Амплитуда (м) - пропорциональна энергии
        amplitude = 0.01 * D / h
        
        return {
            'frequency': f,
            'wavelength': wavelength,
            'amplitude': amplitude
        }

# --- FUNC: map_to_cosmology ---
def map_to_cosmology(self):
        """Отображение параметров орбиты на космологические"""
        # Большая полуось → масштабный фактор Вселенной
        scale_factor = self.a
        
        # Эксцентриситет → параметр плотности Ω
        # Для замкнутой Вселенной: Ω > 1, для открытой Ω < 1
        omega = 1 + (self.e - 0.5) * 2  # преобразование
        
        # Период → возраст Вселенной
        age_factor = self.period * 0.13  # 75.3 лет → ~13.8 млрд лет
        
        return {
            'scale_factor': scale_factor,
            'omega_parameter': omega,
            'universe_age_analogy': age_factor,
            'curvature_sign': 'positive' if omega > 1 else 'negative'
        }

# --- FUNC: orbit_equation ---
def orbit_equation(self, theta):
        """Уравнение кометной орбиты в полярных координатах"""
        r = self.a * (1 - self.e**2) / (1 + self.e * np.cos(theta))
        return r

# --- FUNC: universe_expansion_analogy ---
def universe_expansion_analogy(self, cosmic_time):
        """
        Аналогия: движение по орбите ↔ расширение Вселенной
        """
        # Истинная аномалия как аналог времени
        theta = 2 * np.pi * cosmic_time / self.period
        
        # Радиус орбиты как аналог масштабного фактора
        r = self.orbit_equation(theta)
        
        # Скорость движения (2-й закон Кеплера)
        angular_momentum = np.sqrt(self.a * (1 - self.e**2))
        velocity = angular_momentum / r
        
        return {
            'cosmic_time': cosmic_time,
            'scale_factor': r,
            'expansion_rate': velocity,
            'phase': 'approach' if theta < np.pi else 'recession'
        }

# --- FUNC: generate_cosmic_light_curve ---
def generate_cosmic_light_curve(self):
        """
        Генерация кривой блеска (аналог эволюции Вселенной)
        """
        time_points = np.linspace(0, self.period, 1000)
        light_curve = []
        
        for t in time_points:
            orbit_state = self.universe_expansion_analogy(t)
            
            # Яркость ~ 1/r² (закон обратных квадратов)
            brightness = 1 / orbit_state['scale_factor']**2
            
            # Эффект Доплера для скорости
            doppler_factor = np.sqrt((1 + orbit_state['expansion_rate']) / 
                                   (1 - orbit_state['expansion_rate']))
            
            light_curve.append({
                'time': t,
                'brightness': brightness,
                'redshift': doppler_factor - 1,
                'phase': orbit_state['phase']
            })
        
        return light_curve

