# --- FUNC: add_block ---
def add_block(self, key: str, title: str, emoji: str, payload: Optional[Dict[str, Any]] = None) -> None:
        if key in self.blocks:
            raise ValueError(f"Block '{key}' already exists")
        self.blocks[key] = SessionBlock(
            key=key,
            title=title,
            emoji=emoji,
            payload=payload or {}
        )
        self.history.append({
            "ts": datetime.now().isoformat(),
            "action": "add_block",
            "key": key
        })

# --- FUNC: update_block ---
def update_block(self, block_key: str, updates: Dict[str, Any]) -> None:
        """
        Итеративно обновляет содержимое блока по ключу.
        
        Args:
            block_key (str): Ключ блока (plant, crystal, key_chain_cross, interaction, insights, dynamics)
            updates (Dict[str, Any]): Новые значения для обновления
        """
        if block_key in self.data:
            # Обновляем существующие ключи и добавляем новые
            self.data[block_key].update(updates)
        else:
            # Создаём новый блок, если его нет
            self.data[block_key] = updates

# --- FUNC: detect_evasion ---
def detect_evasion(self, session_data: Dict) -> Dict:
        """Детектирование попыток обхода"""
        warnings = []
        score = 0
        
        # Проверка на ускоренное воспроизведение
        if session_data.get('playback_speed', 1) > 1.5:
            warnings.append("Ускоренное воспроизведение")
            score += 30
        
        # Проверка активности вкладки
        if not session_data.get('tab_active', True):
            warnings.append("Ролик в неактивной вкладке")
            score += 40
        
        # Проверка на ботов
        if self._check_bot_patterns(session_data):
            warnings.append("Подозрительная активность, похожая на бота")
            score += 70
        
        return {
            "risk_score": min(score, 100),
            "warnings": warnings,
            "requires_captcha": score > 50,
            "requires_review": score > 75
        }

# --- FUNC: _check_bot_patterns ---
def _check_bot_patterns(self, session_data: Dict) -> bool:
        """Проверка паттернов ботов"""
        # Анализ временных меток (боты часто имеют точные интервалы)
        timestamps = session_data.get('interaction_timestamps', [])
        if len(timestamps) > 3:
            intervals = [timestamps[i+1] - timestamps[i] for i in range(len(timestamps)-1)]
            # Если все интервалы почти одинаковые - подозрительно
            if max(intervals) - min(intervals) < 0.1:
                return True
        return False

