# --- FUNC: get_db_connection ---
def get_db_connection(self):
        """Контекстный менеджер для подключения к БД"""
        conn = None
        try:
            conn = psycopg2.connect(**self.db_config, cursor_factory=RealDictCursor)
            yield conn
        except Exception as e:
            print(f"Database connection error: {e}")
            raise
        finally:
            if conn:
                conn.close()

# --- FUNC: increment_rate_limit ---
def increment_rate_limit(self, service: str, identifier: str) -> bool:
        """Увеличение счетчика rate limit в Redis"""
        key = f"rate_limit:{service}:{identifier}"
        current = self.redis_client.incr(key)
        
        if current == 1:
            self.redis_client.expire(key, 60)  # TTL 1 minute
        
        return current <= self._get_rate_limit(service)

# --- FUNC: _get_rate_limit ---
def _get_rate_limit(self, service: str) -> int:
        """Получение лимита запросов для сервиса"""
        limits = {
            'telegram': 30,
            'twitter': 300,
            'newsapi': 100
        }
        return limits.get(service, 100)

