# --- FUNC: _calculate_rubric_resilience ---
def _calculate_rubric_resilience(self, opportunities: Dict, global_context: Dict):
        """Расчет индекса экономической устойчивости РФ"""
        total_benefits = {
            'economic_resilience': 0.0,
            'strategic_independence': 0.0, 
            'global_integration': 0.0,
            'innovation_potential': 0.0
        }
        
        opportunity_count = 0
        
        for framework_ops in opportunities.values():
            for opportunity in framework_ops:
                benefits = opportunity.get('rubic_benefits', {})
                for indicator, value in benefits.items():
                    if indicator in total_benefits:
                        total_benefits[indicator] += value
                opportunity_count += 1
        
        if opportunity_count > 0:
            for indicator in total_benefits:
                total_benefits[indicator] /= opportunity_count
        
        # Интегральный индекс (взвешенная сумма)
        self.rubric_indicators['economic_resilience'] = (
            total_benefits['economic_resilience'] * 0.4 +
            total_benefits['strategic_independence'] * 0.3 +
            total_benefits['global_integration'] * 0.2 +
            total_benefits['innovation_potential'] * 0.1
        )

# --- FUNC: _generate_strategic_recommendations ---
def _generate_strategic_recommendations(self, opportunities: Dict) -> List[Dict]:
        """Генерация стратегических рекомендаций"""
        recommendations = []
        
        # Приоритетные проекты
        high_impact_ops = []
        for framework_ops in opportunities.values():
            for op in framework_ops:
                impact_score = sum(op.get('rubic_benefits', {}).values())
                if impact_score > 2.0:  # Высокий совокупный эффект
                    high_impact_ops.append(op)
        
        # Сортировка по воздействию
        high_impact_ops.sort(key=lambda x: sum(x.get('rubic_benefits', {}).values()), reverse=True)
        
        for i, op in enumerate(high_impact_ops[:5]):  # Топ-5 рекомендаций
            recommendations.append({
                'priority': i + 1,
                'project': op['name'],
                'rationale': f"Высокий интегральный эффект на устойчивость РФ",
                'expected_timeline': op.get('implementation_timeline', '1-3 года'),
                'key_metrics': op.get('economic_impact', {}),
                'first_steps': self._define_implementation_steps(op)
            })
        
        return recommendations

# --- FUNC: _create_implementation_roadmap ---
def _create_implementation_roadmap(self, opportunities: Dict) -> Dict[str, Any]:
        """Создание дорожной карты реализации"""
        phases = {
            'phase_1_quick_wins': {
                'timeline': '6-12 месяцев',
                'projects': [],
                'expected_impact': 'Быстрое укрепление позиций'
            },
            'phase_2_strategic_initiatives': {
                'timeline': '1-3 года', 
                'projects': [],
                'expected_impact': 'Структурные улучшения'
            },
            'phase_3_transformational': {
                'timeline': '3-5 лет',
                'projects': [],
                'expected_impact': 'Качественное изменение позиций'
            }
        }
        
        # Распределение проектов по фазам
        for framework_ops in opportunities.values():
            for op in framework_ops:
                timeline = op.get('implementation_timeline', '1-3 года')
                
                if 'месяц' in timeline:
                    phases['phase_1_quick_wins']['projects'].append(op)
                elif '1-3' in timeline:
                    phases['phase_2_strategic_initiatives']['projects'].append(op)
                else:
                    phases['phase_3_transformational']['projects'].append(op)
        
        return phases

