# --- FUNC: predict_risks ---
def predict_risks(self, metrics: SocialMetrics) -> Dict[str, ThreatLevel]:
        """Прогнозирование рисков на основе метрик"""
        risks = {}
        
        # Анализ социальной сплочённости
        if metrics.cohesion_index < 0.3:
            risks['social_fragmentation'] = ThreatLevel.CRITICAL
        elif metrics.cohesion_index < 0.6:
            risks['social_fragmentation'] = ThreatLevel.MEDIUM
            
        # Анализ информационной энтропии
        if metrics.information_entropy > 0.8:
            risks['information_chaos'] = ThreatLevel.HIGH
            
        return risks

# --- FUNC: deploy_interventions ---
def deploy_interventions(self, region: str, risks: Dict[str, ThreatLevel]) -> List[Dict]:
        """Развёртывание вмешательств на основе рисков"""
        interventions = []
        
        for risk_type, level in risks.items():
            if level.value >= ThreatLevel.MEDIUM.value:
                intervention = self._select_intervention(risk_type, level)
                interventions.append(intervention.deploy(region))
                
        return interventions

