# --- FUNC: _calculate_attractiveness_score ---
def _calculate_attractiveness_score(self, incentive: Dict) -> float:
        """Расчет индекса привлекательности 'плюшки'"""
        score = 0.0
        
        # Критерии привлекательности
        criteria = {
            'immediate_benefit': 0.3,
            'long_term_value': 0.25,
            'low_risk': 0.2,
            'high_visibility': 0.15,
            'scalability': 0.1
        }
        
        # Оценка по каждому критерию (упрощенно)
        if 'features' in incentive:
            score += criteria['immediate_benefit'] * min(1.0, len(incentive['features']) / 5)
        
        if 'benefits' in incentive:
            score += criteria['long_term_value'] * 0.8
        
        # Базовая привлекательность
        score += 0.3  # Все предложения имеют базовую привлекательность
        
        return min(1.0, score)

