# --- FUNC: analyze_session_patterns ---
def analyze_session_patterns(session: SessionDataManager) -> Dict[str, Any]:
    """
    Глубинный анализ паттернов сессии
    
    Args:
        session: Менеджер сессии для анализа
        
    Returns:
        Словарь с результатами анализа
    """
    analysis = {
        'dominant_categories': [],
        'emerging_themes': [],
        'temporal_patterns': {},
        'content_complexity': 0
    }
    
    # Анализ доминирующих категорий
    stats = session.get_session_statistics()
    categories = stats['categories']
    total_entities = stats['total_entities']
    
    for category, count in categories.items():
        if count / total_entities > 0.2:  # Более 20% сущностей
            analysis['dominant_categories'].append({
                'category': category,
                'percentage': count / total_entities,
                'count': count
            })
    
    # Анализ тегов для выявления emerging themes
    tag_stats = stats['tags']
    for tag, count in tag_stats.items():
        if count >= 3:  # Тег встречается минимум 3 раза
            analysis['emerging_themes'].append({
                'theme': tag,
                'frequency': count,
                'entities': [e.id for e in session.get_entities_by_tag(tag)]
            })
    
    return analysis

# --- FUNC: integrate_new_data ---
def integrate_new_data(session: SessionDataManager, 
                      new_data: List[Dict[str, Any]],
                      data_type: str = "generic") -> List[str]:
    """
    Интеграция новых данных в существующую сессию
    
    Args:
        session: Целевая сессия
        new_data: Список новых данных для интеграции
        data_type: Тип интегрируемых данных
        
    Returns:
        Список ID созданных сущностей
    """
    created_ids = []
    
    for item in new_data:
        entity_id = session.add_entity(
            content=item.get('content', item),
            category=DataCategory(item.get('category', DataCategory.INTEGRATION)),
            tags=item.get('tags', []) + [f"imported_{data_type}"],
            metadata=item.get('metadata', {})
        )
        created_ids.append(entity_id)
    
    return created_ids

