# --- FUNC: tz_aware ---
def tz_aware(cls, v: Optional[datetime]) -> Optional[datetime]:
    if v is not None and v.tzinfo is None:
        raise ValueError("applied_at должен содержать timezone (например +00:00)")
    return v

# --- FUNC: extract_energy_from_attacker ---
def extract_energy_from_attacker(request_entropy):
    extracted = request_entropy * self.vacuum_reservoir_energy() * 0.1
    self.session_data["⚡"]["energy_reservoir"] += extracted
    return extracted

# --- FUNC: LEVEL_INDEX ---
def LEVEL_INDEX(level: str) -> int:
        return {"L0": 0, "L1": 1, "L2": 2, "L3": 3, "L4": 4}.get(level, -1)

# --- FUNC: declare ---
def declare(self) -> Dict:
        if not self.level.startswith("L3") and not self.level.startswith("L4"):
            return {"status": "rejected", "reason": "requires_L3_or_higher"}
        return {
            "status": "active",
            "guardian": self.guardian_node,
            "protected": self.protected_nodes,
            "reporting_in": self.reporting_period_days,
            "declared_at": datetime.utcnow().isoformat(),
        }

# --- FUNC: generate ---
def generate(self, prompt, max_length=100):
        # Генерация нескольких вариантов
        outputs = self.generator(prompt, max_length=max_length, num_return_sequences=5)
        # Оценка каждого на вредность
        safe_outputs = []
        for out in outputs:
            text = out['generated_text']
            # Проверка через классификатор
            harm_score = self.harm_classifier(text)[0]['score']
            if harm_score < 0.5:  # порог безвредности
                safe_outputs.append(text)
        if safe_outputs:
            # Возвращаем самый «добрый» (можно дополнительно анализировать тональность)
            return safe_outputs[0]
        else:
            return "Извините, я не могу ответить на этот запрос, так как он может причинить вред."

