# --- FUNC: assert_raises ---
def assert_raises(func, expected_error_type, msg):
        try:
            func()
            print(f"❌ ТЕСТ ПРОВАЛЕН: {msg} (ожидалась ошибка, но её нет)")
        except expected_error_type:
            print(f"✅ ТЕСТ ПРОЙДЕН: {msg}")

