# --- FUNC: _new_session_id ---
def _new_session_id():
    global _next_session_id
    with _lock:
        sid = f"session_{_next_session_id}"
        _next_session_id += 1
        return sid

# --- FUNC: test_strict_false_returns_none_and_logs ---
def test_strict_false_returns_none_and_logs(base_session, caplog):
    """Мягкий режим не бросает исключение, но пишет в лог."""
    s = ZStrannik(strict=False)
    bad = copy.deepcopy(base_session)
    bad["tags"] = ["x", "x"]
    
    with caplog.at_level("WARNING"):
        result = s.add_session(bad)
        
    assert result is None
    assert len(s.sessions) == 0
    assert "Отклонено" in caplog.text

# --- FUNC: test_duplicate_id_rejected ---
def test_duplicate_id_rejected(base_session):
    s = ZStrannik()
    s.add_session(base_session)
    with pytest.raises(ValueError, match="уже существует"):
        s.add_session(copy.deepcopy(base_session))

