# --- FUNC: generate_uncertain_code ---
def generate_uncertain_code(observer_hash=None):
    # observer_hash — хеш запроса атакующего (или его ID)
    # Код выбирается из суперпозиции, зависящей от наблюдателя
    rng = random.Random(observer_hash)
    variants = [
        "def f(x): return x * phi",
        "def f(x): return phi * x",
        "def f(x): return x * 1.6180339887"
    ]
    return rng.choice(variants)

