# --- FUNC: calculate_performance_metrics ---
def calculate_performance_metrics(self, test_data):
        """Расчет метрик производительности с φ-взвешиванием"""
        metrics = {
            "stability_score": self._phi_weighted_average(
                test_data.get('position_error', []),
                test_data.get('angle_variance', [])
            ),
            "energy_efficiency": self._golden_efficiency(
                test_data.get('power_consumption', []),
                test_data.get('flight_time', 0)
            ),
            "metaphysical_alignment": self._calculate_resonance(
                test_data.get('vibration_spectrum', [])
            )
        }
        
        return metrics

# --- FUNC: _phi_weighted_average ---
def _phi_weighted_average(self, errors, variances):
        """Φ-взвешенное усреднение метрик"""
        if not errors or not variances:
            return 0
            
        weighted_errors = [e * (1/self.phi) for e in errors]
        weighted_variances = [v * self.phi for v in variances]
        
        return (sum(weighted_errors) + sum(weighted_variances)) / (len(errors) + len(variances))

# --- FUNC: calculate_spiral_parameters ---
def calculate_spiral_parameters(self):
        """Расчет параметров спирали на основе золотого сечения"""
        # Высота системы (ориентировочно)
        base_height = 1000  # метров
        optimal_height = base_height * self.phi ** 2  # ~2.6 км
        
        # Параметры спирали
        turns = self.gamma  # 7 витков как в нашей сессии
        max_radius = 500   # метров
        min_radius = 50    # метров
        
        # Скорость вращения и линейная скорость
        orbital_velocity = 7900  # м/с (первая космическая)
        target_velocity = orbital_velocity * 0.3  # 30% от орбитальной
        
        return {
            "height": optimal_height,
            "turns": turns,
            "max_radius": max_radius,
            "min_radius": min_radius,
            "target_velocity": target_velocity,
            "spiral_length": self._calculate_spiral_length(max_radius, min_radius, turns)
        }

# --- FUNC: _calculate_spiral_length ---
def _calculate_spiral_length(self, r_max, r_min, turns):
        """Длина спирали с затухающей амплитудой"""
        return math.pi * (r_max + r_min) * turns * self.phi

# --- FUNC: simulate_drone_flight ---
def simulate_drone_flight():
    stabilizer = ArduinoPhiStabilizer()
    time_steps = np.linspace(0, 10, 1000)
    dt = time_steps[1] - time_steps[0]
    
    # Имитация данных с датчиков: начальное возмущение и шум
    roll_angles = []
    pitch_angles = []
    yaw_angles = []
    
    corrections_history = []
    
    # Начальное возмущение
    roll = 0.5  # радиан
    pitch = 0.3
    yaw = 0.1
    
    for t in time_steps:
        # Имитация шума датчиков
        gyro_noise = np.random.normal(0, 0.01, 3)
        accel_noise = np.random.normal(0, 0.1, 3)
        
        # Имитация гироскопа: производная от углов плюс шум
        gyro = [0, 0, 0]  # В реальности гироскоп измеряет угловую скорость
        # Мы имитируем гироскоп как разность углов, но это не совсем правильно.
        # Вместо этого, мы будем имитировать угловую скорость как случайную величину,
        # но для простоты представим, что гироскоп измеряет угловую скорость, которая связана с углом через интеграл.
        # Упростим: пусть угловая скорость равна производной угла плюс шум.
        # Но у нас нет модели динамики. Поэтому сделаем простую модель: 
        # углы затухают со временем, но есть случайные возмущения.
        
        # Модель: углы стремятся к нулю, но на них действуют случайные моменты
        roll += -0.1 * roll * dt + 0.1 * np.random.normal() * dt
        pitch += -0.1 * pitch * dt + 0.1 * np.random.normal() * dt
        yaw += -0.1 * yaw * dt + 0.1 * np.random.normal() * dt
        
        # Гироскоп измеряет угловую скорость: производная угла плюс шум
        gyro = [0, 0, 0]  # мы не вычисляем производную, а используем нашу модель для углов
        # Вместо этого, мы будем использовать акселерометр для измерения углов крена и тангажа относительно гравитации.
        # Предположим, что акселерометр измеряет гравитацию в системе координат дрона.
        g = 9.81
        accel = [
            g * np.sin(pitch) + accel_noise[0],
            -g * np.sin(roll) * np.cos(pitch) + accel_noise[1],
            g * np.cos(roll) * np.cos(pitch) + accel_noise[2]
        ]
        
        # Обновляем стабилизатор
        corrections = stabilizer.update(gyro, accel, dt)
        
        # Применяем корректировки к моторам (в модели мы просто обновляем углы)
        # Упрощенная модель: корректировки напрямую уменьшают углы
        roll -= corrections[0] * dt
        pitch -= corrections[1] * dt
        yaw -= corrections[2] * dt
        
        roll_angles.append(roll)
        pitch_angles.append(pitch)
        yaw_angles.append(yaw)
        corrections_history.append(corrections)
    
    # Визуализация
    plt.figure(figsize=(12, 8))
    plt.subplot(2, 1, 1)
    plt.plot(time_steps, roll_angles, label='Roll')
    plt.plot(time_steps, pitch_angles, label='Pitch')
    plt.plot(time_steps, yaw_angles, label='Yaw')
    plt.ylabel('Углы (рад)')
    plt.legend()
    plt.grid(True)
    
    plt.subplot(2, 1, 2)
    corrections_history = np.array(corrections_history)
    plt.plot(time_steps, corrections_history[:,0], label='Correction Roll')
    plt.plot(time_steps, corrections_history[:,1], label='Correction Pitch')
    plt.plot(time_steps, corrections_history[:,2], label='Correction Yaw')
    plt.xlabel('Время (с)')
    plt.ylabel('Корректировки')
    plt.legend()
    plt.grid(True)
    
    plt.show()

