# --- FUNC: _calculate_ideal_distances ---
def _calculate_ideal_distances(self):
        """Вычисление идеальных расстояний между дронами на основе φ"""
        # Используем золотое сечение для определения расстояний
        # Базовое расстояние (может быть адаптивным)
        base_distance = 1.0
        distances = np.ones((self.num_drones, self.num_drones)) * base_distance
        # Модифицируем расстояния в соответствии с φ-спиралью
        for i in range(self.num_drones):
            for j in range(i+1, self.num_drones):
                # Учитываем φ в зависимости от разницы индексов
                factor = self.phi ** (abs(i-j) / self.num_drones)
                distances[i, j] = base_distance * factor
                distances[j, i] = distances[i, j]
        return distances

# --- FUNC: update_positions ---
def update_positions(self, target_position, wind_force=np.zeros(3)):
        """Обновление позиций дронов с учетом целевой позиции и ветра"""
        # Параметры для коррекции
        k_attraction = 0.1  # Притяжение к цели
        k_repulsion = 0.2   # Отталкивание от соседей
        k_phi = 0.3         # Коррекция по φ-расстояниям

        new_positions = np.copy(self.positions)
        for i in range(self.num_drones):
            # Вектор к цели
            to_target = target_position - self.positions[i]
            # Коррекция на основе φ-расстояний до соседей
            phi_correction = np.zeros(3)
            for j in range(self.num_drones):
                if i != j:
                    # Вектор от i к j
                    to_neighbor = self.positions[j] - self.positions[i]
                    current_distance = np.linalg.norm(to_neighbor)
                    ideal_distance = self.ideal_distances[i, j]
                    # Если текущее расстояние не идеальное, корректируем
                    if current_distance > 0:
                        direction = to_neighbor / current_distance
                        # Сила коррекции: стремимся к идеальному расстоянию
                        correction = k_phi * (current_distance - ideal_distance) * direction
                        phi_correction += correction

            # Обновление позиции с учетом ветра (ветер влияет на всех одинаково)
            new_positions[i] += (k_attraction * to_target + phi_correction + wind_force) * 0.1

        self.positions = new_positions

# --- FUNC: get_formation ---
def get_formation(self):
        """Возвращает текущие позиции дронов"""
        return self.positions

