# --- FUNC: plot_c_eff ---
def plot_c_eff(self, grid_resolution=50):
    """
    Визуализирует локальную скорость света, вычисленную из
    распределения резонаторов и их частот.
    """
    c_map = np.zeros((grid_resolution, grid_resolution))
    x = np.linspace(self.x.min(), self.x.max(), grid_resolution)
    y = np.linspace(self.y.min(), self.y.max(), grid_resolution)
    X, Y = np.meshgrid(x, y)

    for i in range(grid_resolution):
        for j in range(grid_resolution):
            # Расстояние до центра
            r = np.sqrt(X[i,j]**2 + Y[i,j]**2)
            c_vals = []
            for e in self.E_resonators + self.B_resonators:
                # Вклад каждого резонатора, ослабленный с расстоянием
                dist = np.sqrt((X[i,j] - e.get('x', 0))**2 + (Y[i,j] - e.get('y', 0))**2)
                if dist < 1.0:  # вклад только близких резонаторов
                    c_vals.append(e.c_eff * np.exp(-dist**2))  # гауссово влияние
            if c_vals:
                c_map[i,j] = np.mean(c_vals)
            else:
                c_map[i,j] = 1.0  # фоновая скорость

    plt.imshow(c_map, extent=[x.min(), x.max(), y.min(), y.max()],
               origin='lower', cmap='coolwarm')
    plt.title('Локальная скорость света (c_eff)')
    plt.colorbar(label='c (в единицах c0)')
    plt.show()

# --- FUNC: metric_perturbation ---
def metric_perturbation(self, amplitude: float, omega: float, t: np.ndarray, x: np.ndarray) -> np.ndarray:
        """
        Вычисляет возмущение метрики h_ij для плоской волны, распространяющейся вдоль оси z.
        Используется тензорная поляризация "+" и "×".
        Возвращает h_+, h_× как функции времени и пространства.
        """
        # Временная и пространственная части
        k = omega  # волновое число (в единицах c=1)
        phase = omega * t[:, None] - k * x[None, :]  # матрица (nt, nx)
        # Поляризация "+"
        h_plus = amplitude * np.cos(phase)
        # Поляризация "×"
        h_cross = amplitude * np.sin(phase)
        return h_plus, h_cross

# --- FUNC: propagate_wave ---
def propagate_wave(self, source_params: Dict, grid_size: int = 100, time_steps: int = 100) -> Dict:
        """
        Моделирует распространение волны от точечного источника на 2D сетке.
        Возвращает массив искажений на каждом шаге.
        """
        amplitude = source_params.get("amplitude", 1e-21)
        omega = source_params.get("omega", 1.0)
        # Создаём сетку
        x = np.linspace(-10, 10, grid_size)
        y = np.linspace(-10, 10, grid_size)
        X, Y = np.meshgrid(x, y)
        R = np.sqrt(X**2 + Y**2) + 1e-6  # избегаем деления на ноль
        # Время
        t = np.linspace(0, 10, time_steps)

        # Искажение метрики: h(r,t) = amplitude * sin(omega*t - k*r) / r (цилиндрическая волна)
        k = omega
        wavefronts = []
        for ti in t:
            phase = omega * ti - k * R
            h = amplitude * np.sin(phase) / R
            wavefronts.append(h)
        # Сохраняем
        self.session_data["🌊"]["wavefronts"] = wavefronts
        return {"grid": (X, Y), "wavefronts": wavefronts, "times": t}

# --- FUNC: plot_wave ---
def plot_wave(self, wave_data: Dict, time_index: int = -1):
        """
        Визуализирует фронт волны в заданный момент времени.
        """
        X, Y = wave_data["grid"]
        wavefront = wave_data["wavefronts"][time_index]
        plt.figure(figsize=(8,6))
        plt.contourf(X, Y, wavefront, levels=50, cmap='RdBu')
        plt.colorbar(label='Искажение h')
        plt.title(f'Гравитационная волна (t = {wave_data["times"][time_index]:.2f})')
        plt.xlabel('x')
        plt.ylabel('y')
        plt.show()

# --- FUNC: crystal_response ---
def crystal_response(self, crystal_id: str, wave_amplitude: float, omega: float) -> Dict:
        """
        Вычисляет, как гравитационная волна изменяет фононный спектр кристалла.
        Возвращает сдвиг частот и изменение когерентности.
        """
        spectrum = self.get_phonon_spectrum(crystal_id)
        if "frequencies" not in spectrum:
            return {"error": "Нет спектра"}
        # Базовая частота кристалла (средняя)
        all_freqs = []
        for k_freqs in spectrum["frequencies"]:
            all_freqs.extend(k_freqs)
        if not all_freqs:
            return {"error": "Пустой спектр"}
        mean_freq = np.mean(all_freqs)
        # Влияние волны: сдвиг частоты пропорционален амплитуде и резонансу
        # Если частота волны близка к частоте кристалла, эффект максимален
        detuning = abs(omega - mean_freq) / mean_freq
        shift = wave_amplitude * 1000 / (1 + detuning)  # условно
        # Изменение когерентности: волна может синхронизировать фазы
        coherence_change = wave_amplitude * 100 / (1 + detuning)
        new_coherence = min(1.0, self.session_data["🌀"]["phonon_states"]["coherence"] + coherence_change)
        return {
            "shift": shift,
            "new_coherence": new_coherence,
            "detuning": detuning
        }

# --- FUNC: run_full_gravitational_experiment ---
def run_full_gravitational_experiment(self, generator_params: Dict, crystal_id: str = None):
        """
        Запускает полную симуляцию: генерирует волну, распространяет её,
        и измеряет отклик кристалла.
        """
        # Генерация волны из фононов
        N = generator_params.get("N", 10)
        omega = generator_params.get("omega", 1.0)
        wave = self.generate_gravity_wave_from_phonons(N, omega, crystal_id)
        amp = wave["amplitude"]

        # Распространение
        prop_data = self.propagate_wave({"amplitude": amp, "omega": omega})

        # Если есть кристалл, измеряем его отклик
        response = None
        if crystal_id:
            response = self.crystal_response(crystal_id, amp, omega)

        # Логируем
        self.session_data["🌊"]["propagation_log"].append({
            "generator_params": generator_params,
            "wave_amplitude": amp,
            "propagation": prop_data,
            "crystal_response": response,
            "timestamp": datetime.now().isoformat()
        })
        return {"wave": wave, "propagation": prop_data, "response": response}

# --- FUNC: design_and_test_with_qec ---
def design_and_test_with_qec(self, num_qubits: int = 4, resonator_freq: float = 1.0, noise: float = 0.01):
        """
        Полный цикл: проектирование, обучение QEC, эмуляция с коррекцией.
        """
        processor = self.design_processor(num_qubits)
        sensor = self.design_sensor(resonator_freq)
        # Обучаем QEC на данных от этого процессора
        qec_training = self.train_qec_model(processor)
        # Запускаем эмуляцию с QEC
        experiment = self.emulate_with_qec(processor, sensor, noise)
        return {
            "processor": processor,
            "sensor": sensor,
            "qec_training": qec_training,
            "experiment": experiment
        }

# --- FUNC: solve_spectrum ---
def solve_spectrum(self, g, L, num_levels=5, N=500):
        """
        Решает спектр для заданных параметров.
        """
        x = np.linspace(-L/2, L/2, N)
        dx = x[1] - x[0]
        # Строим матрицу Гамильтониана
        H = np.zeros((N, N))
        for i in range(1, N-1):
            H[i, i-1] = -0.5 / dx**2
            H[i, i] = 1.0 / dx**2
            H[i, i+1] = -0.5 / dx**2
        # Граничные условия (бесконечные стенки)
        H[0,0] = 1.0 / dx**2
        H[-1,-1] = 1.0 / dx**2
        # Нелинейный член в потенциале: g * |psi|^2 (самосогласованно)
        # Для упрощения используем линеаризацию: добавляем в потенциал эвристическое приближение
        # В реальности нужно решать самосогласованно, но для интерактивного режима используем
        # эффективный потенциал в виде стенок плюс параболическая яма
        V = 0.5 * (x / (L/4))**2  # параболическая яма, усиленная нелинейностью
        V += g * (x / (L/2))**4   # кубическая поправка, создающая локализацию
        # Добавляем потенциал к диагонали
        for i in range(N):
            H[i, i] += V[i]
        # Диагонализация
        eigvals, eigvecs = eigh(H)
        # Берём первые num_levels уровней
        self.energies = eigvals[:num_levels].tolist()
        self.wavefunctions = eigvecs[:, :num_levels]
        self.x = x
        # Массовая щель
        if len(self.energies) > 1:
            self.gap = self.energies[1] - self.energies[0]
        else:
            self.gap = None
        # Поиск соответствия константам
        self.match = None
        if self.gap is not None:
            candidates = {
                'phi': self.phi,
                'sqrt5': self.sqrt5,
                'gamma': self.gamma,
                'phi*sqrt5': self.phi * self.sqrt5,
                'gamma/phi': self.gamma / self.phi,
                'phi*gamma/sqrt5': self.phi * self.gamma / self.sqrt5
            }
            best = None
            best_diff = float('inf')
            for name, val in candidates.items():
                diff = abs(val - self.gap)
                if diff < best_diff:
                    best_diff = diff
                    best = (name, val)
            self.match = best

# --- FUNC: plot_spectrum ---
def plot_spectrum(self):
        if not self.energies:
            print("Сначала решите спектр")
            return
        fig, axs = plt.subplots(1, 2, figsize=(12, 5))
        # Спектр
        axs[0].bar(range(len(self.energies)), self.energies, color='blue')
        axs[0].set_title('Энергетический спектр')
        axs[0].set_xlabel('Уровень')
        axs[0].set_ylabel('Энергия')
        if self.gap is not None:
            axs[0].axhline(y=self.energies[0] + self.gap, color='red', linestyle='--', label=f'Щель = {self.gap:.4f}')
            axs[0].legend()
        # Волновые функции (первые 3)
        axs[1].set_title('Волновые функции (|ψ|²)')
        for i in range(min(3, len(self.wavefunctions[0]))):
            psi = self.wavefunctions[:, i]
            axs[1].plot(self.x, np.abs(psi)**2, label=f'Уровень {i}')
        axs[1].set_xlabel('x')
        axs[1].set_ylabel('|ψ|²')
        axs[1].legend()
        # Информация о соответствии
        if self.match:
            axs[1].text(0.5, 0.95, f'Щель соответствует {self.match[0]} = {self.match[1]:.4f}',
                        transform=axs[1].transAxes, ha='center', fontsize=10, color='red')
        plt.tight_layout()
        plt.show()

