# --- FUNC: generate_fibonacci_sequence ---
def generate_fibonacci_sequence(self, length: int) -> np.ndarray:
        """
        Генерирует одномерную последовательность Фибоначчи (чередование двух типов атомов A и B).
        Использует правило: A -> AB, B -> A.
        Возвращает массив с 0 и 1 (0=A, 1=B).
        """
        seq = [0]  # A
        for _ in range(length):
            new_seq = []
            for s in seq:
                if s == 0:
                    new_seq.extend([0, 1])  # A -> AB
                else:
                    new_seq.append(0)       # B -> A
            seq = new_seq
            if len(seq) > length:
                break
        return np.array(seq[:length])

# --- FUNC: generate_penrose_tiling ---
def generate_penrose_tiling(self, size: int) -> np.ndarray:
        """
        Генерирует двумерную пенроузовскую мозаику (упрощённо) как решётку с двумя типами ромбов.
        Возвращает массив координат вершин и рёбер.
        Для простоты используем метод замены (substitution) для ромбов.
        """
        # Упрощённая реализация: возвращаем случайную сетку с двумя ориентациями
        # В реальности нужен алгоритм построения пенроуза, но для демонстрации используем аппроксимацию
        x = np.linspace(0, size, size)
        y = np.linspace(0, size, size)
        X, Y = np.meshgrid(x, y)
        # Смешиваем две решётки с поворотом на 72 градуса (золотое сечение)
        phi = self.session_data["✨"].get("phi", 1.618)
        angle1 = 0
        angle2 = np.pi / 2 + np.arctan(1/phi)  # ~72 градуса
        # Координаты узлов как суперпозиция двух решёток
        Z = np.sin(2*np.pi * (X * np.cos(angle1) + Y * np.sin(angle1)) / phi) + \
            np.sin(2*np.pi * (X * np.cos(angle2) + Y * np.sin(angle2)) / phi)
        # Порог для получения бинарной структуры (типы атомов)
        binary = (Z > 0).astype(int)
        return binary

# --- FUNC: build_crystal ---
def build_crystal(self, structure_type: str = "fibonacci", **kwargs) -> Dict:
        """
        Строит кристалл заданного типа с параметрами.
        Возвращает словарь с описанием структуры и её геометрией.
        """
        if structure_type == "fibonacci":
            length = kwargs.get("length", 100)
            seq = self.generate_fibonacci_sequence(length)
            # Превращаем в координаты (одномерная цепочка)
            positions = np.arange(len(seq))
            types = seq
            structure = {
                "type": "1D_fibonacci",
                "positions": positions.tolist(),
                "types": types.tolist(),
                "num_atoms": len(seq)
            }
        elif structure_type == "penrose":
            size = kwargs.get("size", 30)
            tiling = self.generate_penrose_tiling(size)
            # Координаты узлов
            coords = np.argwhere(tiling == 1)
            structure = {
                "type": "2D_penrose",
                "coordinates": coords.tolist(),
                "num_atoms": len(coords)
            }
        else:
            # Случайная бинарная структура
            size = kwargs.get("size", 20)
            random_struct = np.random.choice([0, 1], size=(size, size))
            coords = np.argwhere(random_struct == 1)
            structure = {
                "type": "2D_random",
                "coordinates": coords.tolist(),
                "num_atoms": len(coords)
            }
        # Генерируем уникальный ID
        structure["id"] = f"crystal_{hash(str(structure))}"
        self.session_data["🔊"]["crystals"][structure["id"]] = structure
        return structure

# --- FUNC: compute_phonon_spectrum_1d ---
def compute_phonon_spectrum_1d(self, structure: Dict, k_vals: np.ndarray = None) -> Dict:
        """
        Вычисляет фононный спектр для 1D цепочки (последовательность Фибоначчи).
        Использует модель связанных осцилляторов с переменными жёсткостями.
        Возвращает частоты для каждого k.
        """
        if structure["type"] != "1D_fibonacci":
            return {"error": "Поддерживаются только 1D структуры"}

        types = np.array(structure["types"])
        N = len(types)
        # Жёсткости зависят от типа соседей (A-A, A-B, B-B)
        # Используем константы из нашей системы: для A-A: φ, A-B: √5, B-B: γ
        phi = self.session_data["✨"].get("phi", 1.618)
        sqrt5 = self.session_data["✨"].get("sqrt5", 2.236)
        gamma = 7.0
        k_AA = phi
        k_AB = sqrt5
        k_BB = gamma

        # Строим матрицу жёсткостей
        K = np.zeros((N, N))
        for i in range(N-1):
            if types[i] == 0 and types[i+1] == 0:
                k = k_AA
            elif types[i] == 0 and types[i+1] == 1:
                k = k_AB
            else:
                k = k_BB
            K[i, i] += k
            K[i, i+1] -= k
            K[i+1, i] -= k
            K[i+1, i+1] += k
        # Учитываем массу (для простоты считаем все массы = 1)
        M = np.eye(N) * self.phonon_params["mass"]

        # Диагонализация для каждого k (периодические граничные условия)
        if k_vals is None:
            k_vals = np.linspace(0, self.phonon_params["max_k"], self.phonon_params["num_k"])

        frequencies = []
        for k in k_vals:
            # Фаза для Блоха (периодические граничные условия)
            phase = np.exp(1j * k * np.arange(N))
            # Строим динамическую матрицу D = M^{-1/2} K M^{-1/2} с учётом фазы
            # Для простоты используем приближение: применяем фазовый сдвиг к K
            K_shifted = K.copy()
            # Сдвигаем связь между последним и первым атомом
            if N > 1:
                if types[-1] == 0 and types[0] == 0:
                    k_boundary = k_AA
                elif types[-1] == 0 and types[0] == 1:
                    k_boundary = k_AB
                else:
                    k_boundary = k_BB
                K_shifted[-1, -1] += k_boundary
                K_shifted[0, 0] += k_boundary
                K_shifted[-1, 0] -= k_boundary * np.exp(-1j * k * N)
                K_shifted[0, -1] -= k_boundary * np.exp(1j * k * N)
            # Решаем обобщённую проблему собственных значений
            # Для малых систем можно использовать eigh
            try:
                eigvals = eigh(K_shifted, M, eigvals_only=True)
                # Берём только положительные частоты (sqrt собственных значений)
                # Масса = 1, поэтому frequency = sqrt(eigval)
                freqs = np.sqrt(np.maximum(eigvals, 0))
                frequencies.append(freqs)
            except Exception as e:
                frequencies.append(np.zeros(N))

        return {
            "k_values": k_vals.tolist(),
            "frequencies": frequencies,
            "num_modes": N
        }

# --- FUNC: compute_phonon_spectrum_2d ---
def compute_phonon_spectrum_2d(self, structure: Dict, kx_vals: np.ndarray = None, ky_vals: np.ndarray = None) -> Dict:
        """
        Вычисляет фононный спектр для 2D структуры (упрощённо, как сетка осцилляторов с переменными связями).
        """
        # Упрощённая версия: аппроксимируем спектр через сумму плоских волн
        coords = np.array(structure["coordinates"])
        if len(coords) == 0:
            return {"error": "Пустая структура"}
        # Строим матрицу расстояний и используем преобразование Фурье
        # Для демонстрации вернём синтетический спектр
        if kx_vals is None:
            kx_vals = np.linspace(0, np.pi, 20)
            ky_vals = np.linspace(0, np.pi, 20)
        KX, KY = np.meshgrid(kx_vals, ky_vals)
        # Моделируем дисперсию: ω(k) = sqrt( (4 - 2 cos(kx) - 2 cos(ky)) * φ )
        omega = np.sqrt((4 - 2*np.cos(KX) - 2*np.cos(KY)) * self.phi)
        # Добавляем влияние квазипериодичности (модуляция от √5)
        modulation = 1 + 0.1 * np.sin(KX * self.sqrt5) * np.cos(KY * self.sqrt5)
        omega = omega * modulation
        return {
            "kx": kx_vals.tolist(),
            "ky": ky_vals.tolist(),
            "frequencies": omega.tolist()
        }

# --- FUNC: get_phonon_spectrum ---
def get_phonon_spectrum(self, crystal_id: str) -> Dict:
        """
        Возвращает спектр для кристалла по ID. Если спектр не вычислен, вычисляет.
        """
        crystal = self.session_data["🔊"]["crystals"].get(crystal_id)
        if not crystal:
            return {"error": "Кристалл не найден"}
        # Проверяем, есть ли уже спектр
        if crystal_id in self.session_data["🔊"]["phonon_spectra"]:
            return self.session_data["🔊"]["phonon_spectra"][crystal_id]
        # Вычисляем
        if crystal["type"] == "1D_fibonacci":
            spectrum = self.compute_phonon_spectrum_1d(crystal)
        elif "2D" in crystal["type"]:
            spectrum = self.compute_phonon_spectrum_2d(crystal)
        else:
            spectrum = {"error": "Неизвестный тип кристалла"}
        self.session_data["🔊"]["phonon_spectra"][crystal_id] = spectrum
        return spectrum

# --- FUNC: find_phononic_gaps ---
def find_phononic_gaps(self, spectrum: Dict, threshold: float = 0.05) -> List[Tuple[float, float]]:
        """
        Ищет запрещённые зоны (щели) в спектре частот.
        Возвращает список интервалов (low, high), где плотность состояний равна нулю или мала.
        """
        if "frequencies" not in spectrum:
            return []
        # Для 1D случая: frequencies - список списков (по k)
        freq_data = spectrum["frequencies"]
        if not freq_data:
            return []
        # Собираем все частоты
        all_freqs = []
        for k_freqs in freq_data:
            all_freqs.extend(k_freqs)
        all_freqs = np.array(all_freqs)
        # Строим гистограмму
        hist, bin_edges = np.histogram(all_freqs, bins=50)
        bin_centers = (bin_edges[:-1] + bin_edges[1:]) / 2
        # Ищем участки с нулевой (или очень малой) плотностью
        gaps = []
        in_gap = False
        gap_start = 0
        for i, count in enumerate(hist):
            if count < threshold * max(hist) and not in_gap:
                in_gap = True
                gap_start = bin_edges[i]
            elif count >= threshold * max(hist) and in_gap:
                in_gap = False
                gap_end = bin_edges[i]
                if gap_end - gap_start > 0.1:
                    gaps.append((gap_start, gap_end))
        if in_gap:
            gaps.append((gap_start, bin_edges[-1]))
        return gaps

# --- FUNC: find_resonances ---
def find_resonances(self, threshold=0.5):
        """
        Находит устойчивые резонансы в поле (области высокой плотности).
        Использует кластеризацию по амплитуде.
        """
        if self.psi is None:
            return []
        amp = np.abs(self.psi)
        # Порог
        mask = amp > threshold * np.max(amp)
        # Находим центры тяжести кластеров
        from scipy.ndimage import label, center_of_mass
        labeled, num_features = label(mask)
        centers = []
        for i in range(1, num_features+1):
            cy, cx = center_of_mass(mask, labeled, i)
            centers.append((cx, cy))
        # Вычисляем фазу и энергию резонанса
        resonances = []
        for (cx, cy) in centers:
            ix, iy = int(cx), int(cy)
            if 0 < ix < self.N and 0 < iy < self.N:
                phase = np.angle(self.psi[iy, ix])
                energy = np.abs(self.psi[iy, ix])**2
                resonances.append({
                    'x': self.x[ix],
                    'y': self.y[iy],
                    'phase': phase,
                    'energy': energy,
                    'mass': energy / (self.phi * self.sqrt5)  # эвристика
                })
        self.resonances = resonances
        return resonances

# --- FUNC: optimize_crystal ---
def optimize_crystal(self, application: str = "saser", iterations: int = 10) -> Dict:
        """
        Использует эволюционные механизмы MetaphysicalAI для поиска структуры,
        оптимизированной под заданное приложение:
        - "saser": максимальная фононная щель (для звукового лазера)
        - "ultrasound": равномерный спектр с высокими частотами (для УЗИ)
        - "spectroscopy": наличие дискретных резонансов
        Возвращает лучшую найденную структуру и её спектр.
        """
        # Определяем функцию оценки пригодности (fitness) для приложения
        if application == "saser":
            def fitness(structure):
                spec = self.get_phonon_spectrum(structure["id"])
                gaps = self.find_phononic_gaps(spec)
                if not gaps:
                    return 0.0
                # Максимизируем ширину самой широкой щели
                max_gap = max(g[1] - g[0] for g in gaps)
                return max_gap
        elif application == "ultrasound":
            def fitness(structure):
                spec = self.get_phonon_spectrum(structure["id"])
                if "frequencies" not in spec:
                    return 0.0
                all_freqs = []
                for k_freqs in spec["frequencies"]:
                    all_freqs.extend(k_freqs)
                # Цель: высокие частоты и равномерное распределение
                mean_freq = np.mean(all_freqs)
                std_freq = np.std(all_freqs)
                # Чем выше средняя частота и ниже стандартное отклонение, тем лучше
                return mean_freq / (1 + std_freq)
        elif application == "spectroscopy":
            def fitness(structure):
                spec = self.get_phonon_spectrum(structure["id"])
                resonances = self.find_resonances(spec)
                # Цель: много чётких резонансов
                return len(resonances) / (1 + np.std(resonances) if resonances else 1)
        else:
            return {"error": "Неизвестное приложение"}

        # Генерация начальной популяции структур (разнообразных)
        population = []
        for _ in range(10):
            # Случайный выбор типа
            struct_type = random.choice(["fibonacci", "penrose", "random"])
            if struct_type == "fibonacci":
                length = random.randint(50, 200)
                struct = self.build_crystal("fibonacci", length=length)
            elif struct_type == "penrose":
                size = random.randint(20, 40)
                struct = self.build_crystal("penrose", size=size)
            else:
                size = random.randint(15, 30)
                struct = self.build_crystal("random", size=size)
            population.append(struct)

        # Эволюционный цикл
        best_fitness = -float('inf')
        best_struct = None
        for gen in range(iterations):
            # Оценка
            fitnesses = []
            for struct in population:
                fit = fitness(struct)
                fitnesses.append(fit)
                if fit > best_fitness:
                    best_fitness = fit
                    best_struct = struct
            # Отбор (турнирный)
            new_population = []
            while len(new_population) < len(population):
                idx1 = random.randrange(len(population))
                idx2 = random.randrange(len(population))
                parent1 = population[idx1] if fitnesses[idx1] > fitnesses[idx2] else population[idx2]
                # Второй родитель
                idx3 = random.randrange(len(population))
                idx4 = random.randrange(len(population))
                parent2 = population[idx3] if fitnesses[idx3] > fitnesses[idx4] else population[idx4]
                # Кроссинговер (для структур - смешивание параметров)
                if random.random() < 0.7:
                    # Создаём новую структуру как комбинацию двух
                    if parent1["type"] == "1D_fibonacci" and parent2["type"] == "1D_fibonacci":
                        # Смешиваем последовательности
                        seq1 = self.generate_fibonacci_sequence(len(parent1["types"]))
                        seq2 = self.generate_fibonacci_sequence(len(parent2["types"]))
                        # Берём среднюю длину
                        new_len = min(len(seq1), len(seq2))
                        new_seq = np.where(np.random.rand(new_len) < 0.5, seq1[:new_len], seq2[:new_len])
                        new_struct = {
                            "type": "1D_fibonacci",
                            "positions": np.arange(new_len).tolist(),
                            "types": new_seq.tolist(),
                            "num_atoms": new_len
                        }
                        new_struct["id"] = f"crystal_{hash(str(new_struct))}"
                        new_population.append(new_struct)
                    else:
                        # Для 2D используем мутацию
                        child = parent1.copy()
                        # Мутация: случайное изменение координат (сдвиг)
                        if "coordinates" in child:
                            coords = np.array(child["coordinates"])
                            shift = np.random.randint(-2, 2, size=coords.shape)
                            new_coords = coords + shift
                            # Убираем дубликаты
                            unique_coords = np.unique(new_coords, axis=0)
                            child["coordinates"] = unique_coords.tolist()
                            child["num_atoms"] = len(unique_coords)
                            child["id"] = f"crystal_{hash(str(child))}"
                        new_population.append(child)
                else:
                    # Мутация родителя
                    child = parent1.copy()
                    if child["type"] == "1D_fibonacci":
                        # Мутация: инвертировать некоторые биты
                        types = np.array(child["types"])
                        mask = np.random.rand(len(types)) < 0.05
                        types[mask] = 1 - types[mask]
                        child["types"] = types.tolist()
                        child["id"] = f"crystal_{hash(str(child))}"
                    elif "coordinates" in child:
                        # Добавляем случайный атом
                        coords = np.array(child["coordinates"])
                        new_atom = coords[np.random.randint(len(coords))] + np.random.randint(-1, 2, size=2)
                        new_coords = np.vstack([coords, new_atom])
                        unique_coords = np.unique(new_coords, axis=0)
                        child["coordinates"] = unique_coords.tolist()
                        child["num_atoms"] = len(unique_coords)
                        child["id"] = f"crystal_{hash(str(child))}"
                    new_population.append(child)
            population = new_population

        # Сохраняем лучшую структуру и её спектр
        if best_struct:
            self.session_data["🔊"]["optimized_structures"].append({
                "application": application,
                "best_fitness": best_fitness,
                "structure": best_struct,
                "spectrum": self.get_phonon_spectrum(best_struct["id"])
            })
        return {"best_structure": best_struct, "fitness": best_fitness}

