# --- FUNC: evolve_crystal_for_application ---
def evolve_crystal_for_application(self, application: str, generations: int = 5, population_size: int = 10):
        """
        Запускает эволюционный поиск структуры для заданного приложения.
        Результаты сохраняются и могут быть использованы в основной эволюции кода.
        """
        result = self.optimize_crystal(application, iterations=generations)
        # Добавляем найденную структуру как новый "ген" в систему
        best_struct = result.get("best_structure")
        if best_struct:
            crystal_id = best_struct["id"]
            # Генерируем код
            code = self.generate_crystal_code(crystal_id)
            # Сохраняем код в сессии как сгенерированный (можно использовать в эволюции)
            self.session_data["⚡"]["last_generated_code"] = code
            # Добавляем в историю генераций
            self.session_data["🧬"]["generations"].append({
                "iteration": len(self.session_data["🧬"]["generations"]),
                "application": application,
                "crystal_id": crystal_id,
                "fitness": result["fitness"],
                "code": code
            })
        return result

# --- FUNC: plot_crystal_and_spectrum ---
def plot_crystal_and_spectrum(self, crystal_id: str):
        """
        Визуализирует структуру кристалла и его фононный спектр.
        """
        try:
            import matplotlib.pyplot as plt
        except ImportError:
            print("matplotlib не установлен")
            return
        crystal = self.session_data["🔊"]["crystals"].get(crystal_id)
        if not crystal:
            print("Кристалл не найден")
            return
        spectrum = self.get_phonon_spectrum(crystal_id)

        fig, axs = plt.subplots(1, 2, figsize=(12, 5))

        # 1. Структура
        if crystal["type"] == "1D_fibonacci":
            axs[0].bar(np.arange(len(crystal["types"])), crystal["types"], color=['blue', 'red'])
            axs[0].set_title("1D цепочка Фибоначчи")
            axs[0].set_xlabel("Позиция")
            axs[0].set_ylabel("Тип атома (0=A, 1=B)")
        elif "2D" in crystal["type"]:
            coords = np.array(crystal["coordinates"])
            axs[0].scatter(coords[:,0], coords[:,1], s=20)
            axs[0].set_title("2D структура")
            axs[0].set_xlabel("x")
            axs[0].set_ylabel("y")
        else:
            axs[0].text(0.5, 0.5, "Неизвестный тип", ha='center')

        # 2. Спектр
        if "frequencies" in spectrum:
            freq_data = spectrum["frequencies"]
            if freq_data:
                all_freqs = []
                for k_freqs in freq_data:
                    all_freqs.extend(k_freqs)
                axs[1].hist(all_freqs, bins=30, alpha=0.7)
                axs[1].set_title("Фононный спектр (плотность состояний)")
                axs[1].set_xlabel("Частота")
                axs[1].set_ylabel("Количество")
        plt.tight_layout()
        plt.show()

# --- FUNC: fitness ---
def fitness(crystal_freq, coherence):
            # Создаём временный кристалл с заданной частотой (для простоты)
            # В реальности нужно создать кристалл с нужным спектром
            # Здесь мы эмулируем: используем фиктивный кристалл
            bridge = self.build_phonon_bridge(platform1, platform2, None)  # без кристалла
            # Корректируем фиделити на основе частоты и когерентности
            base_fidelity = bridge["fidelity"]
            # Чем ближе частота к резонансу, тем выше фиделити
            f1 = self.session_data["🔗"]["platforms"][platform1]["frequency"]
            f2 = self.session_data["🔗"]["platforms"][platform2]["frequency"]
            target = np.sqrt(f1 * f2)
            detuning = abs(crystal_freq - target) / target
            fidelity = base_fidelity / (1 + detuning * 5)
            # Когерентность усиливает передачу
            fidelity *= (1 + coherence * 0.5)
            return fidelity

# --- FUNC: generate_ocean_dataset ---
def generate_ocean_dataset(self, num_samples: int = 1000, random_seed: int = 42) -> pd.DataFrame:
        """
        Генерирует датасет параметров и результатов полевых испытаний.
        Возвращает pandas DataFrame с колонками:
        - features: глубина, температура, солёность, высота волны, тип дна, частота, толщина, плотность, модуль упругости
        - targets: коэффициент подавления, SNR, ошибка связи
        """
        np.random.seed(random_seed)
        random.seed(random_seed)
        data = []
        # Диапазоны параметров
        depth_range = (20, 200)
        temp_range = (0, 25)
        salinity_range = (30, 40)
        wave_height_range = (0.1, 3.0)
        bottom_types = ['sandy', 'rocky', 'muddy']
        freq_range = (5000, 50000)  # Гц
        thickness_range = (0.01, 0.2)  # м
        density_range = (100, 2000)   # кг/м³
        elastic_range = (1e7, 1e9)    # Па

        for i in range(num_samples):
            # Генерация параметров
            depth = np.random.uniform(*depth_range)
            temp = np.random.uniform(*temp_range)
            salinity = np.random.uniform(*salinity_range)
            wave_height = np.random.uniform(*wave_height_range)
            bottom_type = random.choice(bottom_types)
            freq = np.random.uniform(*freq_range)
            thickness = np.random.uniform(*thickness_range)
            density = np.random.uniform(*density_range)
            elastic = np.random.uniform(*elastic_range)
            # Симуляция (используем упрощённые модели)
            # 1. Скорость звука (приблизительная формула)
            c = 1449 + 4.6*temp - 0.055*temp**2 + 1.39*(salinity-35) + 0.016*depth
            # 2. Эффективный импеданс материала
            c_m = np.sqrt(elastic / density)
            Z_m = density * c_m
            Z_w = 1025 * c
            # 3. Коэффициент отражения (нормальное падение)
            R = (Z_m - Z_w) / (Z_m + Z_w) if (Z_m + Z_w) != 0 else 1.0
            R_power = R**2
            # 4. Подавление эха (зависит от толщины, согласования импедансов)
            # Чем ближе R к 0, тем лучше подавление
            suppression_dB = -10 * np.log10(R_power + 1e-12)
            # Добавляем шум (зависит от состояния моря)
            sea_state_noise = 0.1 * wave_height / 1.0  # условно
            suppression_dB += np.random.normal(0, sea_state_noise * 5)  # шум в измерениях
            suppression_dB = max(0, suppression_dB)  # подавление не может быть отрицательным
            # 5. SNR канала связи (зависит от глубины и частоты)
            # Потери на поглощение: ~ 0.05 дБ/кГц/км для 10 кГц, эмпирически
            absorption = 0.05 * (freq/1000) * (depth/1000)  # дБ
            # Потери на рассеяние от волн
            scattering = 0.01 * wave_height * freq / 1000
            total_loss = absorption + scattering
            SNR = 20 - total_loss + np.random.normal(0, 3)  # дБ, начальный запас 20 дБ
            SNR = max(0, SNR)
            # 6. Ошибка связи (вероятность битовой ошибки из SNR)
            # Для BPSK: BER ≈ 0.5 * erfc(sqrt(SNR))
            from scipy.special import erfc
            SNR_linear = 10**(SNR/10)
            ber = 0.5 * erfc(np.sqrt(SNR_linear))
            # Переводим в процент ошибок на символ (грубо)
            error_rate = ber * 100
            error_rate = min(100, error_rate)
            # Собираем строку
            row = {
                'depth': depth,
                'temperature': temp,
                'salinity': salinity,
                'wave_height': wave_height,
                'bottom_type': bottom_type,
                'frequency': freq,
                'thickness': thickness,
                'density': density,
                'elastic_modulus': elastic,
                'suppression_dB': suppression_dB,
                'SNR_dB': SNR,
                'error_rate_percent': error_rate
            }
            data.append(row)
        df = pd.DataFrame(data)
        self.session_data["📊"]["current_dataset"] = df
        return df

# --- FUNC: save_dataset ---
def save_dataset(self, filename: str = "ocean_dataset.csv") -> str:
        """Сохраняет текущий датасет в CSV файл."""
        df = self.session_data["📊"].get("current_dataset")
        if df is None:
            return "Нет активного датасета. Сначала сгенерируйте его."
        df.to_csv(filename, index=False)
        self.session_data["📊"]["datasets"].append(filename)
        return f"Датасет сохранён как {filename}"

# --- FUNC: split_dataset ---
def split_dataset(self, test_size: float = 0.2, random_state: int = 42) -> Dict:
        """
        Разбивает датасет на обучающую и тестовую выборки.
        Возвращает словарь с X_train, X_test, y_train, y_test.
        """
        df = self.session_data["📊"].get("current_dataset")
        if df is None:
            return {"error": "Нет активного датасета."}
        # Признаки (все кроме целевых)
        feature_cols = ['depth', 'temperature', 'salinity', 'wave_height', 'bottom_type', 
                        'frequency', 'thickness', 'density', 'elastic_modulus']
        # Кодируем категориальный признак bottom_type
        df_encoded = pd.get_dummies(df, columns=['bottom_type'])
        feature_cols_encoded = [col for col in df_encoded.columns if col.startswith('bottom_type') or col in feature_cols]
        X = df_encoded[feature_cols_encoded]
        # Целевые переменные (можно выбрать одну или несколько)
        y = df_encoded[['suppression_dB', 'SNR_dB', 'error_rate_percent']]
        # Разбиение
        X_train, X_test, y_train, y_test = train_test_split(X, y, test_size=test_size, random_state=random_state)
        return {
            'X_train': X_train,
            'X_test': X_test,
            'y_train': y_train,
            'y_test': y_test,
            'feature_names': feature_cols_encoded,
            'target_names': ['suppression_dB', 'SNR_dB', 'error_rate_percent']
        }

# --- FUNC: plot_dataset_distribution ---
def plot_dataset_distribution(self):
        """Визуализирует распределение параметров и целевых переменных."""
        df = self.session_data["📊"].get("current_dataset")
        if df is None:
            print("Нет активного датасета.")
            return
        import matplotlib.pyplot as plt
        fig, axs = plt.subplots(3, 3, figsize=(15, 12))
