# --- FUNC: set_c ---
def set_c(self, new_c):
        self.c_eff = new_c

# --- FUNC: get_curvature ---
def get_curvature(self):
        """Возвращает поле кривизны."""
        return self.field

# --- FUNC: generate_field ---
def generate_field(self, num_states=50, dimensions=4, spread=1.0):
        """
        Создаёт облако состояний в N-мерном пространстве.
        Каждое состояние — это точка с координатами и весом (вероятностью).
        """
        # Генерируем случайные состояния (суперпозиция)
        states = []
        for _ in range(num_states):
            # Координаты в N-пространстве
            coords = np.random.randn(dimensions) * spread
            # Вес состояния (вероятность) — зависит от близости к резонансным частотам
            energy = np.linalg.norm(coords)
            resonance, _ = compute_resonance(energy)
            weight = 1.0 / (1 + np.abs(energy - 1.0))  # чем ближе к единице, тем выше вес
            if resonance:
                weight *= 1.5  # резонансные состояния усиливаются
            states.append({
                'coordinates': coords,
                'weight': weight,
                'energy': energy,
                'resonant': resonance,
                'id': len(states)
            })
        # Нормализуем веса
        total_weight = sum(s['weight'] for s in states)
        for s in states:
            s['weight'] /= total_weight
        self.states = states
        self.superposition_field = states
        return states

# --- FUNC: evolve_field ---
def evolve_field(self, steps=50, dt=0.01):
        """
        Эволюционирует поле по нелинейному уравнению Шрёдингера с
        самодействием (фокусировка, рассеяние).
        Используется спектральный метод (FFT).
        """
        if self.psi is None:
            self.generate_field()

        # Преобразование Фурье
        kx = np.fft.fftfreq(self.N, d=self.x[1]-self.x[0]) * 2*np.pi
        ky = np.fft.fftfreq(self.N, d=self.y[1]-self.y[0]) * 2*np.pi
        KX, KY = np.meshgrid(kx, ky)
        K2 = KX**2 + KY**2

        psi_k = np.fft.fft2(self.psi)
        for _ in range(steps):
            # Нелинейный член: |ψ|² ψ (в реальном пространстве)
            psi_real = np.fft.ifft2(psi_k)
            nl = np.abs(psi_real)**2 * psi_real
            # Переход в Фурье-пространство
            nl_k = np.fft.fft2(nl)
            # Эволюция с учётом дисперсии и нелинейности
            # ∂ψ/∂t = i(∇²ψ + |ψ|²ψ) (без коэффициентов)
            psi_k = psi_k * (1 - 1j * dt * K2) - 1j * dt * nl_k
            # Нормализация (сохранение энергии)
            psi_k = psi_k / np.sqrt(np.mean(np.abs(psi_k)**2))

        self.psi = np.fft.ifft2(psi_k)
        return self.psi

# --- FUNC: observer_sync ---
def observer_sync(self, resonance_index=0):
        """
        Наблюдатель синхронизируется с фазой выбранного резонанса.
        Это создаёт «дыхание» поля в такт с наблюдателем.
        """
        if not self.resonances:
            return
        if resonance_index >= len(self.resonances):
            resonance_index = 0
        res = self.resonances[resonance_index]
        self.observer_phase = res['phase']
        # Модуляция поля: добавляем синхронную осцилляцию
        if self.psi is not None:
            mod = np.exp(1j * 0.1 * np.sin(self.observer_phase))
            self.psi = self.psi * mod
        return self.observer_phase

# --- FUNC: evolve_full ---
def evolve_full(self, steps=50, coupling=0.15, hbar=0.05, metric_strength=0.1,
                    love_strength=0.1, entanglement_strength=0.0):
        """
        Эволюция системы с учётом поля любви как модулирующего фактора.
        """
        if not self.E_resonators or not self.B_resonators:
            print("Добавьте E и B резонаторы.")
            return

        # Обновляем поле любви (медленно меняется, но может быть направлена намерением)
        self.love_field = 0.5 + 0.5 * np.sin(0.1 * self.time_ticks * PHI)
        self.love_field += self.intention * 0.5
        self.love_field = np.clip(self.love_field, 0.1, 1.0)

        e_clock = self.E_resonators[0]
        b_clock = self.B_resonators[0]
        rel_time = self.RelationalTime(e_clock, b_clock, hbar=hbar)

        for step in range(steps):
            tick = rel_time.tick()
            dt = rel_time.get_dt()
            if dt is None or dt == 0:
                continue

            # Замедление времени от кривизны и любви (любовь ускоряет/замедляет)
            curv_avg = np.mean(self.metric.field)
            love_avg = np.mean(self.love_field)
            # Любовь может ускорять время (anti-gravity эффект)
            curvature_factor = 1.0 / (1.0 + metric_strength * curv_avg - love_strength * love_avg)
            dt = dt * curvature_factor

            # 1. Обновляем метрику от энергии
            self.update_metric(dt)

            # 2. Гравитационное красное смещение
            for e in self.E_resonators + self.B_resonators:
                curv_local = self._get_curvature_at(e.x, e.y)
                # Любовь также влияет на частоту (эффект «омоложения»)
                love_local = self.love_field[int(e.y * self.N / 10 + self.N//2), int(e.x * self.N / 10 + self.N//2)]
                e.apply_redshift(curv_local, strength=metric_strength)
                # Дополнительный сдвиг от любви
                e.freq *= (1.0 + love_strength * love_local * 0.1)

            # 3. Переток E-B с учётом метрики и любви
            for e in self.E_resonators:
                for b in self.B_resonators:
                    phase_shift = (metric_strength * curv_avg - love_strength * love_avg) * dt
                    e.phase += phase_shift
                    b.phase += phase_shift

                    delta_phase = e.phase - b.phase
                    transfer = coupling * np.sin(delta_phase) * dt
                    e_energy = e.amp**2
                    b_energy = b.amp**2
                    if e_energy > 0 and b_energy > 0:
                        e.amp = np.sqrt(max(0, e_energy - transfer))
                        b.amp = np.sqrt(max(0, b_energy + transfer))
                    elif e_energy > 0 and b_energy == 0:
                        b.amp = np.sqrt(e_energy)
                        e.amp = 0
                    elif b_energy > 0 and e_energy == 0:
                        e.amp = np.sqrt(b_energy)
                        b.amp = 0
                    e.tick(dt)
                    b.tick(dt)

            # 4. Квантовая запутанность
            if entanglement_strength > 0:
                all_res = self.E_resonators + self.B_resonators
                for i in range(len(all_res)):
                    for j in range(i+1, len(all_res)):
                        r1, r2 = all_res[i], all_res[j]
                        dist = np.hypot(r1.x - r2.x, r1.y - r2.y)
                        if dist < 0.5:
                            avg_phase = (r1.phase + r2.phase) / 2
                            r1.phase += entanglement_strength * (avg_phase - r1.phase) * dt
                            r2.phase += entanglement_strength * (avg_phase - r2.phase) * dt

            # 5. Влияние любви на самосогласованность поля
            # Любовь увеличивает амплитуды резонансов (усиление когерентности)
            for e in self.E_resonators + self.B_resonators:
                love_local = self.love_field[int(e.y * self.N / 10 + self.N//2), int(e.x * self.N / 10 + self.N//2)]
                e.amp *= (1.0 + love_strength * love_local * 0.01 * dt)
                e.amp = min(e.amp, 3.0)

            # 6. Обновление поля
            self._update_field_from_EM()
            self.time_ticks += 1

        print(f"✅ Эволюция завершена. Тиков: {rel_time.ticks:.2f}")
        return self.psi

# --- FUNC: plot_field ---
def plot_field(self, show_resonances=True):
        if self.psi is None:
            print("Поле не создано.")
            return
        fig, axs = plt.subplots(2, 2, figsize=(12, 10))
        im1 = axs[0,0].imshow(np.abs(self.psi).T, extent=[self.x.min(), self.x.max(),
                                                          self.y.min(), self.y.max()],
                              origin='lower', cmap='viridis')
        axs[0,0].set_title('Амплитуда поля |ψ|')
        plt.colorbar(im1, ax=axs[0,0])

        im2 = axs[0,1].imshow(self.metric.field, extent=[self.x.min(), self.x.max(),
                                                         self.y.min(), self.y.max()],
                              origin='lower', cmap='plasma')
        axs[0,1].set_title('Кривизна (гравитация)')
        plt.colorbar(im2, ax=axs[0,1])

        im3 = axs[1,0].imshow(self.love_field, extent=[self.x.min(), self.x.max(),
                                                       self.y.min(), self.y.max()],
                              origin='lower', cmap='Reds')
        axs[1,0].set_title('Поле любви')
        plt.colorbar(im3, ax=axs[1,0])

        # Карта частот
        f_map = np.zeros((self.N, self.N))
        for e in self.E_resonators + self.B_resonators:
            ix = int((e.x - self.x.min()) / (self.x.max() - self.x.min()) * self.N)
            iy = int((e.y - self.y.min()) / (self.y.max() - self.y.min()) * self.N)
            ix = np.clip(ix, 0, self.N-1)
            iy = np.clip(iy, 0, self.N-1)
            f_map[iy, ix] += e.freq
        im4 = axs[1,1].imshow(f_map, extent=[self.x.min(), self.x.max(),
                                             self.y.min(), self.y.max()],
                              origin='lower', cmap='plasma')
        axs[1,1].set_title('Частоты (красное смещение + любовь)')
        plt.colorbar(im4, ax=axs[1,1])

        if show_resonances and self.resonances:
            for res in self.resonances:
                axs[0,0].scatter(res['x'], res['y'], c='red', s=50, marker='o')
                axs[0,1].scatter(res['x'], res['y'], c='red', s=50, marker='o')
        plt.tight_layout()
        plt.show()

