# --- FUNC: _get_curvature_at ---
def _get_curvature_at(self, x, y):
        """Билинейная интерполяция поля кривизны в точке (x,y)."""
        # Преобразуем координаты в индексы сетки
        i = int((x - self.x.min()) / (self.x[1] - self.x[0]))
        j = int((y - self.y.min()) / (self.y[1] - self.y[0]))
        i = max(0, min(self.N-2, i))
        j = max(0, min(self.N-2, j))
        # Билинейная интерполяция
        x1 = self.x[i]; x2 = self.x[i+1]
        y1 = self.y[j]; y2 = self.y[j+1]
        fx = (x - x1) / (x2 - x1) if x2 != x1 else 0
        fy = (y - y1) / (y2 - y1) if y2 != y1 else 0
        f00 = self.metric.field[i, j]
        f10 = self.metric.field[i+1, j] if i+1 < self.N else f00
        f01 = self.metric.field[i, j+1] if j+1 < self.N else f00
        f11 = self.metric.field[i+1, j+1] if i+1 < self.N and j+1 < self.N else f00
        return (1-fx)*(1-fy)*f00 + fx*(1-fy)*f10 + (1-fx)*fy*f01 + fx*fy*f11

# --- FUNC: generate_data ---
def generate_data(self, num_samples=500):
        """
        Генерирует данные: параметры столкновения → характеристики гравитационной волны.
        """
        X = []  # признаки: energy, phi_phase, sqrt5_phase, gamma_phase, mass_gap
        y_amp = []  # амплитуда волны
        y_freq = []  # частота волны
        y_spectrum = []  # спектр (вектор из 10 частот)

        for _ in range(num_samples):
            # Случайные параметры столкновения
            energy = np.random.uniform(100, 5000)  # ГэВ
            phi_phase = np.random.uniform(0, 2*np.pi)
            sqrt5_phase = np.random.uniform(0, 2*np.pi)
            gamma_phase = np.random.uniform(0, 2*np.pi)
            mass_gap = np.random.uniform(0.1, 2.0)  # массовая щель (из предыдущей модели)

            # Эвристика: амплитуда гравитационной волны
            # ~ энергия * sin(фазы) / (1 + массовая щель)
            amp = energy * np.sin(phi_phase) * 0.001 / (1 + mass_gap)
            amp = max(0.01, amp)  # минимальная амплитуда

            # Частота ~ энергия * φ / √5 (резонанс)
            freq = energy * self.phi / self.sqrt5 * 0.01
            freq = max(0.1, freq)

            # Спектр: набор из 10 частот (гармоники)
            spectrum = []
            for i in range(1, 11):
                f = freq * i + np.random.normal(0, 0.1 * freq)
                spectrum.append(max(0.1, f))

            # Сохраняем
            X.append([energy, phi_phase, sqrt5_phase, gamma_phase, mass_gap])
            y_amp.append(amp)
            y_freq.append(freq)
            y_spectrum.append(spectrum)

        X = np.array(X)
        y_amp = np.array(y_amp)
        y_freq = np.array(y_freq)
        y_spectrum = np.array(y_spectrum)

        return X, y_amp, y_freq, y_spectrum

# --- FUNC: plot_predictions ---
def plot_predictions(self, num_samples=10):
        """
        Показывает сравнение реальных и предсказанных значений для нескольких примеров.
        """
        if self.model_amp is None:
            self.train()

        X, y_amp, y_freq, y_spectrum = self.generate_data(num_samples)
        X_scaled = self.scaler.transform(X)

        amp_pred = self.model_amp.predict(X_scaled)
        freq_pred = self.model_freq.predict(X_scaled)

        fig, axs = plt.subplots(2, 2, figsize=(12, 10))

        # Амплитуда
        axs[0,0].scatter(y_amp, amp_pred, alpha=0.6)
        axs[0,0].plot([y_amp.min(), y_amp.max()], [y_amp.min(), y_amp.max()], 'r--')
        axs[0,0].set_title('Амплитуда (предсказание vs реальность)')
        axs[0,0].set_xlabel('Реальная')
        axs[0,0].set_ylabel('Предсказанная')

        # Частота
        axs[0,1].scatter(y_freq, freq_pred, alpha=0.6)
        axs[0,1].plot([y_freq.min(), y_freq.max()], [y_freq.min(), y_freq.max()], 'r--')
        axs[0,1].set_title('Частота (предсказание vs реальность)')
        axs[0,1].set_xlabel('Реальная')
        axs[0,1].set_ylabel('Предсказанная')

        # Гистограмма ошибок для амплитуды
        amp_error = y_amp - amp_pred
        axs[1,0].hist(amp_error, bins=20, alpha=0.7)
        axs[1,0].set_title('Ошибка предсказания амплитуды')
        axs[1,0].set_xlabel('Ошибка')
        axs[1,0].set_ylabel('Частота')

        # Спектр (для одного примера)
        if num_samples > 0:
            idx = 0
            real_spectrum = y_spectrum[idx]
            pred_spectrum = self.model_spectrum.predict(X_scaled[idx:idx+1])[0]
            axs[1,1].plot(range(1, 11), real_spectrum, 'o-', label='Реальный')
            axs[1,1].plot(range(1, 11), pred_spectrum, 's-', label='Предсказанный')
            axs[1,1].set_title('Спектр (пример)')
            axs[1,1].set_xlabel('Мода')
            axs[1,1].set_ylabel('Частота')
            axs[1,1].legend()

        plt.tight_layout()
        plt.show()

