# --- FUNC: _compute_coherence ---
def _compute_coherence(self):
        """Суммарная амплитуда всех резонаторов (мера когерентности)."""
        return sum(r.amp for r in self.E_resonators + self.B_resonators)

# --- FUNC: save_state ---
def save_state(self):
        """Сохраняет текущие состояния всех резонаторов в буфер."""
        state = {
            'time': self.time_ticks,
            'resonators': []
        }
        for e in self.E_resonators + self.B_resonators:
            state['resonators'].append({
                'freq': e.freq,
                'amp': e.amp,
                'phase': e.phase,
                'kind': e.kind,
                'x': e.x,
                'y': e.y,
                'z': e.z,
                'k': e.k,
                'c_eff': e.get_c()
            })
        self.state_buffer.append(state)
        if len(self.state_buffer) > 100:
            self.state_buffer.pop(0)
        print(f"💾 Состояние сохранено в буфер. Всего записей: {len(self.state_buffer)}")

# --- FUNC: time_stretch ---
def time_stretch(self, idx=-1, target_time=None):
        """
        Применяет состояние из буфера (по индексу idx или по времени) к текущим резонаторам.
        idx: -1 — последнее, 0 — самое раннее, и т.д.
        target_time: если указано, выбирается состояние, ближайшее к этому времени.
        Это имитирует «движение назад» во времени.
        """
        if not self.state_buffer:
            print("⚠️ Буфер пуст. Сначала сохраните состояние (save_state).")
            return

        if target_time is not None:
            closest = min(self.state_buffer, key=lambda s: abs(s['time'] - target_time))
            past_state = closest
            print(f"⏳ Выбрано состояние с временем {past_state['time']:.2f} (ближайшее к {target_time})")
        else:
            if idx < 0:
                idx = len(self.state_buffer) + idx
            idx = max(0, min(idx, len(self.state_buffer)-1))
            past_state = self.state_buffer[idx]
            print(f"⏳ Выбрано состояние из буфера с индексом {idx}, время {past_state['time']:.2f}")

        applied = 0
        for res_data in past_state['resonators']:
            for e in self.E_resonators + self.B_resonators:
                if (abs(e.x - res_data['x']) < 1e-6 and
                    abs(e.y - res_data['y']) < 1e-6 and
                    abs(e.z - res_data['z']) < 1e-6 and
                    e.kind == res_data['kind']):
                    e.freq = res_data['freq']
                    e.amp = res_data['amp']
                    e.phase = res_data['phase']
                    e.k = res_data['k']
                    applied += 1
                    break

        print(f"✅ Применено состояние для {applied} резонаторов из {len(past_state['resonators'])} сохранённых.")
        self._update_field_from_EM()

# --- FUNC: optimize_coherence ---
def optimize_coherence(self, steps=50, learning_rate=0.01, delta=0.001):
    """
    Оптимизация параметров (частот и амплитуд) для максимизации когерентности.
    Когерентность = средняя амплитуда поля в центре (или сумма амплитуд резонансов).
    """
    all_res = self.E_resonators + self.B_resonators
    if not all_res:
        print("Нет резонаторов для оптимизации.")
        return

    # Целевая функция: средняя амплитуда поля (в центре)
    def objective():
        self._update_field_from_EM()
        center = self.N//2, self.N//2, self.Nz//2
        return np.abs(self.psi[center]) if self.psi is not None else 0.0

    for step in range(steps):
        # Вычисляем градиенты для каждого резонатора
        grads = []
        for i, res in enumerate(all_res):
            # Градиент по частоте
            res.freq += delta
            f1 = objective()
            res.freq -= 2*delta
            f2 = objective()
            res.freq += delta  # возвращаем обратно
            grad_f = (f1 - f2) / (2*delta)

            # Градиент по амплитуде
            res.amp += delta
            a1 = objective()
            res.amp -= 2*delta
            a2 = objective()
            res.amp += delta
            grad_a = (a1 - a2) / (2*delta)

            grads.append((grad_f, grad_a))

        # Обновляем параметры в сторону увеличения когерентности
        for i, res in enumerate(all_res):
            grad_f, grad_a = grads[i]
            res.freq += learning_rate * grad_f
            res.amp += learning_rate * grad_a
            # Ограничиваем, чтобы не улететь
            res.freq = max(0.1, min(3.0, res.freq))
            res.amp = max(0.1, min(2.0, res.amp))

        # Обновляем поле после изменений
        self._update_field_from_EM()

        if step % 10 == 0:
            print(f"Шаг {step}, когерентность = {objective():.4f}")

    print("✅ Оптимизация завершена.")

# --- FUNC: heart_coherence_step ---
def heart_coherence_step(self, heart_rate=1.0, intensity=0.5):
        """
        Моделирует влияние когерентного сердечного ритма на поле.
        Увеличивает амплитуды резонаторов пропорционально интенсивности и синхронизирует фазы.
        """
        self.heart_rate = heart_rate
        self.coherence = intensity

        # Влияние на амплитуды: усиление в зоне сердца (центр)
        cx, cy = 0.0, 0.0
        for e in self.E_resonators + self.B_resonators:
            dist = np.hypot(e.x - cx, e.y - cy)
            factor = 1.0 + intensity * 0.5 * np.exp(-dist**2 / 1.0)
            e.amp *= factor
            e.amp = min(e.amp, 3.0)
            # Синхронизация фаз с сердечным ритмом
            phase_shift = heart_rate * intensity * 0.1
            e.phase += phase_shift

        self._update_field_from_EM()
        print(f"💖 Сердечная когерентность: частота {heart_rate:.2f}, интенсивность {intensity:.2f}")

# --- FUNC: plot_freq_map ---
def plot_freq_map(self, grid_resolution=50):
        """Визуализация распределения частот резонаторов."""
        freq_map = np.zeros((grid_resolution, grid_resolution))
        x = np.linspace(self.x.min(), self.x.max(), grid_resolution)
        y = np.linspace(self.y.min(), self.y.max(), grid_resolution)
        X, Y = np.meshgrid(x, y)
        for i in range(grid_resolution):
            for j in range(grid_resolution):
                freq_vals = []
                for e in self.E_resonators + self.B_resonators:
                    dist = np.sqrt((X[i,j] - e.x)**2 + (Y[i,j] - e.y)**2)
                    if dist < 2.0:
                        freq_vals.append(e.freq * np.exp(-dist**2 / 0.5))
                freq_map[i,j] = np.mean(freq_vals) if freq_vals else 0
        plt.imshow(freq_map, extent=[x.min(), x.max(), y.min(), y.max()],
                   origin='lower', cmap='plasma')
        plt.title('Распределение частот (гравитационное красное смещение)')
        plt.colorbar(label='f')
        plt.show()

# --- FUNC: plot_heart_coherence ---
def plot_heart_coherence(self):
        """Визуализирует состояние сердечной когерентности."""
        fig, ax = plt.subplots(figsize=(6,4))
        # Сигнал сердца: когерентный ритм
        t = np.linspace(0, 2, 200)
        signal = np.sin(2*np.pi*self.heart_rate*t) * (0.5 + 0.5*self.coherence)
        # Добавляем шум, если когерентность низкая
        noise = (1 - self.coherence) * np.random.normal(0, 0.2, len(t))
        signal += noise
        ax.plot(t, signal, color='red', linewidth=2)
        ax.set_title(f'Сердечный ритм (когерентность: {self.coherence:.2f})')
        ax.set_xlabel('Время')
        ax.set_ylabel('Амплитуда')
        ax.grid(True)
        plt.show()

