# --- FUNC: register_platform ---
def register_platform(self, name: str, platform_type: str, frequency: float,
                          coupling: float = None, decoherence: float = None) -> Dict:
        """
        Регистрирует новую квантовую платформу с заданными параметрами.
        Возвращает словарь с описанием платформы.
        """
        if platform_type not in self.platform_models:
            return {"error": f"Неизвестный тип платформы: {platform_type}"}
        model = self.platform_models[platform_type]
        platform = {
            "name": name,
            "type": platform_type,
            "frequency": frequency,
            "coupling": coupling or model["coupling_strength"],
            "decoherence": decoherence or model["decoherence"],
            "model": model
        }
        self.session_data["🔗"]["platforms"][name] = platform
        return platform

# --- FUNC: build_phonon_bridge ---
def build_phonon_bridge(self, platform1: str, platform2: str, crystal_id: str = None) -> Dict:
        """
        Строит мост между двумя платформами через фононный кристалл.
        Вычисляет эффективность передачи (фиделити) на основе резонанса.
        """
        p1 = self.session_data["🔗"]["platforms"].get(platform1)
        p2 = self.session_data["🔗"]["platforms"].get(platform2)
        if not p1 or not p2:
            return {"error": "Одна из платформ не найдена"}

        # Частоты платформ
        f1 = p1["frequency"]
        f2 = p2["frequency"]
        # Получаем спектр кристалла (если указан)
        crystal_spectrum = None
        if crystal_id:
            spectrum = self.get_phonon_spectrum(crystal_id)
            if "frequencies" in spectrum:
                # Берём среднюю частоту как резонансную
                all_freqs = []
                for k_freqs in spectrum["frequencies"]:
                    all_freqs.extend(k_freqs)
                if all_freqs:
                    crystal_spectrum = np.mean(all_freqs)

        # Резонанс: если частоты платформ близки к частоте кристалла или друг к другу
        if crystal_spectrum:
            # Мост работает хорошо, если частота кристалла близка к среднему геометрическому частот
            target = np.sqrt(f1 * f2)
            detuning = abs(crystal_spectrum - target) / target
            fidelity = 1.0 / (1 + detuning * 10)  # простая модель
        else:
            # Прямое взаимодействие (без кристалла) зависит от близости частот
            detuning = abs(f1 - f2) / max(f1, f2)
            fidelity = 1.0 / (1 + detuning * 5)

        # Учитываем декогеренцию платформ
        decoherence_factor = 1 - (p1["decoherence"] + p2["decoherence"]) / 2
        fidelity *= decoherence_factor

        bridge = {
            "platform1": platform1,
            "platform2": platform2,
            "crystal_id": crystal_id,
            "fidelity": fidelity,
            "detuning": detuning,
            "timestamp": datetime.now().isoformat()
        }
        self.session_data["🔗"]["bridges"].append(bridge)
        return bridge

# --- FUNC: transmit_quantum_state ---
def transmit_quantum_state(self, source: str, target: str, state: np.ndarray, crystal_id: str = None) -> Dict:
        """
        Моделирует передачу квантового состояния (вектора или матрицы плотности)
        от источника к цели через фононный мост.
        Возвращает конечное состояние и фиделити.
        """
        bridge = self.build_phonon_bridge(source, target, crystal_id)
        if "error" in bridge:
            return bridge
        fidelity = bridge["fidelity"]

        # Простая модель: состояние поворачивается на угол, зависящий от частот
        p1 = self.session_data["🔗"]["platforms"][source]
        p2 = self.session_data["🔗"]["platforms"][target]
        phase = (p1["frequency"] - p2["frequency"]) * 0.1  # условно
        # Применяем унитарный оператор вращения к состоянию
        if state.shape[0] == 2:  # кубит
            rotation = expm(-1j * phase * np.array([[0, 1], [1, 0]]) / 2)
            final_state = rotation @ state
        else:
            # Для матриц плотности (2x2)
            if state.shape == (2, 2):
                rotation = expm(-1j * phase * np.array([[0, 1], [1, 0]]) / 2)
                final_state = rotation @ state @ rotation.conj().T
            else:
                final_state = state * fidelity  # упрощённо

        # Добавляем шум от декогеренции
        noise = (1 - fidelity) * np.random.randn(*final_state.shape) * 0.1
        final_state = final_state + noise
        # Нормируем (для векторов)
        if final_state.ndim == 1:
            final_state = final_state / np.linalg.norm(final_state)

        # Сохраняем в лог
        self.session_data["🔗"]["transmission_log"].append({
            "source": source,
            "target": target,
            "fidelity": fidelity,
            "final_state": final_state.tolist(),
            "crystal_id": crystal_id,
            "timestamp": datetime.now().isoformat()
        })
        return {"final_state": final_state, "fidelity": fidelity}

# --- FUNC: optimize_phonon_bridge ---
def optimize_phonon_bridge(self, platform1: str, platform2: str, iterations: int = 10) -> Dict:
        """
        Использует эволюцию для поиска оптимальной частоты кристалла и когерентности,
        чтобы максимизировать фиделити передачи между двумя платформами.
        """
        # Определяем fitness: фиделити передачи
        def fitness(crystal_freq, coherence):
            # Создаём временный кристалл с заданной частотой (для простоты)
            # В реальности нужно создать кристалл с нужным спектром
            # Здесь мы эмулируем: используем фиктивный кристалл
            bridge = self.build_phonon_bridge(platform1, platform2, None)  # без кристалла
            # Корректируем фиделити на основе частоты и когерентности
            base_fidelity = bridge["fidelity"]
            # Чем ближе частота к резонансу, тем выше фиделити
            f1 = self.session_data["🔗"]["platforms"][platform1]["frequency"]
            f2 = self.session_data["🔗"]["platforms"][platform2]["frequency"]
            target = np.sqrt(f1 * f2)
            detuning = abs(crystal_freq - target) / target
            fidelity = base_fidelity / (1 + detuning * 5)
            # Когерентность усиливает передачу
            fidelity *= (1 + coherence * 0.5)
            return fidelity

        # Генерация начальной популяции
        population = []
        for _ in range(10):
            crystal_freq = np.random.uniform(0.5, 5.0)
            coherence = np.random.uniform(0.1, 1.0)
            population.append({"crystal_freq": crystal_freq, "coherence": coherence})

        best_fitness = -float('inf')
        best_individual = None
        for gen in range(iterations):
            # Оценка
            fitnesses = []
            for ind in population:
                fit = fitness(ind["crystal_freq"], ind["coherence"])
                fitnesses.append(fit)
                if fit > best_fitness:
                    best_fitness = fit
                    best_individual = ind.copy()
            # Отбор и мутация (упрощённо)
            new_population = []
            for _ in range(10):
                idx1 = np.random.choice(range(len(population)), p=np.array(fitnesses)/sum(fitnesses))
                idx2 = np.random.choice(range(len(population)), p=np.array(fitnesses)/sum(fitnesses))
                child = {
                    "crystal_freq": (population[idx1]["crystal_freq"] + population[idx2]["crystal_freq"]) / 2,
                    "coherence": (population[idx1]["coherence"] + population[idx2]["coherence"]) / 2
                }
                # Мутация
                if np.random.rand() < 0.2:
                    child["crystal_freq"] += np.random.uniform(-0.5, 0.5)
                    child["crystal_freq"] = max(0.1, child["crystal_freq"])
                    child["coherence"] += np.random.uniform(-0.1, 0.1)
                    child["coherence"] = max(0.0, min(1.0, child["coherence"]))
                new_population.append(child)
            population = new_population

        # Создаём оптимальный кристалл с найденной частотой (для демонстрации)
        # В реальности нужно построить кристалл с нужным спектром
        # Мы сохраняем параметры как "виртуальный" кристалл
        self.session_data["🔗"]["optimized_bridge"] = {
            "platform1": platform1,
            "platform2": platform2,
            "crystal_freq": best_individual["crystal_freq"],
            "coherence": best_individual["coherence"],
            "fitness": best_fitness
        }
        return {"best_individual": best_individual, "best_fitness": best_fitness}

# --- FUNC: plot_hybrid_circuit ---
def plot_hybrid_circuit(self):
        """
        Визуализирует граф платформ и связей между ними (фононные мосты).
        """
        try:
            import networkx as nx
            import matplotlib.pyplot as plt
        except ImportError:
            print("networkx или matplotlib не установлены")
            return

        G = nx.Graph()
        platforms = self.session_data["🔗"]["platforms"]
        for name in platforms:
            G.add_node(name, type=platforms[name]["type"])
        for bridge in self.session_data["🔗"]["bridges"]:
            p1 = bridge["platform1"]
            p2 = bridge["platform2"]
            if p1 in platforms and p2 in platforms:
                G.add_edge(p1, p2, weight=bridge["fidelity"])

        pos = nx.spring_layout(G)
        plt.figure(figsize=(10, 8))
        nx.draw(G, pos, with_labels=True, node_color='lightblue',
                node_size=2000, font_size=12, font_weight='bold')
        # Рисуем веса рёбер
        labels = nx.get_edge_attributes(G, 'weight')
        nx.draw_networkx_edge_labels(G, pos, edge_labels={k: f"{v:.2f}" for k, v in labels.items()})
        plt.title("Гибридная квантовая сеть (фононные мосты)")
        plt.show()

# --- FUNC: generate_hybrid_code ---
def generate_hybrid_code(self, source: str, target: str, crystal_id: str = None) -> str:
        """
        Генерирует Python-код для реализации гибридной передачи на реальном оборудовании.
        """
        code = f"""
# Гибридный квантовый интерфейс: передача от {source} к {target}
# Используется кристалл: {crystal_id}

import numpy as np
from qiskit import QuantumCircuit, execute, Aer  # пример

def hybrid_transfer(state, source_freq, target_freq, crystal_freq):
    '''Модель передачи через фононный мост.'''
    # Вычисляем фиделити
    detuning = abs(crystal_freq - np.sqrt(source_freq * target_freq)) / np.sqrt(source_freq * target_freq)
    fidelity = 1.0 / (1 + detuning * 10)
    # Применяем вращение
    phase = (source_freq - target_freq) * 0.1
    rotation = np.exp(-1j * phase * np.array([[0, 1], [1, 0]]) / 2)
    final_state = rotation @ state
    return final_state * fidelity

def main():
    # Параметры платформ
    source_freq = {self.session_data["🔗"]["platforms"][source]["frequency"]}
    target_freq = {self.session_data["🔗"]["platforms"][target]["frequency"]}
    crystal_freq = {self.session_data["🔗"]["optimized_bridge"]["crystal_freq"] if "optimized_bridge" in self.session_data["🔗"] else 1.0}
    # Исходное состояние кубита |0>
    state = np.array([1, 0])
    # Передача
    final = hybrid_transfer(state, source_freq, target_freq, crystal_freq)
    print(f"Состояние после передачи: {final}")

if __name__ == "__main__":
    main()
"""
        return code

# --- FUNC: check_phononic_tweezers ---
def check_phononic_tweezers(self, field_data):
        """
        Проверяет, соответствуют ли частоты пинцета гармоникам.
        """
        freqs = np.array(field_data.get('frequencies', []))
        if len(freqs) == 0:
            return {'status': 'no_data'}
        # Проверка соотношений
        ratios = []
        for f in freqs:
            for c in [self.phi, self.sqrt5, self.gamma]:
                ratios.append(f / c)
        # Ищем близость к целым числам
        deviations = np.abs(ratios - np.round(ratios))
        avg_dev = np.mean(deviations)
        return {
            'status': 'ok' if avg_dev < 0.1 else 'warning',
            'avg_deviation': avg_dev,
            'harmonic_consistency': avg_dev < 0.1
        }

# --- FUNC: check_neural_interface ---
def check_neural_interface(self, spike_data):
        """
        Проверяет, соответствуют ли спайки нейронов фононным частотам.
        """
        if not spike_data:
            return {'status': 'no_data'}
        inter_spike = np.diff(spike_data)
        if len(inter_spike) == 0:
            return {'status': 'no_data'}
        avg_isi = np.mean(inter_spike)
        # Характерные частоты нейронов ~1-100 Гц
        if 0.01 < avg_isi < 1.0:
            return {'status': 'ok', 'avg_isi': avg_isi}
        return {'status': 'warning', 'avg_isi': avg_isi}

# --- FUNC: check_collider ---
def check_collider(self, event_data):
        """
        Проверяет, совпадают ли энергии продуктов с ожидаемыми резонансами.
        """
        energies = event_data.get('product_energies', [])
        if not energies:
            return {'status': 'no_data'}
        ratios = np.array(energies) / self.phi
        deviations = np.abs(ratios - np.round(ratios))
        avg_dev = np.mean(deviations)
        return {
            'status': 'ok' if avg_dev < 0.15 else 'warning',
            'avg_deviation': avg_dev,
            'resonance_match': avg_dev < 0.15
        }

# --- FUNC: check_audio_interface ---
def check_audio_interface(self, spectrum_data):
        """
        Проверяет, содержит ли звуковой спектр пики на гармониках.
        """
        freqs = spectrum_data.get('frequencies', [])
        amps = spectrum_data.get('amplitudes', [])
        if len(freqs) == 0:
            return {'status': 'no_data'}
        # Ищем пики, близкие к φ, √5, γ и их кратным
        peaks = []
        for i in range(len(freqs)):
            if i > 0 and i < len(freqs)-1:
                if amps[i] > amps[i-1] and amps[i] > amps[i+1]:
                    peaks.append(freqs[i])
        harmonic_peaks = []
        for p in peaks:
            for c in [self.phi, self.sqrt5, self.gamma]:
                if abs(p / c - round(p / c)) < 0.1:
                    harmonic_peaks.append(p)
        return {
            'status': 'ok' if len(harmonic_peaks) > 0 else 'warning',
            'harmonic_peaks': harmonic_peaks,
            'num_peaks': len(harmonic_peaks)
        }

# --- FUNC: full_report ---
def full_report(self):
        """
        Генерирует общий отчёт о согласованности всей системы.
        """
        report = {
            'timestamp': datetime.now().isoformat(),
            'modules': {
                'phononic_tweezers': self.check_phononic_tweezers({}),
                'neural_interface': self.check_neural_interface([]),
                'collider': self.check_collider({}),
                'audio_interface': self.check_audio_interface({})
            },
            'overall_status': 'consistent'
        }
        # Оценка общего статуса
        statuses = [m['status'] for m in report['modules'].values() if m['status'] != 'no_data']
        if all(s == 'ok' for s in statuses):
            report['overall_status'] = 'fully_consistent'
        elif any(s == 'warning' for s in statuses):
            report['overall_status'] = 'partially_consistent'
        else:
            report['overall_status'] = 'inconsistent'
        return report

# --- FUNC: run_phononic_experiment ---
def run_phononic_experiment(self, num_cells: int = 3):
        """
        Запускает эксперимент с множественными фононными пинцетами.
        """
        platform = MultiTargetPhononicPlatform(self.medium)
        ani = platform.run_experiment(num_targets=num_cells)
        return platform, ani

# --- FUNC: generate_beam ---
def generate_beam(self, direction='+x'):
        """
        Генерирует пучок мионов с заданным направлением.
        Возвращает список частиц с координатами, импульсами и временем жизни.
        """
        beam = []
        # Мионы имеют массу ~105 МэВ, импульс p = sqrt(E^2 - m^2)
        mass = 105.6  # МэВ
        total_energy = self.energy * 1000  # переводим в МэВ
        momentum = np.sqrt(total_energy**2 - mass**2)
        # Добавляем случайные отклонения (эмиттанс)
        for _ in range(self.num_particles):
            # Начальная позиция (разброс по поперечному сечению)
            x0 = np.random.normal(0, 0.001)  # мм
            y0 = np.random.normal(0, 0.001)
            z0 = np.random.normal(0, 0.001)
            # Импульс с небольшим разбросом
            px = momentum * np.random.normal(1, 0.01)
            py = np.random.normal(0, 0.01 * momentum)
            pz = np.random.normal(0, 0.01 * momentum)
            if direction == '-x':
                px = -px
            # Время жизни миона ~2.2 мкс (в системе покоя), но в релятивистском случае удлиняется
            lifetime = 2.2e-6 * (total_energy / mass)  # в секундах
            particle = {
                'pos': np.array([x0, y0, z0]),
                'mom': np.array([px, py, pz]),
                'energy': total_energy,
                'mass': mass,
                'lifetime': lifetime,
                'direction': direction,
                'active': True,
                'track': [np.array([x0, y0, z0])]
            }
            beam.append(particle)
        return beam

# --- FUNC: collide_beams ---
def collide_beams(self, beam1, beam2):
        """
        Проводит столкновение двух пучков. Для каждой пары частиц
        рассчитывает вероятность взаимодействия и генерирует продукты.
        """
        products = []
        for p1 in beam1:
            for p2 in beam2:
                if not p1['active'] or not p2['active']:
                    continue
                # Расстояние между частицами в момент встречи (Z = 0)
                dx = p1['pos'][0] - p2['pos'][0]
                dy = p1['pos'][1] - p2['pos'][1]
                dz = p1['pos'][2] - p2['pos'][2]
                if abs(dz) > 0.001:
                    continue
                # Вероятность взаимодействия зависит от энергии и перекрытия
                overlap = np.exp(-(dx**2 + dy**2) / (0.01**2))
                prob = 0.01 * (1 + 0.5 * np.sin(self.phi * self.energy / 1000))
                if np.random.rand() < prob * overlap:
                    # Рождение новых частиц (пионы, каоны, фотоны)
                    products.extend(self._generate_products(p1, p2))
        return products

# --- FUNC: _generate_products ---
def _generate_products(self, p1, p2):
        """
        Моделирует рождение вторичных частиц.
        Использует резонансы с φ, √5, γ для определения спектра.
        """
        products = []
        total_energy = p1['energy'] + p2['energy']
        # Количество продуктов зависит от энергии (резонансный пик при энергии кратной φ)
        n_products = int(2 + 5 * np.sin(total_energy / (self.phi * 1000))**2)
        for _ in range(n_products):
            # Тип частицы
            types = ['pion', 'kaon', 'photon', 'muon', 'electron']
            # Вероятности зависят от энергии
            probs = [
                0.3 + 0.1 * np.sin(total_energy / (self.sqrt5 * 1000)),
                0.2 + 0.1 * np.cos(total_energy / (self.gamma * 1000)),
                0.2 + 0.1 * np.sin(self.Lambda * total_energy),
                0.1,
                0.1
            ]
            probs = np.array(probs) / np.sum(probs)
            ptype = np.random.choice(types, p=probs)
            # Масса и энергия продукта
            masses = {
                'pion': 139.6,
                'kaon': 493.7,
                'photon': 0,
                'muon': 105.6,
                'electron': 0.511
            }
            mass = masses[ptype]
            energy_frac = np.random.uniform(0.1, 0.8)
            energy_prod = total_energy * energy_frac
            # Импульс
            if mass == 0:
                mom = energy_prod
            else:
                mom = np.sqrt(energy_prod**2 - mass**2)
            angle = np.random.uniform(0, 2*np.pi)
            theta = np.arccos(np.random.uniform(-1, 1))
            px = mom * np.sin(theta) * np.cos(angle)
            py = mom * np.sin(theta) * np.sin(angle)
            pz = mom * np.cos(theta)
            # Время жизни (очень малое для симуляции)
            lifetime = 1e-12 * (energy_prod / mass) if mass > 0 else 1e-15
            product = {
                'type': ptype,
                'pos': np.array([0, 0, 0]),
                'mom': np.array([px, py, pz]),
                'energy': energy_prod,
                'mass': mass,
                'lifetime': lifetime,
                'active': True,
                'track': [np.array([0, 0, 0])]
            }
            products.append(product)
        return products

# --- FUNC: simulate_detector ---
def simulate_detector(self, products, beam1, beam2):
        """
        Имитирует работу детектора: регистрирует треки, энергию, время.
        """
        hits = []
        # Регистрируем продукты
        for prod in products:
            if prod['active']:
                hit = {
                    'type': prod['type'],
                    'energy': prod['energy'],
                    'position': prod['pos'].copy(),
                    'momentum': prod['mom'].copy(),
                    'time': np.random.normal(0, 1e-12)
                }
                hits.append(hit)
        # Регистрируем оставшиеся первичные мионы
        for p in beam1 + beam2:
            if p['active']:
                hit = {
                    'type': 'muon',
                    'energy': p['energy'],
                    'position': p['pos'].copy(),
                    'momentum': p['mom'].copy(),
                    'time': np.random.normal(0, 1e-12)
                }
                hits.append(hit)
        self.hits = hits
        return hits

# --- FUNC: predict_products ---
def predict_products(self, energy, phi_phase, sqrt5_phase):
        """
        Предсказывает наиболее вероятный тип продукта.
        """
        if self.ml_model is None:
            self.train_ml_model()
        X_input = np.array([[energy, phi_phase, sqrt5_phase]])
        X_scaled = self.scaler.transform(X_input)
        pred = self.ml_model.predict(X_scaled)[0]
        types = ['pion', 'kaon', 'photon', 'muon', 'electron']
        return types[pred]

# --- FUNC: plot_collision ---
def plot_collision(self, beam1, beam2, products, hits):
        """
        3D-визуализация траекторий и детектированных частиц.
        """
        fig = plt.figure(figsize=(12, 8))
        ax = fig.add_subplot(111, projection='3d')

        # Первичные пучки
        for p in beam1:
            if p['active']:
                ax.plot([p['pos'][0], p['pos'][0] + p['mom'][0]*1e-12],
                        [p['pos'][1], p['pos'][1] + p['mom'][1]*1e-12],
                        [p['pos'][2], p['pos'][2] + p['mom'][2]*1e-12],
                        'b-', alpha=0.2)
        for p in beam2:
            if p['active']:
                ax.plot([p['pos'][0], p['pos'][0] + p['mom'][0]*1e-12],
                        [p['pos'][1], p['pos'][1] + p['mom'][1]*1e-12],
                        [p['pos'][2], p['pos'][2] + p['mom'][2]*1e-12],
                        'r-', alpha=0.2)

        # Продукты
        colors = {'pion': 'green', 'kaon': 'orange', 'photon': 'yellow',
                  'muon': 'purple', 'electron': 'cyan'}
        for prod in products:
            if prod['active']:
                color = colors.get(prod['type'], 'gray')
                ax.scatter(prod['pos'][0], prod['pos'][1], prod['pos'][2],
                           color=color, s=20, label=prod['type'])

        # Детектированные хиты
        for hit in hits:
            ax.scatter(hit['position'][0], hit['position'][1], hit['position'][2],
                       color='red', s=5, alpha=0.5)

        ax.set_xlabel('X (мм)')
        ax.set_ylabel('Y (мм)')
        ax.set_zlabel('Z (мм)')
        ax.set_title('Мионный коллайдер — виртуальный эксперимент')
        ax.legend()
        plt.show()

# --- FUNC: run_experiment ---
def run_experiment(self, visualize=True):
        """
        Запускает полный цикл: генерация, столкновение, детектирование, анализ.
        """
        print("Запуск виртуального мионного коллайдера...")
        print(f"Энергия: {self.energy} ГэВ, частиц в пучке: {self.num_particles}")

        # 1. Генерация пучков
        beam1 = self.generate_beam('+x')
        beam2 = self.generate_beam('-x')

        # 2. Столкновение
        products = self.collide_beams(beam1, beam2)
        print(f"Рождено продуктов: {len(products)}")

        # 3. Детектирование
        hits = self.simulate_detector(products, beam1, beam2)
        print(f"Зарегистрировано хитов: {len(hits)}")

        # 4. ML-анализ
        if self.ml_model is None:
            self.train_ml_model()
        # Предсказываем типы для каждого продукта (для проверки)
        predictions = []
        for prod in products:
            pred_type = self.predict_products(prod['energy'], self.phi, self.sqrt5)
            predictions.append(pred_type)
        print(f"ML-предсказания: {predictions[:5]}...")

        # 5. Визуализация
        if visualize:
            self.plot_collision(beam1, beam2, products, hits)

        return {'beam1': beam1, 'beam2': beam2, 'products': products, 'hits': hits}

# --- FUNC: gross_pitaevskii ---
def gross_pitaevskii(self, x, psi, mu):
        """
        Уравнение Гросса-Питаевского:
        -0.5 * psi'' + g * |psi|^2 * psi = mu * psi
        где mu — химический потенциал (собственное значение)
        """
        # Используем разностную схему для решения на сетке
        # Уравнение в дискретном виде: -0.5 * (psi_{i-1} - 2psi_i + psi_{i+1})/dx^2 + g * |psi_i|^2 * psi_i = mu * psi_i
        # Это нелинейное уравнение, решаем итерационно
        return None

# --- FUNC: solve_nonlinear_schrodinger ---
def solve_nonlinear_schrodinger(self, mu_guess, tol=1e-6, max_iter=100):
        """
        Решает нелинейное уравнение Шрёдингера итерационным методом.
        Возвращает волновую функцию для заданного химического потенциала mu_guess.
        """
        # Инициализация
        psi = np.exp(-self.x**2 / (2 * self.L/4))  # гауссовское начальное приближение
        psi = psi / np.linalg.norm(psi) * np.sqrt(self.dx)

        # Потенциал: добавляем стенки ящика (бесконечные на границах)
        V = np.zeros_like(self.x)
        # Самосогласованное решение
        for iteration in range(max_iter):
            # Строим эффективный потенциал
            V_eff = V + self.g * np.abs(psi)**2
            # Строим матрицу Гамильтониана
            H = np.zeros((self.N, self.N))
            for i in range(1, self.N-1):
                H[i, i-1] = -0.5 / self.dx**2
                H[i, i] = 1.0 / self.dx**2 + V_eff[i]
                H[i, i+1] = -0.5 / self.dx**2
            # Граничные условия (бесконечные стенки)
            H[0, 0] = 1.0 / self.dx**2 + V_eff[0]
            H[-1, -1] = 1.0 / self.dx**2 + V_eff[-1]
            # Диагонализация
            eigvals, eigvecs = eigh(H)
            # Выбираем моду с энергией, близкой к mu_guess
            idx = np.argmin(np.abs(eigvals - mu_guess))
            psi_new = eigvecs[:, idx]
            # Нормализация
            psi_new = psi_new / np.linalg.norm(psi_new) * np.sqrt(self.dx)
            # Проверка сходимости
            if np.linalg.norm(psi_new - psi) < tol:
                psi = psi_new
                break
            psi = psi_new
        # Вычисляем энергию (собственное значение)
        energy = eigvals[idx] if 'eigvals' in locals() else mu_guess
        return psi, energy

# --- FUNC: find_mass_gap ---
def find_mass_gap(self, num_levels=5):
        """
        Находит несколько первых собственных значений (энергетических уровней)
        и вычисляет массовую щель как разницу между первым возбуждённым и основным состоянием.
        """
        energies = []
        # Используем разные начальные приближения для mu
        guesses = np.linspace(0.1, 10.0, num_levels * 2)
        for mu_guess in guesses:
            psi, energy = self.solve_nonlinear_schrodinger(mu_guess)
            energies.append(energy)
        # Убираем дубликаты (сортируем)
        energies = sorted(set(round(e, 4) for e in energies))
        # Берём первые num_levels
        if len(energies) < num_levels:
            # Если мало, дорешаем с другими начальными условиями
            for i in range(num_levels - len(energies)):
                mu_guess = energies[-1] + 0.5
                psi, energy = self.solve_nonlinear_schrodinger(mu_guess)
                energies.append(energy)
        energies = sorted(energies)[:num_levels]
        # Массовая щель — разница между первым и нулевым уровнями
        if len(energies) > 1:
            self.mass_gap = energies[1] - energies[0]
        else:
            self.mass_gap = None
        self.energies = energies
        return energies, self.mass_gap

# --- FUNC: empirical_gap_formula ---
def empirical_gap_formula(self):
        """
        Устанавливает связь между найденной щелью и нашими константами.
        """
        phi = 1.6180339887
        sqrt5 = 2.2360679775
        gamma = 7.0
        Lambda = 0.5527

        if self.mass_gap is None:
            return None

        # Проверяем, какие комбинации дают близкое значение
        candidates = {
            'phi': phi,
            'sqrt5': sqrt5,
            'gamma': gamma,
            'phi*sqrt5': phi * sqrt5,
            'gamma/phi': gamma / phi,
            'Lambda*gamma': Lambda * gamma,
            'phi*gamma/sqrt5': phi * gamma / sqrt5
        }
        best = None
        best_diff = float('inf')
        for name, val in candidates.items():
            diff = abs(val - self.mass_gap)
            if diff < best_diff:
                best_diff = diff
                best = (name, val)
        return best

# --- FUNC: plot_gap ---
def plot_gap(self):
        """
        Показывает спектр энергий и волновые функции.
        """
        if not hasattr(self, 'energies'):
            self.find_mass_gap()

        fig, axs = plt.subplots(2, 1, figsize=(10, 8))

        # Спектр
        axs[0].bar(range(len(self.energies)), self.energies, color='blue')
        axs[0].set_title('Энергетический спектр')
        axs[0].set_xlabel('Уровень')
        axs[0].set_ylabel('Энергия (в условных единицах)')
        if self.mass_gap is not None:
            axs[0].axhline(y=self.energies[0] + self.mass_gap, color='red', linestyle='--', label=f'Щель = {self.mass_gap:.4f}')
            axs[0].legend()

        # Волновые функции для первых двух уровней
        # Для визуализации заново решаем задачу с mu = energies[0] и mu = energies[1]
        if len(self.energies) >= 2:
            psi0, _ = self.solve_nonlinear_schrodinger(self.energies[0])
            psi1, _ = self.solve_nonlinear_schrodinger(self.energies[1])
            axs[1].plot(self.x, np.abs(psi0)**2, label='Основное состояние')
            axs[1].plot(self.x, np.abs(psi1)**2, label='Первое возбуждённое')
            axs[1].set_title('Волновые функции')
            axs[1].set_xlabel('x')
            axs[1].set_ylabel('|ψ|²')
            axs[1].legend()

        plt.tight_layout()
        plt.show()

# --- FUNC: evolve_by_relations ---
def evolve_by_relations(self, steps=50):
        """
        Новая эволюция: время определяется отношением между ДВУМЯ резонансами.
        Если резонансов меньше 2 — эволюция не происходит (время отсутствует).
        """
        if self.psi is None:
            self.generate_field()

        # Убедимся, что у нас есть хотя бы 2 резонанса
        if len(self.resonances) < 2:
            print("⚠️  Для реляционного времени нужно минимум 2 резонанса. Поиск резонансов...")
            self.find_resonances()
            if len(self.resonances) < 2:
                print("❌ Не найдено 2 резонансов. Эволюция невозможна.")
                return self.psi

        # Берём первые два резонанса как "часы" для всей системы
        # (В будущем можно перебирать все пары, но для первого этапа так проще)
        a = self.resonances[0]
        b = self.resonances[1]

        # Создаём реляционные часы
        rel_time = RelationalTime(a, b)

        print(f"⏳ Запуск реляционной эволюции на {steps} шагов...")

        for step in range(steps):
            # 1. Спрашиваем у часов, сколько времени прошло
            tick_result = rel_time.tick()
            dt = rel_time.get_dt()

            if dt is None or dt == 0:
                # Время застыло — поле не эволюционирует, просто ждём
                # (можно вывести точку для отладки)
                # print(".", end="")
                continue

            # 2. Время течёт! Эволюционируем поле на это реляционное dt
            # Используем старый метод, но теперь dt пришло из отношений
            self.evolve_field(steps=1, dt=dt)

            # 3. Обновляем список резонансов (после эволюции они могли измениться)
            self.find_resonances()

            # 4. Если резонансов всё ещё >= 2, обновляем ссылки в реляционных часах
            if len(self.resonances) >= 2:
                # Обновляем фазы, чтобы часы не сбились
                rel_time.phase_a_prev = self.resonances[0]['phase']
                rel_time.phase_b_prev = self.resonances[1]['phase']
                # Можно также обновить сами объекты, если они изменились
                rel_time.a = self.resonances[0]
                rel_time.b = self.resonances[1]

            # Опционально: синхронизация наблюдателя (для красоты)
            # self.observer_sync()

        print(f"✅ Реляционная эволюция завершена. Всего тиков: {rel_time.ticks:.2f}")
        return self.psi

# --- FUNC: evolve_EM_relational ---
def evolve_EM_relational(self, steps=100, hbar=1.0, coupling=0.1):
        """Встроенная реализация метода (твой код с небольшими доработками)."""
        if not self.E_resonators or not self.B_resonators:
            print("Добавьте хотя бы один E и один B резонатор.")
            return

        e_clock = self.E_resonators[0]
        b_clock = self.B_resonators[0]
        rel_time = RelationalTime(e_clock, b_clock, hbar=hbar)

        total_water = 0.0  # литры, накопленные за эволюцию

        for step in range(steps):
            dt = rel_time.get_dt()
            tick = rel_time.tick()
            dt = rel_time.get_dt()

            if dt is None or dt == 0:
                continue

            # Эволюционируем все резонаторы
            for e in self.E_resonators:
                for b in self.B_resonators:
                    delta_phase = e.phase - b.phase
                    transfer = coupling * np.sin(delta_phase) * dt
                    e_energy = e.amp**2
                    b_energy = b.amp**2

                    # Переток энергии (E -> B = конденсация)
                    if e_energy > 0 and b_energy > 0:
                        # Ограничиваем переток, чтобы не уйти в отрицательные
                        max_transfer = min(e_energy, b_energy * 0.5)  # эмпирика
                        actual_transfer = min(transfer, max_transfer)
                        e.amp = np.sqrt(max(0, e_energy - actual_transfer))
                        b.amp = np.sqrt(max(0, b_energy + actual_transfer))
                    elif e_energy > 0 and b_energy == 0:
                        b.amp = np.sqrt(e_energy) * 0.5  # часть переходит
                        e.amp = np.sqrt(e_energy * 0.5)
                    elif b_energy > 0 and e_energy == 0:
                        e.amp = np.sqrt(b_energy) * 0.5
                        b.amp = np.sqrt(b_energy * 0.5)

                    e.tick(dt)
                    b.tick(dt)

            # После обновления полей вычисляем количество образовавшейся воды
            # Вода пропорциональна энергии, перешедшей из E в B за этот шаг
            # Мы используем изменение амплитуды B как индикатор
            # Для простоты: water = k * (b_amp_new - b_amp_old) * площадь * коэффициент
            # Но у нас нет истории старых амплитуд, поэтому используем прирост энергии B
            # Можно вести накопление, вычитая начальную энергию B
            # Здесь я упрощённо: вода = суммарная энергия B минус начальная, умноженная на коэф.
            # Запомним начальную энергию B при первом шаге
            if step == 0:
                self.initial_b_energy = self.B_resonators[0].amp**2
            # Текущая энергия B
            b_energy_now = self.B_resonators[0].amp**2
            delta_energy_b = b_energy_now - self.initial_b_energy
            # Предположим, что 1 единица энергии = 0.1 литра воды (калибровка)
            water_liters = max(0, delta_energy_b * 0.1 * self.area * self.climate.get('wind_speed', 1))
            total_water += water_liters

            self.water_history.append(total_water)
            self.time_history.append(rel_time.ticks)

            # Опционально выводим прогресс
            if step % 10 == 0:
                print(f"Шаг {step}: dt={dt:.3f}, вода={total_water:.2f} л")

        print(f"EM-эволюция завершена. Всего тиков: {rel_time.ticks:.2f}")
        print(f"Итого накоплено воды: {total_water:.2f} литров")
        return total_water

# --- FUNC: plot_frozen_time ---
def plot_frozen_time(self):
        if self.psi is None:
            return
        phase = np.angle(self.psi)
        dphase = np.gradient(phase)
        frozen = np.abs(dphase[0]) + np.abs(dphase[1]) < 0.01
        plt.imshow(frozen, cmap='coolwarm', origin='lower')
        plt.title('Области застывшего времени (синхронизация)')
        plt.colorbar()
        plt.show()

# --- FUNC: on_rel ---
def on_rel(b):
            with self.output:
                clear_output()
                status.value = "<b>Статус:</b> Реляционная эволюция..."
                self.phys.evolve_by_relations(steps=50, hbar=0.1)
                print("Реляционная эволюция завершена.")
                status.value = "<b>Статус:</b> Реляционная эволюция завершена."

# --- FUNC: on_em ---
def on_em(b):
            with self.output:
                clear_output()
                status.value = "<b>Статус:</b> EM-эволюция (квантованная)..."
                self.phys.evolve_EM_relational(steps=100, coupling=0.15, hbar=0.05)
                print("EM-эволюция завершена.")
                status.value = "<b>Статус:</b> EM-эволюция завершена."

# --- FUNC: on_frozen ---
def on_frozen(b):
            with self.output:
                clear_output()
                self.phys.plot_frozen_time()

# --- FUNC: setup_ocean ---
def setup_ocean(self, params: Dict = None) -> Dict:
        """
        Создаёт модель океанской среды с заданными параметрами.
        Вычисляет профиль скорости звука и рельеф дна.
        """
        if params is None:
            params = self.default_ocean.copy()
        # Профиль скорости звука (упрощённая модель)
        depth = params['depth']
        z = np.linspace(0, depth, 100)
        if params['sound_speed_profile'] == 'linear':
            # Линейный градиент: температура падает с глубиной -> скорость уменьшается
            c0 = 1500  # м/с у поверхности
            gradient = -0.02  # (м/с)/м
            c = c0 + gradient * z
        elif params['sound_speed_profile'] == 'Munk':
            # Профиль Манка (реалистичный для океана)
            c = 1500 + 50 * (np.exp(-z/100) + z/100 - 1)  # упрощённо
        else:
            c = np.ones_like(z) * 1500
        # Рельеф дна (простой)
        x = np.linspace(-200, 200, 200)
        y = np.linspace(-200, 200, 200)
        X, Y = np.meshgrid(x, y)
        if params['bottom_type'] == 'sandy':
            bottom_roughness = 0.5  # метры
        elif params['bottom_type'] == 'rocky':
            bottom_roughness = 2.0
        else:
            bottom_roughness = 1.0
        Z_bottom = -depth + bottom_roughness * (np.sin(0.01*X) * np.cos(0.015*Y) + 0.5*np.sin(0.03*(X+Y)))
        # Сохраняем
        ocean_model = {
            'params': params,
            'z': z.tolist(),
            'c': c.tolist(),
            'bottom_x': X.tolist(),
            'bottom_y': Y.tolist(),
            'bottom_z': Z_bottom.tolist(),
            'timestamp': datetime.now().isoformat()
        }
        self.session_data["🌊"]["ocean_params"] = ocean_model
        return ocean_model

# --- FUNC: active_noise_cancellation ---
def active_noise_cancellation(self, sonar_ping: np.ndarray, target_echo: np.ndarray, learning_rate: float = 0.1) -> Dict:
        """
        Реализует адаптивное подавление эхосигнала с использованием фильтра LMS.
        sonar_ping - излучаемый сигнал (опорный)
        target_echo - принимаемый эхосигнал (с помехами и отражением от объекта)
        Возвращает остаточный сигнал (подавленный эхосигнал) и параметры фильтра.
        """
        # Инициализация фильтра (длина 32)
        filter_len = 32
        w = np.zeros(filter_len, dtype=complex)
        # Опорный сигнал (задержанный)
        ref_signal = np.concatenate([np.zeros(filter_len-1), sonar_ping])
        # Адаптивный алгоритм (LMS)
        N = len(sonar_ping)
        output = np.zeros(N, dtype=complex)
        error = np.zeros(N, dtype=complex)
        for i in range(N):
            # Выборка из опорного сигнала
            x = ref_signal[i:i+filter_len][::-1]
            # Выход фильтра
            y = np.dot(w, x)
            # Ошибка (целевой сигнал - выход фильтра)
            e = target_echo[i] - y
            # Обновление весов
            w = w + learning_rate * e * np.conj(x) / (np.dot(x, np.conj(x)) + 1e-6)
            output[i] = y
            error[i] = e
        result = {
            'error': error.tolist(),
            'filter_weights': w.tolist(),
            'output': output.tolist(),
            'power_reduction_dB': 10*np.log10(np.mean(np.abs(target_echo)**2) / (np.mean(np.abs(error)**2)+1e-12))
        }
        self.session_data["🌊"]["active_cancellation"] = result
        return result

# --- FUNC: acoustic_communication_channel ---
def acoustic_communication_channel(self, data: str, carrier_freq: float = 10000, bit_rate: int = 100) -> Dict:
        """
        Моделирует канал акустической связи через кокон.
        Кодирует данные в фазово-модулированный сигнал и пропускает через среду.
        """
        # Кодирование данных в биты
        bits = []
        for char in data:
            bits.extend([int(b) for b in format(ord(char), '08b')])
        # Модуляция BPSK (бинарная фазовая манипуляция)
        samples_per_bit = 10
        fs = bit_rate * samples_per_bit
        t = np.arange(0, len(bits)*samples_per_bit/fs, 1/fs)
        carrier = np.cos(2*np.pi*carrier_freq*t)
        # Символы: +1 для бита 1, -1 для бита 0
        symbols = np.array([1 if b else -1 for b in bits])
        symbols = np.repeat(symbols, samples_per_bit)
        # Модулированный сигнал
        modulated = symbols * carrier
        # Добавление шума океана (гауссовский, уровень зависит от состояния моря)
        noise_level = 0.1 * (1 + 0.5 * np.sin(2*np.pi*0.05*np.arange(len(modulated))))
        noise = np.random.normal(0, noise_level, len(modulated))
        received = modulated + noise
        # Демодуляция (корреляция с несущей)
        demodulated = received * carrier
        # Интегрирование по битовым интервалам
        bit_samples = np.reshape(demodulated[:len(demodulated)//samples_per_bit*samples_per_bit], (-1, samples_per_bit))
        bit_estimates = np.sign(np.mean(bit_samples, axis=1))
        # Восстановление данных
        received_bits = bit_estimates > 0
        received_bits = received_bits.astype(int)
        # Декодирование в строку
        decoded_chars = []
        for i in range(0, len(received_bits), 8):
            byte = 0
            for j in range(8):
                if i+j < len(received_bits):
                    byte = (byte << 1) | received_bits[i+j]
            decoded_chars.append(chr(byte))
        decoded_data = ''.join(decoded_chars)
        result = {
            'original_data': data,
            'decoded_data': decoded_data,
            'error_rate': sum(1 for a,b in zip(data, decoded_data) if a != b) / len(data) if data else 0,
            'modulated_signal': modulated.tolist(),
            'received_signal': received.tolist(),
            'snr': 20*np.log10(np.std(modulated)/np.std(noise))
        }
        self.session_data["🌊"]["comm_channel"] = result
        return result

# --- FUNC: plot_ocean_scene ---
def plot_ocean_scene(self, ocean_model: Dict, object_pos: Tuple[float, float, float] = (0, 0, -50)):
        """
        3D визуализация океанской среды, объекта и трасс распространения звука.
        """
        fig = plt.figure(figsize=(12, 8))
        ax = fig.add_subplot(111, projection='3d')
        # Дно
        X = np.array(ocean_model['bottom_x'])
        Y = np.array(ocean_model['bottom_y'])
        Z = np.array(ocean_model['bottom_z'])
        ax.plot_surface(X, Y, Z, alpha=0.3, color='brown')
        # Поверхность океана (волны)
        x_wave = np.linspace(-200, 200, 100)
        y_wave = np.linspace(-200, 200, 100)
        Xw, Yw = np.meshgrid(x_wave, y_wave)
        Zw = np.zeros_like(Xw)
        ax.plot_surface(Xw, Yw, Zw, alpha=0.1, color='cyan')
        # Объект (подводная лодка)
        obj_x, obj_y, obj_z = object_pos
        ax.scatter(obj_x, obj_y, obj_z, color='red', s=100, label='Объект')
        # Кокон (сфера невидимости)
        u = np.linspace(0, 2*np.pi, 20)
        v = np.linspace(0, np.pi, 20)
        sphere_r = 10
        xs = obj_x + sphere_r * np.outer(np.cos(u), np.sin(v))
        ys = obj_y + sphere_r * np.outer(np.sin(u), np.sin(v))
        zs = obj_z + sphere_r * np.outer(np.ones_like(u), np.cos(v))
        ax.plot_surface(xs, ys, zs, alpha=0.2, color='green')
        # Трассы звука (лучи)
        for angle in np.linspace(-np.pi/4, np.pi/4, 5):
            for depth in np.linspace(-80, -20, 3):
                # Простая линия от гидролокатора к объекту
                x_ray = np.linspace(-100, obj_x, 20)
                y_ray = np.linspace(-100, obj_y, 20)
                z_ray = np.linspace(-10, obj_z, 20)
                ax.plot(x_ray, y_ray, z_ray, color='blue', alpha=0.3)
        ax.set_xlabel('X (м)')
        ax.set_ylabel('Y (м)')
        ax.set_zlabel('Глубина (м)')
        ax.set_title('Океанская среда и акустический кокон')
        ax.legend()
        plt.show()

# --- FUNC: run_field_test ---
def run_field_test(self, test_data: Dict) -> Dict:
        """
        Запускает полный полевой тест:
        - Генерация сонара
        - Активное подавление эхосигнала
        - Акустическая связь
        - Сбор статистики
        """
        # Настройка океана
        ocean = self.setup_ocean(test_data.get('ocean_params'))
        # Параметры объекта
        object_pos = test_data.get('object_pos', (0, 0, -50))
        # Генерация сигнала сонара
        ping_freq = test_data.get('sonar_freq', 15000)
        ping_duration = 0.001  # 1 мс
        fs = 100000  # частота дискретизации
        t_ping = np.linspace(0, ping_duration, int(fs*ping_duration))
        sonar_ping = np.sin(2*np.pi*ping_freq*t_ping)
        # Эхо от объекта (с задержкой и искажениями)
        delay = 0.01  # 10 мс
        echo = np.concatenate([np.zeros(int(fs*delay)), sonar_ping * 0.3, np.zeros(int(fs*0.01))])
        # Добавляем шум океана
        noise = np.random.normal(0, 0.05, len(echo))
        echo += noise
        # Активное подавление
        cancellation = self.active_noise_cancellation(sonar_ping, echo)
        # Акустическая связь
        message = test_data.get('message', 'Hello from stealth!')
        comm = self.acoustic_communication_channel(message, carrier_freq=10000)
        # Результат
        result = {
            'ocean': ocean,
            'cancellation': cancellation,
            'communication': comm,
            'object_pos': object_pos,
            'ping_freq': ping_freq,
            'timestamp': datetime.now().isoformat()
        }
        self.session_data["🌊"]["field_tests"].append(result)
        return result

# --- FUNC: collapse_state ---
def collapse_state(self, state_id=None):
        """
        Коллапсирует суперпозицию в конкретное состояние.
        Если state_id не указан, выбирается случайное с вероятностью, пропорциональной весу.
        """
        if state_id is None:
            # Выбираем состояние с вероятностью, пропорциональной весу
            weights = np.array([s['weight'] for s in self.states])
            idx = np.random.choice(len(self.states), p=weights)
            state_id = self.states[idx]['id']
        # Находим состояние
        for s in self.states:
            if s['id'] == state_id:
                self.collapsed_state = s
                return s
        return None

# --- FUNC: plot_superposition ---
def plot_superposition(self, projection_dims=(0,1,2), show_weights=True):
        """
        Визуализирует поле состояний в 3D-проекции.
        Размер точки пропорционален весу состояния.
        """
        if not self.states:
            self.generate_field()

        dims = projection_dims[:3]
        coords = np.array([s['coordinates'][list(dims)] for s in self.states])
        weights = np.array([s['weight'] for s in self.states])
        energies = np.array([s['energy'] for s in self.states])
        resonant = np.array([s['resonant'] for s in self.states])

        fig = plt.figure(figsize=(10, 8))
        ax = fig.add_subplot(111, projection='3d')

        # Цвета: резонансные состояния — красные, остальные — синие
        colors = ['red' if r else 'blue' for r in resonant]
        sizes = 50 + 200 * weights / np.max(weights)

        sc = ax.scatter(coords[:,0], coords[:,1], coords[:,2],
                        c=colors, s=sizes, alpha=0.7)

        # Если есть коллапсированное состояние, выделяем его
        if self.collapsed_state:
            c_coords = self.collapsed_state['coordinates'][list(dims)]
            ax.scatter([c_coords[0]], [c_coords[1]], [c_coords[2]],
                       color='green', s=300, marker='*', label='Коллапс')

        ax.set_title('Суперпозиционное поле состояний')
        ax.set_xlabel(f'Ось {dims[0]+1}')
        ax.set_ylabel(f'Ось {dims[1]+1}')
        ax.set_zlabel(f'Ось {dims[2]+1}')
        if show_weights:
            # Добавляем цветовую шкалу для весов
            plt.colorbar(sc, label='Вес состояния')
        ax.legend()
        plt.show()

# --- FUNC: animate_field ---
def animate_field(self, steps=30, projection_dims=(0,1,2)):
        """
        Анимация эволюции суперпозиционного поля (состояния движутся).
        """
        if not self.states:
            self.generate_field()

        dims = projection_dims[:3]
        coords = np.array([s['coordinates'][list(dims)] for s in self.states])
        weights = np.array([s['weight'] for s in self.states])

        fig = plt.figure(figsize=(10, 8))
        ax = fig.add_subplot(111, projection='3d')
        sc = ax.scatter(coords[:,0], coords[:,1], coords[:,2],
                        c=weights, cmap='plasma', s=50, alpha=0.7)

        def update(frame):
            # Слегка смещаем координаты (случайное блуждание)
            for i, s in enumerate(self.states):
                s['coordinates'] += np.random.normal(0, 0.05, len(s['coordinates']))
            # Обновляем веса (в зависимости от новой энергии)
            for s in self.states:
                s['energy'] = np.linalg.norm(s['coordinates'])
                resonance, _ = compute_resonance(s['energy'])
                weight = 1.0 / (1 + np.abs(s['energy'] - 1.0))
                if resonance:
                    weight *= 1.5
                s['weight'] = weight
            total = sum(s['weight'] for s in self.states)
            for s in self.states:
                s['weight'] /= total
            # Обновляем scatter
            new_coords = np.array([s['coordinates'][list(dims)] for s in self.states])
            new_weights = np.array([s['weight'] for s in self.states])
            sc._offsets3d = (new_coords[:,0], new_coords[:,1], new_coords[:,2])
            sc.set_array(new_weights)
            ax.set_title(f'Эволюция поля, шаг {frame}')
            return sc,

        ani = FuncAnimation(fig, update, frames=steps, interval=200, blit=False)
        plt.colorbar(sc, label='Вес')
        plt.show()
        return ani

