def on_design_clicked(self, b):
        with self.output:
            self.status_label.value = '⏳ Проектирование...'
            self.ai.lab_log("Начато проектирование процессора и сенсора.")
            # Получаем параметры
            nq = self.num_qubits_slider.value
            freq = self.freq_slider.value
            qf = self.q_factor_slider.value
            # Проектируем
            processor = self.ai.design_processor(nq)
            sensor = self.ai.design_sensor(freq, qf)
            self.ai.session_data["🔬"]["current_processor"] = processor
            self.ai.session_data["🔬"]["current_sensor"] = sensor
            # Если QEC включена, обучаем модель
            if self.use_qec_checkbox.value:
                self.ai.train_qec_model(processor)
                self.ai.lab_log("QEC модель обучена.")
            self.status_label.value = '✅ Проектирование завершено'
            self.ai.lab_log("Проектирование завершено успешно.")
            # Показываем информацию
            with self.plot_output:
                clear_output()
                print("Процессор:")
                print(f"  Кубиты: {nq}, Платформы: {processor['platform_types']}")
                print(f"  Среднее время вентиля: {np.mean(list(processor['gate_times'].values())):.2e} с")
                print(f"Сенсор: частота {freq} ГГц, добротность {qf:.1e}")
                print(f"Чувствительность: {sensor['sensitivity']:.2e}")

# --- FUNC: on_run_clicked ---
def on_run_clicked(self, b):
        if self.running:
            self.ai.lab_log("Эксперимент уже запущен.")
            return
        self.running = True
        self.status_label.value = '⏳ Запуск эксперимента...'
        self.ai.lab_log("Запуск эксперимента...")
        # Получаем параметры
        noise = self.noise_slider.value
        use_qec = self.use_qec_checkbox.value
        # Запускаем эмуляцию
        if use_qec:
            result = self.ai.emulate_with_qec(
                self.ai.session_data["🔬"]["current_processor"],
                self.ai.session_data["🔬"]["current_sensor"],
                noise
            )
        else:
            result = self.ai.emulate_experiment(
                self.ai.session_data["🔬"]["current_processor"],
                self.ai.session_data["🔬"]["current_sensor"],
                noise
            )
        self.last_experiment_result = result
        self.ai.session_data["🔬"]["experiments"].append(result)
        self.experiment_count += 1
        self.ai.session_data["🔬"]["current_experiment"] = result
        # Обновляем логи
        self.ai.lab_log(f"Эксперимент #{self.experiment_count} завершён.")
        self.status_label.value = f'✅ Эксперимент #{self.experiment_count} выполнен'
        # Визуализация
        if self.visualize_checkbox.value:
            self.plot_experiment(result)
        else:
            with self.plot_output:
                clear_output()
                print("Визуализация отключена.")
        self.running = False

