# --- FUNC: plot_experiment ---
def plot_experiment(self, result):
        with self.plot_output:
            clear_output()
            fig, axs = plt.subplots(1, 3, figsize=(15, 4))
            # 1. Идеальное vs шумное vs скорректированное
            ideal = np.array(result['ideal'])
            noisy = np.array(result['noisy'])
            if 'corrected' in result:
                corrected = np.array(result['corrected'])
            axs[0].bar(range(len(ideal)), ideal, alpha=0.5, label='Идеал')
            axs[0].bar(range(len(noisy)), noisy, alpha=0.5, label='Шум')
            if 'corrected' in result:
                axs[0].bar(range(len(corrected)), corrected, alpha=0.5, label='Скорр.')
            axs[0].set_title('Состояния')
            axs[0].set_xticks(range(len(ideal)))
            axs[0].legend()
            # 2. Фиделитет
            labels = ['До коррекции', 'После коррекции'] if 'fidelity_before' in result else ['Измеренный']
            values = [result.get('fidelity_before', 1.0), result.get('fidelity_after', 1.0)] if 'fidelity_before' in result else [np.mean(ideal == noisy)]
            axs[1].bar(labels, values, color=['orange', 'green'])
            axs[1].set_ylim(0, 1)
            axs[1].set_title('Фиделитет')
            axs[1].set_ylabel('Точность')
            # 3. Сигнал сенсора
            axs[2].plot([0, 1], [result['signal'], result['signal']], 'r-', label='Сигнал')
            axs[2].axhline(y=0, color='k', linestyle='--')
            axs[2].set_title('Сигнал сенсора')
            axs[2].set_ylabel('Амплитуда')
            axs[2].set_xlabel('Время (усл.)')
            plt.tight_layout()
            plt.show()
            # Дополнительная информация
            print(f"Обнаружение: {'✅' if result.get('detected', False) else '❌'}")
            print(f"Время выполнения: {result.get('execution_time', 0):.2e} с")
            if 'fidelity_before' in result:
                print(f"Улучшение: {(result['fidelity_after'] - result['fidelity_before'])*100:.1f}%")

