# --- FUNC: apply_love ---
def apply_love(self, strength=1.0, radius=3.0):
    """
    Применяет силу Любви: синхронизация фаз, усиление амплитуд, запутывание.
    strength — интенсивность (0..1).
    """
    if strength == 0:
        return

    # 1. Усиление амплитуд: чем ближе к центру, тем сильнее (любовь распространяется от наблюдателя)
    for e in self.E_resonators + self.B_resonators:
        dist = np.hypot(e.x, e.y)
        if dist < radius:
            factor = 1.0 + strength * (1.0 - dist/radius)
            e.amp *= factor
            e.amp = min(e.amp, 3.0)

    # 2. Синхронизация фаз: все фазы стремятся к средней
    all_res = self.E_resonators + self.B_resonators
    if all_res:
        avg_phase = np.mean([r.phase for r in all_res])
        for r in all_res:
            r.phase += strength * (avg_phase - r.phase) * 0.1

    # 3. Запутывание: максимальная связь
    self.entanglement_strength = min(1.0, self.entanglement_strength + strength * 0.1)

    # 4. Уменьшение кванта времени (ускорение времени, но при синхронизации — застывание)
    self.hbar = max(0.001, self.hbar * (1 - strength * 0.01))

    self._update_field_from_EM()
    print(f"💖 Применена сила Любви (интенсивность {strength:.2f})")

# --- FUNC: add_neuron ---
def add_neuron(self, position: Tuple[float, float], params: Dict) -> int:
        """
        Добавляет нейрон с параметрами (мембранный потенциал, порог, рефрактерность).
        """
        neuron = {
            'id': len(self.neurons),
            'position': np.array(position, dtype=float),
            'membrane_potential': params.get('resting', -70),  # мВ
            'threshold': params.get('threshold', -55),
            'refractory': 0,
            'refractory_period': params.get('refractory_period', 2e-3),  # сек
            'spike': False,
            'input_current': 0.0,
            'params': params
        }
        self.neurons.append(neuron)
        return neuron['id']

# --- FUNC: add_synapse ---
def add_synapse(self, from_id: int, to_id: int, weight: float = 0.5):
        """Добавляет синаптическую связь между нейронами."""
        self.connections.append({
            'from': from_id,
            'to': to_id,
            'weight': weight,
            'delay': np.random.uniform(0, 1e-3)  # случайная задержка
        })

# --- FUNC: update_neuron ---
def update_neuron(self, neuron_id: int, dt: float = 1e-4):
        """
        Обновляет состояние нейрона по модели Ходжкина-Хаксли (упрощённо).
        """
        neuron = self.neurons[neuron_id]
        # Если нейрон в рефрактерном периоде
        if neuron['refractory'] > 0:
            neuron['refractory'] -= dt
            return
        # Мембранный потенциал (интеграция тока)
        C = 1e-6  # ёмкость мембраны (Ф)
        R = 1e6   # сопротивление (Ом)
        tau = R * C  # постоянная времени
        # Входной ток (от других нейронов + ультразвук)
        I_input = neuron['input_current']
        # Обновление потенциала (уравнение RC-цепи)
        dV = (I_input - (neuron['membrane_potential'] - neuron['params']['resting']) / R) / C * dt
        neuron['membrane_potential'] += dV
        # Проверка на спайк
        if neuron['membrane_potential'] >= neuron['threshold']:
            neuron['spike'] = True
            neuron['membrane_potential'] = neuron['params']['resting']
            neuron['refractory'] = neuron['refractory_period']
            # Регистрируем спайк
            self.spike_history.append({
                'time': len(self.spike_history) * dt,
                'neuron_id': neuron_id,
                'potential': neuron['membrane_potential']
            })
            # Передаём сигнал по синапсам
            for conn in self.connections:
                if conn['from'] == neuron_id:
                    target = self.neurons[conn['to']]
                    target['input_current'] += conn['weight'] * 1e-9

# --- FUNC: apply_ultrasound ---
def apply_ultrasound(self, neuron_id: int, amplitude: float, freq: float = 5e6):
        """
        Применяет сфокусированный ультразвук к нейрону, вызывая механическую стимуляцию.
        """
        neuron = self.neurons[neuron_id]
        # Моделируем влияние ультразвука как дополнительный ток
        # Используем эвристику: сила стимуляции пропорциональна амплитуде и частоте
        current = amplitude * freq * 1e-12
        neuron['input_current'] += current

# --- FUNC: read_neural_activity ---
def read_neural_activity(self, neuron_ids: List[int]) -> np.ndarray:
        """
        Считывает активность нейронов (спайки) и возвращает временной ряд.
        """
        # Имитация считывания: возвращаем мембранные потенциалы
        potentials = []
        for nid in neuron_ids:
            potentials.append(self.neurons[nid]['membrane_potential'])
        return np.array(potentials)

# --- FUNC: train_activity_classifier ---
def train_activity_classifier(self, num_samples: int = 200):
        """
        Обучает ML-модель для распознавания паттернов активности (например, движение, стимуляция).
        """
        X = []  # временные ряды (например, 100 временных шагов)
        y = []  # метка: 0 - спокойное состояние, 1 - стимуляция, 2 - движение
        for _ in range(num_samples):
            # Генерируем случайный паттерн активности
            pattern = np.random.randn(100) * 10  # мВ
            # Добавляем спайки
            spike_times = np.random.choice(100, size=np.random.randint(0, 5), replace=False)
            pattern[spike_times] = np.random.uniform(-30, 30, len(spike_times))
            # Метка
            label = np.random.choice([0, 1, 2])
            X.append(pattern)
            y.append(label)
        X = np.array(X)
        y = np.array(y)
        model = RandomForestClassifier(n_estimators=50, random_state=42)
        model.fit(X, y)
        self.ml_model = model
        return model

# --- FUNC: predict_activity ---
def predict_activity(self, pattern: np.ndarray) -> int:
        """
        Предсказывает тип активности по паттерну.
        """
        if self.ml_model is None:
            raise ValueError("ML-модель не обучена")
        return int(self.ml_model.predict([pattern])[0])

# --- FUNC: run_neuro_experiment ---
def run_neuro_experiment(self, num_neurons: int = 5, duration: float = 0.1, dt: float = 1e-4):
        """
        Запускает симуляцию нейронной сети с ультразвуковым управлением.
        """
        # Создаём нейроны
        for i in range(num_neurons):
            pos = (np.random.uniform(-50e-6, 50e-6),
                   np.random.uniform(-50e-6, 50e-6))
            params = {
                'resting': -70,
                'threshold': -55 + np.random.uniform(-5, 5),
                'refractory_period': 2e-3 + np.random.uniform(0, 1e-3)
            }
            self.add_neuron(pos, params)
        # Создаём случайные связи
        for i in range(num_neurons):
            for j in range(num_neurons):
                if i != j and np.random.rand() < 0.3:
                    self.add_synapse(i, j, weight=np.random.uniform(0.1, 0.9))

        # Основной цикл симуляции
        steps = int(duration / dt)
        for step in range(steps):
            # Применяем ультразвук к случайному нейрону (имитация управления)
            if np.random.rand() < 0.01:
                nid = np.random.randint(0, num_neurons)
                self.apply_ultrasound(nid, amplitude=0.5, freq=5e6)
            # Обновляем все нейроны
            for nid in range(num_neurons):
                self.update_neuron(nid, dt)

        # Визуализация активности
        self.plot_activity()
        return self.spike_history

# --- FUNC: plot_activity ---
def plot_activity(self):
        """
        Визуализирует спайки и мембранные потенциалы.
        """
        fig, axs = plt.subplots(2, 1, figsize=(12, 8))
        # 1. Временной ряд спайков
        if self.spike_history:
            times = [s['time'] for s in self.spike_history]
            neuron_ids = [s['neuron_id'] for s in self.spike_history]
            axs[0].scatter(times, neuron_ids, c='red', s=10)
            axs[0].set_ylabel('Нейрон')
            axs[0].set_title('Спайки нейронов во времени')
            axs[0].set_xlim(0, max(times) + 0.01)
        # 2. Мембранные потенциалы последних нейронов
        for i, neuron in enumerate(self.neurons[:5]):
            # Восстанавливаем историю (если есть) — для примера генерируем
            hist = np.random.normal(-70, 10, 100)  # демо
            axs[1].plot(hist, label=f'Нейрон {i}')
        axs[1].set_xlabel('Время (усл. ед.)')
        axs[1].set_ylabel('Мембранный потенциал, мВ')
        axs[1].legend()
        axs[1].set_title('Мембранные потенциалы')
        plt.tight_layout()
        plt.show()

# --- FUNC: train_ml_models ---
def train_ml_models(self, num_samples: int = 1000):
        """
        Генерирует датасет, обучает модели и сохраняет их.
        """
        X, y_supp, y_ber = self.generate_training_data(num_samples)
        X_train, X_test, y_s_train, y_test_s = train_test_split(X, y_supp, test_size=0.2, random_state=42)
        X_train, X_test, y_b_train, y_test_b = train_test_split(X, y_ber, test_size=0.2, random_state=42)
        
        # Модель для подавления
        model_supp = RandomForestRegressor(n_estimators=100, max_depth=10, random_state=42)
        model_supp.fit(X_train, y_s_train)
        y_pred_s = model_supp.predict(X_test)
        
        # Модель для BER
        model_ber = RandomForestRegressor(n_estimators=100, max_depth=10, random_state=42)
        model_ber.fit(X_train, y_b_train)
        y_pred_b = model_ber.predict(X_test)
        
        # Сохраняем модели в сессии
        self.session_data["🌊"]["ml_models"] = {
            'suppression': model_supp,
            'ber': model_ber,
            'metrics': {
                'suppression_r2': r2_score(y_test_s, y_pred_s),
                'suppression_mse': mean_squared_error(y_test_s, y_pred_s),
                'ber_r2': r2_score(y_test_b, y_pred_b),
                'ber_mse': mean_squared_error(y_test_b, y_pred_b)
            }
        }
        # Сохраняем сами модели (можно pickle)
        joblib.dump(model_supp, 'model_suppression.pkl')
        joblib.dump(model_ber, 'model_ber.pkl')
        
        return self.session_data["🌊"]["ml_models"]

# --- FUNC: plot_time_dilation ---
def plot_time_dilation(self, grid_resolution=50):
        """Визуализация фактора замедления времени."""
        factor_map = np.zeros((grid_resolution, grid_resolution))
        x = np.linspace(self.x.min(), self.x.max(), grid_resolution)
        y = np.linspace(self.y.min(), self.y.max(), grid_resolution)
        X, Y = np.meshgrid(x, y)
        for i in range(grid_resolution):
            for j in range(grid_resolution):
                curv = self._get_curvature_at(x[i], y[j])
                factor_map[i,j] = 1.0 / (1.0 + 0.1 * curv)
        plt.imshow(factor_map, extent=[x.min(), x.max(), y.min(), y.max()],
                   origin='lower', cmap='viridis')
        plt.title('Фактор замедления времени (dt_eff / dt)')
        plt.colorbar(label='dt_eff')
        plt.show()

# --- FUNC: generate_state_space ---
def generate_state_space(self, num_nodes=50):
        """
        Создаёт пространство состояний как граф запутанности.
        Каждый узел — подсистема, рёбра — корреляции.
        """
        # Координаты в N-мерном пространстве
        coordinates = np.random.randn(num_nodes, self.dimensions)
        # Нормализуем
        coordinates = coordinates / np.linalg.norm(coordinates, axis=1, keepdims=True)
        # Матрица корреляций (косинусное сходство)
        corr_matrix = coordinates @ coordinates.T
        # Порог для значимых связей
        threshold = 0.1
        corr_matrix = np.where(np.abs(corr_matrix) > threshold, corr_matrix, 0)
        np.fill_diagonal(corr_matrix, 0)
        self.state_space = {
            'nodes': coordinates,
            'correlations': corr_matrix,
            'num_nodes': num_nodes,
            'dimensions': self.dimensions
        }
        self.correlation_matrix = corr_matrix
        return self.state_space

# --- FUNC: evolve_without_time ---
def evolve_without_time(self, steps=10):
        """
        Итерирует систему, изменяя корреляции по спирали (вращение в N-пространстве).
        """
        if self.state_space is None:
            self.generate_state_space()

        nodes = self.state_space['nodes'].copy()
        corr = self.state_space['correlations'].copy()
        history = []

        for step in range(steps):
            # Поворачиваем все узлы в N-пространстве (вращение по спирали)
            angle = step * 0.1 * self.phi
            rotation = np.eye(self.dimensions)
            for i in range(self.dimensions-1):
                for j in range(i+1, self.dimensions):
                    c = np.cos(angle)
                    s = np.sin(angle)
                    rot = np.eye(self.dimensions)
                    rot[i,i] = c; rot[j,j] = c
                    rot[i,j] = -s; rot[j,i] = s
                    rotation = rotation @ rot

            # Применяем вращение к узлам
            nodes_rotated = nodes @ rotation.T
            # Пересчитываем корреляции
            corr_new = nodes_rotated @ nodes_rotated.T
            threshold = 0.1
            corr_new = np.where(np.abs(corr_new) > threshold, corr_new, 0)
            np.fill_diagonal(corr_new, 0)

            # Фиксируем состояние
            state = {
                'step': step,
                'nodes': nodes_rotated.copy(),
                'correlations': corr_new.copy(),
                'entanglement_measure': np.sum(np.abs(corr_new)) / (corr_new.shape[0]**2)
            }
            history.append(state)
            # Обновляем для следующего шага
            nodes = nodes_rotated
            corr = corr_new

        self.history.extend(history)
        return history

# --- FUNC: causality_structure ---
def causality_structure(self, state_index=-1):
        """
        Извлекает причинные связи из текущего состояния как граф.
        """
        if not self.history:
            self.evolve_without_time(10)
        state = self.history[state_index]
        corr = state['correlations']
        # Причинность — это асимметричная часть корреляций
        # (в нашей модели она возникает из спирального вращения)
        # Для простоты берём верхний треугольник
        causality = np.triu(corr, k=1)
        return {
            'causality_matrix': causality,
            'cause_effect_pairs': [(i,j) for i in range(causality.shape[0]) for j in range(causality.shape[1]) if causality[i,j] > 0]
        }

# --- FUNC: plot_state ---
def plot_state(self, state_index=-1, projection_dims=(0,1,2)):
        """
        Проецирует состояние на 3 оси и показывает структуру запутанности.
        """
        if not self.history:
            self.evolve_without_time(10)
        state = self.history[state_index]
        nodes = state['nodes']
        corr = state['correlations']

        # Проекция
        dims = projection_dims
        if len(dims) < 3:
            dims = (0,1,2)
        proj = nodes[:, list(dims)]

        fig = plt.figure(figsize=(10,8))
        ax = fig.add_subplot(111, projection='3d')
        # Узлы
        sc = ax.scatter(proj[:,0], proj[:,1], proj[:,2],
                       c=np.sum(corr, axis=1), cmap='plasma', s=50, alpha=0.8)
        # Рёбра (значимые корреляции)
        threshold = 0.15
        for i in range(corr.shape[0]):
            for j in range(i+1, corr.shape[0]):
                if abs(corr[i,j]) > threshold:
                    ax.plot([proj[i,0], proj[j,0]],
                           [proj[i,1], proj[j,1]],
                           [proj[i,2], proj[j,2]],
                           color='gray', alpha=0.3, linewidth=0.5)
        ax.set_title(f'Состояние {state_index} (измерения {dims})')
        plt.colorbar(sc, label='Степень запутанности')
        plt.show()

# --- FUNC: animate_evolution ---
def animate_evolution(self, steps=20, projection_dims=(0,1,2)):
        """
        Анимация вращения состояний в N-пространстве.
        """
        if not self.history:
            self.evolve_without_time(steps)

        fig = plt.figure(figsize=(8,6))
        ax = fig.add_subplot(111, projection='3d')
        dims = projection_dims
        if len(dims) < 3:
            dims = (0,1,2)

        def update(frame):
            ax.clear()
            state = self.history[frame % len(self.history)]
            nodes = state['nodes']
            corr = state['correlations']
            proj = nodes[:, list(dims)]
            ax.scatter(proj[:,0], proj[:,1], proj[:,2],
                      c=np.sum(corr, axis=1), cmap='plasma', s=30, alpha=0.7)
            threshold = 0.15
            for i in range(corr.shape[0]):
                for j in range(i+1, corr.shape[0]):
                    if abs(corr[i,j]) > threshold:
                        ax.plot([proj[i,0], proj[j,0]],
                               [proj[i,1], proj[j,1]],
                               [proj[i,2], proj[j,2]],
                               color='gray', alpha=0.2, linewidth=0.5)
            ax.set_title(f'Шаг {frame}, запутанность: {state["entanglement_measure"]:.3f}')
            ax.set_xlabel('Ось 1'); ax.set_ylabel('Ось 2'); ax.set_zlabel('Ось 3')
            return ax,

        ani = FuncAnimation(fig, update, frames=len(self.history), interval=100, blit=False)
        plt.show()
        return ani

# --- FUNC: massive_iteration ---
def massive_iteration(self, iterations=1000, batch_size=10):
        """
        Проводит итерации не по времени, а по количеству одновременных сдвигов.
        Как если бы мы сжали миллионы лет в одно мгновение.
        """
        # Генерируем начальное состояние
        self.generate_state_space(num_nodes=30)
        # «Интегрируем» состояния: одновременно применяем все повороты
        for batch in range(iterations // batch_size):
            # Создаём суперпозицию состояний
            superposed_nodes = np.zeros_like(self.state_space['nodes'])
            for _ in range(batch_size):
                nodes = self.state_space['nodes'].copy()
                angle = np.random.uniform(0, 2*np.pi) * self.phi
                rotation = np.eye(self.dimensions)
                for i in range(self.dimensions-1):
                    for j in range(i+1, self.dimensions):
                        c = np.cos(angle)
                        s = np.sin(angle)
                        rot = np.eye(self.dimensions)
                        rot[i,i] = c; rot[j,j] = c
                        rot[i,j] = -s; rot[j,i] = s
                        rotation = rotation @ rot
                superposed_nodes += nodes @ rotation.T / batch_size
            # Обновляем состояние
            self.state_space['nodes'] = superposed_nodes
            self.state_space['correlations'] = superposed_nodes @ superposed_nodes.T
            # Сохраняем результат
            state = {
                'step': batch,
                'nodes': superposed_nodes.copy(),
                'correlations': self.state_space['correlations'].copy(),
                'entanglement_measure': np.sum(np.abs(self.state_space['correlations'])) / (self.state_space['correlations'].shape[0]**2)
            }
            self.history.append(state)
        return self.history

# --- FUNC: on_massive ---
def on_massive(b):
            with output:
                clear_output()
                status.value = "<b>Статус:</b> Массированная интеграция..."
                self.dimensions = dims_slider.value
                self.generate_state_space()
                self.massive_iteration(iterations=100, batch_size=10)
                print(f"Выполнено {len(self.history)} состояний (интеграция).")
                status.value = f"<b>Статус:</b> Интеграция завершена ({len(self.history)} состояний)."

# --- FUNC: extract_phonons_from_strings ---
def extract_phonons_from_strings(self, num_phonons: int = 10) -> List[float]:
        """
        Извлекает фононные частоты из струнных мод и нулей дзета-функции.
        Использует их как основу для звуковых частот (масштабирует в слышимый диапазон).
        """
        imags = self.session_data["📐"].get("imags", [])
        if not imags:
            return []
        # Берём частоты нулей и масштабируем в диапазон 20-20000 Гц
        freq_min, freq_max = 20, 20000
        imags_norm = (np.array(imags) - min(imags)) / (max(imags) - min(imags))
        phonon_freqs = freq_min + imags_norm * (freq_max - freq_min)
        # Берём первые num_phonons
        phonon_freqs = phonon_freqs[:num_phonons].tolist()
        self.session_data["🎵"]["phonon_modes"] = phonon_freqs
        return phonon_freqs

# --- FUNC: generate_sound_wave ---
def generate_sound_wave(self, frequencies: List[float], duration: float = 1.0) -> np.ndarray:
        """
        Генерирует звуковую волну как сумму синусов с заданными частотами.
        Возвращает массив сэмплов.
        """
        t = np.linspace(0, duration, int(self.sample_rate * duration))
        wave = np.zeros_like(t)
        for freq in frequencies:
            # Случайная амплитуда и фаза
            amp = random.uniform(0.1, 0.5)
            phase = random.uniform(0, 2 * math.pi)
            wave += amp * np.sin(2 * math.pi * freq * t + phase)
        # Нормализация
        wave = wave / np.max(np.abs(wave))
        return wave

# --- FUNC: play_phonon_sound ---
def play_phonon_sound(self, frequencies: List[float], duration: float = 2.0):
        """
        Воспроизводит звук фононов (требуется звуковой интерфейс, например, pydub или sounddevice).
        В этой версии сохраняем как WAV-файл.
        """
        try:
            from scipy.io import wavfile
            wave = self.generate_sound_wave(frequencies, duration)
            # Преобразуем в 16-bit целые
            wave_int = np.int16(wave * 32767)
            wavfile.write("phonon_sound.wav", self.sample_rate, wave_int)
            print("Звук сохранён в phonon_sound.wav")
        except ImportError:
            print("scipy не установлен, звук не сохранён")

# --- FUNC: phonon_resonance_fitness ---
def phonon_resonance_fitness(self, code: str) -> float:
        """
        Оценивает код по его резонансу с фононными частотами.
        """
        if not self.session_data["🎵"]["phonon_modes"]:
            self.extract_phonons_from_strings()
        phonons = np.array(self.session_data["🎵"]["phonon_modes"])
