# --- FUNC: collide_in_dimensions ---
def collide_in_dimensions(self, dims: int, mode1: Dict, mode2: Dict, energy: float) -> Dict:
        """
        Столкновение в D-мерном пространстве-времени.
        Использует обобщённые амплитуды для D измерений.
        """
        # Для простоты модифицируем амплитуду, добавляя фактор размерности
        s = energy ** 2
        t = - (energy * 0.1) ** 2
        u = -s - t
        # Амплитуда Вирасоро для D измерений (упрощённо)
        amplitude = self.veneziano_amplitude(s, t, u) * (1 + 0.1 * (dims - 4))
        probability = abs(amplitude) ** 2
        # Продукты зависят от размерности
        if dims > 4:
            # В высших размерностях больше мод
            num_products = dims // 2
        else:
            num_products = 2
        imags = self.session_data["📐"].get("imags", [])
        if imags:
            product_freqs = np.random.choice(imags, size=num_products, replace=False)
        else:
            product_freqs = np.random.uniform(10, 100, num_products)
        products = [{"frequency": f, "mass": f * 0.1} for f in product_freqs]
        return {
            "dimensions": dims,
            "mode1": mode1,
            "mode2": mode2,
            "energy": energy,
            "s": s,
            "t": t,
            "u": u,
            "amplitude": amplitude,
            "probability": probability,
            "products": products
        }

# --- FUNC: primes_modulation ---
def primes_modulation(self, num_primes: int = 10) -> List[int]:
        """
        Генерирует простые числа и использует их для модуляции частот струн.
        Возвращает список простых чисел.
        """
        def is_prime(n):
            if n < 2:
                return False
            for i in range(2, int(math.sqrt(n)) + 1):
                if n % i == 0:
                    return False
            return True
        primes = []
        n = 2
        while len(primes) < num_primes:
            if is_prime(n):
                primes.append(n)
            n += 1
        self.session_data["🌀"]["primes_used"] = primes
        return primes

# --- FUNC: prime_resonance_amplitude ---
def prime_resonance_amplitude(self, s: float, t: float, prime: int) -> complex:
        """
        Модифицирует амплитуду, используя простое число как дополнительный фактор.
        """
        amp = self.veneziano_amplitude(s, t, -s-t)
        # Вводим резонанс на частоте, связанной с простым числом
        resonance = np.sin(prime * s * 0.01) + 1j * np.cos(prime * t * 0.01)
        return amp * resonance

# --- FUNC: create_phonon_application ---
def create_phonon_application(self, name: str, frequencies: List[float]) -> Dict:
        """
        Создаёт приложение на основе фононных частот (например, звуковая терапия, визуализация).
        """
        app = {
            "name": name,
            "frequencies": frequencies,
            "description": f"Приложение использует частоты: {frequencies[:5]}...",
            "timestamp": datetime.now().isoformat()
        }
        self.session_data["🎵"]["phonon_applications"].append(app)
        return app

# --- FUNC: run_advanced_accelerator ---
def run_advanced_accelerator(self, num_collisions: int = 30,
                                 energy_range: Tuple[float, float] = (10, 200),
                                 dimensions: int = 10,
                                 use_primes: bool = True) -> Dict:
        """
        Запускает ускоритель в многомерном пространстве с модуляцией простыми числами.
        """
        # Генерация струнных мод
        if not self.session_data["🌀"].get("string_modes"):
            self.generate_string_modes(20)
        modes = list(self.session_data["🌀"]["string_modes"].values())

        # Простые числа
        if use_primes and not self.session_data["🌀"]["primes_used"]:
            self.primes_modulation(10)
        primes = self.session_data["🌀"]["primes_used"]

        for i in range(num_collisions):
            mode1 = random.choice(modes)
            mode2 = random.choice(modes)
            energy = random.uniform(energy_range[0], energy_range[1])
            # Столкновение в D измерениях
            collision = self.collide_in_dimensions(dimensions, mode1, mode2, energy)
            # Модуляция простыми числами (если есть)
            if use_primes and primes:
                prime = random.choice(primes)
                collision["prime_modulation"] = prime
                # Модифицируем амплитуду
                amp = self.prime_resonance_amplitude(collision["s"], collision["t"], prime)
                collision["amplitude_prime"] = amp
                collision["probability_prime"] = abs(amp)**2
            # Детектирование
            self.detect_products(collision)
            # Сохраняем в историю
            self.session_data["📊"]["collisions"].append(collision)

        # Извлечение фононов
        phonon_freqs = self.extract_phonons_from_strings(20)
        # Создание фононного приложения
        self.create_phonon_application("Струнный резонатор", phonon_freqs)

        # Поиск сигнатур
        signatures = self.find_string_signatures(num_collisions)

        # Спектр
        spectrum = self.compute_spectrum(self.session_data["📊"]["collisions"])

        summary = {
            "num_collisions": num_collisions,
            "dimensions": dimensions,
            "energy_range": energy_range,
            "use_primes": use_primes,
            "num_detected_particles": len(self.session_data["📊"]["detected_particles"]),
            "string_signatures_found": signatures,
            "spectrum_peaks": spectrum[0].tolist() if len(spectrum) > 0 else [],
            "phonon_frequencies": phonon_freqs[:10],
            "timestamp": datetime.now().isoformat()
        }
        self.session_data["📊"]["advanced_summary"] = summary
        return summary

# --- FUNC: string_collision_operator ---
def string_collision_operator(self, code: str) -> str:
        """
        Использует результаты столкновений как оператор мутации для кода.
        Например, заменяет случайную подстроку на продукт столкновения.
        """
        collisions = self.session_data["📊"]["collisions"]
        if not collisions:
            return code
        # Берём последнее столкновение
        last = collisions[-1]
        products = last.get("products", [])
        if not products:
            return code
        # Случайный продукт
        prod = random.choice(products)
        # Извлекаем "частоту" продукта как строку
        freq_str = str(prod.get("frequency", 0))[:4]
        # Заменяем случайную часть кода на эту строку
        if len(code) > 4:
            pos = random.randint(0, len(code)-4)
            new_code = code[:pos] + freq_str + code[pos+4:]
            return new_code
        return code + freq_str

# --- FUNC: evaluate_with_string_resonance ---
def evaluate_with_string_resonance(self, code: str, result: Any) -> float:
        """
        Оценка fitness с учётом резонанса со струнными и фононными частотами.
        """
        base = self.evaluate_code(code, result)
        phonon_res = self.phonon_resonance_fitness(code)
        # Добавляем резонанс с нулями дзета-функции
        zero_res = self.interact_with_spectrum(code)
        # Суммируем с весами
        total = base + 0.3 * phonon_res + 0.2 * zero_res
        return total

