# --- FUNC: generate_seismogram ---
def generate_seismogram(self, depth: float, magnitude: float = 4.0) -> np.ndarray:
        """
        Генерирует синтетическую сейсмограмму для заданной глубины и магнитуды.
        Использует модель слоёв для расчёта времён прихода волн.
        """
        # Временная сетка
        t = np.linspace(0, self.duration, int(self.duration * self.sampling_rate))
        signal = np.zeros_like(t)
        # Расчёт времён прихода P-волны из гипоцентра (глубина)
        # Упрощённо: используем среднюю скорость
        v_p = 6000  # м/с (примерно в коре)
        travel_time = depth / v_p
        # Добавляем импульс с затуханием
        # Используем вейвлет Рикера
        idx = int(travel_time * self.sampling_rate)
        if idx < len(t):
            # Вейвлет Рикера
            peak_freq = 2.0  # Гц
            wavelet = (1 - 2 * (np.pi * peak_freq * (t - travel_time))**2) * np.exp(-(np.pi * peak_freq * (t - travel_time))**2)
            signal += magnitude * wavelet
        # Добавляем шум (сейсмический шум)
        noise = np.random.normal(0, 0.05, len(t))
        signal += noise
        return signal

# --- FUNC: detect_anomalies ---
def detect_anomalies(self, historical_signals: List[np.ndarray]) -> List[Dict]:
        """
        Анализирует временной ряд сейсмограмм и ищет аномалии (потенциальные предвестники).
        """
        anomalies = []
        for i, sig in enumerate(historical_signals):
            features = self.extract_features(sig)
            # Простая эвристика: если энергия растёт, а частота падает — возможно предвестник
            if features['energy'] > np.mean([self.extract_features(s)['energy'] for s in historical_signals[:max(0,i-5)]]) * 1.5:
                anomalies.append({
                    'timestamp': i,
                    'type': 'energy_anomaly',
                    'energy': features['energy']
                })
            if features['arrival_time'] < np.mean([self.extract_features(s)['arrival_time'] for s in historical_signals[:max(0,i-5)]]) * 0.8:
                anomalies.append({
                    'timestamp': i,
                    'type': 'arrival_time_anomaly',
                    'arrival_time': features['arrival_time']
                })
        return anomalies

# --- FUNC: train_wave_classifier ---
def train_wave_classifier(self, num_samples: int = 200):
        """
        Обучает ML-модель классификации сейсмических волн (P, S, поверхностные).
        """
        X = []
        y = []
        for _ in range(num_samples):
            # Генерируем синтетический сигнал с разными параметрами
            depth = np.random.uniform(5, 100)  # км
            mag = np.random.uniform(2, 7)
            signal = self.generate_seismogram(depth, mag)
            features = self.extract_features(signal)
            # Метка: по глубине и соотношению P/S
            if depth < 30:
                label = 0  # P-волна (кора)
            elif depth < 100:
                label = 1  # S-волна
            else:
                label = 2  # поверхностные волны
            X.append([features['max_amplitude'], features['energy'], features['arrival_time']])
            y.append(label)
        X = np.array(X)
        y = np.array(y)
        model = RandomForestClassifier(n_estimators=50, max_depth=10, random_state=42)
        model.fit(X, y)
        return model

# --- FUNC: plot_seismogram ---
def plot_seismogram(self, signal: np.ndarray):
        """
        Визуализирует временной сигнал и его спектр.
        """
        t = np.linspace(0, self.duration, len(signal))
        fig, axs = plt.subplots(2, 1, figsize=(10, 6))
        axs[0].plot(t, signal)
        axs[0].set_title('Сейсмограмма')
        axs[0].set_xlabel('Время, с')
        axs[0].set_ylabel('Амплитуда')
        axs[0].grid(True)
        # Спектр
        fft_vals = fft(signal)
        freqs = fftfreq(len(signal), 1/self.sampling_rate)
        axs[1].plot(freqs[:len(freqs)//2], np.abs(fft_vals[:len(fft_vals)//2]))
        axs[1].set_title('Спектр')
        axs[1].set_xlabel('Частота, Гц')
        axs[1].set_ylabel('Амплитуда')
        axs[1].grid(True)
        plt.tight_layout()
        plt.show()

# --- FUNC: set_motor_commands ---
def set_motor_commands(self, left: float, right: float):
        """Устанавливает скорости левого и правого колеса."""
        # Простая модель дифференциального привода
        self.speed = (left + right) / 2
        self.angular_speed = (right - left) / 0.2

# --- FUNC: get_sensors ---
def get_sensors(self):
        """Получает показания сенсоров."""
        try:
            resp = self.session.get(f'{self.base_url}/sensors', timeout=0.1)
            return resp.json()
        except Exception as e:
            print(f"Ошибка получения сенсоров: {e}")
            return {'ultrasonic': 1.0, 'infrared': 0.5, 'x': 0, 'y': 0, 'angle': 0}

# --- FUNC: get_position ---
def get_position(self) -> Tuple[float, float]:
        return self.x, self.y

# --- FUNC: decode_spikes_to_commands ---
def decode_spikes_to_commands(self, spike_times: List[float]) -> Tuple[float, float]:
        """
        Преобразует времена спайков в команды для робота.
        Использует простую эвристику: частота спайков → скорость, разность фаз → поворот.
        """
        if not spike_times:
            return 0.0, 0.0
        # Частота спайков (Гц)
        if len(spike_times) > 1:
            freq = 1.0 / np.mean(np.diff(spike_times)) if np.mean(np.diff(spike_times)) > 0 else 0
        else:
            freq = 1.0
        # Масштабируем скорость
        speed = np.clip(freq / 10.0, 0, 1)  # макс. 1
        # Угловой поворот: среднее значение спайков (фаза)
        angle_cmd = np.mean(np.sin(spike_times)) * 0.5
        return speed, angle_cmd

# --- FUNC: train_adaptive_model ---
def train_adaptive_model(self, num_samples: int = 100):
        """
        Обучает ML-модель предсказывать оптимальные команды на основе сенсорных данных.
        """
        X = []  # сенсоры
        y = []  # команды (left, right)
        for _ in range(num_samples):
            # Генерируем случайное состояние робота
            self.robot.x = np.random.uniform(-5, 5)
            self.robot.y = np.random.uniform(-5, 5)
            self.robot.angle = np.random.uniform(-np.pi, np.pi)
            sensors = self.robot.get_sensors()
            # Эвристика: команды направляют робота к центру
            dist = np.sqrt(self.robot.x**2 + self.robot.y**2)
            angle_error = np.arctan2(-self.robot.y, -self.robot.x) - self.robot.angle
            # Нормализуем угол
            angle_error = np.arctan2(np.sin(angle_error), np.cos(angle_error))
            # Команды
            left = 0.5 - 0.5 * angle_error / np.pi
            right = 0.5 + 0.5 * angle_error / np.pi
            X.append([sensors['ultrasonic'], sensors['infrared'], dist, angle_error])
            y.append([left, right])
        X = np.array(X)
        y = np.array(y)
        model = RandomForestRegressor(n_estimators=50, max_depth=10, random_state=42)
        model.fit(X, y)
        self.ml_model = model
        return model

# --- FUNC: adaptive_control ---
def adaptive_control(self, sensors: Dict) -> Tuple[float, float]:
        """
        Использует ML-модель для генерации команд на основе сенсоров.
        """
        if self.ml_model is None:
            raise ValueError("ML-модель не обучена")
        dist = np.sqrt(self.robot.x**2 + self.robot.y**2)
        angle_error = np.arctan2(-self.robot.y, -self.robot.x) - self.robot.angle
        angle_error = np.arctan2(np.sin(angle_error), np.cos(angle_error))
        X_input = np.array([[sensors['ultrasonic'], sensors['infrared'], dist, angle_error]])
        left, right = self.ml_model.predict(X_input)[0]
        return left, right

# --- FUNC: animate_robot ---
def animate_robot(self, steps: int = 200, interval: int = 50):
        """
        Анимация движения робота и нейронной активности.
        """
        fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(12, 6))
        ax1.set_xlim(-5, 5)
        ax1.set_ylim(-5, 5)
        ax1.set_title('Робот')
        ax1.set_xlabel('x')
        ax1.set_ylabel('y')
        robot_point, = ax1.plot([], [], 'ro', markersize=10)
        trail_line, = ax1.plot([], [], 'b--', alpha=0.5)
        target_point, = ax1.plot(0, 0, 'g*', markersize=15, label='Цель')

        ax2.set_xlabel('Время (усл.)')
        ax2.set_ylabel('Скорость')
        ax2.set_title('Команды')
        left_line, = ax2.plot([], [], 'r-', label='Левое колесо')
        right_line, = ax2.plot([], [], 'b-', label='Правое колесо')
        ax2.legend()

        command_history = []

        def update(frame):
            # Один шаг управления
            result = self.step(dt=0.02)
            pos = result['position']
            left, right = result['commands']
            command_history.append((left, right))
            # Обновляем позицию робота
            robot_point.set_data([pos[0]], [pos[1]])
            # Траектория
            traj = np.array(self.robot.trajectory)
            if len(traj) > 1:
                trail_line.set_data(traj[:,0], traj[:,1])
            # Команды
            if len(command_history) > 50:
                command_history.pop(0)
            if command_history:
                cmds = np.array(command_history)
                left_line.set_data(range(len(cmds)), cmds[:,0])
                right_line.set_data(range(len(cmds)), cmds[:,1])
            return robot_point, trail_line, left_line, right_line

        ani = FuncAnimation(fig, update, frames=steps, interval=interval, blit=True)
        plt.tight_layout()
        plt.show()
        return ani

# --- FUNC: create_cloak_for_object ---
def create_cloak_for_object(self, object_description: Dict, medium: str = "water"):
        """
        Создаёт акустический кокон для объекта (например, подводной лодки).
        """
        # Проектируем кокон с учётом размеров объекта
        radius = object_description.get("radius", 1.0)
        cloak = self.design_acoustic_cloak(geometry="cylindrical", layers=5, medium=medium)
        cloak["inner_radius"] = radius * 0.8  # чтобы объект поместился
        cloak["outer_radius"] = radius * 1.5
        # Оптимизируем
        opt_result = self.optimize_cloak(medium=medium, frequency=1000, generations=5)
        best_cloak = opt_result["best_cloak"]
        # Проводим эмуляцию эксперимента
        exp = self.emulate_cloak_experiment(best_cloak, frequency=1000, medium=medium)
        return {"cloak": best_cloak, "experiment": exp}

# --- FUNC: apply_stdp ---
def apply_stdp(self, pre_spike_time: float, post_spike_time: float, weight: float) -> float:
        """
        Обновляет синаптический вес на основе STDP.
        """
        dt = pre_spike_time - post_spike_time
        if dt < 0:  # постсинаптический спайк после пресинаптического (LTP)
            delta_w = self.learning_rate * np.exp(dt / self.tau_stdp)
        else:  # LTD
            delta_w = -self.learning_rate * np.exp(-dt / self.tau_stdp)
        return weight + delta_w

# --- FUNC: update_synaptic_weights ---
def update_synaptic_weights(self):
        """
        Обновляет веса на основе зарегистрированных спайков.
        """
        # Для каждой пары нейронов (i, j) с недавними спайками
        for i in range(self.num_neurons):
            for j in range(self.num_neurons):
                if i == j:
                    continue
                # Времена спайков (последние 2)
                times_i = list(self.spike_times[i])
                times_j = list(self.spike_times[j])
                if len(times_i) > 0 and len(times_j) > 0:
                    # Берем последние спайки
                    pre_t = times_i[-1]
                    post_t = times_j[-1]
                    # Применяем STDP
                    self.W[i, j] = self.apply_stdp(pre_t, post_t, self.W[i, j])
        # Ограничиваем веса
        self.W = np.clip(self.W, 0, 1)

# --- FUNC: adapt_acoustic_parameters ---
def adapt_acoustic_parameters(self, target_activity: float = 0.3):
        """
        Адаптирует акустическую стимуляцию для достижения целевого уровня активности.
        """
        # Текущая активность (доля нейронов, сгенерировавших спайк за последние 10 шагов)
        recent_spikes = list(self.spike_history)[-10:]
        current_activity = len(set(recent_spikes)) / self.num_neurons
        # Коррекция силы и частоты
        error = target_activity - current_activity
        # ПИД-подобное управление (упрощённо)
        for i in range(self.num_neurons):
            # Меняем силу
            self.acoustic_strength[i] += 0.01 * error * np.random.randn()
            self.acoustic_strength[i] = np.clip(self.acoustic_strength[i], 0, 1)
            # Меняем частоту (в узком диапазоне)
            self.acoustic_freq[i] += 50 * error * np.random.randn()
            self.acoustic_freq[i] = np.clip(self.acoustic_freq[i], 500, 5000)

# --- FUNC: calculate_anti_wave ---
def calculate_anti_wave(self, incident_wave: np.ndarray, cloak_response: Dict) -> np.ndarray:
        """
        Вычисляет анти-волну для гашения отражённого сигнала.
        Использует измеренную передаточную функцию кокона.
        """
        # Имитация анти-волны: инвертируем фазу и масштабируем по амплитуде отражения
        reflection = cloak_response.get('R', 0.5)
        phase = np.pi  # инверсия фазы
        anti_amplitude = reflection * 0.9  # немного меньше для стабильности
        anti_wave = -anti_amplitude * incident_wave * np.exp(1j * phase)
        return anti_wave

# --- FUNC: apply_suppression ---
def apply_suppression(self, incident_signal: np.ndarray, cloak_id: str) -> np.ndarray:
        """
        Применяет активное подавление к падающему сигналу.
        """
        cloak = self.session_data["🫥"]["cloak_designs"][cloak_id] if cloak_id in self.session_data["🫥"]["cloak_designs"] else None
        if cloak is None:
            return incident_signal
        anti = self.calculate_anti_wave(incident_signal, cloak)
        # Суммируем с падающим сигналом (результирующий эхосигнал)
        result = incident_signal + anti
        self.session_data["🔇"]["suppression_active"] = True
        return result

# --- FUNC: focus_on ---
def focus_on(self, idx=None, x=None, y=None, strength=0.2, radius=1.0):
    """
    Фокусировка наблюдателя на области пространства.
    Увеличивает амплитуды всех EM-резонаторов в радиусе radius от точки (x,y)
    или от idx-го резонанса.
    """
    if idx is not None and 0 <= idx < len(self.resonances):
        x = self.resonances[idx]['x']
        y = self.resonances[idx]['y']
    elif x is None or y is None:
        print("Укажите idx резонанса или координаты (x,y)")
        return

    for e in self.E_resonators + self.B_resonators:
        dist = np.hypot(e.x - x, e.y - y)
        if dist < radius:
            # Усиление амплитуды с плавным затуханием по расстоянию
            factor = 1.0 + strength * (1.0 - dist/radius)
            e.amp *= factor
            e.amp = min(e.amp, 3.0)  # ограничим, чтобы не улетело

    print(f"🌀 Фокусировка в ({x:.2f},{y:.2f}) с силой {strength:.2f}")

# --- FUNC: rl_step ---
def rl_step(self, action, strength=0.1):
        all_res = self.E_resonators + self.B_resonators
        if not all_res:
            return 0.0
        if action >= len(all_res):
            action = len(all_res) - 1
        old_coherence = self._compute_coherence()
        res = all_res[action]
        res.amp *= (1 + strength)
        self._update_field_from_EM()
        new_coherence = self._compute_coherence()
        reward = new_coherence - old_coherence
        if reward < 0:
            res.amp /= (1 + strength)
            self._update_field_from_EM()
            reward = 0.0
        return reward

# --- FUNC: animate_full ---
def animate_full(self, steps=30, interval=200, coupling=0.15, hbar=0.05,
                     metric_strength=0.1, entanglement_strength=0.02,
                     save=False, filename='animation.gif'):
        if not self.E_resonators or not self.B_resonators:
            print("Добавьте E и B резонаторы.")
            return
        z_slice = self.Nz // 2

        fig, axs = plt.subplots(2, 2, figsize=(12, 10))
        fig.suptitle('Эволюция реляционной физики (3D, срез Z=0)', fontsize=16)

        im_psi = axs[0,0].imshow(np.abs(self.psi[:, :, z_slice]).T,
                                 extent=[self.x.min(), self.x.max(), self.y.min(), self.y.max()],
                                 origin='lower', cmap='viridis', animated=True)
        axs[0,0].set_title('|ψ|')

        im_metric = axs[0,1].imshow(self.metric.field[:, :, z_slice].T,
                                    extent=[self.x.min(), self.x.max(), self.y.min(), self.y.max()],
                                    origin='lower', cmap='plasma', animated=True)
        axs[0,1].set_title('Кривизна')

        im_c = axs[1,0].imshow(np.ones((self.N, self.N)),
                               extent=[self.x.min(), self.x.max(), self.y.min(), self.y.max()],
                               origin='lower', cmap='coolwarm', vmin=0.5, vmax=2.0, animated=True)
        axs[1,0].set_title('c_eff')

        im_freq = axs[1,1].imshow(np.ones((self.N, self.N)),
                                  extent=[self.x.min(), self.x.max(), self.y.min(), self.y.max()],
                                  origin='lower', cmap='plasma', animated=True)
        axs[1,1].set_title('Частоты')

        plt.colorbar(im_psi, ax=axs[0,0])
        plt.colorbar(im_metric, ax=axs[0,1])
        plt.colorbar(im_c, ax=axs[1,0])
        plt.colorbar(im_freq, ax=axs[1,1])

        e_clock = self.E_resonators[0]
        b_clock = self.B_resonators[0]
        rel_time = RelationalTime(e_clock, b_clock, hbar=hbar)
        status_text = axs[0,0].text(0.02, 0.98, '', transform=axs[0,0].transAxes,
                                    color='white', fontsize=10, verticalalignment='top')

        def update(frame):
            tick = rel_time.tick()
            dt = rel_time.get_dt()
            if dt is not None and dt > 0:
                curv_avg = np.mean(self.metric.field)
                curvature_factor = 1.0 / (1.0 + metric_strength * curv_avg)
                dt = dt * curvature_factor
                self.time_ticks += dt

                self.update_metric(dt)

                for e in self.E_resonators + self.B_resonators:
                    curv_local = self._get_curvature_at(e.x, e.y, e.z)
                    e.apply_redshift(curv_local, strength=metric_strength)

                for e in self.E_resonators:
                    for b in self.B_resonators:
                        phase_shift = metric_strength * curv_avg * dt
                        e.phase += phase_shift
                        b.phase += phase_shift
                        delta_phase = e.phase - b.phase
                        transfer = coupling * np.sin(delta_phase) * dt
                        e_energy = e.amp**2
                        b_energy = b.amp**2
                        if e_energy > 0 and b_energy > 0:
                            e.amp = np.sqrt(max(0, e_energy - transfer))
                            b.amp = np.sqrt(max(0, b_energy + transfer))
                        elif e_energy > 0 and b_energy == 0:
                            b.amp = np.sqrt(e_energy)
                            e.amp = 0
                        elif b_energy > 0 and e_energy == 0:
                            e.amp = np.sqrt(b_energy)
                            b.amp = 0
                        e.tick(dt)
                        b.tick(dt)

                if entanglement_strength > 0:
                    all_res = self.E_resonators + self.B_resonators
                    for i in range(len(all_res)):
                        for j in range(i+1, len(all_res)):
                            r1, r2 = all_res[i], all_res[j]
                            dist = np.hypot(r1.x - r2.x, r1.y - r2.y, r1.z - r2.z)
                            if dist < 0.5:
                                avg_phase = (r1.phase + r2.phase) / 2
                                r1.phase += entanglement_strength * (avg_phase - r1.phase) * dt
                                r2.phase += entanglement_strength * (avg_phase - r2.phase) * dt

                self._update_field_from_EM()

            im_psi.set_array(np.abs(self.psi[:, :, z_slice]).T)
            im_metric.set_array(self.metric.field[:, :, z_slice].T)

            c_map = np.zeros((self.N, self.N))
            f_map = np.zeros((self.N, self.N))
            for i in range(self.N):
                for j in range(self.N):
                    c_vals = []
                    f_vals = []
                    for e in self.E_resonators + self.B_resonators:
                        dist = np.hypot(self.X[i,j,z_slice] - e.x,
                                        self.Y[i,j,z_slice] - e.y,
                                        self.Z[i,j,z_slice] - e.z)
                        if dist < 2.0:
                            c_vals.append(e.get_c() * np.exp(-dist**2 / 0.5))
                            f_vals.append(e.freq * np.exp(-dist**2 / 0.5))
                    c_map[i,j] = np.mean(c_vals) if c_vals else 1.0
                    f_map[i,j] = np.mean(f_vals) if f_vals else 0
            im_c.set_array(c_map.T)
            im_freq.set_array(f_map.T)

            status_text.set_text(f'Шаг {frame+1}/{steps}, тиков: {rel_time.ticks:.2f}, dt: {dt:.4f}' if dt else 'Время застыло')
            return im_psi, im_metric, im_c, im_freq, status_text

        ani = animation.FuncAnimation(fig, update, frames=steps, interval=interval, blit=True)
        if save:
            ani.save(filename, writer='pillow')
            print(f"Анимация сохранена в {filename}")
        else:
            plt.show()
        return ani

# --- FUNC: on_focus ---
def on_focus(b):
            with self.output:
                clear_output()
                idx = focus_idx_input.value
                strength = focus_strength_slider.value
                if 0 <= idx < len(self.phys.resonances):
                    self.phys.focus_on(idx=idx, strength=strength)
                    print(f"Фокусировка на резонансе {idx} с силой {strength:.2f}")
                    self.phys._update_field_from_EM()
                    self.phys.plot_field()
                else:
                    print("Некорректный индекс резонанса. Сначала найдите резонансы.")

# --- FUNC: on_anim ---
def on_anim(b):
            with self.output:
                clear_output()
                status.value = "<b>Статус:</b> Анимация..."
                ent = entangle_slider.value
                self.phys.animate_full(steps=50, interval=200, coupling=0.15,
                                      hbar=0.05, metric_strength=0.1,
                                      entanglement_strength=ent)
                status.value = "<b>Статус:</b> Анимация завершена."

# --- FUNC: on_rl ---
def on_rl(b):
            with self.output:
                clear_output()
                steps = rl_steps_input.value
                strength = rl_strength_slider.value
                all_res = self.phys.E_resonators + self.phys.B_resonators
                if not all_res:
                    print("Нет резонаторов.")
                    return
                total_reward = 0.0
                for _ in range(steps):
                    action = np.random.randint(0, len(all_res))
                    reward = self.phys.rl_step(action, strength)
                    total_reward += reward
                print(f"RL: {steps} шагов, суммарная награда = {total_reward:.4f}")
                self.phys._update_field_from_EM()
                self.phys.plot_field()

# --- FUNC: encode_message ---
def encode_message(self, message: str, frequency: float) -> np.ndarray:
        """
        Кодирует текстовое сообщение в акустический сигнал с использованием фононных мод.
        """
        # Преобразуем текст в биты (ASCII)
        bits = ''.join(format(ord(c), '08b') for c in message)
        # Модулируем частоту: бит 1 = частота + delta, бит 0 = частота - delta
        delta = 100  # Гц
        t = np.linspace(0, 1, 1000)
        signal = np.array([])
        for bit in bits:
            if bit == '1':
                sig = np.sin(2 * np.pi * (frequency + delta) * t)
            else:
                sig = np.sin(2 * np.pi * (frequency - delta) * t)
            signal = np.concatenate([signal, sig])
        return signal

# --- FUNC: decode_message ---
def decode_message(self, signal: np.ndarray, frequency: float) -> str:
        """
        Декодирует акустический сигнал обратно в текст.
        """
        # Демодуляция: определяем частоту в каждом битовом интервале
        bit_length = 1000
        bits = []
        for i in range(0, len(signal), bit_length):
            segment = signal[i:i+bit_length]
            # БПФ для определения доминирующей частоты
            fft = np.fft.fft(segment)
            freqs = np.fft.fftfreq(len(segment))
            peak_freq = freqs[np.argmax(np.abs(fft))]
            if peak_freq > frequency:
                bits.append('1')
            else:
                bits.append('0')
        # Преобразуем биты в текст
        bit_string = ''.join(bits)
        chars = [chr(int(bit_string[i:i+8], 2)) for i in range(0, len(bit_string), 8)]
        return ''.join(chars)

# --- FUNC: configure_underwater_mode ---
def configure_underwater_mode(self, water_params: Dict):
        """
        Настраивает лабораторию для работы с подводными акустическими системами.
        water_params: {'speed_of_sound': 1500, 'density': 1000, 'depth': 10}
        """
        # Адаптируем константы
        self.session_data["💧"] = water_params
        # Масштабируем частоты: фононные -> акустические
        scale = water_params.get('speed_of_sound', 1500) / 3000  # относительная скорость
        # Сохраняем масштаб для использования в экспериментах
        self.session_data["💧"]["frequency_scale"] = scale
        self.lab_log(f"Подводный режим активирован. Параметры: {water_params}")
        return "Подводный режим настроен"

# --- FUNC: generate_echo_dataset ---
def generate_echo_dataset(self, num_samples: int = 10000, test_size: float = 0.2) -> Dict:
        """
        Генерирует датасет для задачи подавления эхосигнала.
        Признаки: частота, угол падения, толщина материала, плотность, модуль упругости, глубина.
        Цель: коэффициент отражения (R) и коэффициент прохождения (T).
        """
        # Диапазоны параметров
        freqs = np.random.uniform(1000, 50000, num_samples)
        angles = np.random.uniform(0, 60, num_samples)  # градусы
        thickness = np.random.uniform(0.01, 0.1, num_samples)
        density = np.random.uniform(100, 2000, num_samples)
        elastic = np.random.uniform(1e7, 1e9, num_samples)
        depth = np.random.uniform(10, 200, num_samples)

        # Синтетическая функция для R и T (нелинейная, с шумом)
        # Упрощённая модель: R = f(thickness, freq, angle, impedance mismatch)
        c_w = 1500 + 0.02 * depth  # скорость в воде с глубиной
        rho_w = 1025
        Z_w = rho_w * c_w
        # Импеданс материала
        c_m = np.sqrt(elastic / density)
        Z_m = density * c_m
        # Коэффициент отражения (для нормального падения)
        R_0 = (Z_m - Z_w) / (Z_m + Z_w)
        # Учёт угла (приближённо)
        R_theta = R_0 * np.cos(np.radians(angles))**2
        # Учёт резонанса (зависит от толщины и частоты)
        k = 2 * np.pi * freqs / c_m
        resonance = np.sin(k * thickness) * 0.5
        R = R_theta + 0.3 * resonance * np.random.normal(0, 0.1, num_samples)
        R = np.clip(R, 0, 1)
        T = 1 - R + 0.2 * np.random.normal(0, 0.05, num_samples)
        T = np.clip(T, 0, 1)

        # Создаём DataFrame
        df = pd.DataFrame({
            'frequency': freqs,
            'angle': angles,
            'thickness': thickness,
            'density': density,
            'elastic_modulus': elastic,
            'depth': depth,
            'R': R,
            'T': T
        })
        # Разделяем на признаки и цели
        features = df[['frequency', 'angle', 'thickness', 'density', 'elastic_modulus', 'depth']]
        targets = df[['R', 'T']]
        # Масштабируем признаки
        scaler = StandardScaler()
        features_scaled = scaler.fit_transform(features)
        # Разделяем на train/test
        X_train, X_test, y_train, y_test = train_test_split(
            features_scaled, targets, test_size=test_size, random_state=42
        )
        dataset = {
            'X_train': X_train.tolist(),
            'X_test': X_test.tolist(),
            'y_train': y_train.values.tolist(),
            'y_test': y_test.values.tolist(),
            'feature_names': features.columns.tolist(),
            'target_names': ['R', 'T'],
            'scaler': scaler,
            'num_samples': num_samples
        }
        self.session_data["📊"]["datasets"].append(dataset)
        self.session_data["📊"]["current_dataset"] = dataset
        return dataset

# --- FUNC: generate_comm_dataset ---
def generate_comm_dataset(self, num_samples: int = 5000, snr_range: Tuple[float, float] = (5, 30)) -> Dict:
        """
        Генерирует датасет для задачи декодирования акустического сигнала.
        Признаки: SNR, модуляция (BPSK, QPSK), длина сообщения, глубина, волнение.
        Цель: ошибка бит (BER).
        """
        modulations = ['BPSK', 'QPSK']
        snrs = np.random.uniform(snr_range[0], snr_range[1], num_samples)
        msg_lengths = np.random.randint(10, 100, num_samples)
        depths = np.random.uniform(10, 200, num_samples)
        wave_heights = np.random.uniform(0, 2, num_samples)
        # Эффективная SNR с учётом глубины и волнения
        effective_snr = snrs - 0.05 * depths - 0.5 * wave_heights
        # Синтетическая BER (упрощённая модель)
        # BER ~ 0.5 * erfc(sqrt(SNR_eff)) для BPSK, и в 2 раза хуже для QPSK
        ber = np.zeros(num_samples)
        for i in range(num_samples):
            mod = np.random.choice(modulations)
            snr_lin = 10**(effective_snr[i]/10)
            if mod == 'BPSK':
                ber[i] = 0.5 * (1 - np.sqrt(snr_lin/(1+snr_lin)))
            else:  # QPSK
                ber[i] = 0.5 * (1 - np.sqrt(snr_lin/(2+snr_lin)))
            # Добавляем шум
            ber[i] += np.random.normal(0, 0.01)
            ber[i] = np.clip(ber[i], 0, 0.5)
        # Создаём DataFrame
        df = pd.DataFrame({
            'SNR_dB': snrs,
            'modulation': np.random.choice(modulations, num_samples),
            'message_length': msg_lengths,
            'depth': depths,
            'wave_height': wave_heights,
            'BER': ber
        })
        # Кодируем модуляцию (one-hot)
        mod_dummies = pd.get_dummies(df['modulation'], prefix='mod')
        features = pd.concat([
            df[['SNR_dB', 'message_length', 'depth', 'wave_height']],
            mod_dummies
        ], axis=1)
        targets = df[['BER']]
        # Масштабируем
        scaler = StandardScaler()
        features_scaled = scaler.fit_transform(features)
        X_train, X_test, y_train, y_test = train_test_split(
            features_scaled, targets, test_size=0.2, random_state=42
        )
        dataset = {
            'X_train': X_train.tolist(),
            'X_test': X_test.tolist(),
            'y_train': y_train.values.tolist(),
            'y_test': y_test.values.tolist(),
            'feature_names': features.columns.tolist(),
            'target_names': ['BER'],
            'scaler': scaler,
            'num_samples': num_samples
        }
        self.session_data["📊"]["datasets"].append(dataset)
        return dataset

# --- FUNC: generate_cloak_control_dataset ---
def generate_cloak_control_dataset(self, num_samples: int = 10000) -> Dict:
        """
        Генерирует датасет для управления параметрами кокона в реальном времени.
        Признаки: текущий R, T, частота сонара, угол, глубина, скорость объекта.
        Цель: изменение толщины, плотности, упругости для минимизации R.
        """
        # Случайные состояния
        R_current = np.random.uniform(0.1, 0.9, num_samples)
        T_current = 1 - R_current + np.random.normal(0, 0.05, num_samples)
        freq = np.random.uniform(1000, 50000, num_samples)
        angle = np.random.uniform(0, 60, num_samples)
        depth = np.random.uniform(10, 200, num_samples)
        speed = np.random.uniform(0, 10, num_samples)
        # Целевое изменение для минимизации R (упрощённо)
        # Если R > 0.3, нужно уменьшить плотность и увеличить толщину
        delta_density = np.where(R_current > 0.3, -10 * R_current, 10 * R_current)
        delta_thickness = np.where(R_current > 0.3, 0.01 * R_current, -0.01 * R_current)
        delta_elastic = np.where(R_current > 0.3, 1e6 * R_current, -1e6 * R_current)
        # Добавляем шум
        delta_density += np.random.normal(0, 5, num_samples)
        delta_thickness += np.random.normal(0, 0.001, num_samples)
        delta_elastic += np.random.normal(0, 0.1e6, num_samples)
        # Создаём DataFrame
        df = pd.DataFrame({
            'R': R_current,
            'T': T_current,
            'frequency': freq,
            'angle': angle,
            'depth': depth,
            'speed': speed,
            'delta_density': delta_density,
            'delta_thickness': delta_thickness,
            'delta_elastic': delta_elastic
        })
        features = df[['R', 'T', 'frequency', 'angle', 'depth', 'speed']]
        targets = df[['delta_density', 'delta_thickness', 'delta_elastic']]
        # Масштабируем
        scaler = StandardScaler()
        features_scaled = scaler.fit_transform(features)
        X_train, X_test, y_train, y_test = train_test_split(
            features_scaled, targets, test_size=0.2, random_state=42
        )
        dataset = {
            'X_train': X_train.tolist(),
            'X_test': X_test.tolist(),
            'y_train': y_train.values.tolist(),
            'y_test': y_test.values.tolist(),
            'feature_names': features.columns.tolist(),
            'target_names': ['delta_density', 'delta_thickness', 'delta_elastic'],
            'scaler': scaler,
            'num_samples': num_samples
        }
        self.session_data["📊"]["datasets"].append(dataset)
        return dataset

# --- FUNC: export_dataset ---
def export_dataset(self, dataset_id: int = -1, format: str = 'numpy') -> Dict:
        """
        Экспортирует датасет в указанном формате ('numpy', 'tf', 'pytorch').
        """
        if dataset_id == -1:
            dataset = self.session_data["📊"]["current_dataset"]
        else:
            dataset = self.session_data["📊"]["datasets"][dataset_id]
        if dataset is None:
            return {"error": "Датасет не найден"}
        if format == 'numpy':
            return {
                'X_train': np.array(dataset['X_train']),
                'X_test': np.array(dataset['X_test']),
                'y_train': np.array(dataset['y_train']),
                'y_test': np.array(dataset['y_test'])
            }
        elif format == 'tf':
            # TensorFlow Dataset
            try:
                import tensorflow as tf
                train_ds = tf.data.Dataset.from_tensor_slices((dataset['X_train'], dataset['y_train']))
                test_ds = tf.data.Dataset.from_tensor_slices((dataset['X_test'], dataset['y_test']))
                return {'train_ds': train_ds, 'test_ds': test_ds}
            except ImportError:
                return {"error": "TensorFlow не установлен"}
        elif format == 'pytorch':
            try:
                import torch
                from torch.utils.data import TensorDataset, DataLoader
                X_train = torch.tensor(dataset['X_train'], dtype=torch.float32)
                y_train = torch.tensor(dataset['y_train'], dtype=torch.float32)
                X_test = torch.tensor(dataset['X_test'], dtype=torch.float32)
                y_test = torch.tensor(dataset['y_test'], dtype=torch.float32)
                train_ds = TensorDataset(X_train, y_train)
                test_ds = TensorDataset(X_test, y_test)
                return {'train_ds': train_ds, 'test_ds': test_ds}
            except ImportError:
                return {"error": "PyTorch не установлен"}
        else:
            return {"error": f"Неизвестный формат: {format}"}

