# --- FUNC: vacuum_energy_extraction ---
def vacuum_energy_extraction(self, iterations=100):
    """
    Моделирует извлечение энергии из квантового вакуума.
    Использует суперпозицию для генерации кода и оценивает, 
    сколько «энергии» (fitness) удалось получить по сравнению с вложенными мутациями.
    """
    invested = 0  # мера затраченных изменений (например, количество мутаций)
    gained = 0    # суммарный fitness сгенерированных кодов
    for _ in range(iterations):
        # Квантовая мутация (затраты)
        self.quantum_mutate()
        invested += 1
        # Генерация кода из текущего состояния
        code = self.noise_to_code()
        result = self.execute_code(code)
        fitness = self.evaluate_code(code, result)
        gained += fitness
    efficiency = gained / invested if invested else 0
    return efficiency

# --- FUNC: design_acoustic_cloak ---
def design_acoustic_cloak(self, geometry: str = "cylindrical", layers: int = 5,
                             material_params: Dict = None, medium: str = "air") -> Dict:
        """
        Проектирует акустический кокон на основе фононного кристалла.
        geometry: "cylindrical" или "spherical" или "planar".
        layers: количество слоёв метаматериала.
        material_params: dict с плотностью, модулем упругости и т.п.
        medium: среда распространения ("air", "water", "solid").
        """
        if material_params is None:
            # Параметры по умолчанию для фононного кристалла (Al, ПММА и т.п.)
            material_params = {
                "density": 2700,      # кг/м³ (алюминий)
                "young_modulus": 70e9, # Па
                "poisson_ratio": 0.33
            }
        # Вычисляем скорость звука в материале
        speed = np.sqrt(material_params["young_modulus"] / material_params["density"])
        # Параметры слоёв (градиент плотности и модуля)
        layer_params = []
        for i in range(layers):
            # Градиент: от внешнего к внутреннему (для фокусировки)
            factor = 1.0 - i / (layers * 2)
            layer_params.append({
                "density": material_params["density"] * (1 + 0.2 * i),
                "speed": speed * (1 - 0.1 * i)
            })
        cloak = {
            "geometry": geometry,
            "layers": layers,
            "material_params": material_params,
            "layer_params": layer_params,
            "medium": medium,
            "medium_speed": self.media[medium]["speed"],
            "outer_radius": 1.0,  # условно
            "inner_radius": 0.5
        }
        self.session_data["🥽"]["cloaks"].append(cloak)
        return cloak

# --- FUNC: simulate_acoustic_cloak ---
def simulate_acoustic_cloak(self, cloak: Dict, frequency: float = 1000, grid_size: int = 200) -> Dict:
        """
        Симулирует распространение звуковой волны через кокон методом FDTD.
        Возвращает поле давления и коэффициент рассеяния.
        """
        # Параметры сетки
        dx = 0.01  # шаг сетки (м)
        dt = dx / (cloak["medium_speed"] * 2)  # условие Куранта
        Nx = grid_size
        Ny = grid_size
        # Поле давления и скоростей
        p = np.zeros((Nx, Ny))
        vx = np.zeros((Nx, Ny))
        vy = np.zeros((Nx, Ny))
        # Источник (точечный)
        source_x = Nx // 4
        source_y = Ny // 2
        # Кокон: круг с радиусом cloak["outer_radius"] в узлах сетки
        center_x = Nx // 2
        center_y = Ny // 2
        outer_radius = int(cloak["outer_radius"] / dx)
        inner_radius = int(cloak["inner_radius"] / dx)
        # Маска слоёв (градиент плотности)
        mask = np.zeros((Nx, Ny))
        for i in range(Nx):
            for j in range(Ny):
                r = np.sqrt((i - center_x)**2 + (j - center_y)**2)
                if r < outer_radius:
                    mask[i, j] = 1.0
                    # Внутри кокона изменяем скорость звука (по слоям)
                    for layer_idx, layer in enumerate(cloak["layer_params"]):
                        r_layer = inner_radius + (outer_radius - inner_radius) * (layer_idx / len(cloak["layer_params"]))
                        if r < r_layer:
                            mask[i, j] = cloak["medium_speed"] / layer["speed"]
                            break
        # Временные шаги
        num_steps = 500
        p_record = []
        for t in range(num_steps):
            # Источник: импульс
            if t < 20:
                p[source_x, source_y] += 1.0 * np.sin(2 * np.pi * frequency * t * dt)
            # Обновление скорости
            vx[:, :-1] -= (p[:, 1:] - p[:, :-1]) / (mask[:, :-1] * dt)
            vy[:-1, :] -= (p[1:, :] - p[:-1, :]) / (mask[:-1, :] * dt)
            # Обновление давления
            p[1:-1, 1:-1] -= (vx[1:-1, 1:-1] - vx[1:-1, :-2] + vy[1:-1, 1:-1] - vy[:-2, 1:-1]) / (dx * dt)
            # Поглощение на границах (PML упрощённое)
            p[0, :] *= 0.98
            p[-1, :] *= 0.98
            p[:, 0] *= 0.98
            p[:, -1] *= 0.98
            # Запись поля (на каждом 10-м шаге)
            if t % 10 == 0:
                p_record.append(p.copy())
        # Вычисление коэффициента рассеяния (сравнение с полем без кокона)
        # Для простоты: отношение энергии за пределами кокона к энергии источника
        energy_outside = np.sum(p[center_x+outer_radius:, :]**2) + np.sum(p[:center_x-outer_radius, :]**2)
        energy_total = np.sum(p**2)
        scattering = energy_outside / (energy_total + 1e-10)
        result = {
            "pressure_fields": p_record,
            "scattering_coefficient": scattering,
            "frequency": frequency,
            "grid_size": grid_size,
            "dt": dt,
            "dx": dx
        }
        self.session_data["🥽"]["simulations"].append(result)
        return result

# --- FUNC: evaluate_cloak ---
def evaluate_cloak(self, simulation: Dict) -> float:
        """
        Оценивает эффективность кокона: чем меньше рассеяние, тем лучше.
        Возвращает значение от 0 (отлично) до 1 (плохо).
        """
        scattering = simulation.get("scattering_coefficient", 1.0)
        # Нормализуем к 0..1
        effectiveness = 1.0 - min(1.0, scattering * 2)
        return max(0, effectiveness)

# --- FUNC: optimize_cloak ---
def optimize_cloak(self, medium: str = "air", frequency: float = 1000, generations: int = 10) -> Dict:
        """
        Использует эволюционный подход для поиска оптимальных параметров кокона.
        """
        # Определяем диапазоны параметров: количество слоёв, плотность, модуль
        best_cloak = None
        best_score = -1.0
        population = []
        for _ in range(10):
            layers = np.random.randint(2, 8)
            density = np.random.uniform(1000, 8000)
            young_modulus = np.random.uniform(10e9, 200e9)
            cloak = self.design_acoustic_cloak(
                geometry="cylindrical",
                layers=layers,
                material_params={"density": density, "young_modulus": young_modulus, "poisson_ratio": 0.33},
                medium=medium
            )
            population.append(cloak)
        for gen in range(generations):
            scores = []
            for cloak in population:
                sim = self.simulate_acoustic_cloak(cloak, frequency, grid_size=100)
                score = self.evaluate_cloak(sim)
                scores.append(score)
                if score > best_score:
                    best_score = score
                    best_cloak = cloak
            # Отбор и скрещивание
            sorted_indices = np.argsort(scores)[::-1]
            new_population = [population[i] for i in sorted_indices[:5]]  # топ-5
            while len(new_population) < 10:
                parent1 = np.random.choice(new_population)
                parent2 = np.random.choice(new_population)
                # Кроссинговер: смешиваем параметры
                child_layers = (parent1["layers"] + parent2["layers"]) // 2
                child_density = (parent1["material_params"]["density"] + parent2["material_params"]["density"]) / 2
                child_modulus = (parent1["material_params"]["young_modulus"] + parent2["material_params"]["young_modulus"]) / 2
                # Мутация
                if np.random.rand() < 0.2:
                    child_layers += np.random.randint(-1, 2)
                    child_density *= (1 + np.random.uniform(-0.1, 0.1))
                    child_modulus *= (1 + np.random.uniform(-0.1, 0.1))
                child_layers = max(2, min(8, child_layers))
                child_density = max(1000, min(8000, child_density))
                child_modulus = max(10e9, min(200e9, child_modulus))
                child = self.design_acoustic_cloak(
                    geometry="cylindrical",
                    layers=child_layers,
                    material_params={"density": child_density, "young_modulus": child_modulus, "poisson_ratio": 0.33},
                    medium=medium
                )
                new_population.append(child)
            population = new_population
        # Сохраняем лучший результат
        self.session_data["🥽"]["optimizations"].append({
            "best_cloak": best_cloak,
            "best_score": best_score,
            "generations": generations
        })
        return {"best_cloak": best_cloak, "score": best_score}

# --- FUNC: emulate_cloak_experiment ---
def emulate_cloak_experiment(self, cloak: Dict, frequency: float = 1000, medium: str = "water") -> Dict:
        """
        Эмулирует реальный эксперимент: объект внутри кокона, измерение звука снаружи.
        Возвращает уровень звукового давления (SPL) снаружи и внутри.
        """
        # Симулируем поле с коконом
        sim = self.simulate_acoustic_cloak(cloak, frequency, grid_size=150)
        field = sim["pressure_fields"][-1]  # последний кадр
        # Измеряем SPL внутри и снаружи (условно)
        center = field.shape[0] // 2
        radius = int(cloak["outer_radius"] / sim["dx"])
        # Внутри (центр)
        inner_spl = np.mean(field[center-5:center+5, center-5:center+5]**2)
        # Снаружи (на расстоянии radius*2)
        outer_spl = np.mean(field[center+2*radius:center+2*radius+10, center-5:center+5]**2)
        # Если нет кокона, то рассеяние большое, поэтому отношение
        cloak_effect = 1.0 - outer_spl / (inner_spl + 1e-10)
        experiment = {
            "frequency": frequency,
            "medium": medium,
            "inner_spl": inner_spl,
            "outer_spl": outer_spl,
            "cloak_effect": cloak_effect,
            "scattering": sim["scattering_coefficient"]
        }
        return experiment

# --- FUNC: plot_cloak_simulation ---
def plot_cloak_simulation(self, sim: Dict):
        """
        Визуализирует поле давления и кокон.
        """
        field = sim["pressure_fields"][-1]
        plt.figure(figsize=(8,6))
        plt.imshow(field, cmap='RdBu', extent=[-sim["dx"]*sim["grid_size"]/2, sim["dx"]*sim["grid_size"]/2,
                                              -sim["dx"]*sim["grid_size"]/2, sim["dx"]*sim["grid_size"]/2])
        plt.colorbar(label='Давление')
        plt.title('Акустическое поле с коконом')
        plt.xlabel('x (м)')
        plt.ylabel('y (м)')
        plt.show()

# --- FUNC: coherence_heart ---
def coherence_heart(self):
    """
    Вычисляет меру сердечной когерентности — степень согласованности
    фаз всех резонаторов с общим полем.
    Возвращает значение от 0 (хаос) до 1 (полная когерентность).
    """
    if not self.E_resonators and not self.B_resonators:
        return 0.0
    all_res = self.E_resonators + self.B_resonators
    # Вычисляем среднюю фазу поля в центре
    center_phase = np.angle(self.psi[self.N//2, self.N//2]) if self.psi is not None else 0
    # Сравниваем фазы резонаторов с центральной фазой
    phases = [r.phase for r in all_res]
    mean_phase = np.mean(phases)
    coherence = np.exp(-np.std(phases) / (2*np.pi))  # 1 — если все фазы одинаковы
    # Дополнительно учитываем амплитуды как вес
    amps = [r.amp for r in all_res]
    weighted_coherence = coherence * (np.mean(amps) / (max(amps) + 0.01))
    return min(1.0, weighted_coherence)

# --- FUNC: glow_factor ---
def glow_factor(self):
    """
    Возвращает уровень «сияния» системы — визуализация состояния любви.
    """
    return self.coherence_heart() * 100

# --- FUNC: restore_health ---
def restore_health(self, target_coherence=0.95, steps=20):
    """
    Медитативное «возвращение здоровья» — плавное перестроение
    резонаторов к состоянию максимальной когерентности.
    """
    if not self.E_resonators and not self.B_resonators:
        return
    all_res = self.E_resonators + self.B_resonators
    # Сохраняем целевые фазы (средние по полю)
    center_phase = np.angle(self.psi[self.N//2, self.N//2]) if self.psi is not None else 0
    for _ in range(steps):
        for r in all_res:
            # Плавно подтягиваем фазу к центру
            r.phase += 0.1 * (center_phase - r.phase)
            # Усиливаем амплитуды, но не более 2.0
            r.amp = min(2.0, r.amp * 1.02)
        self._update_field_from_EM()
        # Проверяем когерентность
        coh = self.coherence_heart()
        if coh >= target_coherence:
            break
    print(f"✅ Здоровье восстановлено. Когерентность: {self.coherence_heart():.3f}")

