# --- FUNC: optimize_with_love ---
def optimize_with_love(self, steps=30, learning_rate=0.01):
        all_res = self.E_resonators + self.B_resonators
        if not all_res:
            print("Нет резонаторов.")
            return

        def objective():
            self._update_field_from_EM()
            # Когерентность + интеграл любви
            coherence = self._compute_coherence()
            love_integral = np.mean(self.love_field)
            return coherence * (1 + love_integral)

        for step in range(steps):
            grads = []
            for res in all_res:
                # Градиент по частоте
                res.freq += 0.001
                f1 = objective()
                res.freq -= 0.002
                f2 = objective()
                res.freq += 0.001
                grad_f = (f1 - f2) / 0.002

                # Градиент по амплитуде
                res.amp += 0.001
                a1 = objective()
                res.amp -= 0.002
                a2 = objective()
                res.amp += 0.001
                grad_a = (a1 - a2) / 0.002

                grads.append((grad_f, grad_a))

            for i, res in enumerate(all_res):
                res.freq += learning_rate * grads[i][0]
                res.amp += learning_rate * grads[i][1]
                res.freq = max(0.1, min(3.0, res.freq))
                res.amp = max(0.1, min(2.0, res.amp))

            self._update_field_from_EM()
            if step % 10 == 0:
                print(f"Шаг {step}, когерентность = {objective():.4f}")

        print("✅ Оптимизация с любовью завершена.")

# --- FUNC: focus_love ---
def focus_love(self, x=0, y=0, radius=1.0, intensity=0.5):
        """
        Увеличивает поле любви в заданной области, создавая локальное усиление.
        """
        for i in range(self.N):
            for j in range(self.N):
                dist = np.hypot(self.x[i] - x, self.y[j] - y)
                if dist < radius:
                    self.love_field[j, i] += intensity * (1 - dist/radius)
        self.love_field = np.clip(self.love_field, 0.1, 1.0)
        print(f"💖 Любовь сфокусирована в ({x:.2f},{y:.2f})")

# --- FUNC: animate_with_love ---
def animate_with_love(self, steps=50, interval=200, coupling=0.15, hbar=0.05,
                          metric_strength=0.1, love_strength=0.1, entanglement_strength=0.0):
        if not self.E_resonators or not self.B_resonators:
            print("Добавьте E и B резонаторы.")
            return

        fig, axs = plt.subplots(2, 2, figsize=(12, 10))
        fig.suptitle('Эволюция с полем любви', fontsize=16)

        im_psi = axs[0,0].imshow(np.abs(self.psi).T if self.psi is not None else np.zeros((self.N,self.N)),
                                 extent=[self.x.min(), self.x.max(), self.y.min(), self.y.max()],
                                 origin='lower', cmap='viridis', animated=True)
        axs[0,0].set_title('Амплитуда поля |ψ|')

        im_metric = axs[0,1].imshow(self.metric.field, extent=[self.x.min(), self.x.max(), self.y.min(), self.y.max()],
                                    origin='lower', cmap='plasma', animated=True)
        axs[0,1].set_title('Кривизна')

        im_love = axs[1,0].imshow(self.love_field, extent=[self.x.min(), self.x.max(), self.y.min(), self.y.max()],
                                  origin='lower', cmap='Reds', vmin=0, vmax=1, animated=True)
        axs[1,0].set_title('Поле любви')

        im_freq = axs[1,1].imshow(np.ones((self.N,self.N)), extent=[self.x.min(), self.x.max(), self.y.min(), self.y.max()],
                                  origin='lower', cmap='plasma', animated=True)
        axs[1,1].set_title('Частоты')

        e_clock = self.E_resonators[0]
        b_clock = self.B_resonators[0]
        rel_time = self.RelationalTime(e_clock, b_clock, hbar=hbar)

        def update(frame):
            # Один шаг эволюции
            self.evolve_full(steps=1, coupling=coupling, hbar=hbar,
                             metric_strength=metric_strength,
                             love_strength=love_strength,
                             entanglement_strength=entanglement_strength)

            im_psi.set_array(np.abs(self.psi).T if self.psi is not None else np.zeros((self.N,self.N)))
            im_metric.set_array(self.metric.field)
            im_love.set_array(self.love_field)
            # Карта частот
            f_map = np.zeros((self.N, self.N))
            for e in self.E_resonators + self.B_resonators:
                ix = int((e.x - self.x.min()) / (self.x.max() - self.x.min()) * self.N)
                iy = int((e.y - self.y.min()) / (self.y.max() - self.y.min()) * self.N)
                ix = np.clip(ix, 0, self.N-1)
                iy = np.clip(iy, 0, self.N-1)
                f_map[iy, ix] += e.freq
            im_freq.set_array(f_map)

            axs[0,0].set_title(f'Шаг {frame+1}/{steps}, тиков: {rel_time.ticks:.2f}')
            return im_psi, im_metric, im_love, im_freq

        ani = FuncAnimation(fig, update, frames=steps, interval=interval, blit=True)
        plt.show()
        return ani

