# --- FUNC: architecture_fitness ---
def architecture_fitness(self, params: Dict) -> float:
        """
        Вычисляет fitness архитектуры как взвешенную сумму:
        - средняя сила связи между платформами (чем выше, тем лучше)
        - минимальное время операции (чем меньше, тем лучше)
        - компактность (обратная пропорциональность размеру)
        """
        platforms = params.get("platforms", ["superconducting", "ion", "quantum_dot"])
        positions = np.array(params.get("positions", np.random.rand(3, 3) * 1e-6))
        freq = params.get("frequency", 1.0)
        # Вычисляем связи
        n = len(platforms)
        coupling_sum = 0.0
        count = 0
        for i in range(n):
            for j in range(i+1, n):
                dist = np.linalg.norm(positions[i] - positions[j])
                c = self.phonon_coupling_strength(platforms[i], platforms[j], dist, freq)
                coupling_sum += c
                count += 1
        avg_coupling = coupling_sum / count if count > 0 else 0
        # Время операции (SWAP)
        op_time = self.operation_time(avg_coupling, "swap") if avg_coupling > 0 else 1e9
        # Размер (максимальный размах)
        size = np.max(np.max(positions, axis=0) - np.min(positions, axis=0))
        # Fitness: максимизируем связь, минимизируем время и размер
        fitness = avg_coupling * 10 - op_time * 0.1 - size * 1e6
        return fitness

# --- FUNC: bayesian_optimize_architecture ---
def bayesian_optimize_architecture(self, platforms: List[str], bounds: Dict, n_calls: int = 30) -> Dict:
        """
        Использует Gaussian Process для оптимизации positions и frequency.
        """
        # Преобразуем границы в список для DE или GP
        # Для простоты используем дифференциальную эволюцию (она же genetic)
        # Определяем функцию для оптимизации (принимает вектор параметров)
        def objective(x):
            # x = [freq, x1, y1, z1, x2, y2, z2, x3, y3, z3, ...]
            freq = x[0]
            positions = np.array(x[1:]).reshape(-1, 3)
            params = {
                "platforms": platforms,
                "positions": positions,
                "frequency": freq
            }
            return -self.architecture_fitness(params)  # минимизация

        # Границы: частота (0.1-10), координаты (0-1e-6)
        n_platforms = len(platforms)
        bounds_list = [(0.1, 10.0)] + [(0.0, 1e-6)] * (n_platforms * 3)
        # Запускаем дифференциальную эволюцию
        result = differential_evolution(objective, bounds_list, maxiter=n_calls, popsize=10)
        best_x = result.x
        best_freq = best_x[0]
        best_positions = best_x[1:].reshape(-1, 3)
        best_fitness = -result.fun
        # Сохраняем
        best_arch = {
            "platforms": platforms,
            "positions": best_positions.tolist(),
            "frequency": best_freq,
            "fitness": best_fitness
        }
        self.session_data["🧠"]["best_architectures"].append(best_arch)
        return best_arch

# --- FUNC: genetic_optimize_architecture ---
def genetic_optimize_architecture(self, platforms: List[str], pop_size: int = 20, generations: int = 10) -> Dict:
        """
        Генетический алгоритм для поиска оптимального расположения платформ и частоты.
        """
        # Инициализация популяции
        population = []
        for _ in range(pop_size):
            freq = np.random.uniform(0.1, 10.0)
            positions = np.random.rand(len(platforms), 3) * 1e-6
            population.append({"frequency": freq, "positions": positions})

        def evaluate(ind):
            params = {"platforms": platforms, "positions": ind["positions"], "frequency": ind["frequency"]}
            return self.architecture_fitness(params)

        for gen in range(generations):
            # Оценка
            fitnesses = [evaluate(ind) for ind in population]
            # Отбор (турнирный)
            new_population = []
            while len(new_population) < pop_size:
                idx1 = np.random.choice(len(population), p=np.array(fitnesses)/sum(fitnesses))
                idx2 = np.random.choice(len(population), p=np.array(fitnesses)/sum(fitnesses))
                parent1 = population[idx1]
                parent2 = population[idx2]
                # Кроссинговер (среднее)
                child = {
                    "frequency": (parent1["frequency"] + parent2["frequency"]) / 2,
                    "positions": (parent1["positions"] + parent2["positions"]) / 2
                }
                # Мутация
                if np.random.rand() < 0.2:
                    child["frequency"] += np.random.normal(0, 0.1)
                    child["positions"] += np.random.normal(0, 1e-7, size=child["positions"].shape)
                new_population.append(child)
            population = new_population

        # Лучший
        best = max(population, key=evaluate)
        best_fitness = evaluate(best)
        best_arch = {
            "platforms": platforms,
            "positions": best["positions"].tolist(),
            "frequency": best["frequency"],
            "fitness": best_fitness
        }
        self.session_data["🧠"]["best_architectures"].append(best_arch)
        return best_arch

# --- FUNC: evaluate ---
def evaluate(board):
    """
    Оценка позиции с точки зрения белых.
    Положительное значение — преимущество белых, отрицательное — чёрных.
    """
    values = {
        "пешка": 1,
        "конь": 3,
        "слон": 3,
        "ладья": 5,
        "ферзь": 9,
        "король": 1000   # король бесценен, но для оценки используем большое число
    }
    
    score = 0
    for z in range(4):
        for y in range(8):
            for x in range(8):
                p = board.layers[z][y][x]
                if p is not None:
                    sign = 1 if p.color == "белый" else -1
                    score += sign * values[p.type]
    return score

# --- FUNC: evolve_timeless ---
def evolve_timeless(self, dimensions=4, steps=30, num_nodes=30, mode='spiral'):
        """
        Запускает эволюцию системы вне времени, используя TimeAgnosticExplorer.
        """
        self.time_explorer.dimensions = dimensions
        self.time_explorer.generate_state_space(num_nodes=num_nodes)
        if mode == 'spiral':
            self.time_states = self.time_explorer.evolve_without_time(steps)
        elif mode == 'massive':
            self.time_states = self.time_explorer.massive_iteration(iterations=100, batch_size=10)
        else:
            self.time_states = self.time_explorer.evolve_without_time(steps)
        self.time_current = self.time_states[-1] if self.time_states else None
        return self.time_states

# --- FUNC: analyze_time_correlations ---
def analyze_time_correlations(self):
        """
        Возвращает меру запутанности и причинности из текущего состояния.
        """
        if self.time_current is None:
            return {'error': 'Сначала запустите эволюцию вне времени.'}
        corr = self.time_current.get('correlations')
        if corr is None:
            return {'error': 'Нет корреляций.'}
        return {
            'entanglement_measure': self.time_current.get('entanglement_measure', 0),
            'total_correlation': np.sum(np.abs(corr)),
            'avg_correlation': np.mean(np.abs(corr)),
            'dimensions': self.time_explorer.dimensions,
            'num_nodes': self.time_explorer.state_space['num_nodes'] if self.time_explorer.state_space else 0
        }

# --- FUNC: plot_time_state ---
def plot_time_state(self, state_index=-1):
        """
        Визуализирует состояние вне времени.
        """
        if not self.time_states:
            print("Нет состояний. Запустите evolve_timeless().")
            return
        self.time_explorer.plot_state(state_index)

# --- FUNC: on_time_evolve ---
def on_time_evolve(b):
            with self.output:
                clear_output()
                status.value = "<b>Статус:</b> Эволюция вне времени..."
                # Запускаем с параметрами по умолчанию
                steps = self.time_steps_slider.value if hasattr(self, 'time_steps_slider') else 30
                dims = self.time_dims_slider.value if hasattr(self, 'time_dims_slider') else 4
                self.evolve_timeless(dimensions=dims, steps=steps, num_nodes=30, mode='spiral')
                print(f"Выполнено {len(self.time_states)} состояний в {self.time_explorer.dimensions}D.")
                # Обновляем статус
                status.value = f"<b>Статус:</b> Эволюция завершена ({len(self.time_states)} состояний)."
                # Показываем меру запутанности
                corr_info = self.analyze_time_correlations()
                if 'error' not in corr_info:
                    print(f"Мера запутанности: {corr_info['entanglement_measure']:.3f}")

# --- FUNC: on_time_analyze ---
def on_time_analyze(b):
            with self.output:
                clear_output()
                corr_info = self.analyze_time_correlations()
                if 'error' in corr_info:
                    print(corr_info['error'])
                else:
                    print("=== АНАЛИЗ КОРРЕЛЯЦИЙ ===")
                    print(f"Размерность: {corr_info['dimensions']}")
                    print(f"Число узлов: {corr_info['num_nodes']}")
                    print(f"Мера запутанности: {corr_info['entanglement_measure']:.4f}")
                    print(f"Суммарная корреляция: {corr_info['total_correlation']:.4f}")
                    print(f"Средняя корреляция: {corr_info['avg_correlation']:.4f}")

# --- FUNC: on_time_plot ---
def on_time_plot(b):
            with self.output:
                clear_output()
                if not self.time_states:
                    print("Нет состояний. Запустите 'Абсолютное настоящее'.")
                    return
                self.plot_time_state(-1)

# --- FUNC: time_projection ---
def time_projection(self, state_index=0):
        """
        Время как угол поворота в гильбертовом пространстве.
        """
        if self.psi is None:
            return 0
        # Берём вектор состояний
        vec = self.psi.flatten()
        # Угол между вектором и его производной
        if len(self.history) > 1:
            vec_prev = self.history[-1].flatten()
            dot = np.real(np.vdot(vec, vec_prev))
            norm = np.linalg.norm(vec) * np.linalg.norm(vec_prev)
            if norm > 0:
                angle = np.arccos(np.clip(dot / norm, -1, 1))
                return angle
        return 0

# --- FUNC: influence_phase ---
def influence_phase(self, phase, x_idx, y_idx, strength=0.1):
        """
        Кривизна влияет на фазу резонатора: phase += strength * Φ(x,y)
        """
        return phase + strength * self.field[y_idx, x_idx]

# --- FUNC: build_programmable_crystal ---
def build_programmable_crystal(self, config: Dict) -> Dict:
        """
        Создаёт структуру программируемого кристалла с заданными параметрами.
        config содержит:
        - dimensions: 1 или 2
        - size: число атомов (или размер сетки)
        - base_mass, base_spring: начальные значения
        - control_fields: список управляющих полей
        - modulation: тип модуляции (Fibonacci, Penrose, random, custom)
        """
        dims = config.get("dimensions", 1)
        size = config.get("size", 20)
        base_mass = config.get("base_mass", 1.0)
        base_spring = config.get("base_spring", 1.0)
        control_fields = config.get("control_fields", ["electric", "magnetic"])
        modulation = config.get("modulation", "random")

        # Генерируем базовую структуру
        if dims == 1:
            # 1D цепочка
            N = size
            positions = np.arange(N)
            # Массы и жёсткости могут быть модулированы
            if modulation == "Fibonacci":
                # Используем последовательность Фибоначчи для модуляции
                phi = self.phi
                seq = []
                a, b = 0, 1
                for _ in range(N):
                    seq.append(a)
                    a, b = b, (a + b) % 2
                types = np.array(seq)
                masses = base_mass * (1 + 0.5 * types)
                springs = base_spring * (1 + 0.3 * types)
            elif modulation == "sin":
                # Синусоидальная модуляция с частотой φ
                x = np.linspace(0, 2*np.pi*phi, N)
                masses = base_mass * (1 + 0.2 * np.sin(x))
                springs = base_spring * (1 + 0.2 * np.cos(x * 0.7))
            else:
                # Случайная модуляция
                masses = base_mass * (1 + 0.3 * (np.random.rand(N) - 0.5))
                springs = base_spring * (1 + 0.3 * (np.random.rand(N) - 0.5))
                types = np.random.choice([0,1], N)

            structure = {
                "dimensions": 1,
                "N": N,
                "positions": positions.tolist(),
                "masses": masses.tolist(),
                "springs": springs.tolist(),
                "types": types.tolist() if isinstance(types, np.ndarray) else [],
                "control_fields": control_fields,
                "modulation": modulation
            }

        elif dims == 2:
            # 2D сетка (упорядоченная или квазикристаллическая)
            grid = np.random.rand(size, size) < 0.5  # бинарная случайная структура
            coords = np.argwhere(grid)
            N = len(coords)
            # Массы и жёсткости зависят от локального окружения
            masses = base_mass * (1 + 0.2 * np.random.rand(N))
            springs = base_spring * (1 + 0.2 * np.random.rand(N))
            structure = {
                "dimensions": 2,
                "N": N,
                "coordinates": coords.tolist(),
                "masses": masses.tolist(),
                "springs": springs.tolist(),
                "control_fields": control_fields,
                "modulation": modulation
            }
        else:
            return {"error": "Не поддерживаемая размерность"}

        # Генерируем ID и сохраняем
        crystal_id = f"ppc_{hash(str(structure))}"
        structure["id"] = crystal_id
        self.session_data["🔮"]["programmable_crystals"][crystal_id] = structure
        return structure

# --- FUNC: apply_control_field ---
def apply_control_field(self, crystal_id: str, field_type: str, strength: float, profile: str = "uniform") -> Dict:
        """
        Изменяет параметры кристалла под действием внешнего поля.
        field_type: "electric", "magnetic", "strain"
        strength: амплитуда воздействия (от -1 до 1)
        profile: "uniform", "gradient", "local"
        Возвращает обновлённый кристалл.
        """
        crystal = self.session_data["🔮"]["programmable_crystals"].get(crystal_id)
        if not crystal:
            return {"error": "Кристалл не найден"}

        # Копируем для модификации
        new_crystal = crystal.copy()
        N = new_crystal["N"]
        masses = np.array(new_crystal["masses"])
        springs = np.array(new_crystal["springs"])

        # Генерируем профиль поля
        if profile == "uniform":
            field = np.ones(N) * strength
        elif profile == "gradient":
            x = np.array(new_crystal.get("positions", np.arange(N)))
            field = strength * (x / N)  # линейный градиент
        elif profile == "local":
            # Локальное воздействие в центре
            if "positions" in new_crystal:
                center = N // 2
                field = strength * np.exp(-0.1 * (np.arange(N) - center)**2)
            else:
                coords = np.array(new_crystal["coordinates"])
                center = np.mean(coords, axis=0)
                dist = np.linalg.norm(coords - center, axis=1)
                field = strength * np.exp(-0.1 * dist)
        else:
            field = np.random.randn(N) * strength * 0.1

        # Применяем поле к массами и жёсткостям (в зависимости от типа поля)
        if field_type == "electric":
            # Электрическое поле изменяет эффективные массы (за счёт поляризации)
            masses = masses * (1 + 0.2 * field)
            springs = springs * (1 + 0.1 * field)
        elif field_type == "magnetic":
            # Магнитное поле изменяет жёсткости (за счёт магнитострикции)
            springs = springs * (1 + 0.3 * field)
        elif field_type == "strain":
            # Механическое напряжение изменяет и массы, и жёсткости
            masses = masses * (1 + 0.1 * field)
            springs = springs * (1 + 0.2 * field)
        else:
            return {"error": "Неизвестный тип поля"}

        # Обновляем параметры
        new_crystal["masses"] = masses.tolist()
        new_crystal["springs"] = springs.tolist()
        new_crystal["control_fields"] = new_crystal.get("control_fields", [])
        if field_type not in new_crystal["control_fields"]:
            new_crystal["control_fields"].append(field_type)

        # Сохраняем как новую версию
        new_id = f"ppc_{hash(str(new_crystal))}"
        new_crystal["id"] = new_id
        new_crystal["parent_id"] = crystal_id
        new_crystal["field_applied"] = {
            "type": field_type,
            "strength": strength,
            "profile": profile
        }
        self.session_data["🔮"]["programmable_crystals"][new_id] = new_crystal
        return new_crystal

# --- FUNC: compute_ppc_spectrum ---
def compute_ppc_spectrum(self, crystal_id: str, k_vals: np.ndarray = None) -> Dict:
        """
        Вычисляет фононный спектр для программируемого кристалла.
        Учитывает изменяемые массы и жёсткости.
        """
        crystal = self.session_data["🔮"]["programmable_crystals"].get(crystal_id)
        if not crystal:
            return {"error": "Кристалл не найден"}

        N = crystal["N"]
        masses = np.array(crystal["masses"])
        springs = np.array(crystal["springs"])

        # Строим матрицу жёсткости (для 1D)
        if crystal["dimensions"] == 1:
            K = np.zeros((N, N))
            for i in range(N-1):
                k = springs[i]
                K[i, i] += k
                K[i, i+1] -= k
                K[i+1, i] -= k
                K[i+1, i+1] += k
            # Граничные условия (фиксированные или периодические)
            # Для простоты используем фиксированные концы
            # Если нужны периодические, можно добавить связь N-1 -> 0
            M = np.diag(masses)

            # Диагонализация для каждого k (здесь мы не делаем k-зависимость, просто вычисляем собственные частоты)
            # Вместо этого для демонстрации вычислим собственные значения полной системы
            try:
                eigvals = eigh(K, M, eigvals_only=True)
                freqs = np.sqrt(np.maximum(eigvals, 0))
                # Сортируем
                freqs = np.sort(freqs)
                spectrum = {
                    "eigenvalues": eigvals.tolist(),
                    "frequencies": freqs.tolist(),
                    "num_modes": N
                }
            except Exception as e:
                spectrum = {"error": str(e)}
            return spectrum

        elif crystal["dimensions"] == 2:
            # Для 2D используем приближение: вычисляем локальную плотность состояний через когерентный потенциал
            # Упрощённо: возвращаем гистограмму на основе случайных частот
            # Для демонстрации генерируем спектр на основе распределения жёсткостей
            spring_vals = np.array(crystal["springs"])
            mass_vals = np.array(crystal["masses"])
            # Строим частоты как sqrt(k/m) с добавлением случайного разброса
            freqs = np.sqrt(spring_vals / mass_vals) * np.random.normal(1, 0.1, N)
            freqs = np.sort(np.abs(freqs))
            spectrum = {
                "frequencies": freqs.tolist(),
                "num_modes": N
            }
            return spectrum
        else:
            return {"error": "Неизвестная размерность"}

# --- FUNC: evaluate_quantum_metric ---
def evaluate_quantum_metric(self, crystal_id: str, metric_type: str) -> float:
        """
        Оценивает пригодность кристалла для квантовой операции.
        metric_type: "entanglement" (фононная запутанность), "coherence" (время когерентности),
                     "coupling" (сила связи с кубитами)
        """
        spectrum = self.compute_ppc_spectrum(crystal_id)
        if "frequencies" not in spectrum:
            return 0.0

        freqs = np.array(spectrum["frequencies"])
        if len(freqs) < 2:
            return 0.0

        if metric_type == "entanglement":
            # Для запутанности нужны близкие уровни с небольшим расщеплением
            # Оцениваем через среднее расстояние между уровнями
            gaps = np.diff(freqs)
            mean_gap = np.mean(gaps)
            std_gap = np.std(gaps)
            # Хорошо, если gaps малы и равномерны (1/mean_gap и 1/std_gap)
            if mean_gap > 0:
                return 1.0 / (mean_gap * (1 + std_gap))
            else:
                return 0.0

        elif metric_type == "coherence":
            # Время когерентности связано с шириной уровней (обратная связь с окружением)
            # Оцениваем через разброс частот: чем меньше разброс, тем лучше когерентность
            spread = np.std(freqs) / np.mean(freqs) if np.mean(freqs) > 0 else 1.0
            return 1.0 / (1 + spread)

        elif metric_type == "coupling":
            # Сила связи с кубитами: нужны резонансы на определённых частотах
            # Ищем частоты, близкие к нашим константам (φ, √5, γ, Λ)
            targets = [self.phi, self.sqrt5, self.gamma, self.Lambda]
            coupling = 0.0
            for target in targets:
                diff = np.min(np.abs(freqs - target))
                coupling += 1.0 / (1 + diff)
            return coupling

        else:
            return 0.0

# --- FUNC: optimize_for_quantum ---
def optimize_for_quantum(self, metric_type: str = "entanglement", iterations: int = 10) -> Dict:
        """
        Эволюционный поиск кристалла с наилучшим значением заданной квантовой метрики.
        """
        # Генерация начальной популяции
        population = []
        for _ in range(10):
            config = {
                "dimensions": random.choice([1, 2]),
                "size": random.randint(15, 30),
                "modulation": random.choice(["Fibonacci", "sin", "random"]),
                "control_fields": ["electric", "magnetic"]
            }
            crystal = self.build_programmable_crystal(config)
            population.append(crystal)

        best_fitness = -float('inf')
        best_crystal = None
        for gen in range(iterations):
            fitnesses = []
            for crystal in population:
                # Применяем случайные поля для создания разнообразия
                if random.random() < 0.3:
                    field = random.choice(["electric", "magnetic", "strain"])
                    strength = random.uniform(-0.5, 0.5)
                    crystal = self.apply_control_field(crystal["id"], field, strength, "uniform")
                fit = self.evaluate_quantum_metric(crystal["id"], metric_type)
                fitnesses.append(fit)
                if fit > best_fitness:
                    best_fitness = fit
                    best_crystal = crystal

            # Отбор и скрещивание
            new_population = []
            while len(new_population) < len(population):
                # Турнирный отбор
                idx1 = random.randrange(len(population))
                idx2 = random.randrange(len(population))
                parent1 = population[idx1] if fitnesses[idx1] > fitnesses[idx2] else population[idx2]
                # Скрещивание: создаём нового ребёнка как комбинацию параметров
                child = parent1.copy()
                if child["dimensions"] == 1:
                    # Мутация масс и жёсткостей
                    masses = np.array(child["masses"])
                    springs = np.array(child["springs"])
                    mask = np.random.rand(len(masses)) < 0.1
                    masses[mask] *= (1 + random.uniform(-0.2, 0.2))
                    springs[mask] *= (1 + random.uniform(-0.2, 0.2))
                    child["masses"] = masses.tolist()
                    child["springs"] = springs.tolist()
                else:
                    # Для 2D: меняем координаты (добавляем/удаляем атомы)
                    coords = np.array(child["coordinates"])
                    if random.random() < 0.3 and len(coords) > 5:
                        # Удаляем случайный атом
                        idx = random.randint(0, len(coords)-1)
                        coords = np.delete(coords, idx, axis=0)
                    else:
                        # Добавляем атом
                        new_atom = coords[np.random.randint(len(coords))] + np.random.randint(-1, 2, size=2)
                        coords = np.vstack([coords, new_atom])
                    child["coordinates"] = coords.tolist()
                    child["N"] = len(coords)
                child["id"] = f"ppc_{hash(str(child))}"
                new_population.append(child)
            population = new_population

        # Сохраняем лучшую структуру и её метрики
        if best_crystal:
            self.session_data["🔮"]["quantum_metrics"][best_crystal["id"]] = {
                metric_type: best_fitness
            }
            self.session_data["🔮"]["optimized_structures"] = self.session_data["🔮"].get("optimized_structures", [])
            self.session_data["🔮"]["optimized_structures"].append({
                "crystal_id": best_crystal["id"],
                "metric": metric_type,
                "fitness": best_fitness,
                "crystal": best_crystal
            })
        return {"best_crystal": best_crystal, "fitness": best_fitness}

# --- FUNC: generate_ppc_code ---
def generate_ppc_code(self, crystal_id: str) -> str:
        """
        Генерирует Python-код для эмуляции программируемого кристалла,
        включая функции управления полями и расчёта спектра.
        """
        crystal = self.session_data["🔮"]["programmable_crystals"].get(crystal_id)
        if not crystal:
            return "# Кристалл не найден"

        dims = crystal["dimensions"]
        N = crystal["N"]
        masses = crystal["masses"]
        springs = crystal["springs"]
        fields = crystal.get("control_fields", [])

        code = f"""
# Эмуляция программируемого фононного кристалла {crystal_id}
# Размерность: {dims}D, атомов: {N}

import numpy as np
from scipy.linalg import eigh

class ProgrammablePhononicCrystal:
    def __init__(self):
        self.masses = np.array({masses})
        self.springs = np.array({springs})
        self.N = {N}
        self.dim = {dims}
        self.control_fields = {fields}
        self.current_field = {{}}

    def build_hamiltonian(self):
        '''Строит матрицу Гамильтона для текущих параметров.'''
        if self.dim == 1:
            K = np.zeros((self.N, self.N))
            for i in range(self.N-1):
                k = self.springs[i]
                K[i, i] += k
                K[i, i+1] -= k
                K[i+1, i] -= k
                K[i+1, i+1] += k
            M = np.diag(self.masses)
            return K, M
        else:
            # Для 2D используем упрощённую модель
            return None, None

    def compute_spectrum(self):
        '''Вычисляет фононный спектр.'''
        K, M = self.build_hamiltonian()
        if K is None:
            # 2D: возвращаем приблизительный спектр
            freqs = np.sqrt(self.springs / self.masses) * np.random.normal(1, 0.1, self.N)
            return np.sort(freqs)
        eigvals = eigh(K, M, eigvals_only=True)
        return np.sqrt(np.maximum(eigvals, 0))

    def apply_field(self, field_type: str, strength: float, profile: str = 'uniform'):
        '''Применяет внешнее поле для изменения параметров.'''
        if field_type not in self.control_fields:
            print(f"Поле {{field_type}} не поддерживается")
            return
        # Логика изменения масс и жёсткостей (упрощённо)
        if field_type == 'electric':
            self.masses *= (1 + 0.2 * strength)
        elif field_type == 'magnetic':
            self.springs *= (1 + 0.3 * strength)
        elif field_type == 'strain':
            self.masses *= (1 + 0.1 * strength)
            self.springs *= (1 + 0.2 * strength)
        self.current_field[field_type] = {{'strength': strength, 'profile': profile}}

    def get_quantum_metric(self, metric_type):
        '''Вычисляет заданную квантовую метрику.'''
        freqs = self.compute_spectrum()
        if metric_type == 'entanglement':
            gaps = np.diff(freqs)
            mean_gap = np.mean(gaps) if len(gaps) > 0 else 1.0
            return 1.0 / mean_gap
        elif metric_type == 'coherence':
            spread = np.std(freqs) / np.mean(freqs) if np.mean(freqs) > 0 else 1.0
            return 1.0 / (1 + spread)
        elif metric_type == 'coupling':
            targets = [1.618, 2.236, 7.0, 0.5527]
            coupling = 0.0
            for target in targets:
                diff = np.min(np.abs(freqs - target))
                coupling += 1.0 / (1 + diff)
            return coupling
        return 0.0

if __name__ == "__main__":
    crystal = ProgrammablePhononicCrystal()
    print("Спектр:", crystal.compute_spectrum()[:5])
    crystal.apply_field('electric', 0.3)
    print("После поля:", crystal.compute_spectrum()[:5])
    print("Метрика запутанности:", crystal.get_quantum_metric('entanglement'))
"""
        return code

# --- FUNC: plot_ppc ---
def plot_ppc(self, crystal_id: str):
        """
        Визуализирует структуру и управляемые параметры кристалла.
        """
        try:
            import matplotlib.pyplot as plt
        except ImportError:
            print("matplotlib не установлен")
            return
        crystal = self.session_data["🔮"]["programmable_crystals"].get(crystal_id)
        if not crystal:
            print("Кристалл не найден")
            return
        spectrum = self.compute_ppc_spectrum(crystal_id)

        fig, axs = plt.subplots(1, 2, figsize=(12, 5))

        # 1. Структура и параметры
        if crystal["dimensions"] == 1:
            N = crystal["N"]
            masses = np.array(crystal["masses"])
            springs = np.array(crystal["springs"])
            x = np.arange(N)
            axs[0].bar(x, masses, label='Массы', alpha=0.7)
            axs[0].bar(x+0.2, springs, label='Жёсткости', alpha=0.7)
            axs[0].set_title("1D программируемый кристалл")
            axs[0].legend()
        else:
            coords = np.array(crystal["coordinates"])
            axs[0].scatter(coords[:,0], coords[:,1], s=20)
            axs[0].set_title("2D программируемый кристалл")

        # 2. Спектр
        if "frequencies" in spectrum:
            freqs = spectrum["frequencies"]
            axs[1].hist(freqs, bins=20, alpha=0.7)
            axs[1].set_title("Фононный спектр")
            axs[1].set_xlabel("Частота")
            axs[1].set_ylabel("Количество")

        plt.tight_layout()
        plt.show()

# --- FUNC: predict_temp_with_control ---
def predict_temp_with_control(self, params: Dict, control_signal: float) -> float:
        """
        Предсказывает максимальную температуру при заданном управляющем сигнале.
        """
        model = self.session_data["🔥"]["ml_models"].get("thermal_predictor")
        if model is None:
            raise ValueError("ML-модель не обучена. Сначала вызовите train_thermal_ml_model().")
        # Признаки: [k, cp, rho, power, control]
        k = params.get('thermal_conductivity', 148)
        cp = params.get('specific_heat', 700)
        rho = params.get('density', 2330)
        power = params.get('source_power', 100)
        X_input = np.array([[k, cp, rho, power, control_signal]])
        return model.predict(X_input)[0]

# --- FUNC: add_target ---
def add_target(self, position: Tuple[float, float], properties: Dict) -> int:
        """
        Добавляет новую цель (клетку, молекулу) в систему.
        Возвращает ID цели.
        """
        target = {
            'id': len(self.targets),
            'position': np.array(position, dtype=float),
            'properties': properties,
            'velocity': np.zeros(2),
            'trajectory': [position],
            'captured': False
        }
        self.targets.append(target)
        return target['id']

# --- FUNC: set_target_position ---
def set_target_position(self, target_id: int, new_position: Tuple[float, float]):
        """Устанавливает желаемую позицию для цели."""
        if target_id < len(self.targets):
            self.targets[target_id]['target_pos'] = np.array(new_position)

# --- FUNC: compute_forces_on_target ---
def compute_forces_on_target(self, target_id: int) -> np.ndarray:
        """
        Вычисляет результирующую силу, действующую на цель от всех излучателей.
        """
        target = self.targets[target_id]
        pos = target['position']
        F_total = np.zeros(2)
        for src in self.sources:
            # Вектор от источника к цели
            r_vec = pos - np.array([src['x'], src['y']])
            r = np.linalg.norm(r_vec)
            if r < 1e-12:
                continue
            # Сила от источника (обратно пропорциональна квадрату расстояния)
            # Модулируем амплитудой и частотой
            F_mag = src['amplitude'] * src['freq'] * 1e-6 / (r + 1e-12)**2
            F_dir = r_vec / r
            F_total += F_mag * F_dir
        return F_total

# --- FUNC: update_targets ---
def update_targets(self, dt: float = 1e-6):
        """
        Обновляет позиции всех целей на основе действующих сил.
        Использует уравнение движения с вязкостью.
        """
        for target in self.targets:
            # Сила от пинцетов
            F_ac = self.compute_forces_on_target(target['id'])
            # Сила вязкости (демпфирование)
            gamma = 6 * np.pi * self.medium['viscosity'] * target['properties']['radius']
            F_drag = -gamma * target['velocity']
            # Тепловой шум (броуновское движение)
            k_B = 1.38e-23
            noise_amp = np.sqrt(2 * gamma * k_B * self.medium['temperature'] / dt)
            noise = np.random.normal(0, noise_amp, 2)
            # Масса частицы
            m = 4/3 * np.pi * target['properties']['radius']**3 * target['properties']['density']
            # Ускорение
            accel = (F_ac + F_drag + noise) / m
            target['velocity'] += accel * dt
            target['position'] += target['velocity'] * dt
            # Сохраняем траекторию
            target['trajectory'].append(target['position'].copy())

# --- FUNC: train_path_planner ---
def train_path_planner(self, num_samples: int = 300):
        """
        Обучает ML-модель для предсказания оптимального управления,
        чтобы доставить цель в заданную позицию.
        """
        X = []  # [расстояние до цели, скорость, размер частицы]
        y = []  # рекомендуемая амплитуда излучателя
        for _ in range(num_samples):
            dist = np.random.uniform(0, 100e-6)
            speed = np.random.uniform(0, 1e-3)
            radius = np.random.uniform(0.5e-6, 5e-6)
            # Эвристика: амплитуда должна быть пропорциональна dist * speed / radius
            amp = dist * speed / (radius * 1e-6) * 0.1
            amp = np.clip(amp, 0.1, 1.0)
            X.append([dist, speed, radius])
            y.append(amp)
        X = np.array(X)
        y = np.array(y)
        model = RandomForestRegressor(n_estimators=50, max_depth=10, random_state=42)
        model.fit(X, y)
        self.ml_model = model
        return model

# --- FUNC: plan_path ---
def plan_path(self, target_id: int, target_pos: Tuple[float, float]):
        """
        Планирует траекторию для цели с использованием ML-модели.
        """
        if self.ml_model is None:
            raise ValueError("ML-модель не обучена. Сначала вызовите train_path_planner().")
        target = self.targets[target_id]
        dist = np.linalg.norm(target['position'] - np.array(target_pos))
        speed = np.linalg.norm(target['velocity'])
        radius = target['properties']['radius']
        # Предсказываем амплитуду
        amp = self.ml_model.predict([[dist, speed, radius]])[0]
        # Применяем управление к излучателям (упрощённо)
        for src in self.sources:
            src['amplitude'] = amp * 0.8 + 0.2  # небольшое случайное смещение
        return amp

# --- FUNC: launch_robot_brain ---
def launch_robot_brain(self):
        """
        Запускает интеграцию мозга и робота.
        """
        # Создаём робота
        robot = SimulatedRobot()
        # Создаём интерфейс с нейросетью (у нас уже есть нейросеть из предыдущего модуля)
        interface = BrainRobotInterface(self.network, robot)
        # Обучаем адаптивную модель
        interface.train_adaptive_model()
        # Запускаем анимацию
        ani = interface.animate_robot(steps=300, interval=30)
        return interface, ani

# --- FUNC: run_brain_experiment ---
def run_brain_experiment(self, num_neurons: int = 30):
        """
        Запускает эксперимент с виртуальным мозгом.
        """
        brain = PhoNetBrain(num_neurons)
        ani = brain.animate(steps=300, interval=30)
        return brain, ani

# --- FUNC: set_phase ---
def set_phase(self, new_phase):
        self.phase = new_phase

# --- FUNC: set_amp ---
def set_amp(self, new_amp):
        self.amp = new_amp
        self.energy = new_amp**2

# --- FUNC: test_hybrid_bridge ---
def test_hybrid_bridge(self, platforms: List[str], freq: float = 1.0, size: float = 1e-6):
        """
        Быстрый тест: проектирует мост, симулирует его и генерирует код.
        """
        design = self.design_compact_bridge(platforms, freq, size)
        sim = self.hybrid_system_simulation(design)
        code = self.generate_bridge_code(design)
        return {"design": design, "simulation": sim, "code": code}

# --- FUNC: get_time ---
def get_time(self):
        return self.ticks

# --- FUNC: design_metamaterial ---
def design_metamaterial(self, params: Dict) -> Dict:
        """
        Проектирует слой метаматериала с заданными свойствами.
        params: thickness, density_profile, elastic_modulus, anisotropy
        Возвращает словарь с описанием материала и его матрицей передачи.
        """
        # Базовые параметры
        thickness = params.get('thickness', 0.05)  # метры
        density = params.get('density', 500)       # кг/м³ (типично для метаматериалов)
        elastic = params.get('elastic_modulus', 1e8)  # Па (эффективный модуль)
        # Анизотропия: разные свойства в направлениях x и z
        anisotropy = params.get('anisotropy', 0.5)  # отношение плотностей вдоль x/z
        # Рассчитываем скорость звука в материале
        speed = np.sqrt(elastic / density)
        # Импеданс материала
        impedance = density * speed
        # Импеданс воды
        water_impedance = self.water_params['density'] * self.water_params['speed_of_sound']
        # Коэффициент отражения от границы (на нормальное падение)
        R = (impedance - water_impedance) / (impedance + water_impedance)
        # Коэффициент прохождения
        T = 1 - abs(R)
        design = {
            'thickness': thickness,
            'density': density,
            'elastic_modulus': elastic,
            'speed': speed,
            'impedance': impedance,
            'anisotropy': anisotropy,
            'R': R,
            'T': T,
            'frequency_response': self._frequency_response(thickness, speed, impedance, water_impedance)
        }
        self.session_data["🫥"]["cloak_designs"].append(design)
        return design

# --- FUNC: _frequency_response ---
def _frequency_response(self, thickness, speed, imp, water_imp):
        """
        Возвращает частотную характеристику слоя (коэффициент передачи как функция частоты).
        Для простого слоя.
        """
        # Модель: прохождение через четвертьволновый трансформатор
        freq = np.linspace(1000, 50000, 100)  # частотный диапазон
        k = 2 * np.pi * freq / speed
        # Коэффициент прохождения через слой с согласованием импеданса
        # Используем формулу для передаточной матрицы
        # T = 1 / (cos(kL) + 0.5i*(Z1/Z2 + Z2/Z1)*sin(kL))
        Z1 = water_imp
        Z2 = imp
        L = thickness
        cos_term = np.cos(k * L)
        sin_term = np.sin(k * L)
        # Коэффициент передачи мощности
        T_power = 4 * Z1 * Z2 / ((Z1 + Z2)**2 * cos_term**2 + (Z1 * Z2 / Z2 + Z2)**2 * sin_term**2)
        T_power = np.clip(T_power, 0, 1)
        return {'frequencies': freq.tolist(), 'transmission': T_power.tolist()}

# --- FUNC: simulate_acoustic_field ---
def simulate_acoustic_field(self, cloak_design: Dict, frequency: float, angle: float = 0) -> Dict:
        """
        Симулирует распространение звуковой волны через метаматериал.
        Использует метод передаточных матриц для 1D (нормальное падение).
        Возвращает поле давления и коэффициенты отражения/прохождения.
        """
        # Параметры воды
        c_w = self.water_params['speed_of_sound']
        rho_w = self.water_params['density']
        # Параметры материала
        c_m = cloak_design['speed']
        rho_m = cloak_design['density']
        L = cloak_design['thickness']
        # Волновые числа
        k_w = 2 * np.pi * frequency / c_w
        k_m = 2 * np.pi * frequency / c_m
        # Передаточная матрица для слоя
        # Используем стандартную матрицу для акустического слоя
        # |P+  |   = | cos(kL)    i Z sin(kL) | |P+  |
        # |P-  |     | i sin(kL)/Z   cos(kL)  | |P-  |
        Z_w = rho_w * c_w
        Z_m = rho_m * c_m
        # Матрица перехода через слой
        A = np.array([
            [np.cos(k_m * L), 1j * Z_m * np.sin(k_m * L)],
            [1j * np.sin(k_m * L) / Z_m, np.cos(k_m * L)]
        ], dtype=complex)
        # Начальные условия: падающая волна с амплитудой 1
        # Ищем решение: [1, r] = A * [t, 0]
        # r - отражённая, t - прошедшая амплитуды
        # Решаем систему: a11*t + a12*0 = 1 -> t = 1/a11
        # r = a21*t + a22*0 = a21/a11
        t = 1 / A[0, 0]
        r = A[1, 0] / A[0, 0]
        # Мощностные коэффициенты
        T_power = abs(t)**2 * (Z_w / Z_m)  # учёт импедансов
        R_power = abs(r)**2
        # Поле давления: падающая + отражённая (слева) и прошедшая (справа)
        # Пространственная сетка
        x = np.linspace(-0.5, 0.5, 1000)  # координата, м
        # Давление: слева от слоя (x < 0)
        left_mask = x < 0
        right_mask = x >= 0
        p_left = np.exp(1j * k_w * x[left_mask]) + r * np.exp(-1j * k_w * x[left_mask])
        p_right = t * np.exp(1j * k_w * x[right_mask])  # прошедшая в воду
        # Сшивка
        p = np.zeros_like(x, dtype=complex)
        p[left_mask] = p_left
        p[right_mask] = p_right
        # Сохраняем результат
        result = {
            'x': x.tolist(),
            'pressure_real': p.real.tolist(),
            'pressure_abs': np.abs(p).tolist(),
            'T': T_power,
            'R': R_power,
            'frequency': frequency,
            'angle': angle
        }
        self.session_data["🫥"]["simulations"].append(result)
        return result

# --- FUNC: plot_acoustic_field ---
def plot_acoustic_field(self, sim_result: Dict):
        """
        Визуализирует акустическое поле до и после слоя метаматериала.
        """
        x = np.array(sim_result['x'])
        pressure_abs = np.array(sim_result['pressure_abs'])
        pressure_real = np.array(sim_result['pressure_real'])
        fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(12, 5))
        # Амплитуда давления
        ax1.plot(x, pressure_abs, 'b-', label='Амплитуда')
        ax1.axvline(0, color='r', linestyle='--', label='Граница материала')
        ax1.set_title('Амплитуда акустического давления')
        ax1.set_xlabel('x, м')
        ax1.set_ylabel('|p|, отн. ед.')
        ax1.legend()
        # Фаза (реальная часть)
        ax2.plot(x, pressure_real, 'g-', label='Re(p)')
        ax2.axvline(0, color='r', linestyle='--')
        ax2.set_title('Фаза волны (Re(p))')
        ax2.set_xlabel('x, м')
        ax2.set_ylabel('Re(p)')
        ax2.legend()
        plt.tight_layout()
        plt.show()
        # Дополнительная информация
        print(f"Коэффициент прохождения мощности: {sim_result['T']:.3f}")
        print(f"Коэффициент отражения мощности: {sim_result['R']:.3f}")
        print(f"Частота: {sim_result['frequency']:.0f} Гц")

# --- FUNC: run_cloak_demo ---
def run_cloak_demo(self, target_freq: float = 10000) -> Dict:
        """
        Запускает полный демонстрационный цикл: оптимизация → проектирование → симуляция → визуализация.
        """
        # Оптимизация
        opt = self.optimize_cloak(target_freq)
        # Проектируем материал с лучшими параметрами
        best = opt['best_params']
        design = self.design_metamaterial(best)
        # Симулируем на целевой частоте
        sim = self.simulate_acoustic_field(design, target_freq)
        # Визуализируем
        self.plot_acoustic_field(sim)
        return {'design': design, 'simulation': sim, 'optimization': opt}

# --- FUNC: compute_trap_force ---
def compute_trap_force(self, field: np.ndarray, particle_radius: float, 
                           particle_density: float, medium_density: float) -> Tuple[np.ndarray, np.ndarray]:
        """
        Вычисляет силу (Fx, Fy), действующую на частицу в акустическом поле.
        Использует модель градиентной силы (акустический захват).
        Возвращает компоненты силы в каждой точке сетки.
        """
        # Градиент давления (численное дифференцирование)
        grad_x = np.gradient(field.real, axis=1)
        grad_y = np.gradient(field.real, axis=0)
        # Коэффициент пропорциональности (зависит от размера и контраста плотности)
        # Упрощённо: сила ~ -∇(p^2) * (V * (rho_p - rho_m) / (rho_p + 2*rho_m))
        V = 4/3 * np.pi * particle_radius**3
        contrast = (particle_density - medium_density) / (particle_density + 2 * medium_density)
        # Сила = -∇(U), где U ~ V * contrast * p^2
        p2 = field.real**2
        Fx = - V * contrast * np.gradient(p2, axis=1)
        Fy = - V * contrast * np.gradient(p2, axis=0)
        return Fx, Fy

# --- FUNC: simulate_trap ---
def simulate_trap(self, particle_radius: float, particle_density: float, 
                     config: Dict, num_steps: int = 100, dt: float = 1e-6) -> Dict:
        """
        Симулирует движение частицы в акустической ловушке.
        Возвращает траекторию (x, y) и временные метки.
        """
        # Акустическое поле
        x_range = np.linspace(-3e-3, 3e-3, 100)
        y_range = np.linspace(-3e-3, 3e-3, 100)
        field = self.compute_acoustic_field(config, x_range, y_range)
        # Вычисляем силу в каждой точке
        Fx, Fy = self.compute_trap_force(field, particle_radius, particle_density,
                                         self.tweezers_defaults['medium_density'])
        # Начальное положение (смещённое от центра)
        x0 = 1.0e-3
        y0 = 0.0
        # Симуляция движения (используем простую модель с вязким трением)
        # m * dv/dt = F - gamma * v
        gamma = 6 * np.pi * 1e-3 * particle_radius  # вязкость воды (упрощённо)
        mass = 4/3 * np.pi * particle_radius**3 * particle_density
        # Массив для траектории
        trajectory = np.zeros((num_steps, 2))
        pos = np.array([x0, y0])
        vel = np.array([0.0, 0.0])
        for step in range(num_steps):
            # Интерполяция силы в текущей позиции
            ix = int(np.interp(pos[0], x_range, np.arange(len(x_range))))
            iy = int(np.interp(pos[1], y_range, np.arange(len(y_range))))
            # Границы
            ix = max(0, min(len(x_range)-1, ix))
            iy = max(0, min(len(y_range)-1, iy))
            F = np.array([Fx[iy, ix], Fy[iy, ix]])
            # Обновление скорости и позиции (метод Эйлера)
            accel = (F - gamma * vel) / mass
            vel += accel * dt
            pos += vel * dt
            trajectory[step] = pos
        return {
            'trajectory': trajectory.tolist(),
            'field': field.tolist(),
            'x_range': x_range.tolist(),
            'y_range': y_range.tolist(),
            'params': {'radius': particle_radius, 'density': particle_density}
        }

# --- FUNC: plot_tweezers_trajectory ---
def plot_tweezers_trajectory(self, sim_result: Dict):
        """
        Визуализирует траекторию частицы в акустическом поле.
        """
        trajectory = np.array(sim_result['trajectory'])
        fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(12, 5))
        # 1. Интенсивность поля (нормированная)
        field = np.array(sim_result['field'])
        ax1.imshow(field.real, extent=[-3, 3, -3, 3], cmap='RdBu', alpha=0.6)
        ax1.plot(trajectory[:,0]*1e3, trajectory[:,1]*1e3, 'r-', linewidth=2, label='Траектория')
        ax1.scatter(trajectory[0,0]*1e3, trajectory[0,1]*1e3, color='green', s=50, label='Старт')
        ax1.scatter(trajectory[-1,0]*1e3, trajectory[-1,1]*1e3, color='blue', s=50, label='Конец')
        ax1.set_xlabel('x (мм)')
        ax1.set_ylabel('y (мм)')
        ax1.set_title('Акустическое поле и траектория частицы')
        ax1.legend()
        # 2. Зависимость координат от времени
        t = np.arange(len(trajectory)) * 1e-6  # условное время (с)
        ax2.plot(t, trajectory[:,0]*1e3, label='x (мм)')
        ax2.plot(t, trajectory[:,1]*1e3, label='y (мм)')
        ax2.set_xlabel('Время (с)')
        ax2.set_ylabel('Координата (мм)')
        ax2.set_title('Движение частицы')
        ax2.legend()
        plt.tight_layout()
        plt.show()

# --- FUNC: add_obstacle ---
def add_obstacle(self, x: float, y: float, radius: float = 0.2):
        """Добавляет препятствие в среду."""
        self.obstacles.append({'x': x, 'y': y, 'radius': radius})

# --- FUNC: set_goal ---
def set_goal(self, team_id: str, goal: str,
                 milestones: List[str]) -> dict:
        """Устанавливает цель и этапы."""
        path = f"teams.{team_id}"
        self.storage[f"{path}.goal.text"] = goal
        self.storage[f"{path}.goal.set_at"] = datetime.now().isoformat()
        for i, milestone in enumerate(milestones):
            self.storage[f"{path}.goal.milestones.m{i}"] = {
                "text": milestone,
                "done": False
            }
        self.storage[f"{path}.status"] = "in_progress"
        return {"status": "ok", "milestones_count": len(milestones)}

# --- FUNC: evaluate_situation ---
def evaluate_situation(self) -> Dict:
        """
        Оценивает текущую ситуацию: расстояние до цели, ближайшее препятствие,
        угол до цели и препятствия.
        """
        pos = np.array(self.robot.get_position())
        # До цели
        goal_vec = np.array(self.goal) - pos
        goal_dist = np.linalg.norm(goal_vec)
        goal_angle = np.arctan2(goal_vec[1], goal_vec[0])

        # Ближайшее препятствие
        min_dist = float('inf')
        obstacle_angle = 0
        for obs in self.obstacles:
            obs_pos = np.array([obs['x'], obs['y']])
            dist = np.linalg.norm(pos - obs_pos)
            if dist - obs['radius'] < min_dist:
                min_dist = dist - obs['radius']
                obstacle_angle = np.arctan2(obs['y'] - pos[1], obs['x'] - pos[0])

        return {
            'goal_dist': goal_dist,
            'goal_angle': goal_angle,
            'obstacle_dist': min_dist,
            'obstacle_angle': obstacle_angle,
            'current_pos': pos.tolist()
        }

# --- FUNC: decide_action ---
def decide_action(self) -> Tuple[float, float]:
        """
        Принимает решение на основе 2:1 резонансного принципа:
        - 2 части: следование за целью (исследование)
        - 1 часть: избегание препятствий (безопасность)
        Возвращает команды (left, right).
        """
        situation = self.evaluate_situation()
        goal_dist = situation['goal_dist']
        obstacle_dist = situation['obstacle_dist']

        # Базовое направление к цели
        base_angle = situation['goal_angle']
        # Корректировка на препятствие, если оно близко
        if obstacle_dist < 0.5:  # порог опасности
            # Уходим от препятствия
            avoid_angle = situation['obstacle_angle'] + np.pi  # противоположное направление
            # 2:1 резонанс: 2 части — к цели, 1 часть — от препятствия
            if goal_dist > 0.3:
                # Если цель далеко, приоритет — уход от препятствия
                final_angle = avoid_angle * 0.7 + base_angle * 0.3
            else:
                # Если цель близко, приоритет — цель
                final_angle = base_angle * 0.7 + avoid_angle * 0.3
        else:
            # Идём к цели
            final_angle = base_angle

        # Преобразуем угол в команды
        current_angle = self.robot.angle
        angle_error = np.arctan2(np.sin(final_angle - current_angle), np.cos(final_angle - current_angle))

        # Скорость зависит от расстояния до цели
        speed = 0.3 + 0.7 * np.clip(1 - goal_dist / 5.0, 0, 1)

        # Команды с учётом угловой ошибки
        left = speed - 0.5 * angle_error / np.pi
        right = speed + 0.5 * angle_error / np.pi
        # Ограничиваем
        left = np.clip(left, -1, 1)
        right = np.clip(right, -1, 1)
        self.decision_history.append({
            'goal_dist': goal_dist,
            'obstacle_dist': obstacle_dist,
            'final_angle': final_angle,
            'left': left,
            'right': right
        })
        return left, right

# --- FUNC: train_behavior_model ---
def train_behavior_model(self, num_samples: int = 200):
        """
        Обучает ML-модель предсказывать наилучшее действие на основе ситуации.
        Использует синтетические данные с известными правильными ответами.
        """
        X = []  # [goal_dist, obstacle_dist, goal_angle, obstacle_angle]
        y = []  # [left, right]
        for _ in range(num_samples):
            # Генерируем случайную ситуацию
            goal_dist = np.random.uniform(0.1, 5)
            obstacle_dist = np.random.uniform(0.1, 2)
            goal_angle = np.random.uniform(-np.pi, np.pi)
            obstacle_angle = np.random.uniform(-np.pi, np.pi)
            # Эвристика правильного действия (2:1)
            if obstacle_dist < 0.5:
                # Уклонение
                final_angle = obstacle_angle + np.pi
                if goal_dist < 0.3:
                    final_angle = final_angle * 0.3 + goal_angle * 0.7
            else:
                final_angle = goal_angle
            # Преобразуем в команды
            current_angle = 0  # для простоты
            angle_error = np.arctan2(np.sin(final_angle - current_angle), np.cos(final_angle - current_angle))
            speed = 0.3 + 0.7 * np.clip(1 - goal_dist / 5.0, 0, 1)
            left = speed - 0.5 * angle_error / np.pi
            right = speed + 0.5 * angle_error / np.pi
            left = np.clip(left, -1, 1)
            right = np.clip(right, -1, 1)
            X.append([goal_dist, obstacle_dist, goal_angle, obstacle_angle])
            y.append([left, right])
        X = np.array(X)
        y = np.array(y)
        from sklearn.ensemble import RandomForestRegressor
        model = RandomForestRegressor(n_estimators=50, max_depth=10, random_state=42)
        model.fit(X, y)
        self.ml_behavior_model = model
        return model

# --- FUNC: predict_action ---
def predict_action(self, situation: Dict) -> Tuple[float, float]:
        """
        Использует ML-модель для предсказания команд.
        """
        if self.ml_behavior_model is None:
            raise ValueError("ML-модель не обучена")
        X_input = np.array([[situation['goal_dist'], situation['obstacle_dist'],
                            situation['goal_angle'], situation['obstacle_angle']]])
        left, right = self.ml_behavior_model.predict(X_input)[0]
        return left, right

# --- FUNC: evolve_EM_relational_with_metric ---
def evolve_EM_relational_with_metric(self, steps=100, coupling=0.1, hbar=0.1, metric_strength=0.1):
        if not self.E_resonators or not self.B_resonators:
            print("Добавьте E и B резонаторы.")
            return
        e_clock = self.E_resonators[0]
        b_clock = self.B_resonators[0]
        rel_time = RelationalTime(e_clock, b_clock, hbar=hbar)

        for step in range(steps):
            tick = rel_time.tick()
            dt = rel_time.get_dt()
            if dt is None or dt == 0:
                continue

            # 1. Обновляем метрику от текущей плотности энергии
            self.update_metric(dt)

            # 2. Для каждой пары E-B переток энергии с учётом метрики
            for e in self.E_resonators:
                for b in self.B_resonators:
                    # Кривизна влияет на фазы (смещение)
                    phase_shift_e = metric_strength * self.metric.field[self.N//2, self.N//2]
                    phase_shift_b = metric_strength * self.metric.field[self.N//2, self.N//2]
                    e.phase += phase_shift_e * dt
                    b.phase += phase_shift_b * dt

                    delta_phase = e.phase - b.phase
                    transfer = coupling * np.sin(delta_phase) * dt
                    e_energy = e.amp**2
                    b_energy = b.amp**2
                    if e_energy > 0 and b_energy > 0:
                        e.amp = np.sqrt(max(0, e_energy - transfer))
                        b.amp = np.sqrt(max(0, b_energy + transfer))
                    elif e_energy > 0 and b_energy == 0:
                        b.amp = np.sqrt(e_energy)
                        e.amp = 0
                    elif b_energy > 0 and e_energy == 0:
                        e.amp = np.sqrt(b_energy)
                        b.amp = 0
                    e.tick(dt)
                    b.tick(dt)

            # 3. Обновляем поле с учётом метрики (эффективная скорость света)
            # Влияние метрики на c_eff (простая модель: c_eff = 1 + curvature)
            avg_curv = np.mean(self.metric.field)
            self.c_eff = 1.0 + avg_curv * 0.5
            self._update_field_from_EM()

        print(f"✅ EM-реляционная эволюция с метрикой завершена. Тиков: {rel_time.ticks:.2f}")
        return self.psi

# --- FUNC: start ---
def start(self):
        """Запускает сервер в фоновом потоке."""
        from flask import Flask, request, jsonify
        self.app = Flask(__name__)

        @self.app.route('/move', methods=['POST'])
        def move():
            data = request.json
            left = data.get('left', 0)
            right = data.get('right', 0)
            # Модель дифференциального привода
            self.speed = (left + right) / 2
            self.angular_speed = (right - left) / 0.2
            return jsonify({'status': 'ok'})

        @self.app.route('/sensors', methods=['GET'])
        def sensors():
            # Обновляем позицию (симуляция)
            dt = 0.05
            self.x += self.speed * np.cos(self.angle) * dt
            self.y += self.speed * np.sin(self.angle) * dt
            self.angle += self.angular_speed * dt
            # Имитация препятствий
            ultrasonic = 1.0 - 0.5 * np.abs(self.x) / 10.0
            infrared = 0.5 + 0.5 * np.sin(self.y)
            return jsonify({
                'ultrasonic': max(0.1, ultrasonic),
                'infrared': max(0.1, infrared),
                'x': self.x,
                'y': self.y,
                'angle': self.angle
            })

        def run_server():
            self.app.run(host='0.0.0.0', port=self.port, debug=False, use_reloader=False)

        self.running = True
        thread = threading.Thread(target=run_server)
        thread.daemon = True
        thread.start()
        return f"Эмулятор робота запущен на порту {self.port}"

# --- FUNC: avoid_obstacles ---
def avoid_obstacles(self, sensors: Dict) -> Tuple[float, float]:
        """
        Реализует избегание препятствий на основе ультразвукового и ИК-сенсора.
        Возвращает корректировки к левому и правому колесу.
        """
        ultrasonic = sensors.get('ultrasonic', 1.0)
        infrared = sensors.get('infrared', 0.5)
        # Если препятствие близко (ultrasonic < 0.3), уклоняемся
        if ultrasonic < 0.3:
            # Поворачиваем в сторону, где ИК показывает меньше препятствий
            turn = 1.0 - infrared  # если infrared велик, поворачиваем больше
            return -turn, turn  # левое и правое колесо
        else:
            return 0.0, 0.0

# --- FUNC: follow_goal ---
def follow_goal(self, position: np.ndarray, angle: float) -> Tuple[float, float]:
        """
        Вычисляет команды для движения к цели.
        Использует принцип 2:1 (скорость : поворот).
        """
        delta = self.goal - position
        distance = np.linalg.norm(delta)
        if distance < 0.1:
            return 0.0, 0.0  # достигли цели
        # Желаемый угол
        target_angle = np.arctan2(delta[1], delta[0])
        angle_error = target_angle - angle
        angle_error = np.arctan2(np.sin(angle_error), np.cos(angle_error))
        # Принцип 2:1 – базовая скорость и поворот
        speed = 0.5 * min(1.0, distance / 2.0)  # скорость пропорциональна расстоянию
        # Поворот: если ошибка большая, замедляемся и поворачиваем
        if abs(angle_error) > 0.3:
            speed = speed * 0.5  # уменьшаем скорость для поворота
        turn = 0.8 * angle_error / np.pi  # нормализуем
        # Применяем 2:1 – в два раза больше поворота, чем скорости при больших ошибках
        if abs(angle_error) > 0.5:
            turn = turn * 2.0
        return speed - turn, speed + turn

# --- FUNC: decide_commands ---
def decide_commands(self, sensors: Dict) -> Tuple[float, float]:
        """
        Главная функция принятия решений: комбинирует избегание препятствий,
        следование за целью, и адаптивное ML-управление.
        """
        # Базовая команда от следования за целью
        position = np.array([sensors.get('x', 0), sensors.get('y', 0)])
        angle = sensors.get('angle', 0)
        left_goal, right_goal = self.follow_goal(position, angle)
        # Коррекция на препятствия
        left_avoid, right_avoid = self.avoid_obstacles(sensors)
        # Суммируем
        left = left_goal + left_avoid
        right = right_goal + right_avoid
        # Ограничиваем
        left = np.clip(left, -1, 1)
        right = np.clip(right, -1, 1)
        return left, right

# --- FUNC: run_control_loop ---
def run_control_loop(self, steps=100, dt=0.05, use_ml=False):
        """
        Запускает цикл управления роботом.
        """
        self.running = True
        positions = []
        for i in range(steps):
            # Получаем сенсоры
            sensors = self.api.get_sensors()
            self.position = np.array([sensors.get('x', 0), sensors.get('y', 0)])
            self.angle = sensors.get('angle', 0)
            # Принимаем решение
            if use_ml and self.ml_model is not None:
                left, right = self.adaptive_step(sensors)
            else:
                left, right = self.decide_commands(sensors)
            # Отправляем команду
            self.api.send_command(left, right)
            self.command_history.append((left, right))
            positions.append(self.position.copy())
            time.sleep(dt)
        self.running = False
        return np.array(positions)

