# --- FUNC: random_expression ---
def random_expression(self, depth: int = 0, max_depth: int = 4) -> str:
        """Генерирует случайное выражение в виде строки."""
        if depth >= max_depth or random.random() < 0.3:
            # Лист: константа, переменная n, или случайное число
            choices = ['n'] + list(self.constants.keys())
            if random.random() < 0.2:
                # Случайное число
                return f"{random.uniform(0.1, 10.0):.4f}"
            return random.choice(choices)
        else:
            op = random.choice(self.operations)
            if op in ['+', '-', '*', '/']:
                left = self.random_expression(depth+1, max_depth)
                right = self.random_expression(depth+1, max_depth)
                return f"({left} {op} {right})"
            elif op in ['sin', 'cos', 'exp', 'log', 'sqrt']:
                arg = self.random_expression(depth+1, max_depth)
                return f"{op}({arg})"
            else:
                return self.random_expression(depth, max_depth)

# --- FUNC: evaluate_expression ---
def evaluate_expression(self, expr: str, n: float) -> float:
        """Вычисляет выражение для заданного n, используя словарь констант."""
        # Заменяем имена констант их значениями
        local_dict = {**self.constants, 'n': n}
        try:
            # Безопасное вычисление (используем eval с ограничениями)
            result = eval(expr, {"__builtins__": None}, local_dict)
            if isinstance(result, complex) or not math.isfinite(result):
                return float('inf')
            return float(result)
        except Exception:
            return float('inf')

# --- FUNC: crossover ---
def crossover(self, expr1: str, expr2: str) -> str:
        """Обмен подвыражениями между двумя выражениями."""
        # Находим случайные подвыражения (простой способ: разделение по пробелам, но для строк с скобками сложно)
        # Упрощённо: меняем местами части строк (не идеально, но работает)
        if random.random() < 0.5:
            return expr1
        else:
            # Попробуем обменять первые два операнда в бинарной операции (грубо)
            # Для простоты возвращаем expr1 или expr2 с некоторой вероятностью
            return random.choice([expr1, expr2])

# --- FUNC: mutate ---
def mutate(self, expr: str) -> str:
        """Мутация: замена листа или операции."""
        # Если выражение короткое, просто заменим его новым случайным
        if len(expr) < 10 or random.random() < 0.3:
            return self.random_expression()
        # Иначе случайно заменяем один из листьев (константа или n) на другой
        # Для простоты: заменяем все вхождения 'n' на '(n+φ)' или что-то подобное
        if 'n' in expr and random.random() < 0.5:
            # Заменяем n на (n + случайная константа)
            const = random.choice(list(self.constants.keys()))
            return expr.replace('n', f'(n+{const})', 1)
        else:
            # Меняем операцию (очень грубо)
            ops = ['+', '-', '*', '/']
            for op in ops:
                if op in expr:
                    new_op = random.choice(ops)
                    expr = expr.replace(op, new_op, 1)
                    break
            return expr

# --- FUNC: evaluate_with_ml ---
def evaluate_with_ml(self, code: str, result: Any) -> float:
        """
        Расширенная оценка fitness, включающая:
        - базовый fitness (из evaluate_code)
        - резонанс со спектром нулей
        - ML-предсказание следующего нуля (как мера согласованности)
        """
        # Базовый fitness
        base = self.evaluate_code(code, result)
        # Резонанс со спектром
        resonance = self.interact_with_spectrum(code)
        # ML-фактор: насколько код "поддерживает" предсказание следующего нуля
        # Для этого мы можем использовать предсказание модели и сравнивать с реальным значением (если оно известно)
        # В процессе эволюции мы можем использовать MSE предсказания как штраф или бонус
        ml_model = self.session_data["📐"].get("ml_model")
        ml_factor = 0.0
        if ml_model and "model" in ml_model:
            # Получаем текущий номер нуля, для которого делаем предсказание
            imags = self.session_data["📐"].get("imags", [])
            if len(imags) > 5:
                # Попробуем предсказать следующий ноль и сравнить с фактическим (если есть)
                next_pred = self.predict_next_zero()
                if next_pred is not None and len(imags) > 1:
                    # Если у нас есть следующий реальный ноль (для теста)
                    # В эволюции мы можем использовать MSE между предсказанием и реальным значением
                    actual_next = imags[-1]  # последний известный
                    # На самом деле мы хотим, чтобы код как-то влиял на точность предсказания
                    # Здесь мы просто даём бонус, если предсказание близко к реальному
                    diff = abs(next_pred - actual_next)
                    ml_factor = 1.0 / (1.0 + diff)  # чем меньше diff, тем больше фактор
        # Суммируем
        total = base + resonance * 0.2 + ml_factor * 0.1
        return total

# --- FUNC: symbolic_regression_on_zeros ---
def symbolic_regression_on_zeros(self, num_zeros: int = 50) -> str:
        """
        Использует генетическое программирование для поиска формулы, аппроксимирующей нули.
        Возвращает лучшее выражение.
        """
        imags = self.session_data["📐"].get("imags", [])
        if len(imags) < num_zeros:
            self.compute_zeros(n=num_zeros)
            imags = self.session_data["📐"].get("imags", [])
        if len(imags) < 10:
            return "Недостаточно данных"

        # Подготовка данных: n от 1 до N, t = мнимые части
        X = np.arange(1, len(imags)+1).reshape(-1, 1)
        y = np.array(imags)

        # Константы для регрессора
        constants = {
            'phi': self.phi,
            'sqrt5': self.sqrt5,
            'gamma': self.gamma,
            'Lambda': self.Lambda,
            'pi': math.pi,
            'e': math.e
        }
        regressor = SymbolicRegressor(constants)
        best_expr = regressor.evolve(X, y, pop_size=100, generations=30)
        # Сохраняем результат
        self.session_data["📐"]["symbolic_formula"] = {
            "expression": best_expr,
            "mse": -regressor.fitness(best_expr, X, y)  # т.к. fitness = -MSE
        }
        return best_expr

# --- FUNC: build_quantum_gates ---
def build_quantum_gates(self, num_zeros: int = 20) -> Dict[str, np.ndarray]:
        """
        Создаёт квантовые вентили на основе частот нулей.
        Возвращает словарь с матрицами вентилей (унитарные).
        Для простоты используем вращения вокруг оси Z с углами, пропорциональными частотам.
        """
        imags = self.session_data["📐"].get("imags", [])
        if len(imags) < num_zeros:
            self.compute_zeros(n=num_zeros)
            imags = self.session_data["📐"].get("imags", [])

        frequencies = imags[:num_zeros]
        gates = {}
        for idx, f in enumerate(frequencies):
            # Вращение вокруг Z: Rz(θ) = [[e^{-iθ/2}, 0], [0, e^{iθ/2}]]
            theta = f * 0.1  # масштабируем частоту
            cos_half = math.cos(theta/2)
            sin_half = math.sin(theta/2)
            gate = np.array([
                [complex(cos_half, -sin_half), 0],
                [0, complex(cos_half, sin_half)]
            ], dtype=complex)
            gates[f"gate_{idx+1}_freq_{f:.4f}"] = gate
        self.session_data["📐"]["quantum_gates"] = gates
        return gates

# --- FUNC: apply_quantum_gate_to_code ---
def apply_quantum_gate_to_code(self, code: str) -> str:
        """
        Применяет квантовое преобразование к коду: кодирует код в вектор состояния,
        применяет случайный квантовый вентиль из набора, и декодирует обратно в строку.
        Это метафора квантового влияния на генерацию кода.
        """
        gates = self.session_data["📐"].get("quantum_gates")
        if not gates:
            self.build_quantum_gates(10)
            gates = self.session_data["📐"]["quantum_gates"]
        if not gates:
            return code

        # Выбираем случайный вентиль
        gate_name = random.choice(list(gates.keys()))
        gate = gates[gate_name]

        # Преобразуем код в вектор состояний (например, посимвольно)
        # Для простоты: преобразуем каждый символ в комплексное число (ord + i*0)
        # и умножаем на матрицу 2x2, но у нас вектор размерности 2, поэтому нужно разбить на пары
        # Реализуем упрощённо: возьмём первые два символа, применим вентиль, получим новые символы
        if len(code) < 2:
            return code
        # Берём первые два символа как комплексные числа
        c1 = complex(ord(code[0]), 0)
        c2 = complex(ord(code[1]), 0)
        vec = np.array([c1, c2])
        # Применяем вентиль
        new_vec = gate @ vec
        # Преобразуем обратно в символы (берём вещественную часть)
        new_code = chr(int(round(new_vec[0].real))) + chr(int(round(new_vec[1].real)))
        # Заменяем первые два символа в коде
        if len(code) > 2:
            new_code += code[2:]
        return new_code

# --- FUNC: noise_to_code ---
def noise_to_code(self, use_uncertainty: bool = True, use_quantum_gate: bool = True) -> str:
        code = super().noise_to_code(use_uncertainty)
        if use_quantum_gate and random.random() < 0.2:
            code = self.apply_quantum_gate_to_code(code)
        return code

# --- FUNC: acoustic_field ---
def acoustic_field(self, x: np.ndarray, y: np.ndarray, z: np.ndarray, tweezers_params: Dict) -> np.ndarray:
        """
        Моделирует акустическое поле в фокусе пинцета.
        Использует приближение параксиального пучка (гауссов пучок) с функциями Бесселя.
        Возвращает 3D-массив амплитуд давления.
        """
        # Извлекаем параметры
        f = tweezers_params.get('frequency', 10e6)
        power = tweezers_params.get('power', 0.1)
        focal_length = tweezers_params.get('focal_length', 5e-3)
        aperture = tweezers_params.get('aperture', 10e-3)
        # Скорость звука в среде (вода)
        c = 1500  # м/с
        # Длина волны
        lam = c / f
        # Волновое число
        k = 2 * np.pi / lam
        # Фокусное расстояние в длинах волн
        N = aperture / lam  # числовая апертура
        # Гауссов пучок с функциями Бесселя (приближение)
        # Для простоты используем 2D-сечение (x-z)
        x_grid, z_grid = np.meshgrid(x, z, indexing='ij')
        # Расстояние до фокуса
        r = np.sqrt(x_grid**2 + (z_grid - focal_length)**2)
        # Амплитуда давления (безразмерная)
        # Используем функцию Бесселя первого рода для модели дифракции
        # J1(k * a * sin(theta)) / (k * a * sin(theta))
        theta = np.arctan2(x_grid, z_grid - focal_length)
        sin_theta = np.sin(theta)
        # Избегаем деления на ноль
        sin_theta = np.where(np.abs(sin_theta) < 1e-12, 1e-12, sin_theta)
        # Амплитуда: пропорциональна J1(k * a * sin(theta)) / (k * a * sin(theta))
        # где a = aperture/2
        a = aperture / 2
        arg = k * a * sin_theta
        # Функция Бесселя первого рода первого порядка
        J1 = jv(1, arg)
        amplitude = np.abs(2 * J1 / arg)  # нормализованная амплитуда
        # Масштабируем мощность
        amplitude = amplitude * np.sqrt(power)  # пропорционально sqrt(мощности)
        # Обрезаем область за пределами главного лепестка
        amplitude[z_grid < focal_length - aperture/2] = 0
        amplitude[z_grid > focal_length + aperture/2] = 0
        return amplitude

# --- FUNC: simulate_trapping ---
def simulate_trapping(self, particle_radius: float, tweezers_params: Dict) -> Dict:
        """
        Симулирует захват частицы в фокусе акустического пинцета.
        Возвращает силу удержания и положение равновесия.
        """
        # Генерируем поле
        x = np.linspace(-2e-3, 2e-3, 100)
        z = np.linspace(0, 10e-3, 100)
        X, Z = np.meshgrid(x, z, indexing='ij')
        field = self.acoustic_field(X[:,0], None, Z[0,:], tweezers_params)
        # Находим максимум поля (положение фокуса)
        max_idx = np.unravel_index(np.argmax(field), field.shape)
        trap_x = x[max_idx[0]]
        trap_z = z[max_idx[1]]
        # Сила захвата (пропорциональна градиенту интенсивности)
        # Для простоты: сила ~ -grad(I)
        I = field**2
        grad_x = np.gradient(I, axis=0)
        grad_z = np.gradient(I, axis=1)
        # В точке фокуса градиент равен нулю (равновесие), но вблизи есть восстанавливающая сила
        # Оценим потенциальную яму: глубина = I_max - I_min
        I_max = np.max(I)
        I_min = np.min(I)
        well_depth = I_max - I_min
        # Жёсткость ловушки (аналог оптической жёсткости)
        # Приближённо: k_trap ~ I_max / (ширина ямы)^2
        # Найдём ширину ямы (по уровню 1/e)
        # Для простоты: ширина по оси x и z
        x_profile = I[:, max_idx[1]]
        z_profile = I[max_idx[0], :]
        # Нормализуем
        x_profile_norm = x_profile / np.max(x_profile)
        z_profile_norm = z_profile / np.max(z_profile)
        # Находим ширину на уровне 1/e^2
        x_indices = np.where(x_profile_norm > 1/np.exp(2))[0]
        z_indices = np.where(z_profile_norm > 1/np.exp(2))[0]
        if len(x_indices) > 0 and len(z_indices) > 0:
            width_x = x[x_indices[-1]] - x[x_indices[0]]
            width_z = z[z_indices[-1]] - z[z_indices[0]]
        else:
            width_x = 0.5e-3
            width_z = 0.5e-3
        # Жёсткость (условно, пропорциональна I_max / ширина^2)
        k_trap_x = I_max / (width_x**2 + 1e-12) * 1e-6  # масштаб
        k_trap_z = I_max / (width_z**2 + 1e-12) * 1e-6
        # Сила захвата для частицы радиусом r
        # Сила пропорциональна радиусу^3 и градиенту давления
        # Используем упрощённую формулу
        force_x = -k_trap_x * (particle_radius)**3
        force_z = -k_trap_z * (particle_radius)**3
        result = {
            'trap_position': (trap_x, trap_z),
            'well_depth': well_depth,
            'stiffness': (k_trap_x, k_trap_z),
            'force': (force_x, force_z),
            'field': field.tolist(),
            'x_grid': x.tolist(),
            'z_grid': z.tolist()
        }
        self.session_data["🧲"]["simulations"].append(result)
        return result

# --- FUNC: neuron_stimulation ---
def neuron_stimulation(self, field_params: Dict, neuron_position: Tuple[float, float, float]) -> Dict:
        """
        Моделирует стимуляцию нейрона сфокусированным акустическим полем.
        Оценивает изменение мембранного потенциала.
        """
        # Упрощённая модель: акустическое давление вызывает механическое смещение
        # мембраны, что приводит к изменению проницаемости ионных каналов.
        # Используем модель Ходжкина-Хаксли с акустическим возбуждением.
        # Для демонстрации: вычисляем индуцированный потенциал как функцию давления.
        freq = field_params.get('frequency', 10e6)
        power = field_params.get('power', 0.1)
        # Давление в фокусе (приближённо)
        pressure = power * 1000  # Па (условно)
        # Эффект: потенциал изменяется на величину, пропорциональную давлению
        # и частоте (высокие частоты более эффективны для механического воздействия)
        induced_potential = pressure * 1e-6 * (freq / 1e6)  # мВ
        # Порог возбуждения нейрона ~ -55 мВ (сдвиг)
        threshold = 10  # мВ (упрощённо)
        if induced_potential > threshold:
            stimulation = 'активация'
        else:
            stimulation = 'субпороговое'
        result = {
            'pressure': pressure,
            'induced_potential': induced_potential,
            'stimulation': stimulation,
            'neuron_position': neuron_position,
            'params': field_params
        }
        self.session_data["🧲"]["manipulation_history"].append(result)
        return result

# --- FUNC: plot_tweezers_field ---
def plot_tweezers_field(self, sim_result: Dict):
        """
        Визуализирует акустическое поле и положение ловушки.
        """
        field = np.array(sim_result['field'])
        x = np.array(sim_result['x_grid'])
        z = np.array(sim_result['z_grid'])
        trap_x, trap_z = sim_result['trap_position']

        fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(12, 5))
        # Поле
        ax1.imshow(field, extent=[x.min(), x.max(), z.min(), z.max()],
                   origin='lower', aspect='auto', cmap='RdBu_r')
        ax1.scatter(trap_x, trap_z, color='green', s=50, label='Ловушка')
        ax1.set_xlabel('x, мм')
        ax1.set_ylabel('z, мм')
        ax1.set_title('Акустическое поле')
        ax1.legend()
        # Профиль вдоль оси x
        # Берём средний срез по z в области фокуса
        z_idx = np.argmin(np.abs(z - trap_z))
        x_profile = field[:, z_idx]
        ax2.plot(x, x_profile, 'b-', label='Профиль x')
        ax2.axvline(x=trap_x, color='r', linestyle='--', label='Фокус')
        ax2.set_xlabel('x, мм')
        ax2.set_ylabel('Интенсивность (отн. ед.)')
        ax2.set_title('Поперечный профиль ловушки')
        ax2.legend()
        plt.tight_layout()
        plt.show()

