# --- FUNC: draw_kolovrat ---
def draw_kolovrat(draw, center, radius):
    x, y = center
    for i in range(0, 360, 45):  # 8 лучей
        angle = i * 3.1415926535 / 180
        end_x = x + radius * 0.8 * (1.2 * (i % 2)) * (1 if i < 180 else -1) * (1 if i < 90 or i > 270 else -1)
        end_y = y + radius * 0.8 * (1.2 * (i % 2)) * (1 if i < 90 or i > 270 else -1)
        draw.line([(x, y), (end_x, end_y)], fill=colors["red"], width=3)

# --- FUNC: draw_alatyr ---
def draw_alatyr(draw, center, size):
    x, y = center
    points = []
    for i in range(8):
        angle = 3.1415926535 * i / 4
        radius = size if i % 2 == 0 else size * 0.4
        points.append((x + radius * (1 if i < 4 else -1), y + radius * (1 if i % 4 < 2 else -1)))
    draw.polygon(points, fill=colors["gold"], outline=colors["black"])

# --- FUNC: draw_world_tree ---
def draw_world_tree(draw, position, height_tree):
    x, y = position
    trunk_width = 20
    # Ствол
    draw.rectangle([x - trunk_width//2, y, x + trunk_width//2, y + height_tree], fill=colors["black"])
    # Крона (треугольники)
    for i in range(3):
        crown_height = height_tree // 3
        crown_y = y - crown_height * i
        draw.polygon([
            (x - trunk_width*2, crown_y),
            (x + trunk_width*2, crown_y),
            (x, crown_y - crown_height)
        ], fill=colors["red"])

# --- FUNC: draw_gromovik ---
def draw_gromovik(draw, center, radius):
    x, y = center
    for i in range(6):  # 6 лучей
        angle = i * 60 * 3.1415926535 / 180
        end_x = x + radius * (0.8 if i % 2 == 0 else 0.5) * (1 if i < 180 else -1)
        end_y = y + radius * (0.8 if i % 2 == 0 else 0.5) * (1 if i < 90 or i > 270 else -1)
        draw.line([(x, y), (end_x, end_y)], fill=colors["black"], width=3)

