# --- FUNC: update_metrics ---
def update_metrics(self, rtt, error_rate, spoof_count):
        """Обновление матрицы сетевой активности"""
        self.G = np.array([
            [rtt, 0, 0],
            [0, error_rate, 0],
            [0, 0, spoof_count]
        ])

# --- FUNC: calculate_R ---
def calculate_R(self, lambda_param):
        """Расчёт резонансного коэффициента"""
        G_inv = inv(self.G)
        trace = np.trace(np.dot(G_inv, lambda_param))
        return trace / np.sqrt(5)

