def adaptive_threshold(channel):
      # Калибровка порога на основе исторических данных
      return 0.10 + 0.05 * channel.error_rate

# --- FUNC: invert_matrix ---
def invert_matrix(matrix: np.ndarray) -> np.ndarray:
    """Обращение матрицы с обработкой сингулярности"""
    try:
        return inv(matrix)
    except np.linalg.LinAlgError:
        return np.zeros_like(matrix)

# --- FUNC: matrix_multiply ---
def matrix_multiply(a: np.ndarray, b: np.ndarray) -> np.ndarray:
    """Умножение матриц с проверкой размерностей"""
    if a.shape[1] != b.shape[0]:
        raise ValueError("Несовместимые размеры матриц")
    return np.dot(a, b)

# --- FUNC: trace ---
def trace(matrix: np.ndarray) -> float:
    """След матрицы"""
    return np.trace(matrix)

# --- FUNC: block_suspicious_routes ---
def block_suspicious_routes(ips: list) -> None:
    """Блокировка подозрительных IP через iptables (пример)"""
    import subprocess
    for ip in ips:
        subprocess.run(["iptables", "-A", "INPUT", "-s", ip, "-j", "DROP"])

