# --- FUNC: gradient_thickness ---
def gradient_thickness(z_coord, max_thickness):
    return max_thickness * (1 - z_coord / 100)

# --- FUNC: generate_lattice ---
def generate_lattice(width=100, height=100, depth=100, cell=10, wall=2, outer_mult=3):
    # Генерация точек решетки
    x, y, z = np.meshgrid(*[np.arange(0, d, cell) for d in (width, height, depth)])
    points = np.vstack([x.ravel(), y.ravel(), z.ravel()]).T
    
    # Триангуляция и создание сетки
    delaunay = Delaunay(points)
    stl_mesh = mesh.Mesh(np.zeros(delaunay.convex_hull.shape[0], dtype=mesh.Mesh.dtype))
    
    for i, face in enumerate(delaunay.convex_hull):
        stl_mesh.vectors[i] = points[face]
    
    # Усиление внешних стенок
    stl_mesh.vectors[np.any(stl_mesh.vectors[:,:,2] < cell, axis=1)] *= outer_mult
    return stl_mesh

# --- FUNC: hyperboloid_profile ---
def hyperboloid_profile(z, D_in, D_throat, L, n=2.0, z_throat_frac=0.55):
    """
    Профиль гиперболоида: радиус как функция z.
    z в диапазоне [0, L].
    Тонкое место (горловина) на z_throat_frac*L.
    """
    z_throat = z_throat_frac * L
    r_in = D_in / 2
    r_throat = D_throat / 2
    # Плавный переход
    t = np.clip((z - z_throat) / (L - z_throat if z >= z_throat else z_throat + 1e-9), -1, 1)
    r = r_throat + (r_in - r_throat) * np.abs(t)**n
    return r

