# --- FUNC: write_stl ---
def write_stl(triangles, filename):
    """Пишет бинарный STL без зависимостей."""
    n_tri = len(triangles)
    with open(filename, 'wb') as f:
        f.write(b'\x00' * 80)  # header
        f.write(np.uint32(n_tri).tobytes())
        for tri in triangles:
            # нормаль
            v1 = tri[1] - tri[0]
            v2 = tri[2] - tri[0]
            n = np.cross(v1, v2)
            n_norm = np.linalg.norm(n)
            if n_norm > 0:
                n = n / n_norm
            f.write(n.astype(np.float32).tobytes())
            for vertex in tri:
                f.write(vertex.astype(np.float32).tobytes())
            f.write(np.uint16(0).tobytes())

