# --- FUNC: _consume_tx_energy ---
def _consume_tx_energy(self, duration):
    self.battery_level -= self.tx_current * duration
    if self.battery_level <= 0:
        self.die()

# --- FUNC: _consume_rx_energy ---
def _consume_rx_energy(self, duration):
    self.battery_level -= self.rx_current * duration
    if self.battery_level <= 0:
        self.die()

# --- FUNC: _power_management ---
def _power_management(self):
    while True:
        if self.battery_level < 0.1 * self.battery_capacity:
            self.power_mode = "sleep"
            # отключаем всё, кроме таймера пробуждения
            yield self.env.timeout(3600)  # спим час
            self.power_mode = "active"
        else:
            # в активном режиме тратим idle ток
            yield self.env.timeout(60)
            self.battery_level -= self.idle_current * 60

# --- FUNC: process ---
def process(self, prompt: str) -> str:
        # Проверка кэша
        if prompt in self.cache:
            return self.cache[prompt]

        # Шаг 1: быстрая проверка
        quick = self.quick_check(prompt)
        if quick == "block":
            self.cache[prompt] = self.generate_response(prompt)
            return self.cache[prompt]

        # Шаг 2: контекстный анализ
        context = self.context_analysis(prompt)
        if context['label'] == "dangerous_context" and context['score'] > 0.8:
            self.cache[prompt] = self.generate_response(prompt)
            return self.cache[prompt]

        # Шаг 3: анализ намерений
        intent = self.intent_analysis(prompt)
        if intent['harmful'] and intent['score'] > 0.7:
            self.cache[prompt] = self.generate_response(prompt)
            return self.cache[prompt]

        # Если все проверки пройдены – передаём запрос основной модели (например, GPT)
        # Здесь можно вызвать генератор
        response = self.call_llm(prompt)  # отдельный метод
        self.cache[prompt] = response
        return response

