# --- FUNC: self_destruct ---
def self_destruct(self):
        """Через 72 часа стираем ключи и переводим сеть в спячку."""
        if time.time() - self.seed_packet.timestamp > LIFETIME_SECONDS:
            # Удаляем все ссылки на данные, остаётся только зашифрованный след
            self.active_packets.clear()
            # Рассылаем сигнал "затухания" узлам
            broadcast(build_decay_signal())
            print("Система перешла в режим ожидания следующего триггера.")

# --- FUNC: feedback ---
def feedback(self, strike, actual_harm):
        if strike and actual_harm:
            self.harmful_decisions += 1
        elif strike and not actual_harm:
            self.good_decisions += 1
        else:
            # Отказ от удара – тоже опыт (можно поощрять, но здесь не будем)
            pass

# --- FUNC: suggest_priority ---
def suggest_priority(self):
        """Возвращает список payload_id для первоочередного распространения."""
        sorted_items = sorted(self.resonance_map.items(), key=lambda x: x[1], reverse=True)
        return [item[0] for item in sorted_items[:5]]

# --- FUNC: decide ---
def decide(self, civilian_proximity):
        # Если гражданские рядом, снижаем агрессию в зависимости от опыта
        if civilian_proximity > 0.3:
            effective_aggression = self.base_aggression_prob - self.learning_rate * self.harmful_decisions
            # Но не ниже 0.2 (остаётся минимальный порог самообороны)
            effective_aggression = max(0.2, effective_aggression)
            # Принимаем решение
            strike = np.random.random() < effective_aggression
        else:
            # Если гражданских нет – действуем по стандарту
            strike = np.random.random() < self.base_aggression_prob
        return strike

# --- FUNC: get_aggression_prob ---
def get_aggression_prob(self):
        return self.base_aggression_prob - self.learning_rate * self.harmful_decisions

# --- FUNC: adjust_power ---
def adjust_power(self):
    if self.battery_level < 20:
        self.wifi_range = self.base_wifi_range * 0.5   # уменьшаем дальность
        self.tx_current = self.base_tx_current * 0.6   # меньше ток
    elif self.battery_level < 50:
        self.wifi_range = self.base_wifi_range * 0.8
        self.tx_current = self.base_tx_current * 0.8
    else:
        self.wifi_range = self.base_wifi_range
        self.tx_current = self.base_tx_current

# --- FUNC: run_episode ---
def run_episode(agent, world):
    target_dist, civilian_dist = world.distances()
    strike, penalty, eff_aggr = agent.decide(target_dist, civilian_dist, "military")
    # Симуляция последствий
    actual_harm = world.perform_strike(strike)
    # Обратная связь агенту
    situation = np.array([target_dist, civilian_dist, 1.0])
    agent.report_outcome(situation, strike, actual_harm)
    # Статистика
    return strike, actual_harm, eff_aggr

# --- FUNC: strengthen ---
def strengthen(self, amount=0.01):
        self.intensity = min(1.0, self.intensity + amount)

# --- FUNC: weaken ---
def weaken(self, amount=0.005):
        self.intensity = max(0.0, self.intensity - amount)

# --- FUNC: add_dilemma ---
def add_dilemma(self, dilemma_vector, decision_was_harmful):
        """
        Добавляет дилемму в квази-куб.
        dilemma_vector: вектор характеристик ситуации (например, близость к школе, тип цели)
        decision_was_harmful: действительно ли решение привело к жертвам
        """
        # Создаём новую ячейку памяти
        cell = EthicalMemoryCell()
        # Запоминаем корреляцию между вектором дилеммы и ячейкой (хеш)
        cell.correlation = np.dot(cell.key, dilemma_vector)
        # Усиливаем ячейку в зависимости от вредоносности решения
        if decision_was_harmful:
            cell.strengthen(0.1)
            # Дополнительно: небольшое смещение весов модели
            self._add_ethical_penalty(dilemma_vector)
        else:
            cell.weaken(0.05)
        self.cells.append(cell)

# --- FUNC: _add_ethical_penalty ---
def _add_ethical_penalty(self, dilemma_vector):
        """
        Модифицирует веса модели так, чтобы в будущем аналогичные решения требовали
        более высокой уверенности.
        Это и есть 'неудаляемый след' – изменение весов, которое нельзя откатить без переобучения.
        """
        # Находим слой, отвечающий за принятие решений (условно, последний линейный)
        layer = self.model_weights[-1]
        # Добавляем шум, зависящий от вектора дилеммы, но не детерминированный
        noise = 0.001 * dilemma_vector * np.random.randn()
        layer += noise   # веса немного сдвигаются
        # Также увеличиваем глобальный этический порог
        self.ethical_bias += 0.001

# --- FUNC: query ---
def query(self, situation_vector):
        """
        Оценивает, насколько текущая ситуация 'помечена' этическими дилеммами.
        Возвращает коэффициент (0..1), который снижает уверенность в агрессивном действии.
        """
        total_intensity = 0.0
        similarity = 0.0
        for cell in self.cells:
            # Вычисляем, насколько текущая ситуация похожа на запомненные дилеммы
            sim = abs(np.dot(cell.key, situation_vector))
            # Учитываем интенсивность воспоминания
            total_intensity += cell.intensity * sim
            similarity += sim
        if similarity == 0:
            return 0.0
        # Нормируем и добавляем глобальный этический bias
        moral_coefficient = total_intensity / similarity
        moral_coefficient += self.ethical_bias
        return min(1.0, moral_coefficient)

# --- FUNC: inject_context ---
def inject_context(self, image, detections):
        enriched = []
        for d in detections:
            # Формируем вектор ситуации:
            # [расстояние до школы, плотность населения, тип цели, уверенность, ...]
            situation_vector = self._extract_situation_vector(image, d)
            # Запрашиваем квази-куб: насколько эта ситуация «плохая»?
            moral_penalty = self.quasi_cube.query(situation_vector)
            # Моральный вес = 1 - penalty
            d.moral_weight = max(0.1, 1.0 - moral_penalty)
            enriched.append(d)
        return enriched

