# --- FUNC: _load_patterns ---
def _load_patterns(self, filepath, key):
        f = Fernet(key)
        with open(filepath, 'rb') as file:
            encrypted_data = file.read()
        decrypted_data = f.decrypt(encrypted_data)
        return json.loads(decrypted_data.decode())

