# --- FUNC: assign_targets ---
def assign_targets(shield_radius, n_guns, object_position, cloud_field):
    """
    Определяет точки фокусировки каждой пушки так, чтобы создать
    эквипотенциальную поверхность вокруг объекта.
    """
    # 1. Генерация равномерно распределённых точек на сфере радиуса shield_radius
    targets = generate_sphere_points(n_guns, shield_radius)
    # 2. Сдвиг к облаку (компенсация градиента поля)
    for i, target in enumerate(targets):
        # Учитываем направление поля облака (вектор от объекта к облаку)
        field_vector = cloud_field.direction
        # Смещаем точку чуть в сторону облака, чтобы увеличить экранирование
        targets[i] = target + 0.2 * field_vector * shield_radius
    # 3. Передача целей каждой пушке (через локальные контроллеры)
    for gun_id, target in enumerate(targets):
        send_target(gun_id, target)
    return targets

# --- FUNC: dump ---
def dump(cls) -> str:
        """Экспорт всех данных в компактный JSON-строку"""
        import json
        data = {
            k: v for k, v in cls.__dict__.items() 
            if not k.startswith('_') and not callable(v)
        }
        # Обработка вложенных классов/функций для сериализации
        return json.dumps(data, indent=2, ensure_ascii=False)

# --- FUNC: lightning_current ---
def lightning_current(self, t):
        # Аппроксимация разряда: двусторонняя экспонента
        return self.I_peak * (np.exp(-t/self.tau) - np.exp(-t/(self.tau/5)))

# --- FUNC: circuit_equations ---
def circuit_equations(self, state, t, I_source):
        # state = [I_L, U_C, I_smes]
        I_L, U_C, I_smes = state
        dI_L = (I_source - I_L - U_C/self.R_loss) / self.L
        dU_C = (I_L - I_smes) / self.C
        dI_smes = U_C / self.L_smes
        return [dI_L, dU_C, dI_smes]

# --- FUNC: phase_sync ---
def phase_sync(measured_current, target_freq=1e6, tolerance=0.01):
    """
    measured_current: массив отсчётов тока (временной ряд)
    target_freq: целевая частота (1 МГц)
    tolerance: допустимое отклонение
    Возвращает: корректировку для подстройки L или C
    """
    # 1. Вычисление текущей частоты через анализ нулей или FFT
    current_freq = estimate_frequency(measured_current)
    # 2. Вычисление ошибки
    delta_f = target_freq - current_freq
    if abs(delta_f) > tolerance:
        # 3. Корректировка индуктивности или ёмкости (подбор параметров)
        if delta_f > 0:
            # Увеличиваем ёмкость (уменьшаем частоту)
            adjust_capacitance(step=+delta_f * 1e-12)
        else:
            # Уменьшаем ёмкость (увеличиваем частоту)
            adjust_capacitance(step=delta_f * 1e-12)
    return current_freq

