def predict_strike(electric_field_history, weather_data):
    """
    electric_field_history: скользящее окно значений поля (последние N секунд)
    weather_data: температура, давление, влажность
    Возвращает: вероятность удара в ближайшие 10 секунд и ожидаемое время
    """
    # 1. Нормализация входных данных
    norm_input = preprocess(electric_field_history, weather_data)
    # 2. Прогон через обученную LSTM-модель (загружена в FPGA)
    probability, time_to_strike = lstm_model.predict(norm_input)
    # 3. Если вероятность > порога, запускаем подготовку системы
    if probability > 0.7:
        prepare_system(time_to_strike)  # зарядить SMES, активировать лазеры
    return probability, time_to_strike

# --- FUNC: update_data ---
def update_data(self, 
                   target: str, 
                   key: str, 
                   new_data: Any, 
                   deep_merge: bool = False) -> None:
        """
        Обновляет данные в указанном хранилище.
        
        Args:
            target: Целевое хранилище ('keys' или 'storage')
            key: Ключ для обновления
            new_data: Новые данные
            deep_merge: Флаг глубокого слияния словарей
        """
        storage_map = {
            'keys': self.keys,
            'storage': self.storage
        }
        
        if target not in storage_map:
            raise ValueError(f"Неизвестное хранилище: {target}")
            
        current_data = storage_map[target]
        
        if deep_merge and isinstance(current_data.get(key), dict) and isinstance(new_data, dict):
            # Реализация глубокого слияния словарей
            self._deep_merge(current_data[key], new_data)
        else:
            current_data[key] = new_data

# --- FUNC: _deep_merge ---
def _deep_merge(self, base_dict: Dict, update_dict: Dict) -> None:
        """Рекурсивное глубокое слияние словарей"""
        for key, value in update_dict.items():
            if (key in base_dict and 
                isinstance(base_dict[key], dict) and 
                isinstance(value, dict)):
                self._deep_merge(base_dict[key], value)
            else:
                base_dict[key] = value

# --- FUNC: register_function ---
def register_function(self, 
                         func_type: str, 
                         name: str, 
                         func: Callable) -> None:
        """
        Регистрирует функцию для последующего использования.
        
        Args:
            func_type: Тип функции ('update' или 'export')
            name: Имя функции
            func: Callable-объект
        """
        function_registry = {
            'update': self.update_functions,
            'export': self.export_functions
        }
        
        if func_type not in function_registry:
            raise ValueError(f"Неизвестный тип функции: {func_type}")
            
        function_registry[func_type][name] = func

# --- FUNC: execute_function ---
def execute_function(self, 
                        func_type: str, 
                        name: str, 
                        *args, **kwargs) -> Any:
        """
        Выполняет зарегистрированную функцию.
        
        Args:
            func_type: Тип функции ('update' или 'export')
            name: Имя функции
            *args: Аргументы функции
            **kwargs: Ключевые аргументы функции
            
        Returns:
            Результат выполнения функции
        """
        function_registry = {
            'update': self.update_functions,
            'export': self.export_functions
        }
        
        if func_type not in function_registry:
            raise ValueError(f"Неизвестный тип функции: {func_type}")
            
        func = function_registry[func_type].get(name)
        if not func or not callable(func):
            raise ValueError(f"Функция {name} не найдена или не вызываема")
            
        return func(*args, **kwargs)

# --- FUNC: verify_session ---
def verify_session(phi_data: str, timestamp: str, dimensions: str, project: str) -> bool:
    data_string = phi_data + timestamp + dimensions + project
    current_hash = hashlib.sha256(data_string.encode('utf-8')).hexdigest()
    expected_hash = "7aefd9b6c587c14e8d6e8579e1c6c0e8e8f1c3d2c7e4e6e5a0b9c8d7e6f5e4e3d2c1b0a9f8e7d6c5b4a3e2f1e0d9c8b7a6"
    return current_hash == expected_hash

# --- FUNC: iterate_session ---
def iterate_session(self, updates: Dict[str, Any], 
                       description: str = "") -> str:
        """
        🔄 Выполнение итерации системы с новыми данными
        Возвращает ID итерации для отслеживания
        """
        iteration_id = f"iter_{len(self.iteration_history) + 1}"
        
        # Сохраняем состояние до обновления
        previous_state = self.core.export_data(include_sensitive=False)
        
        # Применяем обновления
        if 'parameters' in updates:
            self.core.update_parameters(updates['parameters'])
        
        if 'missions' in updates:
            for mission in updates['missions']:
                self.core.add_mission(mission)
        
        if 'harmony_sessions' in updates:
            for session in updates['harmony_sessions']:
                self.core.add_harmony_session(**session)
        
        # Записываем итерацию в историю
        iteration_record = {
            'id': iteration_id,
            'timestamp': datetime.now().isoformat(),
            'description': description,
            'updates_applied': updates,
            'previous_state': previous_state,
            'new_validation_hash': self.core.validation_hash
        }
        
        self.iteration_history.append(iteration_record)
        
        # Очищаем кэш анализа после изменений
        self.analysis_cache.clear()
        
        return iteration_id

