def close_request(self):
        self.status = "Закрыта"

# --- FUNC: add_record ---
def add_record(self, request_id: str, objects: List[ElectricalObject], 
                  workers: List[str], start: str, end: str):
        record = {
            'request_id': request_id,
            'objects': [obj.inv_number for obj in objects],
            'workers': workers,
            'start': datetime.strptime(start, "%Y-%m-%d %H:%M"),
            'end': datetime.strptime(end, "%Y-%m-%d %H:%M"),
            'man_hours': self._calculate_man_hours(start, end, len(workers))
        }
        self.records.append(record)

# --- FUNC: _calculate_man_hours ---
def _calculate_man_hours(self, start: str, end: str, workers_count: int) -> float:
        start_dt = datetime.strptime(start, "%Y-%m-%d %H:%M")
        end_dt = datetime.strptime(end, "%Y-%m-%d %H:%M")
        duration = (end_dt - start_dt).total_seconds() / 3600
        return round(duration * workers_count, 2)

# --- FUNC: update_timesheet ---
def update_timesheet(self, journal_record: dict):
        for worker in journal_record['workers']:
            key = (worker, journal_record['request_id'])
            hours = journal_record['man_hours'] / len(journal_record['workers'])
            
            if key in self.timesheet:
                self.timesheet[key] += hours
            else:
                self.timesheet[key] = hours

# --- FUNC: get_report ---
def get_report(self):
        return self.timesheet

