        board.set_piece(Position(2, 1, z), Piece("конь", "белый", Position(2,1,z)))
        board.set_piece(Position(7, 1, z), Piece("конь", "белый", Position(7,1,z)))
        # Слоны
        board.set_piece(Position(3, 1, z), Piece("слон", "белый", Position(3,1,z)))
        board.set_piece(Position(6, 1, z), Piece("слон", "белый", Position(6,1,z)))
        # Ферзь
        board.set_piece(Position(4, 1, z), Piece("ферзь", "белый", Position(4,1,z)))
        # Король
        board.set_piece(Position(5, 1, z), Piece("король", "белый", Position(5,1,z)))
        # Пешки (Y=2)
        for x in range(1, 9):
            board.set_piece(Position(x, 2, z), Piece("пешка", "белый", Position(x,2,z)))
        
        # Чёрные (Y=8,7)
        # Ладьи
        board.set_piece(Position(1, 8, z), Piece("ладья", "чёрный", Position(1,8,z)))
        board.set_piece(Position(8, 8, z), Piece("ладья", "чёрный", Position(8,8,z)))
        # Кони
        board.set_piece(Position(2, 8, z), Piece("конь", "чёрный", Position(2,8,z)))
        board.set_piece(Position(7, 8, z), Piece("конь", "чёрный", Position(7,8,z)))
        # Слоны
        board.set_piece(Position(3, 8, z), Piece("слон", "чёрный", Position(3,8,z)))
        board.set_piece(Position(6, 8, z), Piece("слон", "чёрный", Position(6,8,z)))
        # Ферзь
        board.set_piece(Position(4, 8, z), Piece("ферзь", "чёрный", Position(4,8,z)))
        # Король
        board.set_piece(Position(5, 8, z), Piece("король", "чёрный", Position(5,8,z)))
        # Пешки (Y=7)
        for x in range(1, 9):
            board.set_piece(Position(x, 7, z), Piece("пешка", "чёрный", Position(x,7,z)))
    
