# --- FUNC: is_attacked ---
def is_attacked(board, pos, by_color):
    """Проверяет, атакована ли клетка pos фигурами цвета by_color."""
    for piece in board.get_all_pieces(by_color):
        # Временно игнорируем рокировку в генерации ходов, чтобы избежать рекурсии
        for move in generate_moves(board, piece, ignore_castling=True):
            if move == pos:
                return True
    return False

# --- FUNC: bishop_moves ---
def bishop_moves(board, piece):
    moves = []
    x, y, z = piece.pos.x, piece.pos.y, piece.pos.z
    color = piece.color

    # 1. Диагонали в плоскости X-Y (dz=0)
    for dx, dy in [(1,1), (1,-1), (-1,1), (-1,-1)]:
        for step in range(1, 8):
            nx, ny = x + dx*step, y + dy*step
            if nx < 1 or nx > 8 or ny < 1 or ny > 8:
                break
            pos = Position(nx, ny, z)
            if board.is_empty(pos):
                moves.append(pos)
            elif board.is_enemy(pos, color):
                moves.append(pos)
                break
            else:
                break

    # 2. Диагонали в плоскости X-Z (dy=0)
    for dx, dz in [(1,1), (1,-1), (-1,1), (-1,-1)]:
        for step in range(1, 4):
            nx, nz = x + dx*step, z + dz*step
            if nx < 1 or nx > 8 or nz < 1 or nz > 4:
                break
            pos = Position(nx, y, nz)
            if board.is_empty(pos):
                moves.append(pos)
            elif board.is_enemy(pos, color):
                moves.append(pos)
                break
            else:
                break

    # 3. Диагонали в плоскости Y-Z (dx=0)
    for dy, dz in [(1,1), (1,-1), (-1,1), (-1,-1)]:
        for step in range(1, 4):
            ny, nz = y + dy*step, z + dz*step
            if ny < 1 or ny > 8 or nz < 1 or nz > 4:
                break
            pos = Position(x, ny, nz)
            if board.is_empty(pos):
                moves.append(pos)
            elif board.is_enemy(pos, color):
                moves.append(pos)
                break
            else:
                break

    # 4. Идеальные 3D-диагонали (|dx|=|dy|=|dz|)
    for dx in (-1, 1):
        for dy in (-1, 1):
            for dz in (-1, 1):
                for step in range(1, 4):
                    nx, ny, nz = x + dx*step, y + dy*step, z + dz*step
                    if nx < 1 or nx > 8 or ny < 1 or ny > 8 or nz < 1 or nz > 4:
                        break
                    pos = Position(nx, ny, nz)
                    if board.is_empty(pos):
                        moves.append(pos)
                    elif board.is_enemy(pos, color):
                        moves.append(pos)
                        break
                    else:
                        break

    return moves

# --- FUNC: king_moves ---
def king_moves(board, piece, ignore_castling=False):
    moves = []
    x, y, z = piece.pos.x, piece.pos.y, piece.pos.z
    color = piece.color

    # Обычные ходы короля (26 направлений)
    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            for dz in (-1, 0, 1):
                if dx == dy == dz == 0:
                    continue
                pos = Position(x+dx, y+dy, z+dz)
                if in_bounds(pos) and not board.is_own(pos, color):
                    moves.append(pos)

    # Горизонтальная рокировка (уже реализована)
    if not ignore_castling and not piece.moved:
        opponent = "чёрный" if color == "белый" else "белый"
        # ... (код горизонтальной рокировки)

        # --- ВЕРТИКАЛЬНАЯ РОКИРОВКА ---
        # Ищем ладью на той же вертикали X,Y, но на другом Z
        for rook_z in range(1, 5):
            if rook_z == z:
                continue
            rook_pos = Position(x, y, rook_z)
            if board.is_own(rook_pos, color):
                rook = board.get_piece(rook_pos)
                if rook.type == "ладья" and not rook.moved:
                    # Определяем направление и расстояние
                    direction = 1 if rook_z > z else -1
                    distance = abs(rook_z - z)
                    if distance < 2:
                        continue  # слишком близко для вертикальной рокировки

                    # Проверяем, что промежуточные слои пусты
                    empty = True
                    for step in range(1, distance):
                        mid_z = z + direction * step
                        if not board.is_empty(Position(x, y, mid_z)):
                            empty = False
                            break
                    if not empty:
                        continue

                    # Король пойдёт на z + 2*direction, ладья на z + direction
                    king_new_z = z + 2 * direction
                    rook_new_z = z + direction
                    if not (1 <= king_new_z <= 4 and 1 <= rook_new_z <= 4):
                        continue

                    # Проверяем, что конечные клетки не заняты своими (кроме ладьи, которую двигаем)
                    if board.is_own(Position(x, y, king_new_z), color):
                        continue
                    # Ладья переместится на rook_new_z, там не должно быть фигур (кроме самой ладьи? её там нет)
                    if board.is_own(Position(x, y, rook_new_z), color):
                        continue

                    # Проверка атак: король не под шахом, клетки на пути не атакованы
                    if is_attacked(board, piece.pos, opponent):
                        continue
                    if is_attacked(board, Position(x, y, z + direction), opponent):
                        continue
                    if is_attacked(board, Position(x, y, king_new_z), opponent):
                        continue

                    # Всё чисто — добавляем ход
                    moves.append(Position(x, y, king_new_z))

    return moves

# --- FUNC: queen_moves ---
def queen_moves(board, piece):
    return rook_moves(board, piece) + bishop_moves(board, piece)

# --- FUNC: __eq__ ---
def __eq__(self, other):
        return self.x == other.x and self.y == other.y and self.z == other.z

# --- FUNC: __hash__ ---
def __hash__(self):
        return hash((self.x, self.y, self.z))

# --- FUNC: get_piece ---
def get_piece(self, pos):
        return self.layers[pos.z-1][pos.y-1][pos.x-1]

# --- FUNC: set_piece ---
def set_piece(self, pos, piece):
        self.layers[pos.z-1][pos.y-1][pos.x-1] = piece
        if piece:
            piece.pos = pos

# --- FUNC: is_empty ---
def is_empty(self, pos):
        return self.get_piece(pos) is None

# --- FUNC: is_enemy ---
def is_enemy(self, pos, color):
        p = self.get_piece(pos)
        return p is not None and p.color != color

# --- FUNC: is_own ---
def is_own(self, pos, color):
        p = self.get_piece(pos)
        return p is not None and p.color == color

# --- FUNC: get_all_pieces ---
def get_all_pieces(self, color):
        pieces = []
        for z in range(4):
            for y in range(8):
                for x in range(8):
                    p = self.layers[z][y][x]
                    if p and p.color == color:
                        pieces.append(p)
        return pieces

# --- FUNC: make_move ---
def make_move(self, piece, new_pos):
    old_pos = piece.pos
    captured = self.get_piece(new_pos)
    self.history.append((piece, old_pos, captured, new_pos))

    # Перемещаем
    self.set_piece(old_pos, None)
    self.set_piece(new_pos, piece)

    # Проверка превращения
    if piece.type == "пешка":
        if (piece.color == "белый" and new_pos.y == 8) or \
           (piece.color == "чёрный" and new_pos.y == 1):
            # Превращаем в ферзя
            new_piece = Piece("ферзь", piece.color, new_pos)
            self.set_piece(new_pos, new_piece)
            # Обновляем историю, чтобы undo вернул пешку
            self.history[-1] = (piece, old_pos, captured, new_pos, new_piece)

    self.turn = "чёрный" if self.turn == "белый" else "белый"

# --- FUNC: undo_move ---
def undo_move(self):
        piece, old_pos, captured, new_pos = self.history.pop()
        self.set_piece(new_pos, captured)  # вернуть взятую фигуру
        self.set_piece(old_pos, piece)
        self.turn = "чёрный" if self.turn == "белый" else "белый"

# --- FUNC: rook_moves ---
def rook_moves(board, piece):
    moves = []
    x, y, z = piece.pos.x, piece.pos.y, piece.pos.z
    color = piece.color

    # По X
    for dx in (-1, 1):
        for step in range(1, 8):
            nx = x + dx * step
            if nx < 1 or nx > 8:
                break
            pos = Position(nx, y, z)
            if board.is_empty(pos):
                moves.append(pos)
            elif board.is_enemy(pos, color):
                moves.append(pos)
                break
            else:  # своя фигура
                break

    # По Y (аналогично)
    for dy in (-1, 1):
        for step in range(1, 8):
            ny = y + dy * step
            if ny < 1 or ny > 8:
                break
            pos = Position(x, ny, z)
            if board.is_empty(pos):
                moves.append(pos)
            elif board.is_enemy(pos, color):
                moves.append(pos)
                break
            else:
                break

    # По Z (новое!)
    for dz in (-1, 1):
        for step in range(1, 4):  # максимум 3 шага, т.к. всего 4 слоя
            nz = z + dz * step
            if nz < 1 or nz > 4:
                break
            pos = Position(x, y, nz)
            if board.is_empty(pos):
                moves.append(pos)
            elif board.is_enemy(pos, color):
                moves.append(pos)
                break
            else:
                break

    return moves

