# --- FUNC: pawn_moves ---
def pawn_moves(board, piece):
    moves = []
    x, y, z = piece.pos.x, piece.pos.y, piece.pos.z
    color = piece.color
    forward = 1 if color == "белый" else -1

    # Ход вперёд на 1
    ny = y + forward
    if 1 <= ny <= 8:
        pos = Position(x, ny, z)
        if board.is_empty(pos):
            moves.append(pos)
            # Ход на 2 с начальной позиции
            if (color == "белый" and y == 2) or (color == "чёрный" and y == 7):
                ny2 = y + 2*forward
                pos2 = Position(x, ny2, z)
                if board.is_empty(pos2):
                    moves.append(pos2)

    # Взятие по диагонали
    for dx in (-1, 1):
        nx = x + dx
        if 1 <= nx <= 8 and 1 <= ny <= 8:
            pos = Position(nx, ny, z)
            if board.is_enemy(pos, color):
                moves.append(pos)

    # --- НОВОЕ: превращение с переходом на Z±1 ---
    # Проверяем, достигла ли пешка последней горизонтали
    if (color == "белый" and ny == 8) or (color == "чёрный" and ny == 1):
        # Вариант 1: превращение на месте (уже добавлено как обычный ход)
        # Вариант 2: переход на Z±1 с превращением
        for dz in (-1, 1):
            nz = z + dz
            if 1 <= nz <= 4:
                pos = Position(x, ny, nz)
                if board.is_empty(pos):
                    moves.append(pos)      # свободная клетка → переход + превращение
                elif board.is_enemy(pos, color):
                    moves.append(pos)      # взятие + превращение
                # если своя фигура — нельзя

    return moves

