# --- FUNC: stabilize ---
def stabilize(self, system_entropy):
        if system_entropy > 0.618:
            return self.rotation_speed / (PHI * SQRT5)
        else:
            return self.resonance[0] * self.resonance[2]

# --- FUNC: minimax ---
def minimax(board, depth, alpha, beta, maximizing_player):
    if depth == 0 or game_over(board):
        return evaluate(board)

    if maximizing_player:
        max_eval = -float('inf')
        for piece in board.get_all_pieces("белый"):
            for move in generate_moves(board, piece):
                board.make_move(piece, move)
                eval = minimax(board, depth-1, alpha, beta, False)
                board.undo_move()
                max_eval = max(max_eval, eval)
                alpha = max(alpha, eval)
                if beta <= alpha:
                    break
        return max_eval
    else:
        min_eval = float('inf')
        for piece in board.get_all_pieces("чёрный"):
            for move in generate_moves(board, piece):
                board.make_move(piece, move)
                eval = minimax(board, depth-1, alpha, beta, True)
                board.undo_move()
                min_eval = min(min_eval, eval)
                beta = min(beta, eval)
                if beta <= alpha:
                    break
        return min_eval

