# --- FUNC: in_bounds ---
def in_bounds(pos):
    return 1 <= pos.x <= 8 and 1 <= pos.y <= 8 and 1 <= pos.z <= 4

# --- FUNC: generate_moves ---
def generate_moves(board, piece):
    if piece.type == "ладья":
        return rook_moves(board, piece)
    elif piece.type == "слон":
        return bishop_moves(board, piece)
    elif piece.type == "ферзь":
        return queen_moves(board, piece)
    elif piece.type == "конь":
        return knight_moves(board, piece)
    elif piece.type == "король":
        return king_moves(board, piece)
    elif piece.type == "пешка":
        return pawn_moves(board, piece)
    else:
        return []

# --- FUNC: game_over ---
def game_over(board):
    """Проверяет, закончилась ли игра (все короли одного цвета взяты)."""
    white_kings = [p for p in board.get_all_pieces("белый") if p.type == "король"]
    black_kings = [p for p in board.get_all_pieces("чёрный") if p.type == "король"]
    return len(white_kings) == 0 or len(black_kings) == 0

# --- FUNC: search_best_move ---
def search_best_move(board, depth):
    """Возвращает лучший ход для текущего игрока в виде (piece, new_pos)."""
    color = board.turn
    best_move = None
    if color == "белый":
        best_eval = -float('inf')
    else:
        best_eval = float('inf')

    for piece in board.get_all_pieces(color):
        for move in generate_moves(board, piece):
            board.make_move(piece, move)
            # После хода turn переключается, поэтому maximizing_player = (board.turn == "белый")
            eval = minimax(board, depth-1, -float('inf'), float('inf'), board.turn == "белый")
            board.undo_move()

            if color == "белый":
                if eval > best_eval:
                    best_eval = eval
                    best_move = (piece, move)
            else:
                if eval < best_eval:
                    best_eval = eval
                    best_move = (piece, move)

    return best_move

