# --- FUNC: generate_hashtag ---
def generate_hashtag(session_data: Dict) -> str:
        """
        Генерирует уникальный хештег для сессии
        
        Формат: #DeepSeek_Сессия_<Тема>_<Дата>_<Хеш>
        """
        import hashlib
        
        # Извлекаем ключевые данные
        theme = session_data.get('theme', 'Общая')
        date = session_data.get('date', datetime.now().strftime('%Y%m%d'))
        
        # Создаем короткий хеш для уникальности
        content_hash = hashlib.md5(
            str(session_data.get('modules', [])).encode()
        ).hexdigest()[:6].upper()
        
        # Форматируем тему (убираем спецсимволы, ограничиваем длину)
        clean_theme = ''.join(c for c in theme if c.isalnum() or c in ' _')
        clean_theme = clean_theme.replace(' ', '_')[:30]
        
        return f"#DeepSeek_Сессия_{clean_theme}_{date}_{content_hash}"

# --- FUNC: parse_hashtag ---
def parse_hashtag(hashtag: str) -> Dict:
        """Парсит хештег обратно в структурированные данные"""
        parts = hashtag.strip('#').split('_')
        
        return {
            'platform': parts[0] if len(parts) > 0 else '',
            'type': parts[1] if len(parts) > 1 else '',
            'theme': parts[2] if len(parts) > 2 else '',
            'date': parts[3] if len(parts) > 3 else '',
            'hash': parts[4] if len(parts) > 4 else ''
        }

