# --- FUNC: enhanced_plasma_simulation_with_sound ---
def enhanced_plasma_simulation_with_sound(light_wave, sound_freq, t_values, instability_points=None):
    """
    Улучшенная симуляция плазмы с интеграцией звуковой стабилизации.
    """
    # Создаем стабилизатор
    drum_stabilizer = PlasmaDrumStabilizer(base_freq=sound_freq)
    
    # Запускаем обычную симуляцию для получения базовой стабильности
    stability_history = []
    for t in t_values:
        stability, _ = plasma_grid_advanced(
            light_wave, sound_freq, t,
            instability_point=instability_points[0][:3] if instability_points else None,
            obstacle_factor=instability_points[0][3] if instability_points else 0
        )
        stability_history.append(stability.real)
    
    # Генерируем звуковой сигнал для стабилизации
    total_duration = t_values[-1] - t_values[0]
    sound_signal = drum_stabilizer.generate_stabilization_sound(
        stability_history, total_duration, rhythm_type='adaptive'
    )
    
    # Запускаем симуляцию с учетом звукового воздействия
    enhanced_stability = []
    optimized_params = {
        'light_wave': light_wave,
        'sound_freq': sound_freq,
        'phi_shift': 0
    }
    
    for i, t in enumerate(t_values):
        # Применяем звуковое воздействие к параметрам
        sound_influence = sound_signal[int(i * len(sound_signal) / len(t_values))]
        optimized_params = drum_stabilizer.apply_sound_to_plasma(
            optimized_params, sound_influence
        )
        
        # Пересчитываем стабильность с новыми параметрами
        stability, _ = plasma_grid_advanced(
            optimized_params['light_wave'],
            optimized_params['sound_freq'],
            t,
            phi_shift=optimized_params['phi_shift'],
            instability_point=instability_points[0][:3] if instability_points else None,
            obstacle_factor=instability_points[0][3] if instability_points else 0
        )
        enhanced_stability.append(stability.real)
    
    # Визуализируем результаты
    drum_stabilizer.visualize_sound_impact(stability_history, enhanced_stability, sound_signal)
    
    return enhanced_stability, sound_signal

# --- FUNC: detect_instability ---
def detect_instability(self, stability_data, threshold=0.1):
        """
        Обнаружение нестабильностей в данных о стабильности плазмы.
        
        Параметры:
        - stability_data: массив значений стабильности
        - threshold: порог обнаружения нестабильности
        
        Возвращает:
        - Список кортежей (время, сила_нестабильности, тип_нестабильности)
        """
        instability_events = []
        derivative = np.gradient(stability_data)
        
        for i, deriv in enumerate(derivative):
            if abs(deriv) > threshold:
                event_type = "spike" if deriv > 0 else "drop"
                instability_events.append((i, abs(deriv), event_type))
        
        return instability_events

# --- FUNC: generate_stabilization_sound ---
def generate_stabilization_sound(self, stability_data, total_duration, rhythm_type='adaptive'):
        """
        Генерация звукового сигнала для стабилизации плазмы.
        
        Параметры:
        - stability_data: массив значений стабильности
        - total_duration: общая длительность сигнала (сек)
        - rhythm_type: тип ритма ('sharp', 'soft', 'adaptive')
        
        Возвращает:
        - Звуковой сигнал для стабилизации
        """
        if rhythm_type == 'adaptive':
            # Для адаптивного ритма обнаруживаем нестабильности
            instability_events = self.detect_instability(stability_data)
            sound_signal = self._generate_adaptive_rhythm(instability_events, total_duration)
        else:
            # Для неадаптивных ритмов генерируем равномерный паттерн
            t = np.linspace(0, total_duration, int(total_duration * self.sample_rate), endpoint=False)
            if rhythm_type == 'sharp':
                # Резкие регулярные импульсы
                sound_signal = self._generate_sharp_impulse(1.0, 0.01) 
                sound_signal = np.tile(sound_signal, int(total_duration / 0.01))[:len(t)]
            else:  # soft
                # Мягкие регулярные импульсы
                sound_signal = self._generate_soft_impulse(1.0, 0.1)
                sound_signal = np.tile(sound_signal, int(total_duration / 0.1))[:len(t)]
        
        # Нормализуем сигнал
        sound_signal = sound_signal / np.max(np.abs(sound_signal)) if np.max(np.abs(sound_signal)) > 0 else sound_signal
        
        return sound_signal

# --- FUNC: apply_sound_to_plasma ---
def apply_sound_to_plasma(self, plasma_params, sound_signal, influence_factor=0.1):
        """
        Применение звукового воздействия к параметрам плазмы.
        
        Параметры:
        - plasma_params: текущие параметры плазмы
        - sound_signal: звуковой сигнал
        - influence_factor: коэффициент влияния звука на плазму
        
        Возвращает:
        - Модифицированные параметры плазмы
        """
        # Усредняем звуковой сигнал для получения общего воздействия
        sound_influence = np.mean(np.abs(sound_signal)) * influence_factor
        
        # Модифицируем параметры плазмы на основе звукового воздействия
        modified_params = plasma_params.copy()
        modified_params['sound_freq'] *= (1 + sound_influence)
        modified_params['phi_shift'] += sound_influence * np.pi / 2
        
        return modified_params

# --- FUNC: visualize_sound_impact ---
def visualize_sound_impact(self, stability_before, stability_after, sound_signal):
        """
        Визуализация воздействия звука на стабильность плазмы.
        """
        plt.figure(figsize=(12, 8))
        
        # График стабильности до и после
        plt.subplot(3, 1, 1)
        plt.plot(stability_before, 'b-', label='До звукового воздействия')
        plt.plot(stability_after, 'r-', label='После звукового воздействия')
        plt.ylabel('Стабильность')
        plt.legend()
        plt.grid(True)
        
        # График звукового сигнала
        plt.subplot(3, 1, 2)
        plt.plot(sound_signal, 'g-')
        plt.ylabel('Звуковой сигнал')
        plt.grid(True)
        
        # График улучшения стабильности
        plt.subplot(3, 1, 3)
        improvement = np.array(stability_after) - np.array(stability_before)
        plt.plot(improvement, 'm-')
        plt.ylabel('Улучшение стабильности')
        plt.xlabel('Время (отсчеты)')
        plt.grid(True)
        
        plt.tight_layout()
        plt.show()

# --- FUNC: enhanced_fihri_surface ---
def enhanced_fihri_surface(u, v, xi=1.0, stability=1.0, phase=0.0, alpha=2, beta=1, gamma=7):
    """
    Расширенная генерация фигуры Фихри с учетом параметров плазмы
    
    Параметры:
    u, v: угловые параметры [0, 2π]
    xi: коэффициент вихревого усиления/диссипации
    stability: параметр устойчивости плазмы
    phase: фазовый сдвиг
    alpha, beta, gamma: параметры из вашей сессии
    """
    # Базовый тор с модификацией Фихри
    r = np.abs(np.cos(u) + 1j * xi * np.sin(v))
    x = r * np.cos(u)
    y = r * np.sin(u)
    z = np.sin(u) * np.cos(v)
    
    # Модификация на основе параметров плазмы
    phi = (1 + np.sqrt(5)) / 2  # Золотое сечение
    modifier = (alpha / beta) * np.sqrt(gamma) * stability
    
    # Применяем модификатор
    x *= modifier
    y *= modifier
    z *= modifier
    
    # Добавляем фазовый сдвиг
    x_rot = x * np.cos(phase) - y * np.sin(phase)
    y_rot = x * np.sin(phase) + y * np.cos(phase)
    z_rot = z
    
    # Цвет зависит от локальной "устойчивости" - комбинации параметров
    color = stability * (0.5 + 0.5 * np.sin(phi * u + np.sqrt(5) * v + phase))
    
    return x_rot, y_rot, z_rot, color

# --- FUNC: calculate_stability_invariant ---
def calculate_stability_invariant(xi, t, light_wave=532e-9, sound_freq=392480):
    """
    Расчет инварианта устойчивости с учетом параметра ξ
    """
    phi = (1 + 5**0.5) / 2
    base_invariant = (light_wave * sound_freq / phi) * np.sqrt(7) * phi * 2 / 1
    time_factor = np.exp(-1j * 2 * np.pi * 1 * t)
    
    return np.abs(base_invariant * time_factor * xi)

