# --- FUNC: find_optimal_xi ---
def find_optimal_xi():
    t_values = np.linspace(0, 1, 100)
    xi_range = np.linspace(0.5, 1.5, 50)
    
    stability_scores = []
    for xi in xi_range:
        invariants = [calculate_stability_invariant(xi, t) for t in t_values]
        stability_score = np.mean(invariants) / np.std(invariants)
        stability_scores.append(stability_score)
    
    optimal_xi = xi_range[np.argmax(stability_scores)]
    max_stability = np.max(stability_scores)
    
    fig = go.Figure()
    fig.add_trace(go.Scatter(
        x=xi_range,
        y=stability_scores,
        mode='lines',
        name='Стабильность',
        line=dict(width=3, color='purple')
    ))
    
    fig.add_trace(go.Scatter(
        x=[optimal_xi],
        y=[max_stability],
        mode='markers',
        name=f'Оптимум: ξ={optimal_xi:.2f}',
        marker=dict(size=12, color='gold')
    ))
    
    fig.update_layout(
        title='Оптимизация параметра ξ',
        xaxis_title='ξ',
        yaxis_title='Показатель стабильности',
        hovermode='x unified'
    )
    
    return fig, optimal_xi

# --- FUNC: fihri_surface ---
def fihri_surface(u, v, xi=1.0, stability=1.0, phase=0.0):
    """Генерация поверхности Фихри с учётом параметров плазмы"""
    r = np.abs(np.cos(u) + 1j * xi * np.sin(v))
    x = r * np.cos(u)
    y = r * np.sin(u)
    z = np.sin(u) * np.cos(v)
    
    # Модификатор на основе параметров
    modifier = (ALPHA / BETA) * np.sqrt(GAMMA) * stability
    x *= modifier; y *= modifier; z *= modifier
    
    # Вращение по фазе
    x_rot = x * np.cos(phase) - y * np.sin(phase)
    y_rot = x * np.sin(phase) + y * np.cos(phase)
    
    # Цветовая карта устойчивости
    color = stability * (0.5 + 0.5 * np.sin(PHI * u + np.sqrt(5) * v + phase))
    
    return x_rot, y_rot, z, color

# --- FUNC: conquer_last_percent ---
def conquer_last_percent(strategy):
    """Многоуровневый подход к достижению 100%"""
    strategies = {
        'quantum': conquer_quantum_limitations,
        'thermodynamic': conquer_thermodynamic_limits,
        'turbulence': conquer_turbulence,
        'informational': conquer_information_limits
    }
    
    result = 99.0  # Начальная эффективность
    for domain, strategy_func in strategies.items():
        result += strategy_func(result) * 0.0025  # 0.25% от каждого подхода
    
    return min(result, 100.0)

