# --- FUNC: create_orthogonal_basis ---
def create_orthogonal_basis(self):
        """Создание ортогонального базиса пространства"""
        basis = []
        for i in range(self.dimension):
            vec = np.zeros(self.dimension, dtype=complex)
            vec[i] = 1.0
            basis.append(vec)
        return basis

# --- FUNC: create_observable_operator ---
def create_observable_operator(self, eigenvalues, eigenvectors=None):
        """
        Создание оператора наблюдаемой
        eigenvalues: спектр собственных значений
        eigenvectors: собственные векторы (опционально)
        """
        if eigenvectors is None:
            eigenvectors = self.basis
            
        operator = np.zeros((self.dimension, self.dimension), dtype=complex)
        for i, eigenvalue in enumerate(eigenvalues):
            psi = eigenvectors[i]
            operator += eigenvalue * np.outer(psi, psi.conj())
            
        return operator

# --- FUNC: quantum_expectation_value ---
def quantum_expectation_value(self, state, operator):
        """
        Вычисление квантового среднего
        <ψ|O|ψ> для оператора O и состояния ψ
        """
        return np.vdot(state, operator @ state)

# --- FUNC: plot_interference_pattern ---
def plot_interference_pattern(X, Y, intensity, wavefront):
    """Визуализация интерференционной картины"""
    fig = plt.figure(figsize=(15, 5))
    
    # Интенсивность
    plt.subplot(131)
    plt.imshow(intensity, extent=[X.min(), X.max(), Y.min(), Y.max()], 
               cmap='viridis', origin='lower')
    plt.colorbar(label='Интенсивность')
    plt.title('Интенсивность света')
    
    # Фаза
    plt.subplot(132)
    phase = np.angle(wavefront)
    plt.imshow(phase, extent=[X.min(), X.max(), Y.min(), Y.max()],
               cmap='hsv', origin='lower')
    plt.colorbar(label='Фаза (рад)')
    plt.title('Фазовое распределение')
    
    # Комплексная амплитуда (действительная часть)
    plt.subplot(133)
    real_part = np.real(wavefront)
    plt.imshow(real_part, extent=[X.min(), X.max(), Y.min(), Y.max()],
               cmap='RdBu', origin='lower')
    plt.colorbar(label='Re(Амплитуда)')
    plt.title('Действительная часть волнового фронта')
    
    plt.tight_layout()
    plt.show()

