# --- FUNC: calculate_invariant ---
def calculate_invariant(self, t, xi=1.0):
        """Расчёт инварианта устойчивости с учётом параметра ξ"""
        base = (LIGHT_WAVE * SOUND_FREQ / PHI) * np.sqrt(GAMMA) * PHI * ALPHA / BETA
        time_factor = np.exp(-1j * 2 * np.pi * TAU * t)
        return base * time_factor * xi

# --- FUNC: optimal_sound_frequency ---
def optimal_sound_frequency(self, temperature, density):
        """Расчёт оптимальной звуковой частоты для стабилизации"""
        return np.sqrt(temperature * density) / (2 * np.pi * PHI)

# --- FUNC: plasma_grid_advanced ---
def plasma_grid_advanced(light_wave, sound_freq, t, alpha=2, beta=1, gamma=7, 
                        tau=1, phi_shift=0, obstacle_factor=0.0):
    """Расширенная модель плазменной решётки"""
    phi = (1 + 5**0.5) / 2
    base_invariant = (light_wave * sound_freq / phi) * np.sqrt(gamma) * phi * alpha / beta
    phase_factor = cmath.exp(-1j * (2 * cmath.pi * tau * t + phi_shift))
    return base_invariant * phase_factor * (1 - obstacle_factor)

# --- FUNC: calculate_optimal_xi ---
def calculate_optimal_xi(self, t_values):
        """Расчёт оптимального значения ξ для временного диапазона"""
        stability_scores = []
        xi_range = np.linspace(0.5, 1.5, 50)
        
        for xi in xi_range:
            invariants = [np.abs(self.calculate_invariant(t, xi)) for t in t_values]
            stability_scores.append(np.mean(invariants) / np.std(invariants))
            
        optimal_xi = xi_range[np.argmax(stability_scores)]
        self.xi_history.append(optimal_xi)
        return optimal_xi

# --- FUNC: integrated_control ---
def integrated_control(self, t, plasma_instability):
        """
        Интегрированная система управления, объединяющая все подходы
        """
        # 1. Базовый инвариант
        base = self.calculate_invariant(t)
        
        # 2. Регулировка по принципу прялки
        tension, twist = self.spin_plasma(plasma_instability)
        
        # 3. Многослойная защита по принципу иконки
        shield, points = self.icon_protection_shield(t)
        
        # 4. Комбинируем все эффекты
        combined_control = base * tension * twist * shield
        
        # 5. Записываем историю для анализа
        self.stability_history.append(np.abs(combined_control))
        
        return combined_control, points

