# --- FUNC: generate_fihry_torus ---
def generate_fihry_torus(u, v, R=2.0, r=1.0, xi=1.0, n_waves=3):
    """
    Генерация параметрической модели тора с вихревой модуляцией
    в стиле фигуры Фихри.
    
    Параметры:
    u, v: угловые параметры [0, 2π]
    R: большой радиус тора
    r: малый радиус тора  
    xi: коэффициент вихревого усиления/диссипации
    n_waves: количество волновых периодов вокруг тора
    """
    # Базовый тор
    x_base = (R + r * np.cos(v)) * np.cos(u)
    y_base = (R + r * np.cos(v)) * np.sin(u)
    z_base = r * np.sin(v)
    
    # Вихревая модуляция - зависит от ξ
    # Используем золотое сечение и √5 для гармонизации
    phi = (1 + np.sqrt(5)) / 2
    vortex_mod = xi * (np.sin(n_waves * u + phi) * np.cos(n_waves * v - np.sqrt(5)))
    
    # Применяем модуляцию
    x = x_base * (1 + 0.1 * vortex_mod)
    y = y_base * (1 + 0.1 * vortex_mod) 
    z = z_base + 0.2 * vortex_mod
    
    return x, y, z

# --- FUNC: calculate_invariant_with_xi ---
def calculate_invariant_with_xi(light_wave, sound_freq, t, xi, alpha=2, beta=1, gamma=7, tau=1):
    """
    Расчет модифицированного инварианта с коэффициентом вихревого усиления ξ
    """
    phi = (1 + 5**0.5) / 2
    base_invariant = (light_wave * sound_freq / phi) * np.sqrt(gamma) * phi * alpha / beta
    
    # Временная компонента с учетом τ
    time_factor = np.exp(-1j * 2 * np.pi * tau * t)
    
    # Модификация инварианта коэффициентом ξ
    modified_invariant = base_invariant * time_factor * xi
    
    return modified_invariant

# --- FUNC: create_vortex_data ---
def create_vortex_data(xi_values, n_points=100):
    """
    Создание данных для 3D визуализации при разных значениях ξ
    """
    u = np.linspace(0, 2*np.pi, n_points)
    v = np.linspace(0, 2*np.pi, n_points)
    u, v = np.meshgrid(u, v)
    
    figures = []
    for xi in xi_values:
        x, y, z = generate_fihry_torus(u, v, xi=xi)
        figures.append((x, y, z))
        
    return figures

