# --- FUNC: plot_xi_impact_on_invariant ---
def plot_xi_impact_on_invariant():
    """
    Визуализация влияния параметра ξ на инвариант удержания
    """
    t_values = np.linspace(0, 1, 100)
    xi_values = [0.8, 0.9, 1.0, 1.1, 1.2]
    
    fig = go.Figure()
    
    for xi in xi_values:
        invariant_real = []
        invariant_imag = []
        
        for t in t_values:
            invariant = calculate_invariant_with_xi(
                light_wave=532e-9,
                sound_freq=392480, 
                t=t,
                xi=xi
            )
            invariant_real.append(invariant.real)
            invariant_imag.append(invariant.imag)
            
        fig.add_trace(go.Scatter(
            x=t_values,
            y=invariant_real,
            mode='lines',
            name=f'Re(Inv), ξ={xi}'
        ))
        
        fig.add_trace(go.Scatter(
            x=t_values, 
            y=invariant_imag,
            mode='lines',
            name=f'Im(Inv), ξ={xi}',
            line=dict(dash='dash')
        ))
    
    fig.update_layout(
        title='Влияние параметра ξ на инвариант удержания',
        xaxis_title='Время',
        yaxis_title='Значение инварианта',
        hovermode='closest'
    )
    
    return fig

# --- FUNC: enhanced_plasma_model_with_xi ---
def enhanced_plasma_model_with_xi(t, xi, plasma_params):
    """
    Расширенная модель плазмы с учетом параметра вихревого усиления ξ
    """
    # Базовые параметры
    alpha, beta, gamma, tau = 2, 1, 7, 1
    
    # Расчет модифицированного инварианта
    invariant = calculate_invariant_with_xi(
        plasma_params['light_wave'],
        plasma_params['sound_freq'],
        t,
        xi,
        alpha, beta, gamma, tau
    )
    
    # Влияние ξ на стабильность (примерная модель)
    stability = np.abs(invariant) * (1 - 0.1 * np.exp(-xi))
    
    return stability, invariant

# --- FUNC: absolute_formula_vectorized ---
def absolute_formula_vectorized(r, t, xi=1.0, spin_state=None):
    """
    Векторная реализация формулы Абсолюта с квантовыми операторами
    r: вектор положения [x, y, z]
    t: время
    xi: параметр вихревого усиления
    spin_state: вектор спинового состояния
    """
    # Базовые параметры из вашей сессии
    phi = (1 + np.sqrt(5)) / 2
    alpha, beta, gamma, tau = 2, 1, 7, 1
    
    # Векторная базовая компонента
    base_vector = np.array([
        alpha * np.cos(phi * t),
        beta * np.sin(phi * t),
        gamma * np.exp(-1j * 2 * np.pi * tau * t)
    ])
    
    # Тензор вихревого усиления (матрица 3x3)
    vortex_tensor = np.array([
        [xi, 0, 0],
        [0, xi * phi, 0],
        [0, 0, xi * np.sqrt(5)]
    ])
    
    # Применение вихревого усиления
    enhanced_vector = vortex_tensor @ base_vector
    
    # Квантовое спиновое воздействие
    if spin_state is not None:
        # Оператор спинового взаимодействия
        spin_operator = sigma_x * enhanced_vector[0] + \
                       sigma_y * enhanced_vector[1] + \
                       sigma_z * enhanced_vector[2]
        
        # Развитие спинового состояния во времени
        spin_evolution = expm(-1j * spin_operator * t)
        final_spin = spin_evolution @ spin_state
        
        return enhanced_vector, final_spin, spin_operator
    
    return enhanced_vector

