# --- FUNC: current_entropy ---
def current_entropy(self) -> float:
        """
        Вычисляет текущую энтропию системы на основе разброса параметров.
        Для демонстрации используем упрощённую формулу.
        """
        # Пример: энтропия как отклонение от идеальных значений
        values = [self.phi, self.sqrt5, self.gamma, self.lambda0] + list(self.parameters.values())
        mean = sum(values) / len(values)
        variance = sum((x - mean)**2 for x in values) / len(values)
        # Нормируем, чтобы получить значение от 0 до 1
        normalized = variance / (mean**2 + 1e-9)
        return min(normalized, 1.0)

# --- FUNC: check_entropy ---
def check_entropy(self) -> bool:
        """Проверяет, не превышает ли энтропия порог. Возвращает True, если всё в порядке."""
        ent = self.current_entropy()
        if ent > self.entropy_threshold:
            print(f"⚠️ Энтропия ({ent:.3f}) превышает порог ({self.entropy_threshold}).")
            return False
        return True

