# --- FUNC: generate_session_tag ---
def generate_session_tag(core_data: dict = None) -> str:
        """
        🏷️ Генерирует уникальный хештег для текущей сессии
        Формат: ABS_YYYYMMDD_HHMMSS_SHORT_HASH
        """
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        
        # Используем фундаментальные константы для создания уникального хеша
        if core_data and 'fundamentals' in core_data:
            data_str = f"{core_data['fundamentals'].get('φ', 1.618)}" \
                      f"{core_data['fundamentals'].get('√5', 2.236)}" \
                      f"{timestamp}"
        else:
            data_str = f"ABSOLUTE_SYSTEM_{timestamp}"
        
        # Создаем короткий хеш (8 символов)
        short_hash = hashlib.sha256(data_str.encode()).hexdigest()[:8].upper()
        
        return f"ABS_{timestamp}_{short_hash}"

