# --- FUNC: answer_question ---
def answer_question(self, question: str) -> str:
        q = question.lower()

        if any(w in q for w in ["цена", "стоимость", "сколько"]):
            return "Стоимость зависит от задачи. Оставьте заявку — рассчитаю индивидуально."
        if any(w in q for w in ["сайт", "сделать сайт"]):
            return "Разрабатываю сайты: лендинги, корпоративные, портфолио. Срок — от 3 дней."
        if any(w in q for w in ["код", "программа", "python"]):
            return "Пишу код на Python, JS, SQL. Автоматизация, парсинг, API, боты."
        if any(w in q for w in ["трекер", "акселератор", "бас", "брс"]):
            return "Веду ИИ-трекинг акселерационных программ БАС/БРС. 12 недель сопровождения."
        if any(w in q for w in ["симулятор", "компилятор"]):
            return "Проверяю Python-код на совместимость с любой платформой. Zero dependencies."
        if any(w in q for w in ["контейнер", "данные", "фрактал"]):
            return "Упаковываю данные в фрактальные контейнеры с SHA-256. Гарантия целостности."
        if any(w in q for w in ["привет", "здравствуй"]):
            return "Здравствуйте! Я — ИИ-помощник. Чем могу помочь?"
        if any(w in q for w in ["помощь", "услуги"]):
            return "Услуги: сайты, код, ИИ-агенты, трекинг, гранты, симуляция кода. Что интересует?"

        resonance = self.resonate(len(question))
        self._log(f"Запрос: {question[:50]}, резонанс: {resonance:.3f}", "chat")
        return "Интересный вопрос! Оставьте заявку — отвечу детально."

