def generate_tag(self, theme: str, module_keys: List[str]) -> str:
        clean_theme = "".join(c for c in theme if c.isalnum() or c in " _-").strip().replace(" ", "_")
        hash_src = json.dumps(module_keys, ensure_ascii=False).encode("utf-8")
        short_hash = hashlib.md5(hash_src).hexdigest()[:6].upper()
        date = datetime.now().strftime("%Y%m%d")
        return f"#DeepSeek_{clean_theme[:24]}_{date}_{short_hash}"

