# --- FUNC: generate_gyroid ---
def generate_gyroid(size: int = 100, porosity: float = 0.7, smooth: float = 0.5) -> np.ndarray:
    """
    Генерирует гироидную TPMS-структуру с регулируемой пористостью.
    size — разрешение сетки (чем больше, тем детальнее)
    porosity — доля пустот (0..1)
    smooth — степень сглаживания (для подготовки к 3D-печати)
    """
    x, y, z = np.mgrid[:size, :size, :size] * (2 * np.pi / size * 2)
    gyroid = np.sin(x) * np.cos(y) + np.sin(y) * np.cos(z) + np.sin(z) * np.cos(x)
    threshold = np.percentile(gyroid, porosity * 100)
    binary = gyroid < threshold
    if smooth > 0:
        binary = gaussian_filter(binary.astype(float), sigma=smooth) > 0.5
    return binary

# --- FUNC: export_for_3d_print ---
def export_for_3d_print(grid: np.ndarray, filename: str = "gyroid.stl"):
    """Экспортирует структуру в STL с оптимизацией для 3D-печати"""
    mesh = pv.UniformGrid(dimensions=grid.shape).threshold(grid.flatten())
    # Оптимизация: удаление изолированных вокселей
    mesh = mesh.extract_largest()
    mesh = mesh.smooth(n_iter=20, relaxation_factor=0.5)
    mesh.save(filename)
    print(f"✅ Модель сохранена как {filename}")

# --- FUNC: visualize_gyroid ---
def visualize_gyroid(grid: np.ndarray):
    """Интерактивная визуализация гироидной решётки"""
    mesh = pv.UniformGrid(dimensions=grid.shape).threshold(grid.flatten())
    mesh = mesh.extract_largest()
    plotter = pv.Plotter()
    plotter.add_mesh(mesh, color="lightblue", show_edges=True, opacity=0.9)
    plotter.add_axes()
    plotter.show()

