def simulator_analyze(req: CodeCheckRequest):
    if not simulator:
        return {"status": "error", "message": "Симулятор не подключён"}
    try:
        env = TargetEnv(os=req.os, arch=req.arch, python=req.python)
        report = simulator.analyze(req.code, env)
        return {
            "status": report["status"],
            "errors": report["metadata"]["errors_count"],
            "warnings": report["metadata"]["warnings_count"],
            "details": report,
        }
    except Exception as e:
        return {"status": "error", "message": str(e)}

