def simulator_execute(req: CodeCheckRequest):
    if not simulator:
        return {"status": "error", "message": "Симулятор не подключён"}
    try:
        env = TargetEnv(os=req.os, arch=req.arch, python=req.python)
        return simulator.analyze_and_execute(req.code, env, timeout=req.timeout)
    except Exception as e:
        return {"status": "error", "message": str(e)}

