# --- FUNC: hash_token ---
def hash_token(token: str) -> str:
    return hashlib.sha256(token.encode()).hexdigest()

# --- FUNC: verify_admin_token ---
def verify_admin_token(token: str) -> bool:
    """Проверка токена Хранителя (внутренняя)"""
    return hash_token(token) == settings.ADMIN_TOKEN_HASH

# --- FUNC: create_jwt ---
def create_jwt(user_id: str) -> str:
    expire = datetime.utcnow() + timedelta(hours=settings.JWT_EXPIRE_HOURS)
    return jwt.encode(
        {"sub": user_id, "exp": expire},
        settings.SECRET_KEY,
        algorithm=settings.JWT_ALGORITHM
    )

# --- FUNC: verify_jwt ---
def verify_jwt(token: str = Header(...)) -> str:
    try:
        payload = jwt.decode(token, settings.SECRET_KEY, algorithms=[settings.JWT_ALGORITHM])
        return payload["sub"]
    except JWTError:
        raise HTTPException(status_code=401, detail="Неверный токен")

# --- FUNC: search_data ---
def search_data(self, keyword: str) -> Dict[str, Any]:
        """Поиск данных по ключевому слову"""
        results = {}
        for section, content in self.data.items():
            matches = {}
            for key, value in content.items():
                if (keyword.lower() in str(key).lower() or 
                    keyword.lower() in str(value).lower()):
                    matches[key] = value
            if matches:
                results[section] = matches
        return results

