# --- FUNC: aggregate_class_trajectory ---
def aggregate_class_trajectory(students: List[Student]) -> Dict:
    """
    Строит усреднённую траекторию класса
    (для отчётности и планирования)
    """
    # Собираем все модули, которые проходят ученики
    all_modules = {}
    for student in students:
        for module in student.trajectory:
            all_modules[module.id] = all_modules.get(module.id, 0) + 1
    
    # Сортируем по популярности
    sorted_modules = sorted(all_modules.items(), key=lambda x: x[1], reverse=True)
    
    return {
        "class_size": len(students),
        "most_common_modules": [{"module": mid, "students": count} 
                               for mid, count in sorted_modules[:5]],
        "avg_progress": sum(s.progress for s in students) / len(students),
        "bottlenecks": find_common_difficulties(students)  # модули, где больше всего ошибок
    }

