# --- FUNC: register_team ---
def register_team(self, team_id: str, team_name: str,
                      contact_email: str) -> dict:
        """Создаёт новый узел команды."""
        path = f"teams.{team_id}"
        self.storage[f"{path}.name"] = team_name
        self.storage[f"{path}.email"] = contact_email
        self.storage[f"{path}.status"] = "diagnostic"
        self.storage[f"{path}.created"] = datetime.now().isoformat()
        self.storage[f"{path}.diagnostic.answers"] = {}
        self.storage[f"{path}.goal"] = None
        self.storage[f"{path}.tracking.sessions"] = []
        self.storage[f"{path}.reports"] = []

        return {"status": "ok", "team_id": team_id}

