# --- FUNC: save_diagnostic ---
def save_diagnostic(self, team_id: str,
                        answers: Dict[str, str]) -> dict:
        """Сохраняет ответы на диагностику."""
        path = f"teams.{team_id}.diagnostic.answers"
        for i, (key, value) in enumerate(answers.items()):
            self.storage[f"{path}.q{i}"] = {
                "question": key,
                "answer": value
            }
        self.storage[f"teams.{team_id}.status"] = "goal_setting"
        self.storage[f"teams.{team_id}.diagnostic.completed"] = \
            datetime.now().isoformat()
        return {"status": "ok"}

# --- FUNC: add_tracking_session ---
def add_tracking_session(self, team_id: str, week: int,
                             done: str, problems: str,
                             plan: str) -> dict:
        """Добавляет отчёт по неделе."""
        path = f"teams.{team_id}.tracking.sessions.w{week}"
        self.storage[f"{path}.week"] = week
        self.storage[f"{path}.done"] = done
        self.storage[f"{path}.problems"] = problems
        self.storage[f"{path}.plan"] = plan
        self.storage[f"{path}.timestamp"] = datetime.now().isoformat()
        return {"status": "ok", "week": week}

# --- FUNC: _count_sessions ---
def _count_sessions(self, team_id: str) -> int:
        """Считает количество проведённых сессий."""
        try:
            sessions = self.storage[f"teams.{team_id}.tracking.sessions"]
            if isinstance(sessions, dict):
                return len(sessions)
            return 0
        except KeyError:
            return 0

# --- FUNC: export_team ---
def export_team(self, team_id: str) -> str:
        """Экспортирует данные команды в одну строку (gzip+base64)."""
        team_node = self.storage.get_child("teams").get_child(team_id)
        if not team_node:
            raise ValueError("Команда не найдена")
        team_node.freeze()
        return team_node.dumps()

