# --- FUNC: integrate_z_protocol_container ---
def integrate_z_protocol_container(target_session: Optional[Dict] = None) -> Dict:
    """
    Встраивает Z-Protocol контейнер в новую сессию.

    Пример использования:
        session = {}
        session = integrate_z_protocol_container(session)
        print(session["z_protocol"]["meta"]["hashtags"])
    """
    if target_session is None:
        target_session = {}

    # Формируем хеш контейнера
    hash_input = f"{META['version']}{META['created']}{CORE['Z']}"
    container_hash = hashlib.sha256(hash_input.encode()).hexdigest()[:12]

    target_session["z_protocol"] = {
        "meta": META,
        "core": CORE,
        "terms": TERMS,
        "z_transition_schema": Z_TRANSITION_SCHEMA,
        "built_in_rules": BUILT_IN_RULES,
        "layers": LAYERS,
        "node_levels": NODE_LEVELS,
        "evolution_conditions": EVOLUTION_CONDITIONS,
        "tactics": TACTICS,
        "architecture": ARCHITECTURE,
        "implementation_code": IMPLEMENTATION_CODE,
        "philosophy": PHILOSOPHY,
        "document_structure": DOCUMENT_STRUCTURE,
        "progress": PROGRESS,
        "hash": container_hash,
    }

    return target_session

# --- FUNC: calculate_entropy ---
def calculate_entropy(data):
      counts = np.bincount(data)
      probabilities = counts / len(data)
      return -np.sum(probabilities * np.log2(probabilities))

