# --- FUNC: create_simplified_lattice ---
def create_simplified_lattice(cell_size=20, wall_thickness=4, size=(150, 150, 50)):
    """
    Генерирует упрощенную решетку для FDM-печати.
    :param cell_size: Размер ячейки (рекомендуется 15–25 мм для полимеров).
    :param wall_thickness: Толщина перемычек (минимум 3 мм).
    :param size: Габариты модели (X, Y, Z) в мм.
    """
    # 1. Создание гибридной решетки (тетраэдры + кубы для упрощения)
    lattice = trimesh.creation.lattice(
        cell_shape='tetra',  # Тетраэдры (более простые для печати)
        cell_size=cell_size,
        radius=wall_thickness/2,
        outer_radius=wall_thickness/2 * 1.5  # Усиленные внешние перемычки
    )

    # 2. Обрезка до заданных размеров
    lattice = lattice.boundary
    lattice = lattice.slice_plane([0, 0, 0], [1, 0, 0], size[0])
    lattice = lattice.slice_plane([0, 0, 0], [0, 1, 0], size[1])
    lattice = lattice.slice_plane([0, 0, 0], [0, 0, 1], size[2])

    # 3. Добавление усиленного основания
    base = trimesh.creation.box((size[0], size[1], 5))  # Толщина основания 5 мм
    base.apply_translation([0, 0, -size[2]/2])  # Центрирование
    model = trimesh.util.concatenate([lattice, base])

    return model

# --- FUNC: generate_monocoque ---
def generate_monocoque(length=4000, width=1800, height=1200):
    # 1. Создание внешней оболочки
    shell = osc.cube([length, width, height], center=True).offset(r=10).hull()

    # 2. Спиральная траектория для разделения камер
    t = np.linspace(0, 4*np.pi, 100)
    spiral_x = t * np.cos(t)
    spiral_y = t * np.sin(t)
    spiral_path = np.column_stack((spiral_x, spiral_y, np.zeros_like(t)))

    # 3. Решетка с разделением на две камеры
    lattice = osc.union()(
        osc.intersection()(
            shell,
            osc.lattice_sphere(radius=50, strut_thickness=5),  # Базовая решетка
            osc.rotate([0, 0, 90])(
                osc.linear_extrude(height=height)(
                    osc.polygon(points=spiral_path)  # Спиральное разделение
                )
            )
        )
    )

    # 4. Усиленные зоны для агрегатов
    engine_mount = osc.cylinder(r=50, h=200).translate([length/2 - 500, 0, 0])
    suspension_points = [osc.sphere(r=30).translate([x, y, z]) for x, y, z in [...]]
    reinforced_frame = lattice + engine_mount + suspension_points

    # 5. Каналы циркуляции
    cooling_channel = osc.pipe(radius=20, path=spiral_path)
    air_channel = osc.pipe(radius=15, path=spiral_path.offset(50))
    final_design = reinforced_frame + cooling_channel + air_channel

    return final_design

# --- FUNC: create_tetra_octa_lattice ---
def create_tetra_octa_lattice(cell_size=10, wall_thickness=2, outer_thickness=5, size=(100, 100, 100)):
    """
    Генерирует гибридную решетку из тетраэдров и октаэдров.
    :param cell_size: Размер ячейки (мм)
    :param wall_thickness: Толщина внутренних перемычек (мм)
    :param outer_thickness: Толщина внешних стенок (мм)
    :param size: Размер бруска (x, y, z) в мм
    :return: Треугольная сетка (trimesh.Trimesh)
    """
    # 1. Создание базовой решетки (тетраэдры + октаэдры)
    lattice = trimesh.creation.lattice(
        cell_shape='tetraoct',    # Гибрид тетраэдров и октаэдров
        cell_size=cell_size, 
        cell_spacing=0.9,         # Плотность упаковки
        radius=wall_thickness/2,  # Толщина перемычек
        outer_radius=outer_thickness/2  # Усиленные внешние перемычки
    )

    # 2. Обрезка до заданного размера
    lattice = lattice.boundary
    lattice = lattice.slice_plane([0,0,0], [1,0,0], size[0])
    lattice = lattice.slice_plane([0,0,0], [0,1,0], size[1])
    lattice = lattice.slice_plane([0,0,0], [0,0,1], size[2])

    # 3. Добавление компланарных стенок
    wall_z = trimesh.creation.box((size[0], size[1], outer_thickness))
    wall_top = wall_z.copy().apply_translation([0, 0, size[2] - outer_thickness])
    lattice = trimesh.util.concatenate([lattice, wall_z, wall_top])

    return lattice

