# --- FUNC: create_concept ---
def create_concept(self, id: str, name: str, discipline: str, 
                      invariant: str, connections: List[str], importance: float) -> Dict:
        """Создание нового концепта"""
        return {
            "id": id, "name": name, "discipline": discipline,
            "invariant": invariant, "connections": connections,
            "examples": [], "importance": importance,
            "level": self._calc_complexity(invariant)
        }

# --- FUNC: add_example ---
def add_example(self, concept_id: str, example: str):
        """Добавление современного примера к концепту"""
        if concept_id in self.concept_registry:
            self.concept_registry[concept_id]["examples"].append(example)
            self.analytics["modernity"] = min(1.0, self.analytics["modernity"] + 0.01)

# --- FUNC: find_learning_path ---
def find_learning_path(self, target: str) -> List[str]:
        """Поиск оптимального пути обучения"""
        try:
            roots = [n for n in self.knowledge_graph.nodes() if self.knowledge_graph.in_degree(n) == 0]
            paths = [nx.shortest_path(self.knowledge_graph, r, target) for r in roots if nx.has_path(self.knowledge_graph, r, target)]
            return min(paths, key=len) if paths else []
        except:
            return []

# --- FUNC: generate_textbook ---
def generate_textbook(self, discipline: str, level: int) -> Dict:
        """Генерация структуры учебника"""
        concepts = [c for c in self.concept_registry.values() 
                   if c["discipline"] == discipline and c["level"] <= level]
        concepts.sort(key=lambda x: (-x["importance"], x["level"]))
        
        return {
            "discipline": discipline,
            "level": level,
            "chapters": [{
                "title": c["name"],
                "core": c["invariant"],
                "examples": c["examples"][:3],  # 3 самых свежих примера
                "connections": [self.concept_registry[conn]["name"] for conn in c["connections"] 
                              if conn in self.concept_registry]
            } for c in concepts]
        }

# --- FUNC: _calc_complexity ---
def _calc_complexity(self, text: str) -> int:
        """Расчет сложности концепта"""
        return min(4, max(1, len(text) // 20))

# --- FUNC: _update_analytics ---
def _update_analytics(self):
        """Обновление метрик системы"""
        if self.knowledge_graph.number_of_nodes() > 0:
            self.analytics["coherence"] = sum(dict(self.knowledge_graph.degree()).values()) / self.knowledge_graph.number_of_nodes() / 10

# --- FUNC: export_state ---
def export_state(self) -> Dict:
        """Экспорт всего состояния системы"""
        return {
            "fundamental_core": self.fundamental_core,
            "concepts": self.concept_registry,
            "analytics": self.analytics,
            "graph_metrics": {
                "nodes": self.knowledge_graph.number_of_nodes(),
                "edges": self.knowledge_graph.number_of_edges()
            }
        }

# --- FUNC: import_state ---
def import_state(self, data: Dict):
        """Импорт состояния системы"""
        self.fundamental_core = data.get("fundamental_core", {})
        self.concept_registry = data.get("concepts", {})
        self.analytics = data.get("analytics", {})
        
        # Восстановление графа
        self.knowledge_graph = nx.DiGraph()
        for concept_id in self.concept_registry:
            self.knowledge_graph.add_node(concept_id)
            for conn in self.concept_registry[concept_id]["connections"]:
                if conn in self.concept_registry:
                    self.knowledge_graph.add_edge(conn, concept_id)

