# --- FUNC: plot_water_evolution ---
def plot_water_evolution(sim: HyperBalance7Simulation):
    plt.figure(figsize=(10, 5))
    plt.plot(sim.time_history, sim.water_history, 'b-', linewidth=2)
    plt.xlabel('Реляционное время (тики)')
    plt.ylabel('Накопленная вода (л)')
    plt.title('Динамика выработки воды HyperBalance7')
    plt.grid(True)
    plt.show()

# --- FUNC: economic_analysis ---
def economic_analysis(daily_water_liters, cost_prototype=2_800_000, maintenance=150_000,
                      lifetime=10, water_price=0.05):
    yearly_water = daily_water_liters * 365
    revenue = yearly_water * water_price
    total_revenue = revenue * lifetime
    total_cost = cost_prototype + maintenance * lifetime
    net_profit = total_revenue - total_cost
    roi = (net_profit / total_cost) * 100
    payback = cost_prototype / (revenue - maintenance) if (revenue - maintenance) > 0 else float('inf')
    cost_per_liter = total_cost / (yearly_water * lifetime)
    return {
        'yearly_revenue': revenue,
        'total_revenue': total_revenue,
        'total_cost': total_cost,
        'net_profit': net_profit,
        'roi': roi,
        'payback_years': payback,
        'cost_per_liter': cost_per_liter
    }

