def aroma_intensity(user_stress_level):  
        if user_stress_level > 70:  # По данным биодатчиков  
            return 0.8  # Максимальная концентрация  
        else:  
            return 0.3 * np.log(user_stress_level + 1)

# --- FUNC: add_artifact ---
def add_artifact(symbol, V_culture, chi=0.5):  
    # Проверка креативности  
    creativity_score = chi * np.sqrt(V_culture)  
    if creativity_score < 0.3:  
        raise ValueError("Артефакт слишком шаблонный! Измените χ или V_culture.")  
    
    # Расчёт κ  
    κ = 0.1 + 0.9 * (1 - np.exp(-V_culture))  
    κ_creative = κ * (1 + chi * np.sin(np.pi * V_culture)/2)  
    return np.clip(κ_creative, 0, 1)

