def calculate_resonance(self, profile, distance):
        """Расчет резонансного эффекта (из мирных технологий)"""
        base_effect = self.math_core["golden_ratio"] if profile == "MORAL_REALIGNMENT" else 1.0
        return base_effect / (1.0 + distance**2)

