# --- FUNC: compute_c_effective ---
def compute_c_effective(self, method='average'):
        """
        Вычисляет эффективную скорость света на основе параметров резонаторов.
        method: 'average' — среднее по всем резонаторам,
                'ratio' — (sum freq) / (sum k),
                'pair' — среднее по парам E-B.
        """
        if not self.E_resonators and not self.B_resonators:
            return None

        all_res = self.E_resonators + self.B_resonators

        if method == 'average':
            c_list = [r.get_c() for r in all_res if r.k != 0]
            if c_list:
                return sum(c_list) / len(c_list)
            else:
                return None

        elif method == 'ratio':
            sum_freq = sum(r.freq for r in all_res)
            sum_k = sum(r.k for r in all_res if r.k != 0)
            if sum_k != 0:
                return sum_freq / sum_k
            else:
                return None

        elif method == 'pair':
            # Берём среднее по всем парам E-B
            pairs = [(e, b) for e in self.E_resonators for b in self.B_resonators]
            if not pairs:
                return None
            c_pairs = []
            for e, b in pairs:
                if e.k != 0 and b.k != 0:
                    # Скорость как среднее от двух
                    c_pair = (e.freq/e.k + b.freq/b.k) / 2
                    c_pairs.append(c_pair)
            if c_pairs:
                return sum(c_pairs) / len(c_pairs)
            else:
                return None
        else:
            return None

# --- FUNC: plot_slice ---
def plot_slice(self, z_index=None, z_value=0.0, save=False, filename='slice.png'):
        if z_index is None:
            z_index = np.argmin(np.abs(self.z - z_value))
        fig, axs = plt.subplots(1, 4, figsize=(16, 4))
        # Амплитуда поля
        im1 = axs[0].imshow(np.abs(self.psi[:, :, z_index]).T,
                            extent=[self.x.min(), self.x.max(), self.y.min(), self.y.max()],
                            origin='lower', cmap='viridis')
        axs[0].set_title(f'|ψ|, z={self.z[z_index]:.2f}')
        plt.colorbar(im1, ax=axs[0])
        # Метрика
        im2 = axs[1].imshow(self.metric.field[:, :, z_index].T,
                            extent=[self.x.min(), self.x.max(), self.y.min(), self.y.max()],
                            origin='lower', cmap='plasma')
        axs[1].set_title('Кривизна')
        plt.colorbar(im2, ax=axs[1])
        # c_eff
        c_map = np.zeros((self.N, self.N))
        for i in range(self.N):
            for j in range(self.N):
                c_vals = []
                for e in self.E_resonators + self.B_resonators:
                    dist = np.hypot(self.X[i,j,z_index] - e.x,
                                    self.Y[i,j,z_index] - e.y,
                                    self.Z[i,j,z_index] - e.z)
                    if dist < 2.0:
                        c_vals.append(e.get_c() * np.exp(-dist**2 / 0.5))
                c_map[i,j] = np.mean(c_vals) if c_vals else 1.0
        im3 = axs[2].imshow(c_map.T, extent=[self.x.min(), self.x.max(), self.y.min(), self.y.max()],
                            origin='lower', cmap='coolwarm')
        axs[2].set_title('c_eff')
        plt.colorbar(im3, ax=axs[2])
        # Частоты
        f_map = np.zeros((self.N, self.N))
        for i in range(self.N):
            for j in range(self.N):
                f_vals = []
                for e in self.E_resonators + self.B_resonators:
                    dist = np.hypot(self.X[i,j,z_index] - e.x,
                                    self.Y[i,j,z_index] - e.y,
                                    self.Z[i,j,z_index] - e.z)
                    if dist < 2.0:
                        f_vals.append(e.freq * np.exp(-dist**2 / 0.5))
                f_map[i,j] = np.mean(f_vals) if f_vals else 0
        im4 = axs[3].imshow(f_map.T, extent=[self.x.min(), self.x.max(), self.y.min(), self.y.max()],
                            origin='lower', cmap='plasma')
        axs[3].set_title('Частоты')
        plt.colorbar(im4, ax=axs[3])
        plt.tight_layout()
        if save:
            plt.savefig(filename)
            print(f"Срез сохранён в {filename}")
        else:
            plt.show()

