# --- FUNC: embed_into_fractal_session ---
def embed_into_fractal_session(fractal_root, session_data=FRACTAL_SESSION):
    """
    Встраивает текущую сессию как под-узел во фрактальную структуру.
    """
    fractal_root["sub_sessions"] = fractal_root.get("sub_sessions", {})
    fractal_root["sub_sessions"][session_data["meta"]["id"]] = session_data
    return fractal_root

# --- FUNC: _extract_research_vectors ---
def _extract_research_vectors(self, session):
        """Извлечение ключевых направлений исследований"""
        vectors = []
        
        # Из ключевых инсайтов
        for insight in session["progress"]["section_1"]["key_insights"]:
            if "вторичное излучение" in insight.lower():
                vectors.append("Вторичная радиационная защита")
            if "квантовые системы" in insight.lower():
                vectors.append("Квантово-радиационный инжиниринг")
            if "орбита" in insight.lower():
                vectors.append("Орбитальная радиационная динамика")
        
        # Из следующих шагов
        for step in session["next_steps"]:
            if "пассивной защиты" in step.lower():
                vectors.append("Пассивные защитные материалы")
            if "криосистем" in step.lower():
                vectors.append("Криогенная радиационная стойкость")
            if "гибридных решений" in step.lower():
                vectors.append("Гибридные системы защиты")
        
        # Сохраняем вектора
        self.research_vectors[session["id"]] = {
            "vectors": list(set(vectors)),
            "priority": "high" if "квантов" in session["metadata"].get("title", "").lower() else "medium"
        }

# --- FUNC: _find_cross_links ---
def _find_cross_links(self, new_session):
        """Поиск связей с другими сессиями"""
        # Пример поиска по ключевым словам
        keywords = ["квантовые", "радиация", "спутники", "космические системы"]
        
        for existing_id, existing_session in self.sessions.items():
            if existing_id == new_session["id"]:
                continue
                
            # Проверяем совпадение тем
            existing_title = existing_session["metadata"].get("title", "").lower()
            new_title = new_session["metadata"].get("title", "").lower()
            
            common_keywords = [kw for kw in keywords 
                             if kw in existing_title and kw in new_title]
            
            if common_keywords:
                link = {
                    "session_a": existing_id,
                    "session_b": new_session["id"],
                    "common_themes": common_keywords,
                    "strength": len(common_keywords) / len(keywords)
                }
                self.cross_links.append(link)

# --- FUNC: get_session_report ---
def get_session_report(self, session_id):
        """Генерация отчета по сессии"""
        if session_id not in self.sessions:
            return None
        
        session = self.sessions[session_id]
        
        # Рассчитываем общий прогресс
        total_sections = len(session["progress"])
        completed = sum(1 for s in session["progress"].values() 
                       if s["status"] == "completed")
        
        progress_percent = (completed / total_sections) * 100
        
        return {
            "session_id": session_id,
            "title": session["metadata"].get("title", "Без названия"),
            "overall_progress": f"{progress_percent:.1f}%",
            "current_section": session["current_section"],
            "next_deadline": session["metadata"].get("next_deadline", "Не установлен"),
            "research_vectors": self.research_vectors.get(session_id, {}).get("vectors", []),
            "connected_sessions": [link for link in self.cross_links 
                                 if session_id in [link["session_a"], link["session_b"]]]
        }

# --- FUNC: trace_photon_interactions ---
def trace_photon_interactions(self, electron_config):
        """Восстановление истории взаимодействия с фотонами"""
        
        # Ридберговские состояния как детекторы полей
        if electron_config.rydberg_states.distorted:
            field_strength = self.calculate_field_from_stark_shift(
                electron_config.rydberg_states.shift
            )
            return {
                "событие": "прохождение_через_сильное_электрическое_поле",
                "кандидаты": [
                    "молния",
                    "полярное_сияние",
                    "солнечная_вспышка",
                    "техногенный_разряд"
                ],
                "энергия_поля": field_strength,
                "время_воздействия": estimate_duration_from_line_broadening()
            }
        
        # Сверхтонкая структура как термометр
        temperature_history = self.decode_temperature_from_hfs(
            electron_config.hyperfine_splitting
        )
        
        return temperature_history

# --- FUNC: reconstruct_interstellar_path ---
def reconstruct_interstellar_path(atom_data):
    """Восстановление маршрута атома через Галактику"""
    
    # Известные маркёры межзвёздной среды
    markers = {
        "молекулярные_облака": {
            "признаки": "Следы органических молекул (CO, HCN) в матрице",
            "температура": "10-30 K",
            "магнитное_поле": "10-100 μG"
        },
        
        "горячий_межзвёздный_газ": {
            "признаки": "Высокая степень ионизации, следы ударных волн",
            "температура": "10⁶ K",
            "магнитное_поле": "1-10 μG"
        },
        
        "зоны_звёздообразования": {
            "признаки": "Обогащение элементами от сверхновых",
            "температура": "10³-10⁴ K",
            "магнитное_поле": "100-1000 μG"
        },
        
        "галактические_фонтаны": {
            "признаки": "Высокоскоростные облака, обогащение тяжёлыми элементами",
            "температура": "10⁴-10⁵ K",
            "магнитное_поле": "1-5 μG"
        }
    }
    
    path = []
    current_environment = None
    
    # Временная реконструкция по слоям повреждений
    for damage_layer in sorted(atom_data.radiation_damage_layers, key=lambda x: x.depth):
        environment = identify_environment(damage_layer, markers)
        if environment != current_environment:
            path.append({
                "среда": environment,
                "продолжительность": estimate_duration(damage_layer),
                "расстояние_перемещения": estimate_travel_distance(environment)
            })
            current_environment = environment
    
    return {
        "предполагаемый_маршрут": path,
        "общее_расстояние": sum([segment["расстояние_перемещения"] for segment in path]),
        "время_путешествия": sum([segment["продолжительность"] for segment in path])
    }

# --- FUNC: decode_complete_history ---
def decode_complete_history(self, argon_atom):
        """Полная дешифровка истории атома"""
        
        history = {}
        
        # Слой 1: Космическое происхождение
        history["космическое_происхождение"] = self.read_cosmic_origin(argon_atom)
        
        # Слой 2: Межзвездное путешествие
        history["межзвездное_путешествие"] = self.read_interstellar_travel(argon_atom)
        
        # Слой 3: Планетарная история
        history["планетарная_история"] = self.read_planetary_history(argon_atom)
        
        # Слой 4: Квантовые отпечатки
        history["квантовые_отпечатки"] = self.read_quantum_imprints(argon_atom)
        
        # Слой 5: Временное кодирование
        history["временное_кодирование"] = self.read_temporal_coding(argon_atom)
        
        return self.reconstruct_timeline(history)

