# --- FUNC: decode_nuclear_memory ---
def decode_nuclear_memory(nucleus):
    events = []
    
    # Спиновые эхо как временные маркеры
    if nucleus.spin_echo_pattern == "perturbed":
        events.append({
            "type": "магнитная_буря",
            "возможная_эпоха": "исторические_периоды_высокой_солнечной_активности",
            "интенсивность": nucleus.magnetic_moment_deviation * CONST
        })
    
    # Квадрупольные метки
    if nucleus.quadrupole_resonance.shifted:
        events.append({
            "type": "тектоническое_событие",
            "механизм": "деформация_кристаллической_решетки_в_минералах",
            "давление": calculate_pressure_from_quadrupole(nucleus)
        })
    
    return events

