# --- FUNC: quantum_archaeology ---
def quantum_archaeology(atom_quantum_state):
    """Извлечение информации из квантовых отпечатков"""
    
    findings = {}
    
    # 1. Восстановление истории полей
    phase_history = extract_phase_history(atom_quantum_state.phase_accumulation)
    magnetic_history = reconstruct_magnetic_fields(phase_history)
    electric_history = reconstruct_electric_fields(phase_history)
    
    findings["история_магнитных_полей"] = magnetic_history
    findings["история_электрических_полей"] = electric_history
    
    # 2. Поиск следов запутанности
    entanglement_signature = test_bell_inequality(atom_quantum_state.correlation_data)
    
    if entanglement_signature.violated:
        findings["квантовая_запутанность_в_прошлом"] = {
            "степень_нарушения": entanglement_signature.violation_magnitude,
            "вероятный_партнёр": entanglement_signature.likely_partner,
            "время_сохранения": entanglement_signature.coherence_time
        }
    
    # 3. Анализ декогеренции
    decoherence_timeline = analyze_decoherence_pattern(atom_quantum_state.decoherence_signature)
    
    findings["временная_карта_декогеренции"] = decoherence_timeline
    findings["плотность_среды_в_прошлом"] = estimate_past_environment_density(decoherence_timeline)
    
    # 4. Квантовые часы
    quantum_clock_data = extract_quantum_clock_data(atom_quantum_state.energy_level_shifts)
    
    findings["квантовые_часы"] = {
        "относительное_замедление_времени": quantum_clock_data.time_dilation,
        "гравитационный_потенциал_в_прошлом": quantum_clock_data.gravitational_potential,
        "скорость_движения_в_прошлом": quantum_clock_data.velocity
    }
    
    return findings

