# --- FUNC: reconstruct_timeline ---
def reconstruct_timeline(self, atom):
        """Реконструкция временной линии атома"""
        
        timeline = []
        
        # Использование квантовых часов атома
        clock_transitions = atom.quantum_clock_transitions
        for transition in clock_transitions:
            time_marker = {
                "событие": "квантовый_переход",
                "время": transition.time,
                "энергия": transition.energy,
                "контекст": interpret_transition_context(transition)
            }
            timeline.append(time_marker)
        
        # Сортировка по времени
        timeline.sort(key=lambda x: x["время"])
        
        # Заполнение промежутков интерполяцией
        complete_timeline = self.interpolate_timeline(timeline)
        
        return {
            "полная_временная_линия": complete_timeline,
            "первое_событие": timeline[0] if timeline else None,
            "последнее_событие": timeline[-1] if timeline else None,
            "общая_продолжительность": timeline[-1]["время"] - timeline[0]["время"] if len(timeline) > 1 else 0
        }

