# --- FUNC: reconstruct_planetary_events ---
def reconstruct_planetary_events(argon_context):
    """Реконструкция событий на основе контекста атома"""
    
    events = []
    
    # Геологические события
    if argon_context.trapped_in_mineral:
        mineral_age = argon_argon_dating(argon_context.host_mineral)
        
        if mineral_age > 2500000000:  # Архей
            events.append({
                "период": "архей",
                "событие": "формирование континентальной коры",
                "доказательства": "Состав минерала, редкие элементы"
            })
        
        if 540000000 < mineral_age < 2500000000:  # Протерозой
            events.append({
                "период": "протерозой", 
                "событие": "кислородная катастрофа",
                "доказательства": "Изменение изотопного состава серы в матрице"
            })
    
    # Атмосферные события
    atmospheric_history = analyze_atmospheric_traces(argon_context)
    
    for change in atmospheric_history.significant_changes:
        events.append({
            "время": change.time,
            "атмосферное_событие": change.description,
            "изменение_в_Ar": change.effect_on_argon
        })
    
    # События, связанные с жизнью
    if argon_context.associated_with_biomarkers:
        biological_events = analyze_biomarkers(argon_context.biomarkers)
        events.extend(biological_events)
    
    return sorted(events, key=lambda x: x["время"])

