# --- FUNC: run_fdtd_simulation ---
def run_fdtd_simulation(self, wavelength_range=(400, 800)):
        """Упрощённая FDTD симуляция"""
        
        # Упрощённый расчёт на основе теории Ми
        wavelengths = np.linspace(wavelength_range[0], wavelength_range[1], 100)
        
        # Расчёт эффективности для SiO2/Si3N4 системы
        results = {
            "albedo": [],
            "absorption": [],
            "scattering_cross_section": [],
            "phase_shift": []
        }
        
        for λ in wavelengths:
            # Упрощённый расчёт альбедо
            # SiO2 (n=1.46) в Si3N4 (n=2.0) матрице
            n_ratio = 1.46 / 2.0
            d = 200  # нм диаметр
            
            # Параметр размера x = π*d*n_matrix/λ
            x = np.pi * d * 2.0 / λ
            
            # Приближённый расчёт эффективности рассеяния
            if x < 0.1:
                Q_sca = (8/3) * ((n_ratio**2 - 1)/(n_ratio**2 + 2))**2 * x**4
            else:
                # Для более крупных частиц используем аппроксимацию
                Q_sca = 2 - 4 * np.sin(x)/x + 4 * (1 - np.cos(x))/x**2
            
            # Альбедо (предполагаем малое поглощение)
            albedo = Q_sca / (Q_sca + 0.001)  # Малое поглощение
            
            results["albedo"].append(albedo)
            results["absorption"].append(0.001)
            results["scattering_cross_section"].append(Q_sca * np.pi * (d/2)**2)
            results["phase_shift"].append(2 * np.pi * (2.0 - 1.46) * 300 / λ)
        
        return {
            "wavelengths": wavelengths.tolist(),
            "results": results,
            "summary": self.analyze_results(results)
        }

