# --- FUNC: determine_stellar_origin ---
def determine_stellar_origin(isotope_ratios):
    """Определение типа звезды, в которой родился атом"""
    
    signatures = {
        "красный_гигант": {
            "³⁶Ar/³⁸Ar": "~5.0-5.2 (обогащение s-процессами)",
            "дополнительные_метки": "Повышенное содержание Kr, Xe от медленного захвата нейтронов"
        },
        
        "сверхновая_типа_II": {
            "³⁶Ar/³⁸Ar": "~5.5-5.8 (r-процессы, взрывное горение)",
            "дополнительные_метки": "Присутствие ⁴⁴Ti (распадается в ⁴⁴Ca), ⁶⁰Fe"
        },
        
        "нейтронная_звезда_слияние": {
            "³⁶Ar/³⁸Ar": "~6.0+ (экстремальные r-процессы)",
            "дополнительные_метки": "Золото, уран, другие тяжелые элементы от килоновой"
        },
        
        "солнечная_туманность": {
            "³⁶Ar/³⁸Ar": "5.32 ± 0.01 (среднее солнечное значение)",
            "дополнительные_метки": "Соотношения, идентичные солнечному ветру"
        }
    }
    
    best_match = None
    min_diff = float('inf')
    
    for star_type, signature in signatures.items():
        diff = abs(isotope_ratios["³⁶Ar/³⁸Ar"] - float(signature["³⁶Ar/³⁸Ar"].split('~')[-1].split(' ')[0]))
        if diff < min_diff:
            min_diff = diff
            best_match = star_type
    
    return {
        "предполагаемое_происхождение": best_match,
        "достоверность": f"{100 - min_diff*100:.1f}%",
        "дополнительные_подтверждения": signatures[best_match]["дополнительные_метки"]
    }

