# --- FUNC: generate_session_hashtag ---
def generate_session_hashtag(topic: str, date: datetime = None) -> str:
    """Генерация хештега для сессии"""
    if date is None:
        date = datetime.now()
    formatted_date = date.strftime("%Y_%m_%d")
    topic_slug = topic.lower().replace(" ", "_").replace(",", "")
    return f"#deepseek_{topic_slug}_{formatted_date}"

